    ["Eduard"] = {
        ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
        ["*Dialogue 1*"] = "*Diálogo 1*",
        ["Out of my way, punk."] = "Fuera de mi camino, punk.",
        ["*Dialogue 2*"] = "*Diálogo 2*",
        ["I have no interest in talking to a pathetic meat bag like yourself."] = "No tengo ningún interés en hablar con un patético bolsa de carne como tú.",
        ["*Dialogue 3*"] = "*Diálogo 3*",
        ["If I were as ugly as you I would not dare to show my face in public!"] = "¡Si fuera tan feo como tú no me atrevería a mostrar mi cara en público!",
        ["*Dialogue 4*"] = "*Diálogo 4*",
        ["Hmm... you smell strange..."] = "Hmm... hueles raro...",
        ["Strange how?"] = "¿Qué extraño cómo?",
        ["Like a human!"] = "¡Como un humano!",
        ["Oh! Er... I just ate one is why!"] = "¡Oh! Er... ¡acabo de comer uno, por eso!",
        ["*Dialogue 5*"] = "*Diálogo 5*",
        ["Get lost!"] = "¡Piérdete!",
        ["*Dialogue 6*"] = "*Diálogo 6*",
        ["Leave me alone."] = "Déjame en paz.",
        ["*Dialogue 7*"] = "*Diálogo 7*",
        ["Have you no manners?"] = "¿No tienes modales?",
        ["*Dialogue 8*"] = "*Diálogo 8*",
        ["I don't have anything to give you so leave me alone, mendicant."] = "No tengo nada que darte así que déjame en paz, mendigo.",
        ["*Dialogue 9*"] = "*Diálogo 9*",
        ["I don't have time for this right now."] = "No tengo tiempo para esto ahora.",
        ["*Dialogue 10*"] = "*Diálogo 10*",
        ["Don't talk to me again if you value your life!"] = "¡No vuelvas a hablarme si valoras tu vida!",
        ["Give me a moment... I have a bit of someone stuck in my teeth..."] = "Dame un momento... tengo un poco de alguien pegado entre los dientes...",
        ["I haven't smelt you around here before..."] = "No te había olido por aquí antes...",
        ["If you catch anyone promise me you'll share."] = "Si atrapas a alguien, prométeme que lo compartirás.",
        ["You look to me like someone with a healthy taste for blood."] = "Me pareces alguien con un gusto saludable por la sangre.",
        ["Fancy going up to the castle for a bit of a snack?"] = "¿Te apetece subir al castillo a tomar un refrigerio?",
        ["I bet you have wonderful paws."] = "Apuesto a que tienes unas patas maravillosas.",
        ["Seen any humans around here? I'm v-e-r-y hungry."] = "¿Has visto humanos por aquí? Tengo mucha hambre.",
        ["Good day to you, my friend."] = "Buenos días, amigo mío.",
        ["You smell familiar..."] = "Hueles familiar...",
        ["A very miserable day, altogether... enjoy it while it lasts."] = "Un día muy miserable, en definitiva... disfrútalo mientras dure.",
    },
    ["Eduardo (student)"] = {
        ["Hello there."] = "Hola.",
        ["Oh, hi. I'm studying hard for an exam."] = "Ah, hola. Estoy estudiando mucho para un examen.",
        ["What exam is that?"] = "¿Qué examen es ese?",
        ["It's the Earth Sciences exam."] = "Es el examen de Ciencias de la Tierra.",
        ["Interesting...."] = "Interesante....",
        ["I am not sure why I am giving this to the student..."] = "No estoy seguro de por qué le doy esto al estudiante...",
        ["Nothing interesting happens."] = "No pasa nada interesante.",
        ["Oh, hi again. News of your find has spread fast. You are quite famous around here now."] = "Ah, hola de nuevo. La noticia de su hallazgo se ha difundido rápidamente. Eres bastante famoso por aquí ahora.",
        ["I'm setting up a research team and wondered if you'd want to be a part of it..."] = "Estoy formando un equipo de investigación y me preguntaba si te gustaría ser parte de él...",
        ["I'd love to, but only interns and about can work on research teams. The only way I can become an intern is if I impress Acting Guildmaster Reiniger with an artefact find."] = "Me encantaría, pero solo los pasantes y alrededores pueden trabajar en equipos de investigación. La única manera de convertirme en pasante es impresionar a Acting Guildmaster Reiniger con un hallazgo de artefacto.",
        ["It would have to be an artefact related to my specialisation too, which is animal skulls and equipment."] = "Tendría que ser un artefacto relacionado con mi especialización también, que son cráneos y equipos de animales.",
        ["Would it fast track the process if I just brought you a restored artefact that fits?"] = "¿Aceleraría el proceso si solo les trajera un artefacto restaurado que encajara?",
        ["You'd do that just so I can work on your research team? That's so kind."] = "¿Harías eso solo para que yo pueda trabajar en tu equipo de investigación? Eso es muy amable.",
        ["Well, we did study for our exams together - you helped me out a lot, so I'm only returning the favour."] = "Bueno, estudiamos juntos para nuestros exámenes; me ayudaste mucho, así que solo te devolveré el favor.",
        ["Tell you what - if you can bring me a restored ceremonial unicorn ornament from Everlight, I'll report for duty ASAP!"] = "Te diré una cosa: si puedes traerme un adorno ceremonial de unicornio restaurado de Everlight, ¡me presentaré a trabajar lo antes posible!",
        ["I'm on it!"] = "¡Estoy en ello!",
        ["I have a restored ceremonial unicorn ornament from Everlight..."] = "Tengo un adorno ceremonial de unicornio restaurado de Everlight...",
        ["Give ceremonial unicorn ornament to Eduardo?"] = "¿Darle un adorno ceremonial de unicornio a Eduardo?",
        ["Yes."] = "Sí.",
        ["Fantastic! Reporting for duty, boss!"] = "¡Fantástico! ¡Preséntate para el servicio, jefe!",
        ["Eduardo has joined your research team!"] = "¡Eduardo se ha unido a tu equipo de investigación!",
        ["Let me get back to you on this."] = "Déjame responderte sobre esto.",
        ["Whenever you're ready is good."] = "Cuando estés listo es bueno.",
        ["Ready for research whenever you need me, boss!"] = "¡Listo para investigar cuando me necesites, jefe!",
    },
