    ["Elen Anterth"] = {
        ["Hey, welcome to the Max Guild garden!"] = "¡Oye, bienvenido al jardín del gremio Max!",
        ["Oh, hey there!"] = "¡Oh, hola!",
        ["What would you like to say?"] = "¿Qué te gustaría decir?",
        ["What's your name?"] = "¿Cuál es tu nombre?",
        ["I'm Elen! It's great to meet you! Welcome to the Max Guild!"] = "¡Soy Elen! ¡Es un placer conocerte! ¡Bienvenido al gremio Max!",
        ["Well done on getting in here - it's well deserved!"] = "Enhorabuena por haber entrado aquí. ¡Es bien merecido!",
        ["Elen? Shouldn't you be called Maxine or something?"] = "¿Elen? ¿No deberías llamarte Maxine o algo así?",
        ["Maxine? What a strange name that would be for an elf! Haha, I like it!"] = "¿Maxine? ¡Qué nombre más extraño sería ese para un elfo! Jaja, me gusta!",
        ["But no, it's Elen - Elen Anterth. My family falls under the auspices of Clan Cadarn."] = "Pero no, es Elen - Elen Anterth. Mi familia está bajo los auspicios del Clan Cadarn.",
        ["How are you so skilled if the city's only recently been regrown?"] = "¿Cómo eres tan hábil si la ciudad acaba de volver a crecer?",
        ["Oh, I've been all over! My family travelled east with the Cadarn way back."] = "¡Oh, he estado por todas partes! Mi familia viajó hacia el este con el camino de regreso de Cadarn.",
        ["I was only young, but I saw so much and learned a lot. You'd be surprised what sticks with you."] = "Yo era muy joven, pero vi mucho y aprendí mucho. Te sorprendería lo que se te queda grabado.",
        ["Nice cape you have there..."] = "Bonita capa la que tienes ahí...",
        ["Thanks! It took me ages to get, but I got there in the end: I'm fully proficient in every skill."] = "¡Gracias! Me tomó mucho tiempo lograrlo, pero al final lo logré: soy completamente competente en todas las habilidades.",
        ["To do this you need in the following skill levels: 99 [Skill]"] = "Para hacer esto necesitas en el siguiente skill levels: 99 [Skill]",
        ["Wow, that's quite impressive."] = "Vaya, eso es bastante impresionante.",
        ["Thanks. I have faith in you, Player. Just take your time and you'll get there too, I know it!"] = "Gracias. Tengo fe en ti, Player. Tómate tu tiempo y tú también llegarás allí, ¡lo sé!",
