        ["I've maxed all skills!"] = "¡He maximizado todas las habilidades!",
        ["Really? Good for you! Would you like a cape to show off your achievement? It's 2,871,000 coins - 99,000 for each skill!"] = "¿En serio? ¡Bien por usted! ¿Quieres una capa para mostrar tu logro? Son 2.871.000 coins: ¡99.000 por cada habilidad!",
        ["Pay 2,871,000 for a max cape?"] = "¿Pagar 2.871.000 por una capa máxima?",
        ["I'll take one!"] = "¡Me llevaré uno!",
        ["Sure!"] = "¡Claro!",
        ["You don't have enough inventory space to withdraw that many."] = "No tienes suficiente espacio en el inventario para retirar tantos.",
        ["Oh, but you'll need room in your inventory for a cape and hood."] = "Ah, pero necesitarás espacio en tu inventario para una capa y una capucha.",
        ["You can not afford that."] = "No puedes permitirte eso.",
        ["Sorry, hun, but you don't have enough coins on you."] = "Lo siento, cariño, pero no tienes suficiente coins contigo.",
        ["Thanks. Enjoy!"] = "Gracias. ¡Disfrutar!",
        ["No, thanks."] = "No, gracias.",
        ["What happened to your Max cape?"] = "¿Qué pasó con tu capa Max?",
        ["Oh, I'm training [Recently released skill]! No rush, taking my time. You'll probably beat me to max!"] = "¡Oh, estoy entrenando a [Recently released skill]! Sin prisas, tomándome mi tiempo. ¡Probablemente me ganarás al máximo!",
        ["Do you know someone called Max?"] = "¿Conoces a alguien llamado Max?",
        ["You don't mean that bullish human from Varrock, do you?"] = "No te refieres a ese humano optimista de Varrock, ¿verdad?",
        ["Bullish? Well, I guess he is always running from place to place."] = "¿Alcista? Bueno, supongo que siempre está corriendo de un lugar a otro.",
        ["Urgh, I hate that guy."] = "Urgh, odio a ese tipo.",
        ["When did you meet him?"] = "¿Cuándo lo conociste?",
        ["Since the city was regrown, he shows up here sometimes. Never stops long."] = "Desde que la ciudad volvió a crecer, él aparece aquí a veces. Nunca se detiene por mucho tiempo.",
        ["Just rushes about the place training, doesn't take the time to just relax and enjoy things."] = "Simplemente corre por el lugar entrenando, no se toma el tiempo para simplemente relajarse y disfrutar las cosas.",
        ["That sounds like Max."] = "Eso suena como Max.",
        ["I tried talking to him the first few times I saw him, but he always just said he was 'doing his dailies' and didn't have time."] = "Intenté hablar con él las primeras veces que lo vi, pero siempre decía que estaba \"haciendo sus diarios\" y que no tenía tiempo.",
        ["There's more to our beautiful city than 'dailies'."] = "En nuestra hermosa ciudad hay más que \"diarios\".",
