    ["Evey"] = {
        ["Uh... Hello there."] = "Eh... Hola.",
        ["What are you doing here?"] = "¿Qué haces aquí?",
        ["Chad said that they needed some help running the celebration this year so I tagged along."] = "Chad dijo que necesitaban ayuda para organizar la celebración este año, así que los acompañé.",
        ["What's going on around you then?"] = "¿Qué sucede entonces a tu alrededor?",
        ["Oh! We're summoning pretty fire spirits using special fire stones."] = "¡Oh! Estamos convocando bonitos espíritus de fuego usando piedras de fuego especiales.",
        ["That sounds like a lot of fun."] = "Eso suena muy divertido.",
        ["*(If the fire stone hasn't been claimed:)*"] = "*(Si la piedra de fuego no ha sido reclamada:)*",
        ["Can I have a go?"] = "¿Puedo intentarlo?",
        ["Here, take this fire stone. You can use it to summon one of the fire spirits you see around us."] = "Toma, toma esta piedra de fuego. Puedes usarlo para convocar a uno de los espíritus de fuego que ves a nuestro alrededor.",
        ["Thanks, I'll make use of this."] = "Gracias, haré uso de esto.",
        ["*(If the fire stone has been claimed:)*"] = "*(Si la piedra de fuego ha sido reclamada:)*",
        ["Have you got any more fire stones?"] = "¿Tienes más piedras de fuego?",
        ["Sorry, I've not got any on me, but I did give some supplies to Alice."] = "Lo siento, no tengo ninguno encima, pero le di algunos suministros a Alice.",
        ["Ok, thanks."] = "Vale, gracias.",
        ["We're going to be celebrating the new year with fire! I'll be summoning some fire spirits to make this place really festive looking."] = "¡Vamos a celebrar el año nuevo con fuego! Convocaré algunos espíritus del fuego para que este lugar tenga un aspecto realmente festivo.",
        ["Come back soon and you'll be able to help out as well!"] = "¡Vuelve pronto y podrás ayudar también!",
        ["The Wintumber Warmer event hasn't started yet."] = "El evento Wintumber Warmer aún no ha comenzado.",
        ["Select an option"] = "Seleccione una opción",
        ["Chad said that they needed some help running the celebration so I tagged along."] = "Chad dijo que necesitaban ayuda para organizar la celebración, así que los acompañé.",
        ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
        ["Summon spirits."] = "Invocar espíritus.",
        ["*(If the warning hasn't been toggled off:)*"] = "*(Si la advertencia no se ha desactivado:)*",
        ["This will give you XP in both Summoning and Firemaking."] = "Esto le dará XP tanto en Summoning como en Firemaking.",
        ["Continue"] = "Continuar",
        ["Continue, and don't show this again"] = "Continuar y no volver a mostrar esto.",
        ["Go back"] = "volver",
        ["*(Dialogue terminates.)*"] = "*(El diálogo termina.)*",
        ["*(If the warning has been toggled off:)*"] = "*(Si la advertencia se ha desactivado:)*",
        ["It's time for me to move on now as the celebration of the new year has ended."] = "Es hora de seguir adelante ahora que la celebración del nuevo año ha terminado.",
        ["Maybe I'll see you again for some other fire related holiday!"] = "¡Quizás nos veamos de nuevo en otras festividades relacionadas con el fuego!",
        ["The Wintumber Warmer event has ended."] = "El evento Wintumber Warmer ha finalizado.",
    },
    ["Evil Bob"] = {
        ["Conversation 1"] = "Conversación 1",
        ["Let me out of here!"] = "¡Déjame salir de aquí!",
        ["I will never let you go, Player!"] = "¡Nunca te dejaré ir, Player!",
        ["Why not?"] = "¿Por qué no?",
        ["Uhm... Because I say so! And, also because I can never have enough servants! Now catch me some fish, I'm hungry."] = "Uhm... ¡Porque yo lo digo! ¡Y también porque nunca tendré suficientes sirvientes! Ahora cógeme un poco de pescado, tengo hambre.",
        ["What fish, where?"] = "¿Qué pez, dónde?",
        ["Talk to my other servants and hurry it up!"] = "¡Habla con mis otros sirvientes y apúrate!",
        ["Conversation 2"] = "Conversación 2",
        ["I will never let you go, [Player Name]!"] = "¡Nunca te dejaré ir, [Player Name]!",
        ["What's it all about?"] = "¿De qué se trata?",
        ["Sit down and I'll tell you. It's a question of servant shortage."] = "Siéntate y te lo cuento. Es una cuestión de escasez de servidores.",
        ["Go on."] = "Continúa.",
        ["You are a skilled worker. A human like you is worth a great deal as a slave."] = "Eres un trabajador calificado. Un humano como tú vale mucho como esclavo.",
        ["A slave? I will have nothing to do with you. Is that clear? Absolutely nothing."] = "¿Un esclavo? No tendré nada que ver contigo. ¿Está eso claro? Absolutamente nada.",
        ["Now, be reasonable, little human. It's just a matter of time before you do everything I ask of you. Play along and this could be a very nice place."] = "Ahora, sé razonable, pequeño humano. Es sólo cuestión de tiempo antes de que hagas todo lo que te pido. Sigue el juego y este podría ser un lugar muy agradable.",
        ["I will not make any deals with you. I'm a human. I will not be pushed, numbered, meowed at, teleported or enslaved. My life is my own."] = "No haré ningún trato contigo. Soy un humano. No seré empujado, numerado, maullado, teletransportado ni esclavizado. Mi vida es mía.",
        ["Is it?"] = "¿Lo es?",
        ["Yes. You won't hold me."] = "Sí. No me abrazarás.",
        ["Won't I? Let me assure you that there's no way out. Just ask my servants."] = "¿No lo haré? Déjame asegurarte que no hay salida. Pregúntale a mis sirvientes.",
        ["Conversation 3"] = "Conversación 3",
        ["How is it possible that you're talking?"] = "¿Cómo es posible que estés hablando?",
        ["How is it possible that you're not meowing?"] = "¿Cómo es posible que no estés maullando?",
        ["Meowing? Why would I be meowing?"] = "¿Maullidos? ¿Por qué estaría maullando?",
        ["Most humans do; that's why I'm wearing this Amulet of Manspeak. I do try to train my staff in civilised speech. Ah, but I suppose things are slightly different in your world. What a dreadful place that must be."] = "La mayoría de los humanos lo hacen; por eso llevo este Amuleto de Manspeak. Intento entrenar a mi staff en un habla civilizada. Ah, pero supongo que las cosas son ligeramente diferentes en tu mundo. Qué lugar tan espantoso debe ser ese.",
        ["I think I'm getting a headache..."] = "Creo que me duele la cabeza...",
        ["Conversation 4"] = "Conversación 4",
        ["What did you do to Bob?"] = "¿Qué le hiciste a Bob?",
        ["Bob? I am Bob! Oh, you mean the Bob in your world? Nothing. I am the incarnation of Bob here on ScapeRune."] = "¿Bob? ¡Soy Bob! Oh, ¿te refieres al Bob en tu mundo? Nada. Soy la encarnación de Bob aquí en ScapeRune.",
        ["What, you mean this is...like some kind of mirror land?"] = "¿Qué? ¿Quieres decir que esto es... como una especie de tierra de espejos?",
        ["Something like that. Somewhere, in ScapeRune, there must be a human servant called Player. But you work just as well for me. Now get to work, human. Fish for me!"] = "Algo así. En algún lugar, en ScapeRune, debe haber un sirviente humano llamado Player. Pero funcionas igual de bien para mí. Ahora ponte a trabajar, humano. ¡Pescado para mí!",
        ["Hi Evil Bob. I'm Player."] = "Hola Evil Bob. Soy Player.",
        ["Ah, a new prisoner!"] = "¡Ah, un nuevo prisionero!",
        ["Not quite. I was hoping to get some blueberries, please."] = "No del todo. Esperaba conseguir algunos arándanos, por favor.",
        ["Hmm. Normally I wouldn't help a human with something they need."] = "Mmm. Normalmente no ayudaría a un humano con algo que necesita.",
        ["But, I am bored. And you did say please."] = "Pero estoy aburrido. Y dijiste por favor.",
        ["You must get me something in return first. Something shiny."] = "Primero debes darme algo a cambio. Algo brillante.",
        ["Something shiny? There's a lot of shiny things."] = "¿Algo brillante? Hay muchas cosas brillantes.",
        ["Not just anything shiny. Something to keep me entertained."] = "No cualquier cosa brillante. Algo que me mantenga entretenido.",
        ["Now, out of my sight."] = "Ahora, fuera de mi vista.",
        ["Evil Bob's eyes glaze over, as he mentally leaves the conversation."] = "Los ojos de Evil Bob se ponen vidriosos mientras mentalmente abandona la conversación.",
        ["Something entertaining for a cat, and shiny. A mouse... A ball of wool, maybe?"] = "Algo entretenido para un gato y brillante. Un ratón... ¿Un ovillo de lana, tal vez?",
        ["Where is my shiny and entertaining item?"] = "¿Dónde está mi artículo brillante y entretenido?",
        ["I don't have it yet."] = "Aún no lo tengo.",
        ["I don't want to see you until you do."] = "No quiero verte hasta que lo hagas.",
        ["I have something shiny for you."] = "Tengo algo brillante para ti.",
        ["Yes? Give it here."] = "¿Sí? Dámelo aquí.",
        ["File:Golden wool.png You place the ball of golden wool down in front of Evil Bob."] = "Archivo:Golden wool.png Colocas el ovillo de lana dorada delante de Evil Bob.",
        ["This is just what I need. Now, off with you."] = "Esto es justo lo que necesito. Ahora, vete contigo.",
        ["Er... Can I have the blueberries now?"] = "Er... ¿Puedo comer los arándanos ahora?",
        ["Ugh. You again. I suppose a deal is a deal."] = "Uf. Tú otra vez. Supongo que un trato es un trato.",
        ["Evil Bob beckons his servant forward."] = "Evil Bob hace una seña a su sirviente para que se acerque.",
        ["Here you go. Homegrown by the prisoners!"] = "Aquí tienes. ¡Cosecha propia de los prisioneros!",
        ["File:Blueberries.png Evil Bob's servant hands you some blueberries."] = "Archivo:Blueberries.png El sirviente de Evil Bob te entrega algunos arándanos.",
        ["Thanks. I think."] = "Gracias. Creo.",
        ["Get me some fish for my supper, slave."] = "Tráeme algo de pescado para la cena, esclavo.",
        ["I lost the blueberries. Can I have some more?"] = "Perdí los arándanos. ¿Puedo tener un poco más?",
        ["I'm not a charity. I'm evil! Bring me more golden wool and you can have more blueberries."] = "No soy una organización benéfica. ¡Soy malvado! Tráeme más lana dorada y podrás tener más arándanos.",
        ["Here you go."] = "Aquí tienes.",
        ["Evil Bob servant takes the golden wool from you, and gives you some more blueberries."] = "El sirviente de Evil Bob te quita la lana dorada y te da más arándanos.",
    },
    ["Evil Chicken"] = {
        ["*The Evil Chicken yelled the following while attacking:*"] = "*El Evil Chicken gritó lo siguiente mientras atacaba:*",
        ["*When he appeared underwater, the phrases were different:*"] = "*Cuando apareció bajo el agua, las frases fueron diferentes:*",
    },
    ["Evil Dave"] = {
        ["Welcome to my BASEMENT OF DOOM!"] = "¡Bienvenido a mi SÓTANO DE DOOM!",
        ["Select an Option"] = "Selecciona una opción",
        ["Evil Dave's Big Day Out'."] = "El gran día libre de Evil Dave\".",
        ["General chat."] = "Charla general.",
        ["Nice basement!"] = "¡Bonito sótano!",
        ["Nice?!"] = "¡¿Bien?!",
        ["I mean, evil!"] = "Quiero decir, ¡malvado!",
        ["Yeah! I'm going to use it to summon DEMONS to DO MY BIDDING, Or raise an ARMY OF THE UNDEAD! And then I'm going to totally, like, take over the world!"] = "¡Sí! ¡Voy a usarlo para convocar DEMONIOS para CUMPLIR MIS ORDENES, o formar un EJÉRCITO DE NO MUERTOS! ¡Y luego voy a conquistar el mundo por completo!",
        ["Ah-ha-ha-ha-ha-haa!"] = "¡Ah-ja-ja-ja-ja-ja!",
        ["So have you had any luck with the demon-summoning?"] = "Entonces, ¿has tenido suerte con la invocación de demonios?",
        ["Well, I thought I should start small, so I asked Wizard Grayzag for some help with summoning imps..."] = "Bueno, pensé que debería empezar poco a poco, así que le pedí ayuda a Wizard Grayzag para invocar diablillos...",
        ["And did you manage to summon any?"] = "¿Y lograste convocar a alguno?",
        ["Well, not imps, exactly. It turns out they're not the lowest form of demon after all. I got these hell-rats."] = "Bueno, diablillos no, exactamente. Resulta que, después de todo, no son la forma más baja de demonio. Tengo estas ratas infernales.",
        ["They're hardly evil at all! They're just like regular rats only they smell vaguely of sulphur!"] = "¡No son nada malvados! ¡Son como ratas normales, sólo que huelen vagamente a azufre!",
        ["Weren't you going to give up evil?"] = "¿No ibas a renunciar al mal?",
        ["See you later."] = "Hasta luego.",
        ["See you later!"] = "¡Hasta luego!",
        ["Of course you will return! There is no escape from my DARK POWER!"] = "¡Por supuesto que volverás! ¡No hay escapatoria de mi PODER OSCURO!",
        ["If my ARMY OF DARKNESS doesn't get you first!"] = "¡Si mi EJÉRCITO DE LA OSCURIDAD no te atrapa primero!",
        ["If you can find your way out of my BASEMENT OF DOOM!"] = "¡Si puedes encontrar la salida de mi SÓTANO DE DOOM!",
        ["Yeah, well..."] = "Sí, bueno...",
        ["I did try. I wore this bright red jumper and I got up in the morning and spent the day outside in the sunshine..."] = "Lo intenté. Me puse este jersey rojo brillante, me levanté por la mañana y pasé el día afuera bajo el sol...",
        ["*Dave shudders*"] = "*Dave se estremece*",
        ["But I couldn't keep it up. I just didn't find anything good very interesting, you know?"] = "Pero no pude seguir así. Simplemente no encontré nada bueno ni muy interesante, ¿sabes?",
        ["Sometimes I worry about the consequences of evil. I don't really want anyone to get hurt, not like what happened with Denath."] = "A veces me preocupo por las consecuencias del mal. Realmente no quiero que nadie salga lastimado, no como lo que pasó con Denath.",
        ["But I can't not be evil! It's just who I am!"] = "¡Pero no puedo no ser malvado! ¡Es simplemente lo que soy!",
        ["Let me try to explain the time travel thing again..."] = "Déjame intentar explicarte lo del viaje en el tiempo otra vez...",
        ["Although you're here, you're also still in the time freeze."] = "Aunque estás aquí, también estás congelado en el tiempo.",
        ["What?"] = "¿Qué?",
        ["I mean, the whole room was frozen in time at the moment the culinomancer cast his spell, right?"] = "Quiero decir, toda la habitación quedó congelada en el tiempo en el momento en que el culinomante lanzó su hechizo, ¿verdad?",
        ["What? I didn't notice anything."] = "¿Qué? No noté nada.",
        ["Of course you didn't! You were frozen!"] = "¡Por supuesto que no! ¡Estabas congelado!",
        ["So how can I be there and also here? Which one is me?"] = "Entonces, ¿cómo puedo estar allí y también aquí? ¿Cuál soy yo?",
        ["I mean, I feel like I'm me, but what if I'm not me?"] = "Quiero decir, siento que soy yo, pero ¿y si no soy yo?",
        ["That would be terrible!"] = "¡Eso sería terrible!",
        ["They're both you!"] = "¡Ambos sois vosotros!",
        ["How does that work?"] = "¿Cómo funciona eso?",
        ["From YOUR point of view I've saved you, but from MINE I haven't."] = "Desde TU punto de vista te he salvado, pero desde el MÍO no.",
        ["Well that's all right, as long as I'm saved from my point of view!"] = "¡Bueno, está bien, siempre y cuando esté salvo desde mi punto de vista!",
        ["But I have to save you, otherwise you won't be saved!"] = "¡Pero tengo que salvarte, de lo contrario no serás salvo!",
        ["But I'm here so you must already have saved me!"] = "¡Pero estoy aquí, así que ya debes haberme salvado!",
        ["That's what I meant, from your point of view I've saved you but from mine I haven't!"] = "Eso es lo que quise decir, desde tu punto de vista te he salvado pero desde el mío no.",
        ["I've got to take the food back in time to give it to you."] = "Tengo que llevar la comida al pasado para dártela.",
        ["I've to take the food back in time to give it to you."] = "Tengo que llevar la comida al pasado para dártela.",
        ["Why?"] = "¿Por qué?",
        ["Because otherwise you won't be saved from the culinomancer's spell."] = "Porque de lo contrario no te salvarás del hechizo del culinomante.",
        ["But I was saved from the spell! I remember it!"] = "¡Pero me salvé del hechizo! ¡Lo recuerdo!",
        ["Exactly! That's why I know I have to go back and save you!"] = "¡Exactamente! ¡Por eso sé que tengo que regresar y salvarte!",
        ["What will happen if you don't?"] = "¿Qué pasará si no lo haces?",
        ["I can't not, I already have!"] = "¡No puedo no, ya lo hice!",
        ["I can't not, because I already have!"] = "¡No puedo no, porque ya lo hice!",
        ["The fact that you're here means I already did save you, which means that you have to tell me the correct recipe. It's logically impossible for you not to!"] = "El hecho de que estés aquí significa que ya te salvé, lo que significa que tienes que decirme la receta correcta. ¡Es lógicamente imposible que no lo hagas!",
        ["I don't understand this at all."] = "No entiendo esto en absoluto.",
        ["There will be a temporal paradox and the universe will implode!"] = "¡Habrá una paradoja temporal y el universo implosionará!",
        ["Oh no! That would be bad, and not even in an evil way!"] = "¡Oh, no! ¡Eso sería malo, y ni siquiera de forma perversa!",
        ["Exactly! So you've got to tell me the recipe!"] = "¡Exactamente! ¡Así que tienes que contarme la receta!",
        ["But I still don't understand why you need the recipe when you've already saved me!"] = "¡Pero todavía no entiendo por qué necesitas la receta cuando ya me has salvado!",
        ["I don't know."] = "No lo sé.",
        ["That's not very helpful. I don't even understand why you need the recipe anyway."] = "Eso no es de mucha ayuda. De todos modos, ni siquiera entiendo por qué necesitas la receta.",
        ["You've got to tell me because the magic requires it!"] = "¡Tienes que decírmelo porque la magia lo requiere!",
        ["That's what you said before! Honestly, why make it more complicated than it needs to be?"] = "¡Eso es lo que dijiste antes! Honestamente, ¿por qué hacerlo más complicado de lo necesario?",
        ["Oh, never mind."] = "Oh, no importa.",
        ["Choose an option:"] = "Elige una opción:",
        ["Hello Dav-uh Doris?"] = "Hola Dav-uh Doris?",
        ["Look who it is, The Troublemaker."] = "Mira quién es, El Alborotador.",
        ["How are you finding being Dave?"] = "¿Qué te parece ser Dave?",
        ["At first I thought this could be catharsis. I could be the Dave that he never was. I could show him how much better of a Dave I was than him. But soon, it became obvious to me. I could make Dave a better person. I could show Dave what it was like to be Dave. I could make Dave pay."] = "Al principio pensé que esto podría ser una catarsis. Podría ser el Dave que nunca fue. Podría mostrarle que yo era mucho mejor Dave que él. Pero pronto me resultó obvio. Podría hacer de Dave una mejor persona. Podría mostrarle a Dave cómo era ser Dave. Podría hacer que Dave pagara.",
        ["How did that work out for you?"] = "¿Cómo te resultó?",
        ["He doesn't care. He just loves being me. But I learned something. Now I know why Dave wants be evil. Any manner of COLD REPRIEVE is preferable to living out such a MEANINGLESS EXISTENCE."] = "A él no le importa. Le encanta ser yo. Pero aprendí algo. Ahora sé por qué Dave quiere ser malvado. Cualquier forma de RESPUERTO FRÍO es preferible a vivir una EXISTENCIA SIN SENTIDO.",
        ["Um, I'm going to go. Catch you later?"] = "Mmm, me voy. ¿Te veo más tarde?",
        ["GOODBYE DEARIE. GOODBYE."] = "ADIÓS QUERIDA. ADIÓS.",
    },
    ["Evil Goatee"] = {
        ["Oh, I didn't know that!"] = "¡Oh, no lo sabía!",
        ["Baah. Baaah bah ba-baaah. Bah baaaah baaah. Baaaah."] = "Baah. Baaah bah ba-baaah. Bah baaaah baaah. Baaaa.",
        ["*(If big sprout is winning:)*"] = "*(Si el gran brote está ganando:)*",
        ["So evil Niya's sprouts are losing the fight?"] = "¿Entonces los brotes de evil Niya están perdiendo la pelea?",
        ["*(If big zombie sprout is winning:)*"] = "*(Si el gran zombie sprout gana :)*",
        ["Can you remind me how to help you again?"] = "¿Puedes recordarme cómo ayudarte nuevamente?",
        ["So I can promote or corrupt the growth of the bigger sprouts to help them win their fights?"] = "¿Entonces puedo promover o corromper el crecimiento de los brotes más grandes para ayudarlos a ganar sus peleas?",
        ["And if I help out enough with a sister they'll reward me with a set of wings?"] = "¿Y si ayudo lo suficiente con una hermana me recompensarán con un par de alas?",
        ["Goodbye, I guess."] = "Adiós, supongo.",
        ["*(Dialogue terminates.)*"] = "*(El diálogo termina.)*",
        ["Goodbye"] = "Adiós",
        ["*(If the daily fatigue is capped:)*"] = "*(Si la fatiga diaria tiene un límite:)*",
        ["So if had some of Alice's magic plant sprays I would be able to help out more today?"] = "Entonces, si tuviera algunos de los aerosoles de plantas mágicas de Alice, ¿podría ayudar más hoy?",
    },
    ["Evil Niya"] = {
        ["*(First time:)*"] = "*(Primera vez:)*",
        ["*(Subsequent times:)*"] = "*(Tiempos posteriores:)*",
        ["My sisters sprouts are destroying mine! Do something about it!"] = "¡Los brotes de mis hermanas están destruyendo los míos! ¡Haz algo al respecto!",
        ["I have to admit that you've helped me out somewhat more than my sister so far. Make sure it stays that way."] = "Tengo que admitir que hasta ahora me has ayudado un poco más que mi hermana. Asegúrate de que siga así.",
        ["You've helped my sister far too much for my liking, I should do something about you when I have time..."] = "Has ayudado demasiado a mi hermana para mi gusto, debería hacer algo contigo cuando tenga tiempo...",
        ["Can you remind me how to help you again?"] = "¿Puedes recordarme cómo ayudarte nuevamente?",
        ["Goodbye"] = "Adiós",
        ["If only you had some of Alice's magic plant sprays you would be able to help me more today, come back again tomorrow!"] = "Si tan solo tuvieras algunos de los aerosoles de plantas mágicas de Alice, podrías ayudarme más hoy. ¡Vuelve mañana!",
        ["If you know what's good for you, you can help by using your knowledge of herblore to further corrupt the bigger sprouts."] = "Si sabes lo que es bueno para ti, puedes ayudar usando tu conocimiento de la hierba para corromper aún más los brotes más grandes.",
        ["And if you were to help enough I could reward you with one of my older sproouts that I brought back from the dead. They might be strong enough to act as a set of wings."] = "Y si ayudaras lo suficiente, podría recompensarte con uno de mis brotes más viejos que traje de entre los muertos. Podrían ser lo suficientemente fuertes como para actuar como un par de alas.",
        ["If you help me out I could reward you with wings instead!"] = "¡Si me ayudas, podría recompensarte con alas!",
        ["Whatever you do, DON'T promote their growth! That's exactly what my sister wants."] = "Hagas lo que hagas, ¡NO promuevas su crecimiento! Eso es exactamente lo que mi hermana quiere.",
        ["The fighting isn't limited to just here, if you can locate the other sprouts you might find it more rewarding to corrupt the growth there instead."] = "La lucha no se limita solo aquí; si puedes localizar los otros brotes, puede que te resulte más gratificante corromper el crecimiento allí.",
        ["Don't mind my sister, she gets into such a tiff when things don't go her way."] = "No te preocupes por mi hermana, ella se pelea mucho cuando las cosas no salen como ella quiere.",
        ["We'll see about that!"] = "¡Ya veremos!",
        ["Without some magic plant sprays there is only so much you can do a day to help."] = "Sin algunos aerosoles mágicos para plantas, hay mucho que puedes hacer al día para ayudar.",
        ["If you can get your hands on Alice's chests you might be able to find some of those magic plant sprays laying around."] = "Si puedes conseguir los cofres de Alice, es posible que puedas encontrar algunos de esos aerosoles de plantas mágicas por ahí.",
        ["Start corrupting those sprouts!"] = "¡Empieza a corromper esos brotes!",
        ["Oh I can't wait to see the look on my sister's face when she realises that all her precious sprouts are nearly destroyed, just the ones left here."] = "Oh, no puedo esperar a ver la expresión del rostro de mi hermana cuando se dé cuenta de que todos sus preciosos brotes están casi destruidos, solo los que quedan aquí.",
        ["Arise! Rise from the ground and spread yourself throughout Gielinor!"] = "¡Levántate! ¡Levántate del suelo y extiéndete por Gielinor!",
        ["Get a move on and start corrupting the big sprouts,"] = "Muévete y empieza a corromper los grandes brotes.",
        ["I love the smell of burning wood in the morning."] = "Me encanta el olor a madera quemada por la mañana.",
        ["Move it or become kindling!"] = "¡Muévelo o conviértete en leña!",
        ["Shut up Niya!"] = "¡Cállate Niya!",
        ["Start cheering on my small sprouts, or else!"] = "¡Empiece a animar a mis pequeños brotes, o si no!",
    },
    ["Examiner"] = {
        ["Hello there! My colleague tells me you helped to uncover a hidden altar to the god Zaros."] = "¡Hola! Mi colega me dice que ayudaste a descubrir un altar oculto al dios Zaros.",
        ["A great scholar and archaeologist indeed! Good health and prosperity to you."] = "¡Un gran erudito y arqueólogo! Buena salud y prosperidad para ti.",
        ["Select an Option"] = "Selecciona una opción",
        ["Thanks."] = "Gracias.",
        ["Thanks!"] = "¡Gracias!",
        ["I have lost my trowel."] = "He perdido mi paleta.",
        ["Deary me. That was a good one as well. It's a good job I have another. Here you go..."] = "Querido amigo. Esa también fue buena. Es un buen trabajo, tengo otro. Aquí tienes...",
        ["Really? Look in your backpack and make sure first."] = "¿En serio? Mira en tu backpack y asegúrate primero.",
        ["Hi! Please complete this."] = "¡Hola! Por favor complete esto.",
        ["[The examiner has given you a puzzle box!]"] = "[¡El examinador te ha dado una caja de rompecabezas!]",
        ["I'm afraid that you have not finished the puzzle."] = "Me temo que no has terminado el rompecabezas.",
        ["[The examiner has given you another clue scroll!]"] = "[¡El examinador te ha dado otro pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
        ["Correct! Well done!"] = "¡Correcto! ¡Bien hecho!",
        ["Right! Time for your exam."] = "¡Correcto! Hora de tu examen.",
        ["But I haven't studied! I'm not prepared!"] = "¡Pero no he estudiado! ¡No estoy preparado!",
        ["Aha! I am, of course, joking. Here, we learn by doing."] = "¡Ajá! Por supuesto, estoy bromeando. Aquí aprendemos haciendo.",
        ["You Dig?"] = "¿Excavas?",
        ["Talk to an examiner at the Varrock Dig Site's Exam Centre."] = "Hable con un examinador en el centro de exámenes del sitio de excavación Varrock.",
        ["So grab a mattock and get stuck in!"] = "¡Así que toma un azadón y quédate atrapado!",
        ["Looks like I've completed everything. I'd better go and see Hans about that reward!"] = "Parece que he completado todo. ¡Será mejor que vaya a ver a Hans sobre esa recompensa!",
    },
    ["Excited knight"] = {
        ["Hello there!"] = "¡Hola!",
        ["You seem very happy. What's happened?"] = "Pareces muy feliz. ¿Qué ha pasado?",
        ["Saradomin has returned! Soon I shall return to the battle to fight for his glory against evil!"] = "¡Saradomin ha regresado! ¡Pronto regresaré a la batalla para luchar por su gloria contra el mal!",
        ["How did that happen?"] = "¿Cómo sucedió eso?",
        ["Did you see the portal that appeared in Lumbridge?"] = "¿Viste el portal que apareció en Lumbridge?",
        ["Not long ago it finally opened, and through it the evil Zamorak entered the world!"] = "¡No hace mucho que finalmente se abrió y a través de él el malvado Zamorak entró al mundo!",
        ["It's a good thing Saradomin was here to save us."] = "Es bueno que Saradomin estuviera aquí para salvarnos.",
        ["Immediately, they were locked in battle that we mere mortals would struggle to understand."] = "Inmediatamente, se vieron envueltos en una batalla que a nosotros, simples mortales, nos costaría entender.",
        ["Soon, Saradomin's Icyene general came through, and requested that we all aid Saradomin in battle against Zamorak."] = "Pronto, el general Icyene de Saradomin llegó y nos pidió que todos ayudáramos a Saradomin en la batalla contra Zamorak.",
        ["As a White Knight, I must join the battle and aid my lord!"] = "¡Como Caballero Blanco, debo unirme a la batalla y ayudar a mi señor!",
        ["What battle is this?"] = "¿Qué batalla es esta?",
        ["What does Saradomin need?"] = "¿Qué necesita Saradomin?",
        ["Saradomin has called upon everyone to help. And it's not all fighting!"] = "Saradomin ha pedido ayuda a todos. ¡Y no todo es pelear!",
        ["In order to gather power to defeat Zamorak, he needs people to gather Divine Tears, both on and off the battlefield."] = "Para reunir poder para derrotar a Zamorak, necesita personas para recolectar Lágrimas Divinas, tanto dentro como fuera del campo de batalla.",
        ["You should join up too! You can find the recruiter in the camp to the north of the battlefield."] = "¡Tú también deberías unirte! Puedes encontrar al reclutador en el campamento al norte del campo de batalla.",
        ["I am going soon. Although I work only for the glory of Saradomin, I know there will be great rewards for those who help."] = "Me iré pronto. Aunque trabajo sólo para la gloria de Saradomin, sé que habrá grandes recompensas para quienes ayuden.",
        ["How did that start?"] = "¿Cómo empezó eso?",
        ["What about Zamorak?"] = "¿Qué pasa con Zamorak?",
        ["Oh, I see."] = "Oh, ya veo.",
        ["Evil Zamorak fights against our lord on the battlefield."] = "El malvado Zamorak lucha contra nuestro señor en el campo de batalla.",
        ["His minions are numerous, and they are seeking the power that rightfully belongs to Saradomin."] = "Sus secuaces son numerosos y buscan el poder que por derecho pertenece a Saradomin.",
        ["I can hardly believe this, but there are people joining Zamorak too!"] = "¡No puedo creerlo, pero también hay gente que se une a Zamorak!",
        ["They are recruiting both fighters and skilled workers, and some are actually joining with his evil minions!"] = "¡Están reclutando luchadores y trabajadores calificados, y algunos de hecho se están uniendo a sus malvados secuaces!",
        ["I would keep away from the camp to the south of the battlefield - that's where the evil ones are found."] = "Me mantendría alejado del campamento al sur del campo de batalla; ahí es donde se encuentran los malvados.",
        ["How did that start"] = "¿Cómo empezó eso?",
        ["Where is this battlefield?"] = "¿Dónde está este campo de batalla?",
        ["So I could join Zamorak?"] = "¿Entonces podría unirme a Zamorak?",
        ["You could, but I cannot believe that you would join with Zamorak."] = "Podrías, pero no puedo creer que te unieras a Zamorak.",
        ["He may promise you rewards, but at what cost? And can you trust him?"] = "Puede que te prometa recompensas, pero ¿a qué precio? ¿Y puedes confiar en él?",
        ["No. I would keep away from the camp to the south of the battlefield."] = "No. Me mantendría alejado del campamento al sur del campo de batalla.",
        ["How did the battle start?"] = "¿Cómo empezó la batalla?",
        ["The Battle of Lumbridge is a titanic struggle between two gods!"] = "¡La Batalla de Lumbridge es una lucha titánica entre dos dioses!",
        ["The great Saradomin and his followers are fighting the evil Zamorak and his demons!"] = "¡El gran Saradomin y sus seguidores están luchando contra el malvado Zamorak y sus demonios!",
        ["I'm going there as soon as I can. As a White Knight, it is my duty!"] = "Iré allí tan pronto como pueda. ¡Como Caballero Blanco, es mi deber!",
        ["How did that happen"] = "¿Cómo sucedió eso?",
        ["Where is the battlefield?"] = "¿Dónde está el campo de batalla?",
        ["The battlefield is between Lumbridge and Draynor, immediately to the west of Lumbridge Castle."] = "El campo de batalla está entre Lumbridge y Draynor, inmediatamente al oeste del Castillo Lumbridge.",
        ["You'll find the recruiter to the north of the battlefield. Talk to the recruiter there to join with us!"] = "Encontrarás al reclutador al norte del campo de batalla. ¡Habla con el reclutador allí para unirte a nosotros!",
        ["But keep away from the camp to the south. There they are recruiting people to join Zamorak."] = "Pero mantente alejado del campamento del sur. Allí están reclutando personas para unirse a Zamorak.",
        ["How did the battle start"] = "¿Cómo empezó la batalla?",
        ["May Saradomin be with you!"] = "¡Que Saradomin esté contigo!",
    },
    ["Explorer Jack"] = {
        ["Now, do you have a question about the Task System? Or perhaps I know of a quest that might interest you."] = "Ahora, ¿tiene alguna pregunta sobre el sistema de tareas? O tal vez conozco una misión que podría interesarte.",
        ["What do you wish to say?"] = "¿Qué deseas decir?",
        ["I'd like to ask about achievements and task rewards."] = "Me gustaría preguntar sobre los logros y las recompensas de las tareas.",
        ["You mentioned a quest?"] = "¿Mencionaste una misión?",
        ["I did, I did! So, you're interested? Spiffing! I can see the exploring fibre in you!"] = "¡Lo hice, lo hice! Entonces, ¿estás interesado? ¡Escupiendo! ¡Puedo ver la fibra exploradora en ti!",
        ["Er..."] = "Eh...",
        ["Oh, that exploring flames in your eyes! Just like me in my younger days - eager to discover and take on new challenges, eh?"] = "¡Oh, esas llamas exploradoras en tus ojos! Como yo en mi juventud: ansioso por descubrir y asumir nuevos desafíos, ¿eh?",
        ["Um... so you're going to give me a quest?"] = "Um... ¿entonces me vas a dar una misión?",
        ["A quest? But indeed! A tale of riches is what you need, what?"] = "¿Una misión? ¡Pero efectivamente! Una historia de riquezas es lo que necesitas, ¿qué?",
        ["Is it?"] = "¿Lo es?",
        ["Yes, and I have just the thing. A snow imp wandered through my door one day and I, curious about foreign lands, as every good explorer should be, asked him for tales of his homeland."] = "Sí, y tengo justo lo que necesitas. Un día, un diablillo de las nieves entró por mi puerta y yo, curioso por las tierras extranjeras, como debe ser todo buen explorador, le pedí historias de su tierra natal.",
        ["Nothing."] = "Nada.",
        ["So, how can I help you?"] = "Entonces, ¿en qué puedo ayudarte?",
        ["About Myths of the White Lands..."] = "Sobre Mitos de las Tierras Blancas...",
        ["I think I've finished all of the Beginner Tasks in the Lumbridge set."] = "Creo que terminé todas las tareas para principiantes del conjunto Lumbridge.",
        ["You have? Oh, well done! We'll make an explorer of you yet."] = "¿Tienes? ¡Ah, bien hecho! Todavía haremos de ti un explorador.",
        ["Thank you. Is there a reward?"] = "Gracias. ¿Hay una recompensa?",
        ["Ah, yes indeed."] = "Ah, sí, claro.",
        ["Having completed the beginner tasks, you have been granted the ability to use the Explorer emote to show to your friends."] = "Después de completar las tareas para principiantes, se te ha otorgado la posibilidad de usar el gesto Explorer para mostrárselo a tus amigos.",
        ["I have also given you an explorer's ring. Now, this is more than just any old ring. Aside from looking good, it also has magical properties giving you a small but useful boost to your Magic and Prayer."] = "También te he regalado un anillo de explorador. Ahora, esto es más que cualquier anillo viejo. Además de verse bien, también tiene propiedades mágicas que le brindan un pequeño pero útil impulso a su Magic y Prayer.",
        ["Your ring has the ability to restore some of your run energy for you."] = "Tu anillo tiene la capacidad de restaurar parte de tu energía de carrera.",
        ["For each of the first three sections of the diary you complete, your ring will gain an extra charge, so the ring you receive from the medium level tasks will have 3 charges for example."] = "Por cada una de las tres primeras secciones del diario que completes, tu anillo obtendrá una carga adicional, por lo que el anillo que recibas de las tareas de nivel medio tendrá 3 cargas, por ejemplo.",
        ["If they should run out, the ring is recharged by the sun each day, so you will be able to use it again tomorrow and so on."] = "Si se agotan, el anillo se recarga con el sol cada día, por lo que podrás volver a usarlo mañana y así sucesivamente.",
        ["As an extra reward, you can have this old magical lamp to help with your skills. I was going to use it myself, but I don't really need it."] = "Como recompensa adicional, puedes tener esta antigua lámpara mágica para ayudarte con tus habilidades. Iba a usarlo yo mismo, pero realmente no lo necesito.",
        ["Thanks very much."] = "Muchas gracias.",
        ["If you should lose your ring, come back to see me and I'm sure I'll have another. Now, did you have anything further to ask?"] = "Si pierdes tu anillo, vuelve a verme y seguro que tendré otro. Ahora, ¿tenías algo más que preguntar?",
        ["What ho, there! How's that ring working out for you?"] = "¡Qué carajo! ¿Cómo te va ese anillo?",
        ["I lost it."] = "Lo perdí.",
        ["Lost it, eh? Well, I have another one here that you can have. Try not to lose this one; it doesn't do for explorers like us to go losing things, what?"] = "Lo perdiste, ¿eh? Bueno, tengo otro aquí que puedes tener. Intenta no perder este; No sirve que exploradores como nosotros vayamos perdiendo cosas, ¿qué?",
        ["Tell me about the Achievement System."] = "Háblame del Sistema de Logros.",
        ["Well, the Achievement System is a method of guiding yourself while you explore the world."] = "Bueno, el Sistema de Logros es un método para guiarte mientras exploras el mundo.",
        ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from me."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de mi parte.",
        ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area that they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
        ["Choose an option:"] = "Elige una opción:",
        ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
        ["For completing the Lumbridge and Draynor set, you are presented with an explorer's ring."] = "Por completar el conjunto Lumbridge y Draynor, se te presenta un anillo de explorador.",
        ["This ring will become increasingly useful with each difficultly level of the set that you complete."] = "Este anillo será cada vez más útil con cada nivel de dificultad del conjunto que completes.",
        ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
        ["You may also see what rewards a set item provides by hovering over the Rewards icon for its Exploration Achievement set in the Achievements interface."] = "También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de Recompensas de su Logro de exploración establecido en la interfaz de Logros.",
        ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
        ["You need to complete all of the Tasks in the set of a particular difficulty, then you can claim your reward. Most of the Lumbridge set's Tasks are straightforward, although you might find some require quests to be started, if not finished."] = "Debes completar todas las tareas del conjunto de una dificultad particular y luego podrás reclamar tu recompensa. La mayoría de las tareas del conjunto Lumbridge son sencillas, aunque es posible que algunas requieran que se inicien, si no se terminan.",
        ["To claim the Lumbridge set reward, speak to Bob in Bob's Axes in Lumbridge, Ned in Draynor Village, or myself."] = "Para reclamar la recompensa del conjunto Lumbridge, habla con Bob en Bob's Axes en Lumbridge, Ned en Draynor Village o conmigo mismo.",
        ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
        ["Can I claim any rewards from you?"] = "¿Puedo reclamar alguna recompensa de usted?",
        ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
        ["Explorer's ring 1"] = "Anillo del explorador 1",
        ["Explorer's ring 1? Yes, but I'm afraid it would cost you 500 coins."] = "¿Anillo 1 del explorador? Sí, pero me temo que te costaría 500 coins.",
        ["Purchase another for 500 coins?"] = "¿Comprar otro por 500 coins?",
        ["Yes"] = "si",
        ["[You're handed another Explorer's ring 1.]"] = "[Te entregan el anillo de otro Explorador 1.]",
        ["No thanks."] = "No, gracias.",
        ["Explorer's ring 2"] = "Anillo del explorador 2",
        ["Explorer's ring 2? Yes, but I'm afraid it would cost you 1,000 coins."] = "¿Anillo del explorador 2? Sí, pero me temo que te costaría 1.000 coins.",
        ["Purchase another for 1,000 coins?"] = "¿Comprar otro por 1.000 coins?",
        ["[You're handed another Explorer's ring 2.]"] = "[Te entregan el anillo de otro Explorador 2.]",
        ["Explorer's ring 3"] = "Anillo del explorador 3",
        ["Explorer's ring 3? Yes, but I'm afraid it would cost you 2,000 coins."] = "¿Anillo del explorador 3? Sí, pero me temo que te costaría 2000 coins.",
        ["Purchase another for 2,000 coins?"] = "¿Comprar otro por 2000 coins?",
        ["[You're handed another Explorer's ring 3.]"] = "[Te entregan el anillo de otro Explorador 3.]",
        ["Explorer's ring 4"] = "Anillo del explorador 4",
        ["Explorer's ring 4? Yes, but I'm afraid it would cost you 10,000 coins."] = "¿Anillo del explorador 4? Sí, pero me temo que te costaría 10.000 coins.",
        ["Purchase another for 10,000 coins?"] = "¿Comprar otro por 10.000 coins?",
        ["[You're handed another Explorer's ring 4.]"] = "[Te entregan el anillo de otro Explorador 4.]",
        ["Sorry, you're not owed any achievement rewards at the moment. Look at your Achievement System for things to do to earn more."] = "Lo sentimos, no se te debe ninguna recompensa por logros en este momento. Mire su sistema de logros para saber qué hacer para ganar más.",
        ["I'll just fill your inventory with what you need, then."] = "Entonces llenaré tu inventario con lo que necesitas.",
        ["There you go. You didn't have enough space for everything you're owed, so I've held on to the rest."] = "Ahí lo tienes. No tenías suficiente espacio para todo lo que te debían, así que me quedé con el resto.",
        ["There you go."] = "Ahí lo tienes.",
        ["Eh, I haven't made any progress with the stones. Please come back later."] = "Eh, no he avanzado nada con las piedras. Por favor vuelve más tarde.",
        ["I let those stones thaw, making a very smelly discovery."] = "Dejé que esas piedras se descongelaran, haciendo un descubrimiento muy maloliente.",
        ["I'm sorry."] = "Lo siento.",
        ["You knew about it?"] = "¿Lo sabías?",
        ["I did. When I exited the cave with the 'stones' I met some snow imps, who let me into a secret. This whole quest was a prank on you, as they judged you nosy, greedy and annoying. It was meant to teach you a lesson. They didn't leave me much choice but to complete their plan."] = "Lo hice. Cuando salí de la cueva con las 'piedras' me encontré con unos diablillos de nieve, que me contaron un secreto. Toda esta búsqueda fue una broma para ti, ya que te consideraron entrometido, codicioso y molesto. Estaba destinado a enseñarte una lección. No me dejaron mucha opción más que completar su plan.",
        ["Haha, that's a good one, chum! I suppose I deserve it. Nosy, haha!"] = "Jaja, ¡esa es buena, amigo! Supongo que lo merezco. Entrometido, jaja!",
        ["Glad to see you're taking it lightly."] = "Me alegra ver que te lo estás tomando a la ligera.",
        ["Eh, I've got good news! While you were gone, I managed to sell them to a wandering witch for a goodly sum. She identified it as yeti dung, and said it was a key ingredient in some very advanced ancient potions."] = "¡Eh, tengo buenas noticias! Mientras no estabas, logré vendérselos a una bruja errante por una buena suma. Lo identificó como estiércol de yeti y dijo que era un ingrediente clave en algunas pociones antiguas muy avanzadas.",
        ["Really?"] = "¿En serio?",
        ["Yes indeed! I've kept some of the money for you. There you go."] = "¡Sí, claro! He guardado parte del dinero para ti. Ahí tienes.",
        ["Thank you!"] = "¡Gracias!",
        ["I've been to that ice cave the snow imp mentioned. Sliding is great fun! You should go back there sometime."] = "He estado en esa cueva de hielo que mencionó el diablillo de las nieves. ¡Deslizarse es muy divertido! Deberías volver allí alguna vez.",
        ["Oh and I made a fascinating discovery! in some places, there are paintings on the walls that appear to have been made by a primitive civilisation."] = "¡Ah, y hice un descubrimiento fascinante! en algunos lugares hay pinturas en las paredes que parecen haber sido realizadas por una civilización primitiva.",
        ["I know the ones you mean. They're how I figured how to defeat the yeti. I also found more in the other rooms."] = "Sé a quién te refieres. Así es como descubrí cómo derrotar al yeti. También encontré más en las otras habitaciones.",
        ["Ha, but there are some other ones! I could see some behind roots and things. Do go and have a look sometime."] = "¡Ja, pero hay otros! Pude ver algo detrás de las raíces y esas cosas. Ve y echa un vistazo alguna vez.",
        ["From the sound of it, there's one you haven't seen."] = "Por lo que parece, hay uno que no has visto.",
        ["Stupendous! Look what Foreman George and his team of builders have done! This house is perfect!"] = "¡Estupendo! ¡Mira lo que han hecho Foreman George y su equipo de constructores! ¡Esta casa es perfecta!",
        ["I just need to get a carpet and a few decorations and those months of sleeping rough in the ruins of my house will become a distant memory."] = "Sólo necesito una alfombra y algunas decoraciones y esos meses de dormir a la intemperie en las ruinas de mi casa se convertirán en un recuerdo lejano.",
        ["Since the battle between Saradomin and Zamorak started, my house has been a complete wreck!"] = "Desde que comenzó la batalla entre Saradomin y Zamorak, ¡mi casa ha sido un completo desastre!",
        ["But Foreman George and his team are on the case now. I can't wait to see what they do to it."] = "Pero Foreman George y su equipo ahora están en el caso. No puedo esperar a ver qué le hacen.",
        ["One thing's for sure: it can't be any worse than the ruin the battle left me with!"] = "Una cosa es segura: ¡no puede ser peor que la ruina que me dejó la batalla!",
        ["My house! There I was, sat in the living room, having a nice cup of tea and minding my own business, and BANG! My house collapses around me!"] = "¡Mi casa! Allí estaba yo, sentado en la sala de estar, tomando una buena taza de té y ocupándome de mis propios asuntos, y ¡BANG! ¡Mi casa se derrumba a mi alrededor!",
        ["I went to look - after all I am an explorer - and there, right outside my house, I found Saradomin and Zamorak fighting it out!"] = "Fui a buscar, después de todo soy un explorador, y allí, justo afuera de mi casa, encontré a Saradomin y Zamorak peleando.",
        ["Seems that their battle had a rather unfortunate effect on my foundations. So, I went back inside and made another cup of tea."] = "Parece que su batalla tuvo un efecto bastante desafortunado en mis cimientos. Entonces, volví adentro y preparé otra taza de té.",
        ["I thought to myself that it'll take more than a world-destroying battle between two gigantic all-powerful gods to stop me!"] = "¡Pensé para mis adentros que se necesitaría más que una batalla de destrucción mundial entre dos dioses gigantescos y todopoderosos para detenerme!",
        ["So I'm not letting it get me down. I'm still a taskmaster and I have a job to do!"] = "Así que no dejaré que eso me deprima. ¡Todavía soy un capataz y tengo un trabajo que hacer!",
        ["Glad to see the battle is over now. I'm not sure how Zamorak will recover from that defeat."] = "Me alegra ver que la batalla ya terminó. No estoy seguro de cómo se recuperará Zamorak de esa derrota.",
    },
    ["Eye of Cythan"] = {
        ["You are seen. All your secrets are laid bare before Cythan's gaze."] = "Ya te ven. Todos tus secretos quedan al descubierto ante la mirada de Cythan.",
        ["Your secret shames. Your hidden fears. The wicked thoughts you have for your friends."] = "Tus vergüenzas secretas. Tus miedos ocultos. Los malos pensamientos que tienes hacia tus amigos.",
        ["That you'd see them suffer. That you'd see them kneel. That they would love you, fear you, or both."] = "Que los verías sufrir. Que los verías arrodillarse. Que te amarían, te temerían o ambas cosas.",
        ["You are a dark thing. A monster. You only pretend to be a hero."] = "Eres algo oscuro. Un monstruo. Sólo pretendes ser un héroe.",
        ["Why be enslaved to the lie?"] = "¿Por qué estar esclavizado a la mentira?",
        ["Free yourself. Become the nightmare you were born to be."] = "Libérate. Conviértete en la pesadilla para la que naciste.",
        ["Let the veil fall. Embrace the Master's gift."] = "Deja caer el velo. Abrazad el regalo del Maestro.",
        ["Sister attend, they approach."] = "Hermana atiende, se acercan.",
        ["They have bested all that came before us. Their skill should be respected."] = "Han superado a todos los que nos precedieron. Se debe respetar su habilidad.",
        ["Yet still, we cannot relent. We must destroy them."] = "Aún así, no podemos ceder. Debemos destruirlos.",
        ["A pity that they oppose us. Imagine what we could achieve together."] = "Una pena que se nos opongan. Imagínese lo que podríamos lograr juntos.",
        ["They could be so much greater than they are now."] = "Podrían ser mucho mayores de lo que son ahora.",
        ["The world guardian is too small a title. Why guard when you could rule?"] = "El título de guardián del mundo es demasiado pequeño. ¿Por qué proteger cuando puedes gobernar?",
        ["The world guardian is too small a focus. Why settle for just one world?"] = "El guardián del mundo es un foco demasiado pequeño. ¿Por qué conformarse con un solo mundo?",
        ["Join us. We shall make you powerful."] = "Únase a nosotros. Te haremos poderoso.",
        ["Kolthregar demands their death."] = "Kolthregar exige su muerte.",
        ["Cythan craves their suffering."] = "Cythan anhela su sufrimiento.",
        ["I shall feed their soul to the void. May it fuel Kranon's sorcery."] = "Alimentaré su alma hasta el vacío. Que alimente la hechicería de Kranon.",
        ["I shall burn the hope from their spirit. I will see them broken before me."] = "Quemaré la esperanza de su espíritu. Los veré destrozados delante de mí.",
        ["Sisters attend, they approach."] = "Las hermanas asisten, se acercan.",
        ["The thread cutter."] = "El cortahilos.",
        ["The storm bringer."] = "El que trae la tormenta.",
        ["The final calamity."] = "La calamidad final.",
        ["They cannot be allowed to interfere."] = "No se les puede permitir interferir.",
        ["The Ambassador must weaken the veil."] = "The Ambassador debe debilitar el velo.",
        ["The elders have decreed it."] = "Los mayores lo han decretado.",
        ["Agnes has decreed it."] = "Agnes lo ha decretado.",
        ["There is too much at stake."] = "Hay demasiado en juego.",
        ["The Tribunal needs it done."] = "El Tribunal necesita que se haga.",
    },
    ["Ezekial Lovecraft"] = {
        ["Well hello there; welcome to our little village. Pray, stay awhile."] = "Bueno, hola; bienvenidos a nuestro pequeño pueblo. Por favor, quédate un rato.",
        ["Select an Option"] = "Selecciona una opción",
        ["What do you do here?"] = "¿Qué haces aquí?",
        ["I supply the local fishermen with the tools and bait they need to do their job."] = "Proporciono a los pescadores locales las herramientas y el cebo que necesitan para hacer su trabajo.",
        ["Interesting. Have you been doing it long?"] = "Interesante. ¿Llevas mucho tiempo haciéndolo?",
        ["Why yes, all of my life. I took over from my father, who inherited the business from his father and so on."] = "Pues sí, toda mi vida. I reemplazó a mi padre, quien heredó el negocio de su padre y así sucesivamente.",
        ["In fact, there have been Lovecraft's selling bait for over ten generations."] = "De hecho, Lovecraft ha sido el cebo de venta durante más de diez generaciones.",
        ["Wow, that's some lineage."] = "Vaya, eso sí que es un linaje.",
        ["Oh yes, we have a long and interesting family history. For one reason or another the Lovecraft's have always been bait sellers or writers."] = "Oh, sí, tenemos una historia familiar larga e interesante. Por una razón u otra los Lovecraft siempre han sido vendedores de cebo o escritores.",
        ["Hmm, yes well. I'm sure it's all fascinating, but I..."] = "Hmm, sí, bueno. Estoy seguro de que todo es fascinante, pero yo...",
        ["Oh very, very fascinating, for instance my great grandfather Howard..."] = "Oh, muy, muy fascinante, por ejemplo mi bisabuelo Howard...",
        ["Yawn. Oh, I'm sorry but I really must be getting on. I think my giraffe needs feeding."] = "Bostezo. Oh, lo siento, pero realmente debo seguir adelante. Creo que mi jirafa necesita alimentación.",
        ["Your?"] = "¿Tu?",
        ["Giraffe. Sorry, but he gets cranky without enough sugar. Bye now!"] = "Jirafa. Lo siento, pero se pone de mal humor sin suficiente azúcar. ¡Hasta luego!",
        ["Oh right, goodbye."] = "Ah, claro, adiós.",
        ["Can I buy some fishing supplies please?"] = "¿Puedo comprar algunos suministros de pesca, por favor?",
        ["You are a bit too strange for me. Bye."] = "Eres un poco extraño para mí. Adiós.",
        ["Sniff. Yes, everyone says that."] = "Olfatea. Sí, todo el mundo dice eso.",
        ["You know, you sound just like the mayor?"] = "¿Sabes? ¿Suenas igual que el alcalde?",
        ["Really? That's the nicest thing anyone has ever said. I admire him a great deal. He works so hard for this town."] = "¿En serio? Eso es lo más bonito que alguien haya dicho jamás. Lo admiro mucho. Trabaja muy duro para esta ciudad.",
        ["You look like him as well?"] = "¿Tú también te pareces a él?",
        ["Hmm, I don't think I do."] = "Hmm, no creo.",
        ["No really, what with the unhealthy skin tone and bulging eyes. The resemblance is uncanny."] = "No, realmente, con el tono de piel poco saludable y los ojos saltones. El parecido es asombroso.",
        ["Well, I haven't spoken to him in a while. I don't get out much."] = "Bueno, hace tiempo que no hablo con él. No salgo mucho.",
        ["I can see why."] = "Puedo ver por qué.",
        ["Maybe the Mayor has finally seen how much I admire him and has grown to admire me?"] = "¿Quizás el alcalde finalmente ha visto cuánto lo admiro y ha llegado a admirarme a mí?",
        ["Anything's possible I suppose. Wait a minute, you mean you've always looked that odd?"] = "Supongo que todo es posible. Espera un momento, ¿quieres decir que siempre te has visto así de raro?",
        ["Hey, I resent that!"] = "¡Oye, eso me molesta!",
        ["I'm sorry, it's just... Nevermind."] = "Lo siento, es sólo que... No importa.",
        ["Are you not going home, Ezekial?"] = "¿No te vas a casa, Ezekial?",
        ["Oh, I will soon; I'm just taking in the atmosphere..."] = "Oh, lo haré pronto; Sólo estoy asimilando la atmósfera...",
        ["The 'atmosphere'? This place has brought us nothing but trouble."] = "¿La 'atmósfera'? Este lugar no nos ha traído más que problemas.",
        ["Absolutely, but that just increases my determination to rid the world of those sea slugs once and for all. Anger is an energy, Player."] = "Absolutamente, pero eso solo aumenta mi determinación de librar al mundo de esas babosas marinas de una vez por todas. La ira es una energía, Player.",
        ["I'm a bit worried about you, Ezekial. I think you ought to go home and relax."] = "Estoy un poco preocupado por ti, Ezekial. Creo que deberías irte a casa y relajarte.",
        ["Maybe you're right. I'll go soon, just give me a little more time."] = "Quizás tengas razón. Iré pronto, sólo dame un poco más de tiempo.",
        ["Hello, Ezekial."] = "Hola, Ezequial.",
        ["Why, hello, Player! I'm so pleased to see you again. Life has been very dull in this quiet little village ever since our last adventure."] = "¡Hola, Player! Me alegro mucho de verte de nuevo. La vida ha sido muy aburrida en este pequeño y tranquilo pueblo desde nuestra última aventura.",
        ["I see you have some rubium - would you like to sell it to me?"] = "Veo que tienes rubium. ¿Te gustaría vendérmelo?",
        ["Well, that depends! How much would you give me for [amount] pieces?"] = "Bueno, ¡eso depende! ¿Cuánto me darías por las piezas [amount]?",
        ["For that amount of rubium I can offer you [10 gp per rubium]."] = "Por esa cantidad de rubium te puedo ofrecer [10 gp per rubium].",
        ["Okay, it's a deal!"] = "¡Está bien, trato!",
        ["It's a pleasure doing business with you."] = "Es un placer hacer negocios con usted.",
        ["I'm sorry, Ezekial. I think I'm going to keep hold of it myself for now."] = "Lo siento, Ezekial. Creo que por ahora me lo quedaré yo mismo.",
        ["Come back later if you change your mind. I'm going to need all that I can get hold of if we're going to finally beat the sea slugs."] = "Vuelve más tarde si cambias de opinión. Voy a necesitar todo lo que pueda conseguir si finalmente queremos vencer a las babosas marinas.",
        ["So, no sign of any more sea slug activity?"] = "Entonces, ¿no hay señales de más actividad de babosas marinas?",
        ["No, it's all very quiet around here at the moment. maybe a little too quiet..."] = "No, todo está muy tranquilo por aquí en este momento. tal vez un poco demasiado silencioso...",
        ["I see. Let's hope it stays that way!"] = "Ya veo. ¡Esperemos que siga así!",
        ["Oh, I don't know about that. I'm looking forward to going on another adventure with you sometime."] = "Oh, no sé nada de eso. Estoy deseando emprender otra aventura contigo algún día.",
        ["I need to get going; see you later."] = "Necesito ponerme en marcha; hasta luego.",
        ["Okay, Player. Pray, don't be a stranger."] = "Está bien, Player. Por favor, no seas un extraño.",
        ["Hi Ezekial!"] = "¡Hola Ezekial!",
        ["Hey Player! How's it going?"] = "¡Hola Player! ¿Cómo estás?",
        ["Hah, I doubt we'll see any more of them. Not after the mess we made of their queen. Which is a shame because I really miss our missions together."] = "Ja, dudo que veamos más de ellos. No después del desastre que hicimos con su reina. Lo cual es una pena porque realmente extraño nuestras misiones juntos.",
        ["Don't worry, I'm sure we'll need your explosive expertise again."] = "No te preocupes, estoy seguro de que volveremos a necesitar tu explosiva experiencia.",
        ["Thanks Player."] = "Gracias Player.",
        ["I need to get going now, see you later!"] = "Necesito irme ahora, ¡hasta luego!",
        ["No problems Player. Good luck on your travels!"] = "No hay problemas Player. ¡Buena suerte en tus viajes!",
    },
    ["Ezreal"] = {
        ["Everything belongs in a museum! It also happens that contributing to Velucia's collections is a good way to earn chronotes, which you can spend in my shop! Want a look?"] = "¡Todo pertenece a un museo! ¡También sucede que contribuir a las colecciones de Velucia es una buena manera de ganar cronotas, que puedes gastar en mi tienda! ¿Quieres echar un vistazo?",
        ["We have a range of consumables and unlocks to assist your archaeological progress, whatever level of qualification you've achieved!"] = "¡Tenemos una variedad de consumibles y desbloqueos para ayudarte en tu progreso arqueológico, sin importar el nivel de calificación que hayas alcanzado!",
        ["Oh, I see you have an energised meteorite shard. Are you having buyer's remorse? If so, I can offer a refund on that."] = "Oh, veo que tienes un fragmento de meteorito energizado. ¿Tiene usted remordimiento del comprador? Si es así, puedo ofrecer un reembolso por eso.",
        ["Return energised meteorite shard for a full refund?"] = "¿Devolver un fragmento de meteorito energizado para obtener un reembolso completo?",
        ["Yes, refund me."] = "Sí, reembolsame.",
        ["No, I'll keep it."] = "No, me lo quedaré.",
        ["No, thank you. I'll keep hold of it."] = "No, gracias. Lo conservaré.",
    },
}

dialogues.all = {
    ["What do you do for fun on this ship? You know, when you're not doing pirate stuff."] = "¿Qué haces para divertirte en este barco? Ya sabes, cuando no estás haciendo cosas de piratas.",
    ["All sorts! Hide and seek, pin the patch on the pirate, walk the plank!"] = "¡De todo tipo! ¡A las escondidas, ponle el parche al pirata, camina sobre la tabla!",
    ["What a life! Wait a minute. 'Walk the plank'? Surely that's a bit dangerous?"] = "¡Qué vida! Espera un minuto. ¿'Caminar por la tabla'? ¿Seguramente eso es un poco peligroso?",
    ["Well of course, but where's the fun without a few deaths?"] = "Bueno, por supuesto, pero ¿dónde está la diversión sin algunas muertes?",
    ["I think I'll stick to Runelink."] = "Creo que me quedaré con Runelink.",
    ["Hello there. What's in the pot?"] = "Hola. ¿Qué hay en la olla?",
    ["The stew for the servants' main meal."] = "El guiso de la comida principal de los sirvientes.",
    ["Can I have some?"] = "¿Me das un poco?",
    ["Well not unless you become a servant. There's a war on, you know, so food is scarce."] = "Bueno, no a menos que te conviertas en un sirviente. Hay una guerra, ya sabes, por lo que la comida escasea.",
    ["Good point. I should probably leave you to it."] = "Buen punto. Probablemente debería dejarte con eso.",
    ["Bye then."] = "Adiós entonces.",
    ["Hi!"] = "¡Hola!",
    ["Welcome to Mad Eadgar's! We don't serve trolls!"] = "¡Bienvenido a Mad Eadgar! ¡No servimos a trolls!",
    ["Welcome to Mad Eadgar's! You'll never want to leave!"] = "¡Bienvenido a Mad Eadgar! ¡Nunca querrás irte!",
    ["Welcome to Mad Eadgar's! Happiness in a bowl!"] = "¡Bienvenido a Mad Eadgar! ¡Felicidad en un cuenco!",
    ["Welcome to Mad Eadgar's! Serving all day, every day!"] = "¡Bienvenido a Mad Eadgar! ¡Sirviendo todo el día, todos los días!",
    ["Would you care to sample our delicious home cooking?"] = "¿Te importaría probar nuestra deliciosa cocina casera?",
    ["Select an option"] = "Seleccione una opción",
    ["Why do you live so close to the trolls?"] = "¿Por qué vives tan cerca de los trolls?",
    ["Why do you live so close to the trolls? Isn't it dangerous?"] = "¿Por qué vives tan cerca de los trolls? ¿No es peligroso?",
    ["Well, I suppose I do keep getting captured by the trolls and thrown in prison...But they always release me in the end, I'm far too old and skinny for their tastes."] = "Bueno, supongo que los trolls me siguen capturando y encarcelando... Pero al final siempre me liberan, soy demasiado viejo y flaco para sus gustos.",
    ["In any case, this is my home, and I'm not leaving it. And this area has the tastiest goats!"] = "En cualquier caso, esta es mi casa y no voy a salir de ella. ¡Y esta zona tiene las cabras más sabrosas!",
    ["What do you have to offer?"] = "¿Qué tienes para ofrecer?",
    ["The chef's recommendation for today is mountain goat stew. I'll give some stew in exchange for logs for my fire. They're hard to come by around here."] = "La recomendación de The chef para hoy es el guiso de cabrito. Daré un guiso a cambio de logs para mi fuego. Es difícil conseguirlos por aquí.",
    ["Thanks, I might come back with some logs."] = "Gracias, puede que vuelva con algo de logs.",
    ["I'd like some mountain goat stew, please."] = "Me gustaría un guiso de cabra montesa, por favor.",
    ["You eat Eadgar's mountain goat stew."] = "Comes el guiso de cabra montesa de Eadgar.",
    ["No thanks, Eadgar."] = "No, gracias, Eadgar.",
    ["Your loss!"] = "¡Tú te lo pierdes!",
    ["Hello!"] = "¡Hola!",
    ["Hello?"] = "¿Hola?",
    ["Oh! Hello there. Sorry, I didn't really notice you."] = "¡Oh! Hola. Lo siento, realmente no te noté.",
    ["It's okay. I just hoped you'd have some chocolate for me."] = "Está bien. Sólo esperaba que tuvieras un poco de chocolate para mí.",
    ["So did I, but it's all gone wrong. I only wanted a bit of a rest. Now no one will get their chocolate goodness."] = "Yo también, pero todo salió mal. Sólo quería descansar un poco. Ahora nadie obtendrá su chocolate.",
    ["WHAT?"] = "¿QUÉ?",
    ["I know, depressing, isn't it?"] = "Lo sé, deprimente, ¿no?",
    ["Why? What happened this year?"] = "¿Por qué? ¿Qué pasó este año?",
    ["I'm getting too old for this chocolate delivery job, so I went away on a little holiday, hopping that would refresh me. I left my son in charge of the Egg Plant...and now it's all in pieces because he's so lazy."] = "Me estoy haciendo demasiado mayor para este trabajo de repartidor de chocolate, así que me fui de vacaciones con la esperanza de que eso me refrescara. Dejé a mi hijo a cargo de la Berenjena... y ahora está todo hecho pedazos porque es muy vago.",
    ["What? You have a son?"] = "¿Qué? ¿Tienes un hijo?",
    ["What's so special about an egg plant?"] = "¿Qué tiene de especial una berenjena?",
    ["Why do you need a holiday?"] = "¿Por qué necesitas unas vacaciones?",
    ["Can I help?"] = "¿Puedo ayudar?",
    ["Oh, would you? I hope I'm not being too much truffle. Er...trouble."] = "Oh, ¿lo harías? Espero no estar siendo demasiado trufa. Er... problemas.",
    ["Of course, what shall I do?"] = "Por supuesto, ¿qué debo hacer?",
    ["You could fix up the Egg Plant so it's working; that would be a start."] = "Podrías arreglar la berenjena para que funcione; eso sería un comienzo.",
    ["Okay!"] = "¡Está bien!",
    ["Now you've agreed to help, you'll need to get through the warrens to the Egg Plant, to speak to that lazy son of mine. For that you need to be bunny-sized!"] = "Ahora que has aceptado ayudar, tendrás que atravesar los laberintos hasta la Berenjena para hablar con ese hijo mío perezoso. ¡Para eso necesitas tener el tamaño de un conejito!",
    ["How do I do that?"] = "¿Cómo hago eso?",
    ["You simply go down the rabbit hole. My magic will sort the transformation, though you may feel a little itchy for a couple of weeks afterwards."] = "Simplemente baja por la madriguera del conejo. Mi magia ordenará la transformación, aunque es posible que sientas un poco de picazón durante un par de semanas después.",
    ["I'd like to ask something else."] = "Me gustaría preguntar algo más.",
    ["Off I go then!"] = "¡Entonces me voy!",
    ["Bye, then."] = "Adiós, entonces.",
    ["Happy Easter, Player, and welcome to the Blooming Burrow!"] = "¡Felices Pascuas, Player, y bienvenido a Blooming Burrow!",
    ["Our celebrations are in full swing - there's plenty to explore and help out with!"] = "Nuestras celebraciones están en pleno apogeo: ¡hay mucho que explorar y ayudar!",
    ["Choose an option:"] = "Elige una opción:",
    ["Talk about 'Great Egg-spectations'."] = "Hablemos de 'Grandes Espectáculos de Huevos'.",
    ["Do you have a quest for me?"] = "¿Tienes una búsqueda para mí?",
    ["Talk about 'Corporate Egg-spionage'."] = "Hable sobre el 'espionaje corporativo de huevos'.",
    ["What's new this Easter?"] = "¿Qué hay de nuevo esta Semana Santa?",
    ["Is there anything new to do in the Burrow this spring?"] = "¿Hay algo nuevo que hacer en La Madriguera esta primavera?",
    ["Ayah has spotted some more spies above the burrows to the east. Speak to her just past the beehives if you want to help investigate."] = "Ayah ha detectado más espías sobre las madrigueras del este. Habla con ella justo después de las colmenas si quieres ayudar a investigar.",
    ["Consider me !"] = "¡Considérame !",
    ["What's going on here?"] = "¿Qué está pasando aquí?",
    ["Many things! You can find my numerous nephews scattered around the burrow, each offering a different activity."] = "¡Muchas cosas! Puedes encontrar a mis numerosos sobrinos repartidos por la madriguera, cada uno ofreciendo una actividad diferente.",
    ["My nephew Fizzy Bunny needs some help wrangling some escaped chocolate bunnies. You can also help out my factory, the Egg Plant, by mining some chocolate, and smithing some foil."] = "Mi sobrino Fizzy Bunny necesita ayuda para lidiar con algunos conejitos de chocolate que se escaparon. También puedes ayudar a mi fábrica, la Berenjena, extrayendo un poco de chocolate y forjando papel de aluminio.",
    ["More recently, my brother Rich has been looking for eager sailors to test out his new carrot boats, and my other brother, Sticky, is looking after the Burrow's bees."] = "Más recientemente, mi hermano Rich ha estado buscando marineros entusiastas para probar sus nuevos barcos zanahoria, y mi otro hermano, Sticky, está cuidando de las abejas de Burrow.",
    ["Stewy, Gooey, and Chewy, could also use a hand... But I'd need you to help me out first before I grant you access to the factory line."] = "A Stewy, Gooey y Chewy también les vendría bien una mano... Pero primero necesitaría que me ayudaras antes de otorgarte acceso a la línea de fábrica.",
    ["The activities will reward you some skilling experience and spring tokens. You can exchange spring tokens with Gummy Bunny, for some lovely springtime rewards!"] = "Las actividades te recompensarán con experiencia en habilidades y fichas de primavera. ¡Puedes intercambiar tokens de primavera con Gummy Bunny para obtener hermosas recompensas de primavera!",
    ["My nephew Nougat Bunny has also set up a bunch of egg hunts for you adventurers this year! You should talk to find out more about it."] = "¡Mi sobrino Nougat Bunny también ha organizado un montón de búsquedas de huevos para ustedes, aventureros, este año! Deberías hablar para saber más al respecto.",
    ["Lovely! It sounds like there's a lot to help out with, then."] = "¡Encantador! Entonces parece que hay mucho con lo que ayudar.",
    ["What is this place?"] = "¿Qué es este lugar?",
    ["What is this place? It's beautiful!"] = "¿Qué es este lugar? ¡Es hermoso!",
    ["Thank you! My evergrowing family and I settled here a little while back."] = "¡Gracias! Mi familia, cada vez mayor, y yo nos establecimos aquí hace un tiempo.",
    ["You remember my old burrow and factory?"] = "¿Recuerdas mi antigua madriguera y mi fábrica?",
    ["It's been a while since I last visited, but yes, I do."] = "Ha pasado un tiempo desde la última vez que lo visité, pero sí, lo hago.",
    ["Well, with the rate my nephews and nieces were popping into this world at, we soon outgrew that place!"] = "Bueno, con el ritmo al que mis sobrinos y sobrinas estaban apareciendo en este mundo, ¡pronto se nos quedó pequeño ese lugar!",
    ["It took a lot of bunny-power, but we lugged all of our heavy factory equipment out of the old burrow and into this new, more spacious, one."] = "Se necesitó mucha fuerza de conejo, pero sacamos todo nuestro equipo pesado de fábrica de la vieja madriguera y lo metimos en esta nueva y más espaciosa.",
    ["All of my niblings get a hole of their own, and I get my own office. Everyone's happy!"] = "Todos mis hijos tienen su propio hueco y yo tengo mi propia oficina. ¡Todos están felices!",
    ["Is there a spare hole that I could come and live in? I'd be happy to stay here all the time."] = "¿Hay algún hueco libre donde pueda venir a vivir? Estaría feliz de quedarme aquí todo el tiempo.",
    ["I'm afraid not. Any empty holes are reserved for future bunlings."] = "Me temo que no. Los agujeros vacíos se reservan para futuros atados.",
    ["Oh well."] = "Ah, bueno.",
    ["Farewell."] = "Adiós.",
    ["Bye for now!"] = "¡Adiós por ahora!",
    ["Have a happy Easter!"] = "¡Que tengas una feliz Pascua!",
    ["You've unlocked the 'Easter Egg' colour for the 'the Egg' title!"] = "¡Has desbloqueado el color 'Huevo de Pascua' para el título 'el Huevo'!",
    ["Oh, I love your title! Very festive! Let me give it a lick of paint in my favourite colours for you."] = "¡Oh, me encanta tu título! ¡Muy festivo! Déjame darle una mano de pintura en mis colores favoritos para ti.",
    ["Hey Player, how's it going?"] = "Hola Player, ¿cómo te va?",
    ["**Select an Option**"] = "**Seleccione una opción**",
    ["Who are you?"] = "¿Quién eres?",
    ["I'm Associate Easty. Acting Guildmaster Reiniger assigned me to assist you with the monolith."] = "Soy el asociado Easty. Acting Guildmaster Reiniger me asignó para ayudarte con el monolito.",
    ["I can keep hold of any relics you've discovered, until you are ready to offer them to the monolith. I will also happily assist you with any monolith research we uncover."] = "Puedo conservar cualquier reliquia que hayas descubierto hasta que estés listo para ofrecerla al monolito. También estaré encantado de ayudarle con cualquier investigación de monolitos que descubramos.",
    ["What are you doing here?"] = "¿Qué haces aquí?",
    ["Watching over the monolith of course!"] = "¡Vigilando el monolito, por supuesto!",
    ["You're more than welcome to use it, though, Player. I've been made aware of the odd connection you have with it. Mostly, I'm here to keep the other archaeologists away, to keep them safe. Only you seem to have a connection with it so far, so we need to be careful."] = "Sin embargo, eres más que bienvenido a usarlo, Player. Me han informado de la extraña conexión que tienes con ello. Principalmente estoy aquí para mantener alejados a los otros arqueólogos, para mantenerlos a salvo. Sólo tú pareces tener una conexión con ello hasta ahora, así que debemos tener cuidado.",
    ["That being sad, you're still going to need to throw some chronotes my way if you want to make use of it."] = "Aunque sea triste, igual tendrás que lanzarme algunas cronotas si quieres usarlas.",
    ["Why?"] = "¿Por qué?",
    ["We need to make sure the guild stay afloat somehow, am I right? Also, I'm not an intern."] = "Necesitamos asegurarnos de que el gremio se mantenga a flote de alguna manera, ¿verdad? Además, no soy pasante.",
    ["Ask about relic management."] = "Pregunta sobre la gestión de reliquias.",
    ["Can you tell me more about the monolith?"] = "¿Puedes contarme más sobre el monolito?",
    ["You've had more of a connection with it than I have. I daren't touch it, not after what happened to Guildmaster Tony."] = "Has tenido más conexión con ello que yo. No me atrevo a tocarlo, no después de lo que le pasó a Guildmaster Tony.",
    ["What did happen to Tony?"] = "¿Qué le pasó a Tony?",
    ["Ah, yes! No one really knows, for sure. He was always very hands on, even as Guildmaster. He took it upon himself to research the monolith, alone, after it activated."] = "¡Ah, sí! Nadie lo sabe realmente, con seguridad. Siempre fue muy práctico, incluso como Guildmaster. Se encargó de investigar el monolito, solo, después de que se activó.",
    ["Then, one day, there was a commotion from it and the only thing left of Tony was his old mattock, which we locked away in his office for safekeeping."] = "Entonces, un día, hubo una conmoción y lo único que quedó de Tony fue su viejo azadón, que guardamos bajo llave en su oficina para guardarlo.",
    ["Do you know how the monolith activated?"] = "¿Sabes cómo se activó el monolito?",
    ["Ah, yes! That's something else we don't know... One day, it was just a dormant hunk of stone that nobody was paying attention to anymore - more interesting recent finds, you see?"] = "¡Ah, sí! Eso es algo más que no sabemos... Un día, era sólo un trozo de piedra latente al que ya nadie prestaba atención: hallazgos recientes más interesantes, ¿entiendes?",
    ["Then the next day, we awoke and it was stood impossibly upright, floating and bobbling and twisting in the unnerving way it's doing behind me right now."] = "Luego, al día siguiente, nos despertamos y estaba increíblemente erguido, flotando, balanceándose y retorciéndose de la forma inquietante que está haciendo detrás de mí en este momento.",
    ["Is there anything you DO know?"] = "¿Hay algo que SÍ sepas?",
    ["Ah! Well, what we do know is that the monolith gave off a burst of energy that morning after it first opened up. We've seen a bunch of what we're calling time sprites flying about around excavations. Those are what led us to set up each of our dig sites."] = "¡Ah! Bueno, lo que sí sabemos es que el monolito emitió una explosión de energía esa mañana después de que se abrió por primera vez. Hemos visto un montón de lo que llamamos duendes del tiempo volando alrededor de las excavaciones. Esos son los que nos llevaron a establecer cada uno de nuestros sitios de excavación.",
    ["We even tracked some time sprites flying off in the direction of Anachronia, but they haven't landed up there yet. It'll be to do with the strange time distortion going on over there, but they should land eventually."] = "Incluso rastreamos algunos duendes del tiempo que volaban en dirección a Anacronia, pero aún no han aterrizado allí. Tendrá que ver con la extraña distorsión del tiempo que ocurre allí, pero eventualmente deberían aterrizar.",
    ["It's almost as if the monolith has an interest in some very specific relics from our past, like it's sending out feelers. Relics like you one you offered to it."] = "Es casi como si el monolito tuviera interés en algunas reliquias muy específicas de nuestro pasado, como si estuviera enviando sondas. Reliquias como la que tú le ofreciste.",
    ["If you stumble across any more relics on your journey to become a master archaeologist, you'll want to make sure you bring it back here and see if the monolith is interested."] = "Si te topas con más reliquias en tu viaje para convertirte en un maestro arqueólogo, querrás asegurarte de traerlas aquí y ver si el monolito está interesado.",
    ["We figure it's the only way we're going to figure out what this thing actually is...and hopefully get Tony back too, while we're at it."] = "Creemos que es la única manera de descubrir qué es realmente esto... y, con suerte, recuperar a Tony también, mientras estamos en ello.",
    ["Can you explain relic powers to me?"] = "¿Puedes explicarme los poderes de las reliquias?",
    ["From what we can gather, the monolith consumes each relic offered to it, but draws the inherent quality or essence of the relic into it as powers."] = "Por lo que podemos deducir, el monolito consume cada reliquia que se le ofrece, pero atrae la cualidad o esencia inherente de la reliquia como poderes.",
    ["These powers can then be harnessed by tapping into the monolith's internal energy source. Well, you can do that, at least. No one else."] = "Estos poderes se pueden aprovechar aprovechando la fuente de energía interna del monolito. Bueno, al menos puedes hacer eso. Nadie más.",
    ["The monolith seems to have a limit of energy that it can exert, and certain powers require a greater amount of its pool of power than others."] = "El monolito parece tener un límite de energía que puede ejercer, y ciertos poderes requieren una mayor cantidad de su reserva de poder que otros.",
    ["There might be a way to tap into more of the monolith's reserves, but I'm not too sure. We'll need to do some research."] = "Podría haber una manera de aprovechar más reservas del monolito, pero no estoy muy seguro. Tendremos que investigar un poco.",
    ["At least, that's how it looks to me, from what I've seen so far."] = "Al menos, eso es lo que me parece a mí, por lo que he visto hasta ahora.",
    ["Do you have any relics?"] = "¿Tienes alguna reliquia?",
    ["Not at the moment, but if you lose any relics, come see me."] = "No por el momento, pero si pierdes alguna reliquia, ven a verme.",
    ["You're going to need some space in your backpack."] = "Necesitarás algo de espacio en tu backpack.",
    ["You receive: [relic]."] = "Recibirás: [relic].",
    ["There you are!"] = "¡Ahí estás!",
    ["Ask about something else."] = "Pregunta por otra cosa.",
    ["I have nothing to say to you, false prophet!"] = "¡No tengo nada que decirte, falso profeta!",
    ["Leave us to our fate. We care nothing for the world that betrayed us, or those that come from it."] = "Déjanos a nuestra suerte. No nos importa nada el mundo que nos traicionó, ni los que vienen de él.",
    ["Ask about Archaeology"] = "Preguntar por Archaeology",
    ["Select an Option"] = "Selecciona una opción",
    ["I am Eblis, the elder of this settlement you refer to as a 'bandit camp'."] = "Soy Eblis, el mayor de este asentamiento al que te refieres como \"campamento de bandidos\".",
    ["We are no bandits. We are the descendants of what was once the greatest empire in Gielinor."] = "No somos bandidos. Somos descendientes de lo que alguna vez fue el imperio más grande de Gielinor.",
    ["Once my people were great, powerful, wealthy and respected. Now we are this."] = "Una vez mi pueblo era grande, poderoso, rico y respetado. Ahora somos esto.",
    ["What are you collecting?"] = "¿Qué estás coleccionando?",
    ["It has come to my attention that the ancient city of Senntisten has been rediscovered."] = "Me ha llamado la atención que la antigua ciudad de Senntisten ha sido redescubierta.",
    ["I seek artefacts from that city. Remnants of our once-great history."] = "Busco artefactos de esa ciudad. Restos de nuestra otrora gran historia.",
    ["In short, I seek to collect that which was lost to us. A small part of our former glory."] = "En resumen, busco recuperar lo que se nos perdió. Una pequeña parte de nuestra antigua gloria.",
    ["What are your collection rewards?"] = "¿Cuáles son las recompensas de tu colección?",
    ["Yes, of course you would only be interested in the rewards."] = "Sí, por supuesto que solo te interesarían las recompensas.",
    ["I have gathered ancient treasure troves which contain great wealth. Bring me artefacts from Senntisten and these wonders can be yours."] = "He reunido antiguos tesoros que contienen una gran riqueza. Tráeme artefactos de Senntisten y estas maravillas pueden ser tuyas.",
    ["A fair trade, I think."] = "Creo que es un trato justo.",
    ["Bye."] = "Adiós.",
    ["Ask about Desert Treasure"] = "Preguntar por Desert Treasure",
    ["Hello again."] = "Hola de nuevo.",
    ["Greetings. I await the return of my Lord Azzanadra and of our god. I do not know why, but I feel this spot has some significance..."] = "Saludos. I espero el regreso de mi Señor Azzanadra y de nuestro dios. I no sé por qué, pero siento que este lugar tiene algún significado...",
    ["Tell Eblis that Zaros has returned?"] = "¿Dile a Eblis que Zaros ha regresado?",
    ["Yes."] = "Sí.",
    ["About that..."] = "Sobre eso...",
    ["What? What is it?"] = "¿Qué? ¿Qué es?",
    ["Yeah, so...Zaros IS back."] = "Sí, entonces... Zaros ESTÁ de regreso.",
    ["Really? Where? You'd better not be joking!"] = "¿En serio? ¿Dónde? ¡Será mejor que no estés bromeando!",
    ["He's...actually, you know, I'm not sure where. I'd assume at Senntisten Temple."] = "Él está... en realidad, ya sabes, no estoy seguro de dónde. Supongo que en el templo Senntisten.",
    ["Are you sure? What did he look like? Is he coming here?"] = "¿Estás seguro? ¿Qué aspecto tenía? ¿Viene aquí?",
    ["Positive - I helped make it happen. He looked strong...divine... I think he'd rather the other gods didn't know he was back, though."] = "Positivo: ayudé a que esto sucediera. Se veía fuerte... divino... Aunque creo que preferiría que los otros dioses no supieran que había regresado.",
    ["Of course. I...I shall not tell a soul. You're definitely sure? Yes, of course you are. Surely it is only a matter of time now before Lord Azzanadra returns to us with new instruction."] = "Por supuesto. Yo... no se lo diré a nadie. ¿Estás definitivamente seguro? Sí, por supuesto que lo eres. Seguramente es sólo cuestión de tiempo antes de que Lord Azzanadra regrese a nosotros con nuevas instrucciones.",
    ["Actually...about that..."] = "En realidad... sobre eso...",
    ["Oh, er, never mind."] = "Oh, eh, no importa.",
    ["You know, I think you're right - there does seem to be something special about this spot. There's an abundance of anima and divine energy in the area."] = "Sabes, creo que tienes razón: parece haber algo especial en este lugar. Hay abundancia de ánima y energía divina en la zona.",
    ["Perhaps some remnant of the Zaros-Kharid war?"] = "¿Quizás algún vestigio de la guerra Zaros-Kharid?",
    ["Maybe?"] = "¿Quizás?",
    ["Ask about Desert Trasure"] = "Pregunte sobre Desert Trasure",
    ["Tell Eblis that Zaros has left?"] = "¿Dile a Eblis que Zaros se ha ido?",
    ["About that. Zaros did return..."] = "Sobre eso. Zaros regresó...",
    ["This is wonderous news! Perhaps my people can once again take their rightful place in the..."] = "¡Esta es una noticia maravillosa! Quizás mi pueblo pueda volver a ocupar el lugar que le corresponde en...",
    ["Then he left again. Via an elder artefact...into a place called Erebus, where we cannot follow him."] = "Luego se fue de nuevo. A través de un artefacto antiguo... a un lugar llamado Erebus, donde no podemos seguirlo.",
    ["I see."] = "Ya veo.",
    ["But Azzanadra has now ascended to god hood."] = "Pero Azzanadra ahora ha ascendido a la categoría de dios.",
    ["The great Azzanadra? A god? This is wonderful news. Truly wonderful."] = "¿El gran Azzanadra? ¿Un dios? Esta es una maravillosa noticia. Realmente maravilloso.",
    ["Thank you for telling me this my friend. I shall spread the good news to my people."] = "Gracias por contarme esto, amigo mío. Difundiré la buena nueva a mi pueblo.",
    ["Engrams must be charged and handed in to Orla before you can display their echo on a plinth."] = "Los engramas deben cargarse y entregarse a Orla antes de que puedas mostrar su eco en un pedestal.",
    ["Displaying echoes is not required for any passive beneficial effects."] = "No es necesario mostrar ecos para ningún efecto beneficioso pasivo.",
    ["*(12 engram boxes are shown. If the engram has been handed in the box contains its name and a checkbox. If the engram has already been placed on a plinth the box is greyed out and the checkbox is ticked. If the engram has not been handed in the box is greyed out, contains the text '[Uncharged]' and a checkbox that is filled with a '?'.)*}}"] = "*(Se muestran 12 cuadros de engrama. Si el engrama se ha entregado, el cuadro contiene su nombre y una casilla de verificación. Si el engrama ya se ha colocado en un pedestal, el cuadro está atenuado y la casilla de verificación está marcada. Si el engrama no se ha entregado, el cuadro está atenuado y contiene el texto '[Uncharged]' y una casilla de verificación llena con un '?'.)*}}",
    ["CANCEL"] = "CANCELAR",
    ["What would you like to do?"] = "¿Qué te gustaría hacer?",
    ["Talk to the echo."] = "Habla con el eco.",
    ["Recolour this echo."] = "Vuelva a colorear este eco.",
    ["Which colour?"] = "¿Qué color?",
    ["Blue."] = "Azul.",
    ["cond=After prestige 1:"] = "cond=Después del prestigio 1:",
    ["cond=After prestige 2:"] = "cond=Después del prestigio 2:",
    ["Clear this plinth."] = "Limpia este pedestal.",
    ["colour=yellow"] = "color = amarillo",
    ["*grumble* What do you want?"] = "*gruñido* ¿Qué quieres?",
    ["What services do you offer?"] = "¿Qué servicios ofrecen?",
    ["*grumble* It says on the board right there. You can rent a boat, or I can take you on a boat tour."] = "*gruñido* Dice en el pizarrón de ahí. Puedes alquilar un barco o puedo llevarte a un paseo en barco.",
    ["Take a boat out onto the lake."] = "Tome un bote hacia el lago.",
    ["Go on a boat tour."] = "Realizar un recorrido en barco.",
    ["Nothing."] = "Nada.",
    ["Actually, I don't think I want anything."] = "En realidad, no creo que quiera nada.",
    ["Fine."] = "Bien.",
    ["You'll need both hands free to do that."] = "Necesitará ambas manos libres para hacerlo.",
    ["*grumble* Welcome to Ed's boat tours in the City of Um. Today we'll be rowing around Lake Mnemosyne, while I tell you some fun facts about the sights."] = "*gruñido* Bienvenido a los recorridos en barco de Ed en el City of Um. Hoy estaremos remando alrededor del lago Mnemosyne, mientras te cuento algunos datos curiosos sobre los lugares de interés.",
    ["*grumble* First stop, the Well of Souls. A masterpiece of architecture, this vessel harbours all of the souls that live here, in Um."] = "*gruñido* Primera parada, el Pozo de las Almas. Una obra maestra de la arquitectura, este barco alberga a todas las almas que viven aquí, en Um.",
    ["It was created in the First Age, not long after the City itself, and boasts stone carvings of skulls and Death himself."] = "Fue creada en la Primera Edad, no mucho después de la propia Ciudad, y cuenta con esculturas en piedra de calaveras y de la propia Muerte.",
    ["If you look close enough, you can even see the individual souls floating about in its bowl."] = "Si miras lo suficientemente cerca, puedes incluso ver las almas individuales flotando en su cuenco.",
    ["It really is an impressive structure."] = "Realmente es una estructura impresionante.",
    ["Indeed. I wouldn't get too close if I were you though - there's quite a drop surrounding it."] = "De hecho. Aunque yo no me acercaría demasiado si fuera tú: hay una gran caída a su alrededor.",
    ["*grumble* For our second stop, just some of the many shipwrecks in Mnemosyne."] = "*gruñido* Para nuestra segunda parada, solo algunos de los muchos naufragios en Mnemosyne.",
    ["Imagined into existence by the many sailors and pirates alike, these wrecks scatter themselves across the rocky outcrops."] = "Estos restos de naufragios, imaginados por muchos marineros y piratas, se esparcen por los afloramientos rocosos.",
    ["Have you met many famous beings in Um?"] = "¿Has conocido a muchos seres famosos en Um?",
    ["Great question. With Um having seen many residents over the years, I have met my fair share of notable Gielinorians."] = "Gran pregunta. Como Um ha visto a muchos residentes a lo largo de los años, he conocido a una buena cantidad de gielinorianos notables.",
    ["Like who?"] = "¿Como quién?",
    ["Well, to name a few, Queen Glarial of the elves, Obi'Sooth of the aviansie, and the infamous Count Draynor."] = "Bueno, por nombrar algunos, la Reina Glarial de los elfos, Obi'Sooth de los aviansie y el infame Count Draynor.",
    ["Most of them pass through to the afterlife, but some, such as the legendary fisherwoman Tavia, choose to hang around in Um for a while."] = "La mayoría de ellos pasan al más allá, pero algunos, como la legendaria pescadora Tavia, eligen quedarse en Um por un tiempo.",
    ["No gods, though, as beings such as them - as well as Mahjarrat and demons - do not pass through the Underworld."] = "Sin embargo, no hay dioses, ya que seres como ellos, así como Mahjarrat y los demonios, no pasan por el inframundo.",
    ["*grumble* The third stop on our tour is the dastardly Rasial's citadel."] = "*gruñido* La tercera parada de nuestro recorrido es la ciudadela del cobarde Rasial.",
    ["Whilst not in the City of Um, the citadel sits high in the sky - with views over a vast array of the Underworld."] = "Aunque no está en City of Um, la ciudadela se encuentra en lo alto del cielo, con vistas a una amplia gama del inframundo.",
    ["I haven't personally visited, but I hear it has an impressive central chamber, complete with an antique organ."] = "No lo he visitado personalmente, pero he oído que tiene una impresionante cámara central, completa con un órgano antiguo.",
    ["*grumble* I don't get fazed easily... But looking up at that citadel for too long sends a rattle down my old bones."] = "*gruñido* No me desconcierto fácilmente... Pero mirar esa ciudadela durante demasiado tiempo hace que mis viejos huesos se estremezcan.",
    ["If you're lucky, you might come across some fellow boaters when exploring Mnemosyne, such as our locals Sammy and Deano."] = "Si tienes suerte, es posible que te encuentres con otros navegantes cuando explores Mnemosyne, como nuestros lugareños Sammy y Deano.",
    ["*grumble* Our penultimate stop on the tour is the graveyard and market of Um."] = "*gruñido* Nuestra penúltima parada del recorrido es el cementerio y mercado de Um.",
    ["Rather than honouring the dead, the shrines in the graveyard honour the living. Many residents light candles within them to look over their living loved ones, while they wait for them to pass."] = "En lugar de honrar a los muertos, los santuarios en el cementerio honran a los vivos. Muchos residentes encienden velas en su interior para contemplar a sus seres queridos vivos, mientras esperan a que pasen.",
    ["How thoughtful."] = "Qué pensativo.",
    ["The market is home to a variety of traders, who come from all over to sell their wares on the docks of Um."] = "El mercado es el hogar de una variedad de comerciantes, que vienen de todas partes para vender sus productos en los muelles de Um.",
    ["*grumble* And our final stop on this tour is the centre of the City itself."] = "*gruñido* Y nuestra última parada en este recorrido es el centro de la ciudad.",
    ["The City of Um was created by Death in the First Age, and has since seen a vast variety of beings pass through - humans, trolls, elves, and more."] = "El City of Um fue creado por la Muerte en la Primera Edad y desde entonces ha visto pasar una gran variedad de seres: humanos, trolls, elfos y más.",
    ["Residents that pass through here create the features of the city through their memories. This leaves most of the structures to deteriorate over time as the residents pass on, and their memories are forgotten."] = "Los residentes que pasan por aquí crean las características de la ciudad a través de sus recuerdos. Esto hace que la mayoría de las estructuras se deterioren con el tiempo a medida que los residentes fallecen y sus recuerdos se olvidan.",
    ["However, one of the most notable and longest-standing features of Um is its giant hourglass."] = "Sin embargo, una de las características más notables y duraderas de Um es su reloj de arena gigante.",
    ["This is one of the few surviving original features since the City's inception, having been kept in memory due to the frequent visits by Death."] = "Esta es una de las pocas características originales que se conservan desde los inicios de la ciudad, y se ha mantenido en la memoria debido a las frecuentes visitas de la Muerte.",
    ["Now, does anyone have any questions before we end the tour?"] = "Ahora, ¿alguien tiene alguna pregunta antes de finalizar el recorrido?",
    ["Actually, I was hoping you could tell me about-"] = "En realidad, esperaba que pudieras contarme sobre-",
    ["No? Lovely. This was Ed's boat tours - check out the gift shop, tell your friends, and have a mediocre rest of your day."] = "¿No? Hermoso. Estos fueron los recorridos en barco de Ed: visita la tienda de regalos, cuéntaselo a tus amigos y disfruta de un resto mediocre de tu día.",
    ["You have unlocked the title: 'Player, |colour=#0f0}}"] = "Has desbloqueado el título: 'Player, |color=#0f0}}",
    ["25 souls fly over to power the vessel."] = "25 almas vuelan para impulsar el barco.",
    ["Congratulations! You have completed: 'Tourist of Um' - Take one of Ed's boat tours."] = "¡Felicitaciones! Has completado: 'Turista de Um': realiza uno de los recorridos en barco de Ed.",
    ["Actually, I was hoping you could tell me-"] = "En realidad, esperaba que pudieras decirme-",
    ["You again? I guess I can answer a question for you this time."] = "¿Tú otra vez? Supongo que esta vez puedo responderte una pregunta.",
    ["Ask about Ed's favourite place in Um."] = "Pregunta sobre el lugar favorito de Ed en Um.",
    ["I was hoping you could tell me what your favourite place is in Um?"] = "Esperaba que pudieras decirme cuál es tu lugar favorito en Um.",
    ["Lake Mnemosyne. It's peaceful and spacious."] = "Lago Mnemosyne. Es tranquilo y espacioso.",
    ["Ask about Ed's residence in Um."] = "Pregunte sobre la residencia de Ed en Um.",
    ["I was hoping you could tell me why you stay here in Um?"] = "Esperaba que pudieras decirme por qué te quedas aquí en Um.",
    ["*grumble* I like running my business here, and that's all you need to know."] = "*gruñido* Me gusta administrar mi negocio aquí, y eso es todo lo que necesitas saber.",
    ["Ask about nothing."] = "Preguntar por nada.",
    ["I was hoping you could tell me about... Nothing?"] = "Esperaba que pudieras contarme sobre... ¿Nada?",
    ["Nothing? Stop wasting my time, kid."] = "¿Nada? Deja de hacerme perder el tiempo, chico.",
    ["Now, this was Ed's boat tours - check out the gift shop, tell your friends, and have a mediocre rest of your day."] = "Ahora, estos fueron los recorridos en barco de Ed: visita la tienda de regalos, cuéntaselo a tus amigos y disfruta de un resto mediocre de tu día.",
    ["Hello there! Are you interested in buying one of my special team capes?"] = "¡Hola! ¿Estás interesado en comprar una de mis capas especiales del equipo?",
    ["What do team capes do?"] = "¿Qué hacen las capas del equipo?",
    ["If you and your friends all wear the same team cape, you'll be less likely to attack your friends by accident, and you'll find it easier to attack everyone else."] = "Si tú y tus amigos usan la misma capa del equipo, será menos probable que ataques a tus amigos por accidente y te resultará más fácil atacar a todos los demás.",
    ["They're very useful in the Wilderness and other player-vs-player combat areas where you might come across friends you don't want to harm."] = "Son muy útiles en Wilderness y otras áreas de combate jugador contra jugador donde puedes encontrarte con amigos a los que no quieres hacer daño.",
    ["So would you like to buy one?"] = "Entonces, ¿te gustaría comprar uno?",
    ["*(Displays the options below)*"] = "*(Muestra las opciones a continuación)*",
    ["Yes please!"] = "¡Sí, por favor!",
    ["*(Opens Edmond's Wilderness Cape Shop)*"] = "*(Abre la tienda de capas Wilderness de Edmond)*",
    ["I'd like to access my bank please."] = "Me gustaría acceder a mi banco por favor.",
    ["*(Opens the bank interface)*"] = "*(Abre la interfaz del banco)*",
    ["No thanks."] = "No, gracias.",
    ["Ah hello again and thank you again for rescuing my daughter."] = "Ah, hola de nuevo y gracias de nuevo por rescatar a mi hija.",
    ["No problem."] = "No hay problema.",
    ["Elena told me the truth you uncovered about the plague. So it is you that liberated us from the mourners. You are truly a hero."] = "Elena me contó la verdad que descubriste sobre la plaga. Entonces fuiste tú quien nos liberó de los dolientes. Eres realmente un héroe.",
    ["Can I help you?"] = "¿Puedo ayudarte?",
    ["Possibly. Do you have a challenge for me?"] = "Posiblemente. ¿Tienes un desafío para mí?",
    ["Yes I do, as a matter of fact."] = "Sí, de hecho.",
    ["[Edmond has given you a challenge scroll!]"] = "[¡Edmond te ha dado un pergamino de desafío!]",
    ["Please enter the answer to the question."] = "Ingrese la respuesta a la pregunta.",
    ["Enter amount: [Input field]"] = "Ingrese la cantidad: [Input field]",
    ["Is that your final answer? Because it sounds unlikely to me."] = "¿Es esa tu respuesta final? Porque me parece improbable.",
    ["[Edmond has given you another clue scroll!]"] = "[¡Edmond te ha dado otro pergamino de pistas!]",
    ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
    ["Sounds good!"] = "¡Suena bien!",
    ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
    ["*Dialogue 1*"] = "*Diálogo 1*",
    ["Out of my way, punk."] = "Fuera de mi camino, punk.",
    ["*Dialogue 2*"] = "*Diálogo 2*",
    ["I have no interest in talking to a pathetic meat bag like yourself."] = "No tengo ningún interés en hablar con un patético bolsa de carne como tú.",
    ["*Dialogue 3*"] = "*Diálogo 3*",
    ["If I were as ugly as you I would not dare to show my face in public!"] = "¡Si fuera tan feo como tú no me atrevería a mostrar mi cara en público!",
    ["*Dialogue 4*"] = "*Diálogo 4*",
    ["Hmm... you smell strange..."] = "Hmm... hueles raro...",
    ["Strange how?"] = "¿Qué extraño cómo?",
    ["Like a human!"] = "¡Como un humano!",
    ["Oh! Er... I just ate one is why!"] = "¡Oh! Er... ¡acabo de comer uno, por eso!",
    ["*Dialogue 5*"] = "*Diálogo 5*",
    ["Get lost!"] = "¡Piérdete!",
    ["*Dialogue 6*"] = "*Diálogo 6*",
    ["Leave me alone."] = "Déjame en paz.",
    ["*Dialogue 7*"] = "*Diálogo 7*",
    ["Have you no manners?"] = "¿No tienes modales?",
    ["*Dialogue 8*"] = "*Diálogo 8*",
    ["I don't have anything to give you so leave me alone, mendicant."] = "No tengo nada que darte así que déjame en paz, mendigo.",
    ["*Dialogue 9*"] = "*Diálogo 9*",
    ["I don't have time for this right now."] = "No tengo tiempo para esto ahora.",
    ["*Dialogue 10*"] = "*Diálogo 10*",
    ["Don't talk to me again if you value your life!"] = "¡No vuelvas a hablarme si valoras tu vida!",
    ["Give me a moment... I have a bit of someone stuck in my teeth..."] = "Dame un momento... tengo un poco de alguien pegado entre los dientes...",
    ["I haven't smelt you around here before..."] = "No te había olido por aquí antes...",
    ["If you catch anyone promise me you'll share."] = "Si atrapas a alguien, prométeme que lo compartirás.",
    ["You look to me like someone with a healthy taste for blood."] = "Me pareces alguien con un gusto saludable por la sangre.",
    ["Fancy going up to the castle for a bit of a snack?"] = "¿Te apetece subir al castillo a tomar un refrigerio?",
    ["I bet you have wonderful paws."] = "Apuesto a que tienes unas patas maravillosas.",
    ["Seen any humans around here? I'm v-e-r-y hungry."] = "¿Has visto humanos por aquí? Tengo mucha hambre.",
    ["Good day to you, my friend."] = "Buenos días, amigo mío.",
    ["You smell familiar..."] = "Hueles familiar...",
    ["A very miserable day, altogether... enjoy it while it lasts."] = "Un día muy miserable, en definitiva... disfrútalo mientras dure.",
    ["Hello there."] = "Hola.",
    ["Oh, hi. I'm studying hard for an exam."] = "Ah, hola. Estoy estudiando mucho para un examen.",
    ["What exam is that?"] = "¿Qué examen es ese?",
    ["It's the Earth Sciences exam."] = "Es el examen de Ciencias de la Tierra.",
    ["Interesting...."] = "Interesante....",
    ["I am not sure why I am giving this to the student..."] = "No estoy seguro de por qué le doy esto al estudiante...",
    ["Nothing interesting happens."] = "No pasa nada interesante.",
    ["Oh, hi again. News of your find has spread fast. You are quite famous around here now."] = "Ah, hola de nuevo. La noticia de su hallazgo se ha difundido rápidamente. Eres bastante famoso por aquí ahora.",
    ["I'm setting up a research team and wondered if you'd want to be a part of it..."] = "Estoy formando un equipo de investigación y me preguntaba si te gustaría ser parte de él...",
    ["I'd love to, but only interns and about can work on research teams. The only way I can become an intern is if I impress Acting Guildmaster Reiniger with an artefact find."] = "Me encantaría, pero solo los pasantes y alrededores pueden trabajar en equipos de investigación. La única manera de convertirme en pasante es impresionar a Acting Guildmaster Reiniger con un hallazgo de artefacto.",
    ["It would have to be an artefact related to my specialisation too, which is animal skulls and equipment."] = "Tendría que ser un artefacto relacionado con mi especialización también, que son cráneos y equipos de animales.",
    ["Would it fast track the process if I just brought you a restored artefact that fits?"] = "¿Aceleraría el proceso si solo les trajera un artefacto restaurado que encajara?",
    ["You'd do that just so I can work on your research team? That's so kind."] = "¿Harías eso solo para que yo pueda trabajar en tu equipo de investigación? Eso es muy amable.",
    ["Well, we did study for our exams together - you helped me out a lot, so I'm only returning the favour."] = "Bueno, estudiamos juntos para nuestros exámenes; me ayudaste mucho, así que solo te devolveré el favor.",
    ["Tell you what - if you can bring me a restored ceremonial unicorn ornament from Everlight, I'll report for duty ASAP!"] = "Te diré una cosa: si puedes traerme un adorno ceremonial de unicornio restaurado de Everlight, ¡me presentaré a trabajar lo antes posible!",
    ["I'm on it!"] = "¡Estoy en ello!",
    ["I have a restored ceremonial unicorn ornament from Everlight..."] = "Tengo un adorno ceremonial de unicornio restaurado de Everlight...",
    ["Give ceremonial unicorn ornament to Eduardo?"] = "¿Darle un adorno ceremonial de unicornio a Eduardo?",
    ["Fantastic! Reporting for duty, boss!"] = "¡Fantástico! ¡Preséntate para el servicio, jefe!",
    ["Eduardo has joined your research team!"] = "¡Eduardo se ha unido a tu equipo de investigación!",
    ["Let me get back to you on this."] = "Déjame responderte sobre esto.",
    ["Whenever you're ready is good."] = "Cuando estés listo es bueno.",
    ["Ready for research whenever you need me, boss!"] = "¡Listo para investigar cuando me necesites, jefe!",
    ["**Edward** Hello there! Are you interested in buying one of my special team capes?"] = "**Edward** ¡Hola! ¿Estás interesado en comprar una de mis capas especiales del equipo?",
    ["**Player** What do team capes do?"] = "**Player** ¿Qué hacen las capas del equipo?",
    ["**Edward** If you and your friends all wear the same team cape, you'll be less likely to attack your friends by accident, and you'll find it easier to attack everyone else."] = "**Edward** Si tú y tus amigos usan la misma capa del equipo, será menos probable que ataques a tus amigos por accidente y te resultará más fácil atacar a todos los demás.",
    ["**Edward** They're very useful in Clan Wars and other player-vs- player combat areas where you might come across friends you don't want to harm."] = "**Edward** Son muy útiles en Guerras de Clanes y otras áreas de combate jugador contra jugador donde puedes encontrarte con amigos a los que no quieres hacer daño.",
    ["**Edward** So would you like to buy one?"] = "**Edward** Entonces, ¿te gustaría comprar uno?",
    ["**Player** No thanks."] = "**Player** No, gracias.",
    ["*(Dialogue ends)*"] = "*(Termina el diálogo)*",
    ["Hello Good Sir, can I do anything for you?"] = "Hola buen señor, ¿puedo hacer algo por usted?",
    ["No I'm fine, I'm just wandering around."] = "No, estoy bien, solo estoy deambulando.",
    ["Looking to make a donation to a good cause?"] = "¿Quieres hacer una donación para una buena causa?",
    ["How can I help?"] = "¿Cómo puedo ayudar?",
    ["These lands are absolutely ripe with artefacts which the clan could benefit from."] = "Estas tierras están repletas de artefactos de los que el clan podría beneficiarse.",
    ["Notably, we uncovered some kind of archaeological site just to the west of me, as well as various ancient remains we've found all across the Hollow."] = "En particular, descubrimos una especie de sitio arqueológico justo al oeste de mí, así como varios restos antiguos que hemos encontrado por todo el Hollow.",
    ["If you manage to excavate any artefacts, I'd be willing to give you some Spooky tokens in exchange."] = "Si logras excavar algún artefacto, estaré dispuesto a darte algunas fichas Spooky a cambio.",
    ["I can also impart a bit of my knowledge of prayer on you, as well as some more Spooky tokens, in exchange for any ancient remains you find while working within the Hollow."] = "También puedo impartirte un poco de mis conocimientos sobre la oración, así como algunas fichas más espeluznantes, a cambio de cualquier resto antiguo que encuentres mientras trabajas en el Hueco.",
    ["*yawn* I'd very much like to lay them to rest if you bring me a full set."] = "*bostezo* Me gustaría mucho dejarlos descansar si me traes un juego completo.",
    ["Can I see your collections?"] = "¿Puedo ver tus colecciones?",
    ["*yawn* Goodbye."] = "*bostezo* Adiós.",
    ["The following has been added to your currency pouch: 1,500 x Spooky tokens."] = "Se ha agregado lo siguiente a su bolsa de divisas: 1500 x tokens Spooky.",
    ["You have reached the Spooky token soft cap of 150,000. You need to spend some tokens in the Spooky Reward Shop before you can earn more."] = "Ha alcanzado el límite flexible del token Spooky de 150.000. Debes gastar algunas fichas en Spooky Reward Shop antes de poder ganar más.",
    ["The following has been added to your currency pouch: [number] x Spooky tokens"] = "Se ha agregado lo siguiente a su bolsa de divisas: [número] x tokens Spooky",
    ["The following has been added to your currency pouch: 1,000 x Spooky tokens."] = "Se ha agregado lo siguiente a su bolsa de divisas: 1000 x tokens Spooky.",
    ["You contribute [number] [item/items] to the collection."] = "Contribuyes con [número] [item/items] a la colección.",
    ["You do not have any of that item."] = "No tienes nada de ese artículo.",
    ["You have nothing to contribute at this time."] = "No tienes nada que aportar en este momento.",
    ["You've already contributed that."] = "Ya has contribuido con eso.",
    ["You find [number] [Material]."] = "Encontrarás [número] [Material].",
    ["You find"] = "Encuentras",
    ["The material you were collecting is no longer available at this spot."] = "El material que estabas recopilando ya no está disponible en este lugar.",
    ["You can only buy 10 Effigies a month from Vicendithas, you can by [number] more."] = "Solo puedes comprar 10 Efigies al mes en Vicendithas, puedes comprar [número] más.",
    ["You can once again collect materials in the Effigy Incubator under Anachronia."] = "Una vez más puedes recolectar materiales en Effigy Incubator en Anacronia.",
    ["Category:NPC dialogue"] = "Categoría: Diálogo NPC",
    ["Category:Scenery transcripts"] = "Categoría: Transcripciones de paisajes",
    ["Category:Tutorial transcripts"] = "Categoría: Transcripciones de tutoriales",
    ["Hi. Interesting building you have here."] = "Hola. Interesante edificio el que tenéis aquí.",
    ["Well, thanks."] = "Bueno, gracias.",
    ["Is there any way I can get involved?"] = "¿Hay alguna manera de participar?",
    ["Perhaps one day, but I'm looking for someone with better skills to be honest."] = "Quizás algún día, pero para ser honesto, estoy buscando a alguien con mejores habilidades.",
    ["Oh. Fair enough."] = "Oh. Me parece bien.",
    ["So, what exactly are you doing up here, all by yourself."] = "Entonces, ¿qué estás haciendo exactamente aquí arriba, solo?",
    ["Oh, me keeping very close watch on horizon - it very important job, keeping watch for king."] = "Oh, yo vigilo muy de cerca el horizonte; es un trabajo muy importante, vigilar al rey.",
    ["Don't you ever get lonely?"] = "¿Nunca te sientes solo?",
    ["Oh, not at all. There lots of rocks and sticks to talk to - dey make very good company."] = "Oh, para nada. Hay muchas piedras y palos con quienes hablar; son una muy buena compañía.",
    ["You talk to rocks and sticks?"] = "¿Hablas con piedras y palos?",
    ["Yeah, dey very good listeners."] = "Sí, son muy buenos oyentes.",
    ["Well, I can't argue with that."] = "Bueno, no puedo discutir eso.",
    ["So, what exactly are you doing up here, all by yourself?"] = "Entonces, ¿qué estás haciendo exactamente aquí arriba, solo?",
    ["Der usual. Watch fire. Watch horizon. Watch fire some more."] = "Lo habitual. Mira el fuego. Mirar horizonte. Mira disparar un poco más.",
    ["Sounds absolutely thrilling. Look, not to change the subject, but is there any way you could help me out? I've got a couple of questions."] = "Suena absolutamente emocionante. Mira, no quiero cambiar de tema, pero ¿hay alguna manera de que puedas ayudarme? Tengo un par de preguntas.",
    ["Hmm, not so sure. Maybe if you help trolls, me help you."] = "Hmm, no estoy tan seguro. Quizás si ayudas a los trolls, yo te ayude.",
    ["Oh but I'm a great friend of the trolls. Just ask anybo- I mean any troll."] = "Ah, pero soy un gran amigo de los trolls. Pregúntale a cualquiera, me refiero a cualquier troll.",
    ["Don't know. I think about it. Meanwhile, leave me alone and let me get back to watching fire."] = "No lo sé. Lo pienso. Mientras tanto, déjame en paz y déjame volver a mirar el fuego.",
    ["[My Arm's Big Adventure] in order to earn Egg's trust.}}"] = "[My Arm's Big Adventure] para ganarse la confianza de Egg.}}",
    ["Oh, hello. What you want?"] = "Oh, hola. ¿Lo que quieras?",
    ["Could you look after this beacon for me?"] = "¿Podrías cuidar esta baliza por mí?",
    ["Yes. Once beacon lit, leave 5 logs with me and I take care of fire for while."] = "Sí. Una vez encendida la baliza, deja 5 logs conmigo y yo me encargo del fuego por un tiempo.",
    ["I could, but fire dying out now. You make it blaze again, then I look after it for you."] = "Podría, pero el fuego ya se está extinguiendo. Tú lo haces arder de nuevo y luego yo lo cuido por ti.",
    ["You must give the fire tender five of the same type of log for the beacon."] = "Debes darle al bombero cinco troncos del mismo tipo para la baliza.",
    ["How can I tend fire for you? You not have enough good logs for me!"] = "¿Cómo puedo cuidar el fuego por ti? ¡No tienes suficiente logs bueno para mí!",
    ["Need five logs to tend fire. That okay with you?"] = "Necesitas cinco logs para cuidar el fuego. ¿Te parece bien?",
    ["Do you want to give five logs to the fire tender?"] = "¿Quieres darle cinco logs al fuego?",
    ["Here are five logs for you."] = "Aquí tienes cinco logs para ti.",
    ["Thanks. I use these five logs to keep beacon burning while you away."] = "Gracias. Utilizo estos cinco logs para mantener la baliza encendida mientras estás fuera.",
    ["I think I'll keep hold of my logs for now."] = "Creo que conservaré mi logs por ahora.",
    ["Okay. You know where I am if you change mind."] = "Está bien. Sabes dónde estoy si cambias de opinión.",
    ["Yes. Please don't ask me for confirmation in future."] = "Sí. Por favor, no me pidas confirmación en el futuro.",
    ["Of course. I use logs you already left with me."] = "Por supuesto. Yo uso logs que ya me dejaste.",
    ["Can you tell me about other beacons?"] = "¿Puedes hablarme de otras balizas?",
    ["Here you go. Have look at my map."] = "Aquí tienes. Mira mi mapa.",
    ["Is it possible to get information about beacons that are further away?"] = "¿Es posible obtener información sobre balizas que están más alejadas?",
    ["Hmm, me have sharp eyes, can see very far. Can tell you about all lit beacons in both directions from here. But, little flappy macaw can see much further still."] = "Hmm, tengo ojos agudos, puedo ver muy lejos. Puedo informarle sobre todas las balizas encendidas en ambas direcciones desde aquí. Pero el pequeño guacamayo flappy puede ver mucho más lejos aún.",
    ["Flappy macaw?"] = "¿Guacamaya Flappy?",
    ["If you brings Egg a little flappy macaw, I tell you anything you want to know about ALL de beacons!"] = "Si le traes a Egg una pequeña guacamaya flappy, ¡te cuento todo lo que quieras saber sobre TODAS las balizas!",
    ["Macaw can fly high into air and see long distance. They smart enough to report about things very much far away."] = "El guacamayo puede volar alto en el aire y ver a larga distancia. Son lo suficientemente inteligentes como para informar sobre cosas muy lejanas.",
    ["You have macaw there in your pack. You give macaw, I tell you about other beacons."] = "Tienes guacamayo ahí en tu mochila. Le das guacamayo, te hablo de otras balizas.",
    ["How's it going?"] = "¿Cómo te va?",
    ["Oh, it going great! Nice, rocky mountain. Nice, scenic dirt. Best of all, it a nice, quiet day - so far, no danger in sight, though me not stop looking."] = "¡Oh, va genial! Bonita montaña rocosa. Tierra agradable y pintoresca. Lo mejor de todo es que es un día agradable y tranquilo; hasta el momento no hay peligro a la vista, aunque no dejo de mirar.",
    ["I'm done talking to you, now!"] = "¡Ya terminé de hablar contigo!",
    ["Goodbye den, little human."] = "Adiós guarida, pequeño humano.",
    ["Do you want to give the fire tender your macaw?"] = "¿Quieres darle al fuego tierno tu guacamayo?",
    ["Thank you. Macaw help me tell you more about de other beacons."] = "Gracias. Guacamayo ayúdame a contarte más sobre las otras balizas.",
    ["I think I'll keep my macaw for now."] = "Creo que me quedaré con mi guacamaya por ahora.",
    ["I've already given her a macaw; she doesn't need another."] = "Ya le regalé una guacamaya; ella no necesita otra.",
    ["There's no fire here for the fire tender to tend."] = "Aquí no hay fuego para que lo atienda el bombero.",
    ["Since I'm here and the beacon's fire is dying down, I might as well tend the fire myself."] = "Ya que estoy aquí y el fuego de la baliza se está apagando, también podría cuidarlo yo mismo.",
    ["The fire tender needs five of the same type of log to maintain this fire."] = "El bombero necesita cinco troncos del mismo tipo para mantener este fuego.",
    ["You give the fire tender 5 [type] logs."] = "Le das al fuego tierno 5 [type] logs.",
    ["I think I'll hang on to my logs after all."] = "Creo que, después de todo, me quedaré con mi logs.",
    ["Yes. Please don't ask me for confirmation again."] = "Sí. Por favor, no vuelvas a pedirme confirmación.",
    ["You've already left logs with this fire tender."] = "Ya saliste de logs con este ténder de fuego.",
    ["Oi! Get away from that! Until you've proven yourself a true ally of Varrock, you can't use that!"] = "¡Oye! ¡Aléjate de eso! Hasta que no hayas demostrado que eres un verdadero aliado de Varrock, ¡no podrás usar eso!",
    ["You need to claim the reward for the elite set Tasks in Varrock to use this chest."] = "Debes reclamar la recompensa por las tareas del conjunto de élite en Varrock para usar este cofre.",
    ["Welcome to the Artisans' Workshop. We've got normal smithing in the front, and burial smithing in the back!"] = "Bienvenido al Taller de Artesanos. ¡Tenemos herrería normal en el frente y herrería funeraria en la parte trasera!",
    ["Also, I... my cousin will occasionally stop by and hand you some ceremonial sword plans to complete for extra experience."] = "Además, yo... mi primo de vez en cuando pasa por aquí y te entrega algunos planos de espada ceremoniales para que los completes y obtengas experiencia adicional.",
    ["What would you like to say?"] = "¿Qué te gustaría decir?",
    ["What's a ceremonial sword?"] = "¿Qué es una espada ceremonial?",
    ["A ceremonial sword distinguishes the wielder from his peers. They are items of beauty and craftsmanship that are favoured by officers and the very rich."] = "Una espada ceremonial distingue al portador de sus compañeros. Son artículos de belleza y artesanía preferidos por los oficiales y los muy ricos.",
    ["I'm guessing they're expensive?"] = "¿Supongo que son caros?",
    ["Quite so. We use only the purest metal to get the most malleable and perfect swords. Each blade requires a lot of ore, which we smelt into a pure, dense metal. But if we give you some plans, we'll supply all the materials so you'll be able to freely smith your ceremonial sword!"] = "Así es. Utilizamos sólo el metal más puro para conseguir las espadas más maleables y perfectas. Cada hoja requiere una gran cantidad de mineral, que fundimos hasta obtener un metal puro y denso. ¡Pero si te damos algunos planos, te proporcionaremos todos los materiales para que puedas forjar libremente tu espada ceremonial!",
    ["Can you show me how to make a ceremonial sword?"] = "¿Puedes mostrarme cómo hacer una espada ceremonial?",
    ["[You need to hammer the sword into the design above.]"] = "[Debes clavar la espada en el diseño de arriba.]",
    ["[Choose points along the sword, hammering away as it cools. Once the sword is cool, you will no longer be able to work the sword.]"] = "[Elija puntos a lo largo de la espada y golpéelos mientras se enfría. Una vez que la espada esté fría, ya no podrás usarla.]",
    ["[There are different strengths of 'hit'.]"] = "[Hay diferentes puntos fuertes del \"golpe\".]",
    ["[pic=Hammer detail.png]"] = "[pic=Martillo detail.png]",
    ["Once your sword is as close to the plans as possible, or it has cooled down, speak to me."] = "Una vez que tu espada esté lo más cerca posible de los planos o se haya enfriado, habla conmigo.",
    ["I'll reward you with extra experience based on how closely you kept to the design."] = "Te recompensaré con experiencia adicional según lo cerca que te hayas mantenido del diseño.",
    ["cond=If the player has ceremonial sword plans in their backpack"] = "cond=Si el player tiene planos de espada ceremoniales en su backpack",
    ["Your sword is awarded [number]% of its potential experience. Reasonable work."] = "Tu espada recibe el [número]% de su experiencia potencial. Trabajo razonable.",
    ["Your sword is awarded [number]% of its potential experience."] = "Tu espada recibe el [número]% de su experiencia potencial.",
    ["I am Egil, ceremonial sword specialist and, apparently, one of the workshop's more senior artisans."] = "Soy Egil, especialista en espadas ceremoniales y, aparentemente, uno de los artesanos más veteranos del taller.",
    ["Apparently?"] = "¿Aparentemente?",
    ["I don't hold much stock in titles. They garnish the ego, but are rather impractical."] = "No tengo muchas acciones en títulos. Adornan el ego, pero son bastante poco prácticos.",
    ["Can I change my cannon?"] = "¿Puedo cambiar mi cañón?",
    ["I'm afraid you don't have any cannon upgrades unlocked. You can unlock golden and royale cannon upgrades here at my store, or different upgrades through other methods you may uncover on your travels."] = "Me temo que no tienes ninguna mejora de cañón desbloqueada. Puedes desbloquear mejoras de cañones dorados y reales aquí en mi tienda, o diferentes actualizaciones a través de otros métodos que puedas descubrir en tus viajes.",
    ["Dwarf multicannon."] = "Multicañón enano.",
    ["You need to bring a golden, royale, or siege engine multicannon to exchange for a normal dwarf multicannon."] = "Debes traer un cañón múltiple dorado, real o de asedio para cambiarlo por un cañón múltiple enano normal.",
    ["Don't waste my time, we're not giving you multicannons for free! You'll need to bring in a multicannon and I'll convert it."] = "¡No me hagas perder el tiempo, no te daremos multicañones gratis! Necesitarás traer un cañón múltiple y lo convertiré.",
    ["Gold multicannon."] = "Multicañón de oro.",
    ["You need to bring a normal, royale, or siege engine multicannon to exchange for a golden dwarf multicannon."] = "Debes traer un cañón múltiple normal, real o de asedio para cambiarlo por un cañón múltiple enano dorado.",
    ["cond=If the player has unlocked the royale cannon:"] = "cond=Si el player ha desbloqueado el cañón real:",
    ["You need to bring a normal, golden, or siege engine multicannon to exchange for a royale dwarf multicannon."] = "Debes traer un cañón múltiple normal, dorado o de asedio para cambiarlo por un cañón múltiple enano real.",
    ["What would you like to say:"] = "¿Qué te gustaría decir?",
    ["Luminite Injector?"] = "¿Inyector de luminita?",
    ["What is a luminite injector?"] = "¿Qué es un inyector de luminita?",
    ["If you activate it anywhere in the workshop, it'll overload the pipes within the workshop, causing you and everyone else to generate more progress while smithing!"] = "Si lo activas en cualquier parte del taller, sobrecargará las tuberías dentro del taller, lo que hará que tú y todos los demás generen más progreso mientras forjan.",
    ["That sounds dangerous. How long does it last?"] = "Eso suena peligroso. ¿Cuánto dura?",
    ["Ah, the workshop can take it! She might burst a pipe every now and then, though. They each last for 5 minutes, but you can queue several up to work at once."] = "¡Ah, el taller puede soportarlo! Pero de vez en cuando podría reventar una tubería. Cada uno dura 5 minutos, pero puedes poner varios en cola para trabajar a la vez.",
    ["In fact, there is one active right now! It'll expire in [time given in minutes and seconds]."] = "De hecho, ¡hay uno activo ahora mismo! Caducará en [time given in minutes and seconds].",
    ["Are there any rewards?"] = "¿Hay alguna recompensa?",
    ["Goodbye."] = "Adiós.",
    ["You don't have anything planted in that patch. Plant something and I might agree to look after it for you."] = "No tienes nada plantado en ese parche. Planta algo y tal vez acepte cuidarlo por ti.",
    ["I want [number] [items] for that."] = "Quiero [número] [items] para eso.",
    ["Thanks, maybe another time."] = "Gracias, tal vez en otro momento.",
    ["Pay [number] [items]?"] = "¿Pagar [número] [items]?",
    ["That'll do nicely, [sir/madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [sir/madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["The gardener is now looking after the patch for you."] = "El jardinero ahora se ocupará del parche por usted.",
    ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
    ["I don't know what you're talking about - I'm already looking after that patch for you."] = "No sé de qué estás hablando. Ya estoy cuidando ese parche por ti.",
    ["Oh sorry, I forgot."] = "Oh, lo siento, lo olvidé.",
    ["I think you should claim the XP from that patch before having it chopped down."] = "Creo que deberías reclamar los XP de ese parche antes de eliminarlo.",
    ["Pay 200 gp to have the tree chopped down?"] = "¿Pagar 200 po para que talen el árbol?",
    ["Yes, get rid of the tree."] = "Sí, deshazte del árbol.",
    ["I'll want 200 gp for chopping down that tree."] = "Querré 200 po por talar ese árbol.",
    ["You can not afford that."] = "No puedes permitirte eso.",
    ["The gardener obligingly removes your tree."] = "El jardinero amablemente retira su árbol.",
    ["Would you chop my tree down for me?"] = "¿Podrías talar mi árbol por mí?",
    ["You look like you could chop it down yourself. I can chop the tree down for you if you like, but I'll want 200 gp to make it worth my while."] = "Parece que podrías cortarlo tú mismo. Puedo talar el árbol si quieres, pero necesitaré 200 po para que valga la pena.",
    ["200 gp? I'll do it myself."] = "¿200 po? Lo haré yo mismo.",
    ["Okay, go ahead."] = "Está bien, adelante.",
    ["I don't have 200 gp I'm afraid."] = "Me temo que no tengo 200 po.",
    ["Would you look after my crops for me?"] = "¿Cuidarías mis cultivos por mí?",
    ["If you like, but I want [number] [item] for that."] = "Si quieres, pero quiero [número] [item] para eso.",
    ["I'm afraid I don't have enough of those at the moment."] = "Me temo que no tengo suficientes en este momento.",
    ["Well, I'm not wasting my time for free."] = "Bueno, no voy a perder el tiempo gratis.",
    ["Okay, it's a deal."] = "Está bien, es un trato.",
    ["That'll do nicely, [Sir/Madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [Sir/Madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["No, that's too much."] = "No, eso es demasiado.",
    ["Can you stop weeding my farming patches please."] = "¿Puedes dejar de desherbar mis parcelas de cultivo, por favor?",
    ["Sure, I'll stop weeding them now."] = "Claro, dejaré de eliminarlos ahora.",
    ["Can you keep my farming patches weeded please?"] = "¿Puedes mantener mis parcelas de cultivo desyerbadas, por favor?",
    ["That shouldn't be a problem, Martin said I should give you special attention for your help with the fairies! Be sure to clear your allotment though as I don't want to interupt their growth!"] = "Eso no debería ser un problema, ¡Martin dijo que debería darte especial atención por tu ayuda con las hadas! ¡Asegúrate de limpiar tu asignación ya que no quiero interrumpir su crecimiento!",
    ["Can you sell me something?"] = "¿Puedes venderme algo?",
    ["That depends on whether I have it to sell. What is it that you're looking for?"] = "Eso depende de si lo tengo para vender. ¿Qué es lo que estás buscando?",
    ["That's all, thanks."] = "Eso es todo, gracias.",
    ["Some plant cure."] = "Alguna cura vegetal.",
    ["Plant cure, eh? I might have some put aside for myself. Tell you what, I'll sell you some plant cure for 25 gp if you like."] = "Cura vegetal, ¿eh? Quizás tenga algo reservado para mí. Te diré una cosa, te venderé una cura vegetal por 25 po si quieres.",
    ["I don't have enough money for that, I'm afraid."] = "Me temo que no tengo suficiente dinero para eso.",
    ["Yes, that sounds like a fair price."] = "Sí, parece un precio justo.",
    ["No thanks, I can get that much cheaper elsewhere."] = "No, gracias, puedo conseguirlo mucho más barato en otro sitio.",
    ["A bucket of compost."] = "Un balde de abono.",
    ["A bucket of compost, eh? I might have one spare... tell you what, I'll sell it to you for 35 gp if you like."] = "Un balde de abono, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 35 po si quieres.",
    ["A rake."] = "Un rastrillo.",
    ["A rake, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un rastrillo, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See more items)"] = "(Ver más artículos)",
    ["A watering can"] = "una regadera",
    ["A watering can."] = "Una regadera.",
    ["A watering can, eh? I might have one spare... tell you what, I'll sell it to you for 25 gp if you like."] = "Una regadera, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 25 po si quieres.",
    ["A gardening trowel"] = "Una paleta de jardinería",
    ["A gardening trowel."] = "Una paleta de jardinería.",
    ["A gardening trowel, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Una paleta de jardín, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["A seed dibber"] = "Un zambullidor de semillas",
    ["A seed dibber."] = "Un arrancador de semillas.",
    ["A seed dibber, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un zambullidor de semillas, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See previous items)"] = "(Ver artículos anteriores)",
    ["Forget it."] = "Olvídalo.",
    ["Forget it, you don't have anything I need."] = "Olvídalo, no tienes nada que necesite.",
    ["That looks like something that you can make normal compost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of compost."] = "Parece algo con lo que se puede hacer abono normal. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de abono.",
    ["That looks like something that you can make supercompost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of supercompost."] = "Parece algo con lo que se puede hacer supercompost. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de supercompost.",
    ["Of course, I will aid you. If you have any chronicle fragments in your bank, I can draw them here so don't worry about collecting them. Although, you do have access to Guthix's shrine. If you take your fragments there you will be able to offer them for a greater reward than I can give. Would you still like to offer them to me?"] = "Por supuesto que te ayudaré. Si tienes fragmentos de crónica en tu banco, puedo sacarlos aquí, así que no te preocupes por recolectarlos. Aunque tienes acceso al santuario de Guthix. Si llevas allí tus fragmentos podrás ofrecerlos por una recompensa mayor que la que Yo puedo dar. ¿Aún te gustaría ofrecérmelos?",
    ["Would you like Eilwynn to convert your chronicle fragments?"] = "¿Quieres que Eilwynn convierta tus fragmentos de crónica?",
    ["You don't have any chronicle fragments to hand in."] = "No tienes ningún fragmento de crónica para entregar.",
    ["Hello."] = "Hola.",
    ["Good day, Your Royal Highness."] = "Buenos días, Su Alteza Real.",
    ["*(If the player has some valkyrie feathers, and hasn't unlocked all the rewards:)*"] = "*(Si el player tiene algunas plumas de valquiria y no ha desbloqueado todas las recompensas:)*",
    ["*(Dialogue from handing in occurs, then continues below.)*"] = "*(Se produce un diálogo desde la entrega, luego continúa a continuación.)*",
    ["Here weeps a world-wound, where the essence of the Most High bleeds into the air. I fear the End of Things may be upon us. With Hati, Sköll and Fenrir once more in the world, I must stand vigil here to keep them at bay."] = "Aquí llora una herida del mundo, donde la esencia del Altísimo sangra en el aire. Temo que el fin de las cosas esté sobre nosotros. Con Hati, Sköll y Fenrir una vez más en el mundo, debo permanecer alerta aquí para mantenerlos a raya.",
    ["*(If this option wasn't used last:)*"] = "*(Si esta opción no se utilizó la última vez:)*",
    ["I am Eir, a valkyrie - guardian of the realm to which the longhall people go when they are slain. We met once, when you approached its gates before your time."] = "Soy Eir, una valquiria, guardiana del reino al que va la gente de Longhall cuando son asesinados. Nos conocimos una vez, cuando te acercaste a sus puertas antes de tiempo.",
    ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
    ["*(After another dialogue option has been chosen, and if not chosen last:)*"] = "*(Después de haber elegido otra opción de diálogo, y si no se eligió al final:)*",
    ["*(Repeats the initial dialogue then returns to the previous options.)*"] = "*(Repite el diálogo inicial y luego regresa a las opciones anteriores.)*",
    ["*(If this option wasn't used last, and after the \"Can I help?\" option after asking about rewards, or after \"What rewards can I get\" after asking if you can help:)*"] = "*(Si esta opción no se usó la última vez, y después de la opción \"¿Puedo ayudar?\" después de preguntar sobre las recompensas, o después de \"¿Qué recompensas puedo obtener\" después de preguntar si puedes ayudar:)*",
    ["The End of Things?"] = "¿El fin de las cosas?",
    ["The world's last days, as the scrolls and sagas say: when god fights god, and every field is drenched with heroes' blood. Did we not speak of this, when we last met? Now that Fenrir appears, we fear the End of Things is at hand. Inside my hall, the glorious dead prepare to play their role. I, too, must arm myself for war."] = "Los últimos días del mundo, como dicen los pergaminos y las sagas: cuando dios lucha contra dios, y cada campo está empapado de sangre de héroes. ¿No hablamos de esto la última vez que nos vimos? Ahora que aparece Fenrir, tememos que el fin de las cosas esté cerca. Dentro de mi salón, los muertos gloriosos se preparan para desempeñar su papel. Yo también debo armarme para la guerra.",
    ["What rewards can I get?"] = "¿Qué recompensas puedo obtener?",
    ["You will be rewarded with a variety of Jormungand weapons."] = "Serás recompensado con una variedad de armas Jormungand.",
    ["Oh boy! What kind of weapons!?"] = "¡Dios mío! ¿¡Qué tipo de armas!?",
    ["There will be some swords, a staff, and a bow. As well as a matching Jormungand cape. But if that's not your style we also have some Huginn and Muninn blades!"] = "Habrá algunas espadas, un staff y un arco. Además de una capa Jormungand a juego. Pero si ese no es tu estilo, ¡también tenemos algunas palas Huginn y Muninn!",
    ["Huginn and Muninn blades! It's just what I've always wanted! There can't possibly be anything else."] = "¡Cuchillas Huginn y Muninn! ¡Es justo lo que siempre he querido! No puede haber nada más.",
    ["You will also have exclusive access to our chariot for all your teleportation needs and an adorable Valkyrie bobblehead pet."] = "También tendrás acceso exclusivo a nuestro carro para todas tus necesidades de teletransportación y a una adorable mascota cabezón Valquiria.",
    ["Wow! Really!? I feel like the End of Things has come and I've gone to the Hall of Fallen Warriors!"] = "¡Guau! ¿¡En realidad!? ¡Siento que ha llegado el fin de las cosas y he ido al Salón de los Guerreros Caídos!",
    ["... I'm just going to pretend you didn't say that. If you can gather enough valkyrie feathers to restore our wings you will gain the greatest honour of all. I will make you an honourary valkyrie with the 'of the Valkyrie' title."] = "... Voy a fingir que no dijiste eso. Si puedes reunir suficientes plumas de valquiria para restaurar nuestras alas, obtendrás el mayor honor de todos. Te haré una valquiria honoraria con el título de \"de la Valquiria\".",
    ["Amazing! Sounds like I better get to it!"] = "¡Increíble! ¡Parece que será mejor que lo haga!",
    ["We must bring the valkyries into this world to stop the End of Things. To do so I need you to bring me Valkyrie feathers, which are hidden around the world."] = "Debemos traer las valquirias a este mundo para detener el Fin de las Cosas. Para ello necesito que me traigas plumas de Valquiria, que se encuentran escondidas en todo el mundo.",
    ["*(If the Jormungand ring hasn't been returned:)*"] = "*(Si el anillo Jormungand no ha sido devuelto:)*",
    ["You can also bring me the Jormungand ring, I am not of this world and cannot retrieve it myself. Hati, Sköll or Fenrir may have it. It could also be hidden within the greater wisps that float around the world-wound."] = "También puedes traerme el anillo de Jormungand, no soy de este mundo y no puedo recuperarlo yo mismo. Puede que Hati, Sköll o Fenrir lo tengan. También podría estar oculto dentro de los mechones más grandes que flotan alrededor del mundo.",
    ["*(Continues below.)*"] = "*(Continúa a continuación.)*",
    ["I will reward you greatly for any help you can provide."] = "Te recompensaré enormemente por cualquier ayuda que puedas brindar.",
    ["*(The dialogue terminates.)*"] = "*(El diálogo termina.)*",
    ["You have my thanks adventurer. We could not have repelled the wolves without you."] = "Tienes mi agradecimiento aventurero. No podríamos haber repelido a los lobos sin ti.",
    ["Always happy to help, especially when it comes to the impending apocalypse."] = "Siempre dispuesto a ayudar, especialmente cuando se trata del inminente apocalipsis.",
    ["So, what happens now?"] = "Entonces, ¿qué pasa ahora?",
    ["My valkyries and I shall return to the Fremennik spiritual realm and resume our usual duties."] = "Mis valquirias y yo regresaremos al reino espiritual de Fremennik y reanudaremos nuestros deberes habituales.",
    ["That sounds like fun! Maybe someday I'll come visit!"] = "¡Eso suena divertido! ¡Quizás algún día venga a visitarte!",
    ["Again!"] = "¡Otra vez!",
    ["Let's hope not adventurer..."] = "Esperemos que no sea aventurero...",
    ["You do not have anything to hand in."] = "No tienes nada que entregar.",
    ["Handing in event currency will increase your progress for this event unlocking unique rewards. This will remove currency up to the amount that is required to complete the event."] = "Entregar la moneda del evento aumentará tu progreso en este evento y desbloqueará recompensas únicas. Esto eliminará moneda hasta la cantidad necesaria para completar el evento.",
    ["Do you wish to continue?"] = "¿Quieres continuar?",
    ["*(Dialogue terminates.)*"] = "*(El diálogo termina.)*",
    ["Yes"] = "si",
    ["*(If not handing in the 20,000th feather:)*"] = "*(Si no entregas la pluma número 20.000:)*",
    ["You hand in [number] Valkyrie Feathers. You need to hand in [number] more to complete the event."] = "Entregas [número] Valkyrie Feathers. Debes entregar [número] más para completar el evento.",
    ["*(If handing in the 20,000th feather:)*"] = "*(Si entregas la pluma número 20.000:)*",
    ["You have completed the event."] = "Has completado el evento.",
    ["*(If no new rewards are unlocked, and none of the rewards have been unlocked before:)*"] = "*(Si no se desbloquean nuevas recompensas y ninguna de las recompensas se ha desbloqueado antes:)*",
    ["You haven't handed in enough valkyrie feathers for me to give you any rewards."] = "No me has entregado suficientes plumas de valquiria para darte ninguna recompensa.",
    ["*(If no new rewards are unlocked, but some of the rewards have been unlocked before:)*"] = "*(Si no se desbloquean nuevas recompensas, pero algunas de las recompensas se han desbloqueado antes:)*",
    ["You have more rewards to unlock. Collect more valkyrie feathers to get them."] = "Tienes más recompensas para desbloquear. Recoge más plumas de valquiria para conseguirlas.",
    ["You have unlocked X/9 of the rewards for the Winter Wolves event."] = "Has desbloqueado X/9 de las recompensas del evento Winter Wolves.",
    ["*(If rewards are unlocked:)*"] = "*(Si las recompensas están desbloqueadas:)*",
    ["*(Repeated once for each item unlocked)*"] = "*(Se repite una vez por cada elemento desbloqueado)*",
    ["Congratulations, you have unlocked [reward]."] = "Felicitaciones, has desbloqueado [reward].",
    ["You have unlocked all of the rewards available for this event. You can convert any remaining currency into consumable rewards."] = "Has desbloqueado todas las recompensas disponibles para este evento. Puedes convertir cualquier moneda restante en recompensas consumibles.",
    ["I have brought you the Jormungand ring!"] = "¡Te he traído el anillo Jormungand!",
    ["Excellent work hero, if you would present the ring to me I can reward you justly. I can aid you in Divination, or in Prayer. Which do you choose?"] = "Excelente trabajo héroe, si me presentas el anillo puedo recompensarte justamente. Puedo ayudarte en Divination, o en Prayer. ¿Cuál eliges?",
    ["You have Valhalla's thanks! Depart in peace, hero."] = "¡Tienes el agradecimiento de Valhalla! Vete en paz, héroe.",
    ["You have nothing to hand in"] = "No tienes nada que entregar",
    ["Eir! I defeated the secret fourth winter wolf!"] = "¡Eir! ¡Derroté al cuarto lobo secreto del invierno!",
    ["Fourth wolf? Adventurer, there are but three wolves..."] = "¿Cuarto lobo? Aventurero, sólo hay tres lobos...",
    ["But... I got its ring, it's gotta be as valuable as the Jormungand ring right?"] = "Pero... tengo su anillo, debe ser tan valioso como el anillo de Jormungand, ¿verdad?",
    ["... I do not know what this is."] = "... No sé qué es esto.",
    ["Can I have a reward?"] = "¿Puedo recibir una recompensa?",
    ["... Please?"] = "... ¿Por favor?",
    ["... *sigh* Fine... I guess I can aid you in Divination... or in Prayer... Which do you choose?"] = "... *suspiro* Bien... Supongo que puedo ayudarte en Divination... o en Prayer... ¿Cuál eliges?",
    ["There you go..."] = "Ahí tienes...",
    ["You have nothing to hand in."] = "No tienes nada que entregar.",
    ["Seers say these golden apples once kept the gods young. But no apples could protect my god, the Most High Guthix, from the trickster who woke him to his death. Here weeps a world-wound, where the essence of the Most High bleeds into the air. I fear the End of Things may be upon us. With Hati and Sköll oncemore in the world, I must stand vigil here to keep them at bay."] = "Los videntes dicen que estas manzanas doradas alguna vez mantuvieron jóvenes a los dioses. Pero ninguna manzana pudo proteger a mi dios, el Altísimo Guthix, del embaucador que lo despertó hasta su muerte. Aquí llora una herida del mundo, donde la esencia del Altísimo sangra en el aire. Temo que el fin de las cosas esté sobre nosotros. Ahora que Hati y Sköll están de nuevo en el mundo, debo permanecer aquí vigilante para mantenerlos a raya.",
    ["*(After another dialogue option has been chosen:)*"] = "*(Después de haber elegido otra opción de diálogo:)*",
    ["*(Same as when talking to her for the first time.)*"] = "*(Igual que cuando hablé con ella por primera vez.)*",
    ["Bring me my arms: my spear and magic helmet. I am not of this world, and cannot reach them myself. Hati and Sköll have them - the wolves who chase the moon and sun. They also hide within the greater wisps that float around the world-wound. Each hero may find one, many times, but not both. To get the other, you must find another hero, and arrange a trade. Return to me with both and you will be rewarded."] = "Tráeme mis brazos: mi lanza y mi casco mágico. No soy de este mundo y no puedo alcanzarlos por mí mismo. Hati y Sköll los tienen: los lobos que persiguen la luna y el sol. También se esconden dentro de los mechones más grandes que flotan alrededor del mundo. Cada héroe puede encontrar uno, muchas veces, pero no ambas. Para conseguir el otro, debes encontrar otro héroe y concertar un intercambio. Vuelve a mí con ambos y serás recompensado.",
    ["I need my spear and helmet. The winter wolves have them, and the greater wisps of the world-wound."] = "Necesito mi lanza y mi casco. Los lobos del invierno los tienen, y los lobos más grandes del mundo están heridos.",
    ["*(Continues with the options from first time.)*"] = "*(Continúa con las opciones de la primera vez.)*",
    ["You have my helmet! But I also need my spear. Find another helmet, and trade it with another hero to get my spear, then bring them to me."] = "¡Tienes mi casco! Pero también necesito mi lanza. Encuentra otro casco, cámbialo con otro héroe para conseguir mi lanza y luego tráemelo.",
    ["You have my spear! But I also need my helmet. Find another spear, and trade it with another hero to get my helmet, and then bring them to me."] = "¡Tienes mi lanza! Pero también necesito mi casco. Encuentra otra lanza, cámbiala con otro héroe para conseguir mi casco y luego tráemela.",
    ["My spear and helmet! Thank you, hero. Will you give them to me?"] = "¡Mi lanza y mi casco! Gracias, héroe. ¿Me los darás?",
    ["Yes, take them."] = "Sí, llévalos.",
    ["I can aid you in Divination, or in Prayer. Which do you choose?"] = "Puedo ayudarte en Divination, o en Prayer. ¿Cuál eliges?",
    ["*(Skill selection interface opens.)*"] = "*(Se abre la interfaz de selección de habilidades.)*",
    ["*(If a selection isn't made:)*"] = "*(Si no se hace una selección:)*",
    ["You must choose an appropriate skill."] = "Debes elegir una habilidad adecuada.",
    ["*(If a selection is made:)*"] = "*(Si se hace una selección:)*",
    ["You have Valhalla's thanks! The semblance of my arms is yours to wear. Depart in peace, hero."] = "¡Tienes el agradecimiento de Valhalla! La apariencia de mis brazos es tuya para que la uses. Vete en paz, héroe.",
    ["You can now access cosmetic override versions of the valkyrie spear and helmet from the Wardrobe interface."] = "Ahora puedes acceder a versiones de anulación cosmética de la lanza y el casco de Valquiria desde la interfaz del Armario.",
    ["Not now."] = "Ahora no.",
    ["*(If there are clockwork pieces to hand in:)*"] = "*(Si hay piezas de relojería para entregar:)*",
    ["*(Dialogue from handing in clockwork pieces occurs, then continues below.)*"] = "*(Se produce un diálogo sobre la entrega de piezas de relojería y luego continúa a continuación.)*",
    ["Hello! I'm looking for people to help save Christmas. Would you be able to help?"] = "¡Hola! Estoy buscando personas para ayudar a salvar la Navidad. ¿Podrías ayudar?",
    ["Talk about..."] = "Hablar de...",
    ["*(Only if not asked last:)*"] = "*(Solo si no se preguntó al final:)*",
    ["My name is Eira. I'm Santa's head elf."] = "Mi nombre es Eira. Soy Santa's head elf.",
    ["Or at least I am at the moment!"] = "¡O al menos lo estoy en este momento!",
    ["We're having a few issues at the workshop and I need to get it all sorted before Santa gets back from his holidays."] = "Estamos teniendo algunos problemas en el taller y necesito solucionarlo todo antes de que Santa regrese de sus vacaciones.",
    ["What as happened?"] = "¿Qué pasó?",
    ["Santa is having his yearly holiday, just before the Christmas rush, but this year the snow implings aren't happy about it at all."] = "Santa está teniendo sus vacaciones anuales, justo antes de la temporada navideña, pero este año los implicados en la nieve no están nada contentos con eso.",
    ["They all want a holiday too, and because they can't have one they've decided to be naughty and steal all of the clockwork pieces from the workshop."] = "Todos ellos también quieren unas vacaciones y, como no pueden tenerlas, han decidido ser traviesos y robar todas las piezas de relojería del taller.",
    ["Clockwork pieces?"] = "¿Piezas de relojería?",
    ["Yes, they are used to make Santa's new toy for this year; a clockwork gnome pet."] = "Sí, se utilizan para hacer el nuevo juguete de Papá Noel para este año; una mascota gnomo mecánico.",
    ["So you can't make any more?"] = "¿Entonces no puedes hacer más?",
    ["Not until we get some of the clockwork pieces back, which is where you come in, I hope."] = "No hasta que recuperemos algunas de las piezas del mecanismo, que es donde tú entras, espero.",
    ["The snow implings have deposited the clockwork pieces all throughout Gielinor."] = "Los impactos de nieve han depositado las piezas del mecanismo de relojería por todo Gielinor.",
    ["You'll likely find them while you are doing your day to day activities."] = "Probablemente los encontrarás mientras realizas tus actividades diarias.",
    ["What should I do with them when I find them?"] = "¿Qué debo hacer con ellos cuando los encuentre?",
    ["If you could bring them back to me, that would be a huge help!"] = "Si pudieras devolvérmelos, ¡sería de gran ayuda!",
    ["I'll be able to get you some rewards for doing it too."] = "Yo también podré conseguirte algunas recompensas por hacerlo.",
    ["I'm hoping to get the whole thing cleared up before Santa comes back."] = "Espero aclarar todo antes de que regrese Santa.",
    ["Anything else I should know?"] = "¿Algo más que deba saber?",
    ["You might come across some of the naughty snow implings themselves."] = "Es posible que te encuentres con algunos de los implícitos traviesos de la nieve.",
    ["If you catch them they should have a pile of clockwork pieces on them."] = "Si los atrapas, deberían tener un montón de piezas de relojería.",
    ["I think if they run out of pieces that will head back to the workshop and get back to work."] = "Creo que si se quedan sin piezas regresarán al taller y volverán al trabajo.",
    ["At least, I hope that's what will happen."] = "Al menos, espero que eso sea lo que suceda.",
    ["What are the rewards?"] = "¿Cuáles son las recompensas?",
    ["Once we've got our stocks replenished I can fashion the clockwork pieces into some rewards for you."] = "Una vez que hayamos repuesto nuestras existencias, puedo convertir las piezas del mecanismo en algunas recompensas para ti.",
    ["There will be a clockwork shield and a clockwork crown, both very fetching."] = "Habrá un escudo mecánico y una corona mecánica, ambos muy atractivos.",
    ["Anything else?"] = "¿Algo más?",
    ["Yes, there will be a clockwork lemon. Flighty little thing. You can wind it up and watch it fly around your head!"] = "Sí, habrá un limón mecánico. Cosita voluble. ¡Puedes darle cuerda y verlo volar alrededor de tu cabeza!",
    ["Adorable but strange."] = "Adorable pero extraño.",
    ["And then there is, of course, the clockwork gnome pet."] = "Y luego está, por supuesto, la mascota del gnomo mecánico.",
    ["Considering you'll be helping us be able to make these for all the children this year, you should get one too."] = "Teniendo en cuenta que nos ayudarás a poder hacer estos para todos los niños este año, tú también deberías conseguir uno.",
    ["*(Only after asking something else:)*"] = "*(Solo después de preguntar algo más :)*",
    ["May you have lots of luck with all of your gathering!"] = "¡Que tengas mucha suerte con toda tu reunión!",
    ["Thanks for helping me collect up all of the clockwork pieces. I still have some time here to thank you for your efforts."] = "Gracias por ayudarme a reunir todas las piezas del mecanismo de relojería. Todavía tengo algo de tiempo aquí para agradecerles por sus esfuerzos.",
    ["You hand in [X] Clockwork pieces. You need to hand in [Y] more to complete the event."] = "Entregas piezas de relojería [X]. Debes entregar [Y] más para completar el evento.",
    ["*(Dialogue from claiming rewards occurs.)*"] = "*(Se produce un diálogo para reclamar recompensas.)*",
    ["You haven't handed in enough clockwork pieces for me to give you any rewards."] = "No me has entregado suficientes piezas de relojería para darte ninguna recompensa.",
    ["*(If a customisation is unlocked:)*"] = "*(Si una personalización está desbloqueada:)*",
    ["*(The following is repeated for all the unlocked rewards:)*"] = "*(Lo siguiente se repite para todas las recompensas desbloqueadas :)*",
    ["Congratulations, you have unlocked the [Clockwork Shield/Clockwork Crown/Clockwork Gnome Pet]."] = "Felicitaciones, ha desbloqueado el [Clockwork Shield/Clockwork Crown/Clockwork Gnome Pet].",
    ["*(If an item is rewarded:)*"] = "*(Si un artículo es recompensado:)*",
    ["*(If the inventory is full:)*"] = "*(Si el inventario está lleno:)*",
    ["You do not have enough inventory space for some of the rewards. Please make some space and try again."] = "No tienes suficiente espacio en el inventario para algunas de las recompensas. Por favor, deja algo de espacio e inténtalo de nuevo.",
    ["*(If there is space in inventory:)*"] = "*(Si hay espacio en el inventario:)*",
    ["Congratulations, you have been awarded [an event mystery box/the Clockwork Lemon item]."] = "Felicitaciones, ha sido galardonado con [an event mystery box/the Clockwork Lemon item].",
    ["You have unlocked [X]/6 of the rewards for the Going Like Clockwork event."] = "Has desbloqueado [X]/6 de las recompensas del evento Going Like Clockwork.",
    ["You have more rewards to unlock. Collect more clockwork pieces to get them."] = "Tienes más recompensas para desbloquear. Recoge más piezas de relojería para conseguirlas.",
    ["You've already claimed all of the rewards I have to offer."] = "Ya has reclamado todas las recompensas que tengo para ofrecer.",
    ["You have unlocked all of the rewards available for this event. You can convert any remaining clockwork pieces into consumable rewards."] = "Has desbloqueado todas las recompensas disponibles para este evento. Puedes convertir las piezas de relojería restantes en recompensas consumibles.",
    ["How does the Terrorbird Racing work?"] = "¿Cómo funciona Terrorbird Racing?",
    ["These races are an extra part of the Christmas festivities for this year. They're very exciting."] = "Estas carreras son una parte extra de las festividades navideñas de este año. Son muy emocionantes.",
    ["You can race once an hour and the idea is to get round all of the 8 gates in the quickest time possible."] = "Puedes correr una vez por hora y la idea es pasar las 8 puertas en el menor tiempo posible.",
    ["The quicker you are the greater your reward will be at the end of the race."] = "Cuanto más rápido seas, mayor será tu recompensa al final de la carrera.",
    ["As you go through each gate you'll be told where the next gate can be found."] = "A medida que atraviesas cada puerta, se te indicará dónde se puede encontrar la siguiente puerta.",
    ["Remember, you'll need to be wearing a Terrorbird mount to be able to take part. It adds to the fun!"] = "Recuerda, necesitarás llevar una montura Terrorbird para poder participar. ¡Se suma a la diversión!",
    ["Where can I get a Terrorbird costume?"] = "¿Dónde puedo conseguir un disfraz de Terrorbird?",
    ["You can wear your own Terrorbird mount costume but there is a special Christmas themed one available for free in Solomon's Store."] = "Puedes usar tu propio disfraz de montura Terrorbird, pero hay uno especial con temática navideña disponible de forma gratuita en la tienda de Solomon.",
    ["How do the hi-scores work?"] = "¿Cómo funcionan las puntuaciones altas?",
    ["The top 10 quickest times are stored and can be seen by checking on any of the race gates."] = "Los 10 tiempos más rápidos se almacenan y se pueden ver consultando cualquiera de las puertas de la carrera.",
    ["Hopefully you'll make the top 10!"] = "¡Ojalá llegues al top 10!",
    ["Bye for now."] = "Adiós por ahora.",
    ["Happy racing!"] = "¡Felices carreras!",
    ["Gosh, it's a nice day! Now, can I help you with tool storage, or a trip to Winkin's Farm, or something else?"] = "¡Dios, qué lindo día! Ahora, ¿puedo ayudarte con el almacenamiento de herramientas, con un viaje a Winkin's Farm o con algo más?",
    ["Tool storage."] = "Almacenamiento de herramientas.",
    ["What can you store?"] = "¿Qué puedes almacenar?",
    ["I can hold onto your rake, seed dibber, spade, secateurs, watering can and trowel - but not those trowels used for archaeology."] = "Puedo sostener tu rastrillo, sembrador, pala, tijeras de podar, regadera y paleta, pero no esas paletas que se usan en arqueología.",
    ["I can also store a few buckets and scarecrows for you, and even compost and supercompost. Of course, compost is essential for good Farming, so I can store lots of that for you."] = "También puedo guardarte algunos cubos y espantapájaros, e incluso abono y supercompost. Por supuesto, el abono es esencial para un buen Farming, así que puedo almacenar mucho para ti.",
    ["Also, if you hand me your Farming produce, I might be able to change it into banknotes."] = "Además, si me entregas tus productos Farming, tal vez pueda convertirlos en billetes.",
    ["So, would you like me to look after your Farming tools?"] = "Entonces, ¿te gustaría que cuidara tus herramientas Farming?",
    ["Yes, please."] = "Sí, por favor.",
    ["*(Farming Store opens)*"] = "*(Se abre la tienda Farming)*",
    ["What do you do with the tools you're storing?"] = "¿Qué haces con las herramientas que estás almacenando?",
    ["What do you do with the tools you're storing? They can't all possibly fit in your pockets!"] = "¿Qué haces con las herramientas que almacenas? ¡No caben todos en tus bolsillos!",
    ["Of course not. I have a toolshed. It is rather a curious shed, though. Sometimes, items just seem to appear in there."] = "Por supuesto que no. Tengo un cobertizo para herramientas. Aunque es un cobertizo bastante curioso. A veces, los elementos simplemente parecen aparecer allí.",
    ["So, would you like me to look after your tools?"] = "Entonces, ¿te gustaría que cuidara tus herramientas?",
    ["Yes please."] = "Sí, por favor.",
    ["*(Same as above)*"] = "*(Igual que arriba)*",
    ["No thanks, I'll keep hold of my stuff."] = "No gracias, guardaré mis cosas.",
    ["*(Same as below)*"] = "*(Igual que a continuación)*",
    ["Well, I shall be here if you ever decide that I may be of service."] = "Bueno, estaré aquí si alguna vez decides que puedo ser útil.",
    ["Winkin's Farm."] = "La granja de Winkin.",
    ["Can you take me to Winkin's Farm?"] = "¿Puedes llevarme a Winkin's Farm?",
    ["Avach nimporto!"] = "¡Avach nimporto!",
    ["Actually, I'm fine."] = "En realidad, estoy bien.",
    ["Composting"] = "compostaje",
    ["*(Tool leprechaun dialogue)*"] = "*(diálogo Tool leprechaun)*",
    ["Other topics."] = "Otros temas.",
    ["Aren't you a bit tall for a leprechaun?"] = "¿No eres un poco alto para ser un duende?",
    ["I'm not a leprechaun! Why would you ask such a strange question?"] = "¡No soy un duende! ¿Por qué harías una pregunta tan extraña?",
    ["Well, you're looking after tools like leprechauns do."] = "Bueno, estás cuidando las herramientas como lo hacen los duendes.",
    ["I'm of the Crwys clan. We have a special affinity with nature. It is my duty and pleasure to tend this farming patch."] = "Soy del clan Crwys. Tenemos una afinidad especial con la naturaleza. Es mi deber y un placer cuidar de esta parcela agrícola.",
    ["*If item(s) cannot be exchanged for banknotes by a Tool leprechaun:*"] = "*Si los artículos no se pueden cambiar por billetes mediante un Tool leprechaun:*",
    ["Sorry, I can't turn that into a banknote."] = "Lo siento, no puedo convertir eso en un billete.",
    ["*If item(s) can be exchanged for banknotes by a Tool leprechaun:*"] = "*Si los artículos se pueden cambiar por billetes mediante un Tool leprechaun:*",
    ["*If you are exchanging exactly one item for banknotes:*"] = "*Si vas a cambiar exactamente un artículo por billetes:*",
    ["The elf exchanges your item for a banknote."] = "El elfo cambia tu artículo por un billete.",
    ["*If you are exchanging multiple items for banknotes:*"] = "*Si vas a cambiar varios artículos por billetes:*",
    ["The elf exchanges your items for banknotes."] = "El elfo cambia tus artículos por billetes.",
    ["*If item(s) are already in noted form: *"] = "*Si los artículos ya están en formato anotado: *",
    ["​**Eirlys:** That IS a banknote!"] = "​**Eirlys:** ¡Eso ES un billete!",
    ["Y..y..you hold the stone of..."] = "Y..y..tienes la piedra de...",
    ["There is no time."] = "No hay tiempo.",
    ["You can never let it be freed."] = "Nunca podrás dejar que sea liberado.",
    ["It's not time yet."] = "Aún no es el momento.",
    ["Who are you? What can't be freed? No time for what?"] = "¿Quién eres? ¿Qué no se puede liberar? ¿No hay tiempo para qué?",
    ["So many questions."] = "Muchas preguntas.",
    ["So little time."] = "Muy poco tiempo.",
    ["Liberate us."] = "Libéranos.",
    ["Free us."] = "Libéranos.",
    ["Don't let it out."] = "No lo dejes salir.",
    ["PROMISE US."] = "PROMETANOS.",
    ["I don't kno.."] = "No lo sé..",
    ["I promise."] = "Lo prometo.",
    ["It's coming for us."] = "Viene por nosotros.",
    ["We can no longer endure this pain."] = "Ya no podemos soportar este dolor.",
    ["We are not ready."] = "No estamos listos.",
    ["As you try to talk to the ghost you can't seem to find the words."] = "Mientras intentas hablar con el fantasma, parece que no puedes encontrar las palabras.",
    ["*You can only talk with the Guard while wielding any type of monkey greegree.*"] = "*Solo puedes hablar con el Guardia mientras empuñas cualquier tipo de mono greegree.*",
    ["Grrr ... What do you want?"] = "Grrr... ¿Qué quieres?",
    ["I must speak with Awowogei on a subject of great import."] = "Debo hablar con Awowogei sobre un tema de gran importancia.",
    ["As you wish."] = "Como desees.",
    ["I would like to leave now."] = "Me gustaría irme ahora.",
    ["Move!"] = "¡Muévete!",
    ["The Blade seemed almost drawn to this tiny moon. I later learned they shared a long history."] = "The Blade parecía casi atraído por esta pequeña luna. Más tarde supe que compartían una larga historia.",
    ["I discovered rents in the dimensional fabric...wounds in the weave between worlds that will not heal."] = "Descubrí desgarros en el tejido dimensional... heridas en el tejido entre mundos que no sanarán.",
    ["Those threads allowed me to find my way to many worlds that would otherwise have remained forever hidden from the Blade."] = "Esos hilos me permitieron encontrar mi camino a muchos mundos que de otro modo habrían permanecido ocultos para siempre de Blade.",
    ["Dimensionally speaking, Zanaris is a nexus of planar threads. Its radials spiral into a network of near-infinite ravaged planes: husks of dead worlds, drained of every ounce of life."] = "Dimensionalmente hablando, Zanaris es un nexo de hilos planos. Sus radiales forman una espiral en una red de planos devastados casi infinitos: cáscaras de mundos muertos, desprovistos de cada gramo de vida.",
    ["I was alarmed by this revelation. What interdimensional predator could wreak such devastation?"] = "Esta revelación me alarmó. ¿Qué depredador interdimensional podría causar tal devastación?",
    ["Was this the work of Tuska, the great beast that devoured my kin on Naragun? Could its appetite be so voracious? Or worse, was Tuska but one insatiable entity in a great swarm of devastation?"] = "¿Fue esto obra de Tuska, la gran bestia que devoró a mis parientes en Naragun? ¿Podría ser su apetito tan voraz? O peor aún, ¿Tuska no era más que una entidad insaciable en medio de un gran enjambre de devastación?",
    ["I could only hope this parasite was long since deceased. The alternative - that it lingered in the dark void between worlds, and could strike at any moment - haunted my dreams for many centuries."] = "Sólo podía esperar que este parásito hubiera fallecido hace mucho tiempo. La alternativa -que permanecía en el oscuro vacío entre mundos y podía atacar en cualquier momento- persiguió mis sueños durante muchos siglos.",
    ["...Each gap between worlds cut by the Blade is like a rip in clothing, and they fray, as such, with each use."] = "... Cada espacio entre mundos cortado por Blade es como un desgarro en la ropa y, como tal, se deshilacha con cada uso.",
    ["I must take care to hem each edge I have carved. Only the Blade keeps them stable. Many pieces must be sacrificed..."] = "Debo tener cuidado de hacer dobladillos en cada borde que he tallado. Solo la Hoja los mantiene estables. Muchas piezas deben ser sacrificadas...",
    ["Calamity! I underestimated the ability of the Blade. I have sundered a planet."] = "¡Calamidad! I subestimó la capacidad de Blade. I he partido un planeta.",
    ["It was a world of divine beauty and fabulous magic, a realm of wild nature where four ruling courts of the seasons were in constant conflict, yet maintained a tumultuous balance of power."] = "Era un mundo de belleza divina y magia fabulosa, un reino de naturaleza salvaje donde cuatro tribunales gobernantes de las estaciones estaban en constante conflicto, pero mantenían un tumultuoso equilibrio de poder.",
    ["Yet, at the core of this world of light, I witnessed a great darkness. A corrupt, ravenous presence; a bloated parasite that fed voraciously on the living, whose appetite could never be satisfied."] = "Sin embargo, en el centro de este mundo de luz, fui testigo de una gran oscuridad. Una presencia corrupta y voraz; un parásito hinchado que se alimentaba vorazmente de los vivos, cuyo apetito nunca podía ser satisfecho.",
    ["Arrogantly, I sought to cut that devouring corruption from its host. Instead, I destroyed the planet, shattering its fragments across the cosmos."] = "Arrogantemente, traté de cortar esa corrupción devoradora de su anfitrión. En lugar de eso, destruí el planeta, haciendo añicos sus fragmentos por todo el cosmos.",
    ["Worst of all, I fear my actions have released corruption from its prison."] = "Lo peor de todo es que temo que mis acciones hayan liberado la corrupción de su prisión.",
    ["Its tendrils entwine the threads of mortality. It has taken root in pathways I have opened."] = "Sus zarcillos entrelazan los hilos de la mortalidad. Ha echado raíces en los caminos que he abierto.",
    ["There are many places I now dare not travel, for fear that corruption may probe deeper into the cosmos, and find a new host."] = "Hay muchos lugares a los que ahora no me atrevo a viajar, por temor a que la corrupción pueda profundizar en el cosmos y encontrar un nuevo anfitrión.",
    ["I have sought out the elements of the sundered world. Some of them endure. A land of perpetual light and one of eternal winter, and a periphery where neither can endure the other."] = "He buscado los elementos del mundo dividido. Algunos de ellos perduran. Una tierra de luz perpetua y de invierno eterno, y una periferia donde ninguno puede soportar al otro.",
    ["But there are large fragments of Renmark I have been unable to locate. I can only hope that some of its inhabitants may have survived my hubris."] = "Pero hay grandes fragmentos de Renmark que no he podido localizar. I sólo puedo esperar que algunos de sus habitantes hayan sobrevivido a mi arrogancia.",
    ["color=yellow"] = "color=amarillo",
    ["Wow, what is that you are wearing?"] = "Vaya, ¿qué es lo que llevas puesto?",
    ["I'm wearing fully upgraded elder rune armour. You will be able to smith it yourself in the upcoming Mining and Smithing rework."] = "Llevo una armadura de runas antiguas totalmente mejorada. Podrás crearlo tú mismo en la próxima revisión de Mining y Smithing.",
    ["To smith it, first you'll need to mine some light and dark animica ore, which requires 90 Mining and an appropriate pickaxe."] = "Para forjarlo, primero necesitarás extraer un poco de mineral de animica claro y oscuro, lo que requiere 90 Mining y un pico apropiado.",
    ["Then with 90 Smithing, you'll be able to smelt the ores and a rune bar into elder rune bars, and smith elder rune armour and weapons."] = "Luego, con 90 Smithing, podrás fundir los minerales y una barra de runas para convertirlas en barras de runas mayores y forjar armaduras y armas de runas mayores.",
    ["Oh wow! Do you have more information about the rework?"] = "¡Oh, vaya! ¿Tienes más información sobre el retrabajo?",
    ["*(If you have at least one inventory space:)*"] = "*(Si tienes al menos un espacio de inventario:)*",
    ["You're handed a flyer"] = "Te entregaron un folleto",
    ["*(If your inventory is full:)*"] = "*(Si tu inventario está lleno:)*",
    ["If you've got a free space, I can give you a flyer"] = "Si tienes un espacio libre, puedo darte un folleto",
    ["Hey! scheck it out! Itsh an outerlandub! Yer shud go shpeak to the chieftain!"] = "¡Oye! ¡compruébalo! ¡Es un lugar exterior! ¡Deberías ir a hablar con el jefe!",
    ["The who?"] = "¿Quién?",
    ["That guy over there by that stuff! (hic) Yeh, abshoultely! He's da bosh!"] = "¡Ese tipo que está junto a esas cosas! (hic) ¡Sí, absolutamente! ¡Es un idiota!",
    ["Hey! Itsh you again! Whatshyerfashe!"] = "¡Oye! ¡Eres tú otra vez! ¡Qué tímido!",
    ["Nah nah nah, not them, the other one, whatshyerfashe!"] = "Nah nah nah, ellos no, el otro, ¡qué tímido!",
    ["Thatsh what I said diddle I?"] = "¿Eso es lo que dije, timón?",
    ["Um.... okay. I'll leave you to your drinking."] = "Um... está bien. Te dejo con tu bebida.",
    ["Thanksh pal! You're alright!"] = "¡Gracias amigo! ¡Estás bien!",
    ["Can I ask you about V?"] = "¿Puedo preguntarte sobre V?",
    ["Oh V. We will miss...he. He wassa good man...da dee dum de...er....bam?"] = "Oh V. Lo extrañaremos... él. Era un buen hombre... da dee dum de... er... ¿bam?",
    ["Can I ask you about something else?"] = "¿Puedo preguntarte algo más?",
    ["*(The following dialogue appears both as overhead chat messages as well as entries in the chat box with the format: *''.)"] = "*(El siguiente diálogo aparece como mensajes de chat generales y como entradas en el cuadro de chat con el formato: *''.)",
    ["Hey, welcome to the Max Guild garden!"] = "¡Oye, bienvenido al jardín del gremio Max!",
    ["Oh, hey there!"] = "¡Oh, hola!",
    ["What's your name?"] = "¿Cuál es tu nombre?",
    ["I'm Elen! It's great to meet you! Welcome to the Max Guild!"] = "¡Soy Elen! ¡Es un placer conocerte! ¡Bienvenido al gremio Max!",
    ["Well done on getting in here - it's well deserved!"] = "Enhorabuena por haber entrado aquí. ¡Es bien merecido!",
    ["Elen? Shouldn't you be called Maxine or something?"] = "¿Elen? ¿No deberías llamarte Maxine o algo así?",
    ["Maxine? What a strange name that would be for an elf! Haha, I like it!"] = "¿Maxine? ¡Qué nombre más extraño sería ese para un elfo! Jaja, me gusta!",
    ["But no, it's Elen - Elen Anterth. My family falls under the auspices of Clan Cadarn."] = "Pero no, es Elen - Elen Anterth. Mi familia está bajo los auspicios del Clan Cadarn.",
    ["How are you so skilled if the city's only recently been regrown?"] = "¿Cómo eres tan hábil si la ciudad acaba de volver a crecer?",
    ["Oh, I've been all over! My family travelled east with the Cadarn way back."] = "¡Oh, he estado por todas partes! Mi familia viajó hacia el este con el camino de regreso de Cadarn.",
    ["I was only young, but I saw so much and learned a lot. You'd be surprised what sticks with you."] = "Yo era muy joven, pero vi mucho y aprendí mucho. Te sorprendería lo que se te queda grabado.",
    ["Nice cape you have there..."] = "Bonita capa la que tienes ahí...",
    ["Thanks! It took me ages to get, but I got there in the end: I'm fully proficient in every skill."] = "¡Gracias! Me tomó mucho tiempo lograrlo, pero al final lo logré: soy completamente competente en todas las habilidades.",
    ["To do this you need in the following skill levels: 99 [Skill]"] = "Para hacer esto necesitas en el siguiente skill levels: 99 [Skill]",
    ["Wow, that's quite impressive."] = "Vaya, eso es bastante impresionante.",
    ["Thanks. I have faith in you, Player. Just take your time and you'll get there too, I know it!"] = "Gracias. Tengo fe en ti, Player. Tómate tu tiempo y tú también llegarás allí, ¡lo sé!",
    ["Yeah, maybe..."] = "Sí, tal vez...",
    ["Just remember: don't rush it. It's the journey, not the destination!"] = "Sólo recuerda: no te apresures. ¡Es el viaje, no el destino!",
    ["I've maxed all skills!"] = "¡He maximizado todas las habilidades!",
    ["Really? Good for you! Would you like a cape to show off your achievement? It's 2,871,000 coins - 99,000 for each skill!"] = "¿En serio? ¡Bien por usted! ¿Quieres una capa para mostrar tu logro? Son 2.871.000 coins: ¡99.000 por cada habilidad!",
    ["Pay 2,871,000 for a max cape?"] = "¿Pagar 2.871.000 por una capa máxima?",
    ["I'll take one!"] = "¡Me llevaré uno!",
    ["Sure!"] = "¡Claro!",
    ["You don't have enough inventory space to withdraw that many."] = "No tienes suficiente espacio en el inventario para retirar tantos.",
    ["Oh, but you'll need room in your inventory for a cape and hood."] = "Ah, pero necesitarás espacio en tu inventario para una capa y una capucha.",
    ["Sorry, hun, but you don't have enough coins on you."] = "Lo siento, cariño, pero no tienes suficiente coins contigo.",
    ["Thanks. Enjoy!"] = "Gracias. ¡Disfrutar!",
    ["No, thanks."] = "No, gracias.",
    ["What happened to your Max cape?"] = "¿Qué pasó con tu capa Max?",
    ["Oh, I'm training [Recently released skill]! No rush, taking my time. You'll probably beat me to max!"] = "¡Oh, estoy entrenando a [Recently released skill]! Sin prisas, tomándome mi tiempo. ¡Probablemente me ganarás al máximo!",
    ["Do you know someone called Max?"] = "¿Conoces a alguien llamado Max?",
    ["You don't mean that bullish human from Varrock, do you?"] = "No te refieres a ese humano optimista de Varrock, ¿verdad?",
    ["Bullish? Well, I guess he is always running from place to place."] = "¿Alcista? Bueno, supongo que siempre está corriendo de un lugar a otro.",
    ["Urgh, I hate that guy."] = "Urgh, odio a ese tipo.",
    ["When did you meet him?"] = "¿Cuándo lo conociste?",
    ["Since the city was regrown, he shows up here sometimes. Never stops long."] = "Desde que la ciudad volvió a crecer, él aparece aquí a veces. Nunca se detiene por mucho tiempo.",
    ["Just rushes about the place training, doesn't take the time to just relax and enjoy things."] = "Simplemente corre por el lugar entrenando, no se toma el tiempo para simplemente relajarse y disfrutar las cosas.",
    ["That sounds like Max."] = "Eso suena como Max.",
    ["I tried talking to him the first few times I saw him, but he always just said he was 'doing his dailies' and didn't have time."] = "Intenté hablar con él las primeras veces que lo vi, pero siempre decía que estaba \"haciendo sus diarios\" y que no tenía tiempo.",
    ["There's more to our beautiful city than 'dailies'."] = "En nuestra hermosa ciudad hay más que \"diarios\".",
    ["Does he come in here at all?"] = "¿Entra aquí?",
    ["There's no gain for him here, he says. It'd be a waste, he says."] = "Aquí no hay ningún beneficio para él, dice. Sería un desperdicio, dice.",
    ["You're not welcome here then, I said."] = "Entonces no eres bienvenido aquí, dije.",
    ["Can I toggle my Max Guild teleport?"] = "¿Puedo alternar mi teletransporte del Max Guild?",
    ["Of course! You're currently set to arrive in the [garden/tower]. Do you want to arrive in the [tower/garden] instead?"] = "¡Por supuesto! Actualmente estás listo para llegar al [garden/tower]. ¿Quieres llegar al [tower/garden]?",
    ["Change Max Guild teleport?"] = "¿Cambiar el teletransporte del gremio Max?",
    ["More..."] = "Más...",
    ["About the Task System..."] = "Acerca del sistema de tareas...",
    ["I've completed all of the Elite tasks in the Tirannwn set."] = "He completado todas las tareas Elite del conjunto Tirannwn.",
    ["Well done Player. I have special quiver kept for you."] = "Bien hecho Player. Tengo un carcaj especial reservado para ti.",
    ["[Elen hands you a quiver, a few lamps and a lot of resources.]"] = "[Elen te entrega un carcaj, algunas lámparas y muchos recursos.]",
    ["Take this well deserved reward - you have impressed us all. The quiver will allow you to teleport to the resource dungeon, fight dark beasts easier and use our Lords and Ladies' likeness when in the photobooth."] = "Llévate esta merecida recompensa: nos has impresionado a todos. El carcaj te permitirá teletransportarte a la mazmorra de recursos, luchar contra bestias oscuras más fácilmente y usar la imagen de nuestros Señores y Damas cuando estés en el fotomatón.",
    ["Thanks! What else does it do?"] = "¡Gracias! ¿Qué más hace?",
    ["Because you completed the Elite task set, you will be able to persuade Coeden to give you some logs, use less charges when using Most Wanted cards and your attuned crystal bow and ward."] = "Debido a que completaste el conjunto de tareas Elite, podrás persuadir a Coeden para que te dé algo de logs, usar menos cargas al usar las cartas Most Wanted y tu arco y guardián de cristal sintonizados.",
    ["Ah, quiver-bearer! How is it going?"] = "¡Ah, portador de la aljaba! ¿Cómo está yendo?",
    ["I lost it."] = "Lo perdí.",
    ["Oh, no!"] = "¡Oh, no!",
    ["Never mind, I have another one. Here..."] = "No importa, tengo otro. Aquí...",
    ["[Elen hands you a quiver.]"] = "[Elen te entrega un carcaj.]",
    ["Tell me about the Achievement System."] = "Háblame del Sistema de Logros.",
    ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
    ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
    ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
    ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
    ["Tell me about the set reward for this area."] = "Cuéntame sobre la recompensa establecida para esta área.",
    ["For completing the Tirannwn set, you are presented with a quiver."] = "Por completar el conjunto Tirannwn, se te presenta un carcaj.",
    ["This quiver will become increasingly useful as you complete greater difficulties of task sets."] = "Este carcaj será cada vez más útil a medida que completes conjuntos de tareas de mayor dificultad.",
    ["When you are presented with your rewards, you will be told of its uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
    ["You may also see what rewards a set item provides by hovering over the Rewards icon for its Exploration Achievement set in the Achievements interface."] = "También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de Recompensas de su Logro de exploración establecido en la interfaz de Logros.",
    ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
    ["How do I claim the rewards?"] = "¿Cómo reclamo las recompensas?",
    ["You need to complete all of the Tasks in a set of a particular difficulty, then you can claim your reward."] = "Debes completar todas las tareas de un conjunto de una dificultad particular y luego podrás reclamar tu recompensa.",
    ["Some of the Tirannwn set's Tasks are simple, some will require skill levels, and others require quests to be started or completed."] = "Algunas de las tareas del conjunto Tirannwn son simples, algunas requerirán skill levels y otras requieren que se inicien o completen misiones.",
    ["To claim your Tirannwn set rewards, speak to the Elven Tracker near the Lodestone, Gwir in Lletya, Elen in the city or myself."] = "Para reclamar las recompensas del conjunto Tirannwn, habla con Elven Tracker cerca de Lodestone, Gwir en Lletya, Elen en la ciudad o conmigo mismo.",
    ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
    ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
    ["Tirannwn quiver 1"] = "Tirannwn carcaj 1",
    ["Tirannwn quiver 1? Yes, but I'm afraid it would cost you 5,000 coins."] = "Tirannwn carcaj 1? Sí, pero me temo que te costaría 5.000 coins.",
    ["Purchase another for 5,000 coins?"] = "¿Comprar otro por 5.000 coins?",
    ["[You're handed another Tirannwn quiver 1.]"] = "[Te entregan otro carcaj Tirannwn 1.]",
    ["Tirannwn quiver 2"] = "Tirannwn carcaj 2",
    ["Tirannwn quiver 2? Yes, but I'm afraid it would cost you 10,000 coins."] = "¿Tirannwn carcaj 2? Sí, pero me temo que te costaría 10.000 coins.",
    ["Purchase another for 10,000 coins?"] = "¿Comprar otro por 10.000 coins?",
    ["[You're handed another Tirannwn quiver 2.]"] = "[Te entregan otro carcaj Tirannwn 2.]",
    ["Tirannwn quiver 3"] = "Tirannwn carcaj 3",
    ["Tirannwn quiver 3? Yes, but I'm afraid it would cost you 25,000 coins."] = "Tirannwn carcaj 3? Sí, pero me temo que te costaría 25.000 coins.",
    ["Purchase another for 25,000 coins?"] = "¿Comprar otro por 25.000 coins?",
    ["[You're handed another Tirannwn quiver 3.]"] = "[Te entregan otro carcaj Tirannwn 3.]",
    ["Tirannwn quiver 4"] = "Tirannwn carcaj 4",
    ["Tirannwn quiver 4? Yes, but I'm afraid it would cost you 50,000 coins."] = "Tirannwn carcaj 4? Sí, pero me temo que te costaría 50.000 coins.",
    ["Purchase another for 50,000 coins?"] = "¿Comprar otro por 50.000 coins?",
    ["[You're handed another Tirannwn quiver 4.]"] = "[Te entregan otro carcaj Tirannwn 4.]",
    ["Sorry, hun, I only sell skill capes in the tower."] = "Lo siento, cariño, solo vendo capas de habilidad en la torre.",
    ["Ooh, but I could tell you who DOES sell skill capes - want me to tell you where all the skill masters are?"] = "Oh, pero podría decirte quién SÍ vende capas de habilidades. ¿Quieres que te diga dónde están todos los maestros de habilidades?",
    ["Ask about the skill masters?"] = "¿Preguntar sobre los maestros de habilidades?",
    ["I'll break it down for you, or I'll be droning on for ages!"] = "¡Te lo desglosaré o seguiré hablando durante mucho tiempo!",
    ["Ask about which category of cape?"] = "¿Preguntar sobre qué categoría de capa?",
    ["Combat."] = "Combate.",
    ["There's a couple you can get from the Warriors' Guild in Burthorpe - the attack cape from Ajjat, and the strength cape from Yadech Strongarm."] = "Hay un par que puedes obtener de Warriors' Guild en Burthorpe: el attack cape de Ajjat y la capa de fuerza de Yadech Strongarm.",
    ["The magic cape is sold by the robe store owner in Yanille's Wizards' Guild, and the ranged cape by the armour salesman in the Ranging Guild at Hemenster."] = "La capa mágica la vende robe store owner en el Wizards' Guild de Yanille, y la capa a distancia la vende armour salesman en Ranging Guild en Hemenster.",
    ["If you're after the Defence cape, talk to Harlan at the Lumbridge Combat Academy. For Constitution, talk to Surgeon General Tafani in her house near the north entrance of Al Kharid."] = "Si buscas la capa Defence, habla con Harlan en Lumbridge Combat Academy. Para Constitution, habla con Surgeon General Tafani en su casa cerca de la entrada norte de Al Kharid.",
    ["For Necromancy's cape, you'll want to search the City of Um for a phantom named the Spirit of Accomplishment."] = "Para la capa de Necromancy, querrás buscar en City of Um un fantasma llamado the Spirit of Accomplishment.",
    ["Oh, and they're more like support skills, but the prayer cape can be bought from Brother Jered at Edgeville Monstary, and Pikkupstix in Taverley sells the summoning cape."] = "Ah, y son más bien habilidades de apoyo, pero la capa de oración se puede comprar en Brother Jered en Edgeville Monstary, y Pikkupstix en Taverley vende la capa de invocación.",
    ["Gathering."] = "Reunión.",
    ["I made a new friend in Orla Fairweather - she sells the cape for divination. It's a skill close to my heart."] = "Hice una nueva amiga en Orla Fairweather: ella vende la capa para adivinación. Es una habilidad cercana a mi corazón.",
    ["The master fisher at the Fishing Guild north of Ardougne sells that cape. I don't like fish - yuck!"] = "El master fisher del Gremio Fishing al norte de Ardougne vende esa capa. No me gusta el pescado, ¡qué asco!",
    ["If you're after a mining cape, talk to the dwarf who runs the Mining Guild in Falador."] = "Si buscas una capa minera, habla con el enano que dirige el gremio Mining en Falador.",
    ["If you want a woodcutting cape, head to the forest north of Falador and find Wilfred!"] = "¡Si quieres una capa de leñador, dirígete al bosque al norte de Falador y encuentra Wilfred!",
    ["Oh, and if you're a fan of the past you could get the archaeology cape from Reiniger at the Archaeology Guild."] = "Ah, y si eres fanático del pasado, puedes conseguir la capa de arqueología de Reiniger en el Gremio Archaeology.",
    ["I don't keep my house well-maintained since I set myself up here, but I have my construction cape - I got it from an estate agent."] = "No mantengo mi casa en buen estado desde que me instalé aquí, pero tengo mi capa de construcción, la compré de un estate agent.",
    ["And the master crafter in the Crafting Guild north of Rimmington sorted me out with that cape."] = "Y el master crafter en el Gremio Crafting al norte de Rimmington me resolvió con esa capa.",
    ["Ignatius Vulcan is a strange one, but he more than earned his firemaking cape - he's in the forests south of Seers' Village."] = "Ignatius Vulcan es extraño, pero se ganó con creces su capa de hacer fuego: está en los bosques al sur de Seers' Village.",
    ["Not far from him, in Catherby, you'll find Hickton - he sells the fletching cape."] = "No muy lejos de él, en Catherby, encontrarás a Hickton; él vende la capa con plumas.",
    ["And who can forget Thurgo in his hut at Mudskipper Point? He sells the smithing cape...and eats redberry pies!"] = "¿Y quién puede olvidar a Thurgo en su cabaña en Mudskipper Point? Vende la capa de herrería... ¡y come pasteles de frutos rojos!",
    ["Oh, and as for Invention...you could probably invent your OWN skillcape! Or go see Doc in the Invention Guild."] = "Ah, y en cuanto a Invention... ¡probablemente podrías inventar tu PROPIO skillcape! O ve a ver Doc en el Invention Guild.",
    ["Naturalist."] = "Naturalista.",
    ["The Varrock Cooks' Guild's head chef will dish out a cooking cape for you."] = "head chef del gremio de cocineros Varrock te repartirá una capa de cocina.",
    ["Head to Draynor Village market and talk to Martin the master gardener if you're after a farming cape."] = "Dirígete al mercado Draynor Village y habla con Martin the master gardener si buscas una capa agrícola.",
    ["If you'd like a herblore cape, talk to Kaqemeex at the stone circle in Taverley."] = "Si quieres una capa herblore, habla con Kaqemeex en el círculo de piedras en Taverley.",
    ["Oh, and Larriar in the Runecrafting Guild atop the Wizards' Tower will sell you that cape!"] = "¡Ah, y Larriar en el Runecrafting Guild encima del Wizards' Tower te venderá esa capa!",
    ["Survivalist."] = "Superviviente.",
    ["Cap'n Izzy No-Beard in Brimhaven Agility Arena sells the agility cape."] = "Cap'n Izzy No-Beard en Brimhaven Agility Arena vende la capa de agilidad.",
    ["He's not quite a master, but Thok Thokson sells the dungeoneering cape over at Daemonheim. He's a bit of a mumbler, that one, doesn't always make sense."] = "No es un gran maestro, pero Thok Thokson vende la capa de mazmorra en Daemonheim. Es un poco murmurador, eso no siempre tiene sentido.",
    ["Track down the hunting expert in the Feldip Hills if you're after a hunter cape."] = "Localiza el hunting expert en Feldip Hills si buscas una capa de cazador.",
    ["I'm sure Morvran of Clan Iorwerth would dispute this, but Kuradal in the Ancient Cavern is a master slayer."] = "Estoy seguro de que Morvran del Clan Iorwerth discutiría esto, pero Kuradal en la Caverna Antigua es un maestro asesino.",
    ["And finally, you can pilfer the thieving cape from Martin Thwait - he's found in the Rogues' Den, beneath the Pick and pub in Taverley."] = "Y, por último, puedes robar la capa de ladrón de Martin Thwait; se encuentra en Rogues' Den, debajo del pub Pick and en Taverley.",
    ["**Elen:** Wanna hear about more, or have you heard enough?"] = "**Elen:** ¿Quieres saber más o ya has oído suficiente?",
    ["Hear about more?"] = "¿Escuchaste más?",
    ["Yes - tell me more!"] = "Sí, ¡cuéntame más!",
    ["No - I've heard enough!"] = "No, ¡ya he oído suficiente!",
    ["Okay, well, see you around!"] = "Está bien, ¡nos vemos!",
    ["View regular capes"] = "Ver capas regulares",
    ["View inverted capes"] = "Ver inverted capes",
    ["Welcome! Are you a volunteer? If so, you should speak to Orla over there. She'll set you in the right direction."] = "¡Bienvenido! ¿Eres voluntario? Si es así, deberías hablar con Orla que está allí. Ella te guiará en la dirección correcta.",
    ["Hello Elena."] = "Hola Elena.",
    ["Hey, how are you?"] = "Hola, ¿cómo estás?",
    ["Good thanks, yourself?"] = "Muchas gracias, ¿tú también?",
    ["Not bad, let me know when you hear from King Lathas again."] = "No está mal, avísame cuando vuelvas a tener noticias de King Lathas.",
    ["Will do."] = "Lo haré.",
    ["Hello Player. It's been a long time. What can I do for you?"] = "Hola Player. Ha pasado mucho tiempo. ¿Qué puedo hacer por ti?",
    ["Just passing by."] = "Sólo estoy de paso.",
    ["Hey ya Elena."] = "Hola, Elena.",
    ["Hello Player, so have you found out what those Mourners are up to yet?"] = "Hola Player. ¿Ya has descubierto qué están haciendo esos dolientes?",
    ["Sort of, they seem to be looking for an old temple buried deep under the mountain. This temple is meant to give them access to great magical power, but I have no idea what that is yet."] = "Más o menos, parecen estar buscando un antiguo templo enterrado en lo profundo de la montaña. Este templo está destinado a darles acceso a un gran poder mágico, pero todavía no tengo idea de qué es.",
    ["Well let me know when you find out."] = "Bueno, avísame cuando lo sepas.",
    ["I will."] = "Lo haré.",
    ["Hello Player, so have you found out what those Mourners are up to yet? <ref>Dialogue ends at this point. Probably an oversight by Jagex</ref>"] = "Hola Player. ¿Ya has descubierto qué están haciendo esos dolientes? <ref>El diálogo termina en este punto. Probablemente un descuido de Jagex</ref>",
    ["It's hard to believe it's all over, Player!"] = "¡Es difícil creer que todo haya terminado, Player!",
    ["Now that the Mourners are gone from West Ardougne, I'm going to focus on my studies."] = "Ahora que los Mourners se han ido de West Ardougne, me concentraré en mis estudios.",
    ["I think I'll travel to the elven lands and meet your new friends. I suspect they have an understanding of the sciences that is quite different from ours - perhaps I can learn from them."] = "Creo que viajaré a las tierras de los elfos y conoceré a tus nuevos amigos. Sospecho que tienen una comprensión de las ciencias bastante diferente a la nuestra; tal vez yo pueda aprender de ellos.",
    ["Hello, still looking for tracks?"] = "Hola, ¿sigues buscando pistas?",
    ["The tracks of my brethren are harder to follow than you could imagine."] = "Las huellas de mis hermanos son más difíciles de seguir de lo que puedas imaginar.",
    ["I guess so."] = "Supongo que sí.",
    ["**Player: :** Hello, still looking for tracks?"] = "**Player: :** Hola, ¿sigues buscando pistas?",
    ["**Elf Tracker: :** No need! My brethren are thriving in Prifddinas, thanks to you. Why not pay them a visit?"] = "**Elf Tracker: :** ¡No es necesario! Mis hermanos están prosperando en Prifddinas, gracias a ti. ¿Por qué no hacerles una visita?",
    ["I've completed all of the Easy tasks in the Tirannwn set."] = "He completado todas las tareas fáciles del conjunto Tirannwn.",
    ["Ah, that's a relief. You can wear the Tirannwn quiver now. I have one for you."] = "Ah, eso es un alivio. Ya puedes usar el carcaj Tirannwn. Tengo uno para ti.",
    ["[The Elf Tracker hands you a quiver and an old lamp.]"] = "[El Elf Tracker te entrega un carcaj y una lámpara vieja.]",
    ["This is a powerful quiver. It will help you through leaf traps, make fighting mourners easier as well as acting like a chime."] = "Este es un carcaj poderoso. Te ayudará a superar las trampas de hojas, facilitará la lucha contra los dolientes y actuará como un timbre.",
    ["Thanks!"] = "¡Gracias!",
    ["Now that you've completed the Easy task set you can also sell your limestone to Meredith, claim free swamp tar in the Lletya general store and lots more."] = "Ahora que has completado el conjunto de tareas Fácil, también puedes vender tu piedra caliza a Meredith, reclamar alquitrán de pantano gratis en Lletya general store y mucho más.",
    ["You again? How did you get on with the quiver?"] = "¿Tú otra vez? ¿Cómo te fue con el carcaj?",
    ["Lost? Well, it just so happens I found another. Take better care of this one."] = "¿Perdido? Bueno, da la casualidad de que encontré otro. Cuida mejor este.",
    ["[The Elf Tracker hands you a quiver.]"] = "[El Elf Tracker te entrega un carcaj.]",
    ["Some also give items that will help complete other tasks, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otras tareas y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
    ["You need to complete all tasks within a particular difficulty set, then you can claim your reward."] = "Debes completar todas las tareas dentro de un conjunto de dificultad particular y luego podrás reclamar tu recompensa.",
    ["Some of the Tirannwn set's tasks are simple, some require certain skill levels, and others require quests to be started or completed."] = "Algunas de las tareas del conjunto Tirannwn son simples, algunas requieren cierto skill levels y otras requieren que se inicien o completen misiones.",
    ["To claim your Tirannwn set rewards, speak to Gwir in Lletya, Arianwyn in the city, Elen in the city or myself."] = "Para reclamar las recompensas del conjunto Tirannwn, habla con Gwir en Lletya, Arianwyn en la ciudad, Elen en la ciudad o conmigo mismo.",
    ["Me? I'm a musician! Let me help you relax: sit down, rest your weary limbs and allow me to wash away the troubles of the day. After a long trek, what could be better than some music to give you the energy to continue? Did you know music has curative properties? Music stimulates the healing humours in your body, so they say."] = "¿Yo? ¡Soy músico! Déjame ayudarte a relajarte: siéntate, descansa tus miembros cansados ​​y permíteme eliminar los problemas del día. Después de un largo viaje, ¿qué mejor que un poco de música para darte energía para continuar? ¿Sabías que la música tiene propiedades curativas? La música estimula los humores curativos del cuerpo, según dicen.",
    ["Who says that, then?"] = "¿Quién dice eso entonces?",
    ["I was told by a travelling medical practitioner, selling oil extracted from snakes. It's a commonly known fact, so he said. After resting to some music, you will be able to run longer, and your life points will increase noticeably. A panacea, if you will. Ah, the power of music."] = "Me lo contó un médico que viajaba y vendía aceite extraído de serpientes. Es un hecho comúnmente conocido, dijo. Después de descansar con un poco de música, podrás correr más tiempo y tus puntos de vida aumentarán notablemente. Una panacea, por así decirlo. Ah, el poder de la música.",
    ["So, just listening to some music will cure me of all my ills?"] = "Entonces, ¿solo escuchar un poco de música me curará de todos mis males?",
    ["Well, not quite. Poison, lack of faith, and dismembered limbs are all a bit beyond even the most rousing of harmonies, but I guarantee you will feel refreshed, and better equipped to take on the challenges of the day."] = "Bueno, no del todo. El veneno, la falta de fe y los miembros desmembrados están un poco más allá incluso de las armonías más conmovedoras, pero te garantizo que te sentirás renovado y mejor equipado para afrontar los desafíos del día.",
    ["Does this cost me anything?"] = "¿Esto me cuesta algo?",
    ["Oh, no! My reward is the pleasure I bring to the masses. Just remember me and tell your friends, and that is payment enough. So sit down and enjoy!"] = "¡Oh, no! Mi recompensa es el placer que brindo a las masas. Sólo recuérdame y díselo a tus amigos, y eso es pago suficiente. ¡Así que siéntate y disfruta!",
    ["Can I ask you some questions about resting?"] = "¿Puedo hacerte algunas preguntas sobre el descanso?",
    ["How does resting work?"] = "¿Cómo funciona el descanso?",
    ["Have you ever been on a long journey, and simply wanted to have a rest? When you're running from city to city, it's so easy to run out of breath, don't you find?"] = "¿Alguna vez has estado en un viaje largo y simplemente quisiste descansar? Cuando corres de ciudad en ciudad, es muy fácil quedarte sin aliento, ¿no te parece?",
    ["Yes, I can never run as far as I'd like."] = "Sí, nunca puedo correr tan lejos como quisiera.",
    ["Well, you may rest anywhere, simply choose the Rest option on the run buttons. When you are nice and relaxed, you will recharge your run energy more quickly and your life points twice as fast as you would do so normally. Of course, you can't do anything else while you're resting, other than talk."] = "Bueno, puedes descansar en cualquier lugar, simplemente elige la opción Descanso en los botones de ejecución. Cuando estés agradable y relajado, recargarás tu energía de carrera más rápidamente y tus puntos de vida dos veces más rápido de lo que lo harías normalmente. Por supuesto, mientras descansas no puedes hacer nada más que hablar.",
    ["Why not?"] = "¿Por qué no?",
    ["Well, you wouldn't be resting, now would you? Also, you should know that resting by a musician, has a similar effect but the benefits are greater."] = "Bueno, no estarías descansando, ¿verdad? Además, debes saber que el descanso junto a un músico, tiene un efecto similar pero los beneficios son mayores.",
    ["What's special about resting by a musician?"] = "¿Qué tiene de especial el descanso de un músico?",
    ["The effects of resting are enhanced by music. Your run energy will recharge many times the normal rate, and your life points three times as fast. Simply sit down and rest as you would normally, nice and close to the musician. You'll turn to face the musician and hear the music. Like resting anywhere, if you do anything other than talk, you will stop resting."] = "Los efectos del descanso se potencian con la música. Tu energía de carrera se recargará muchas veces más rápido que lo normal y tus puntos de vida tres veces más rápido. Simplemente siéntate y descansa como lo harías normalmente, agradable y cerca del músico. Te volverás hacia el músico y escucharás la música. Como descansar en cualquier lugar, si haces algo más que hablar, dejarás de descansar.",
    ["Can you summarise the effects for me?"] = "¿Puedes resumirme los efectos?",
    ["Certainly. You can rest anywhere, simply choose the Rest option on the run buttons. Resting anywhere will replenish your run energy more quickly than normal, your life points will replenish twice as fast as well! Resting by a musician will replenish your run energy many times faster than normal, and your life points will also replenish three times as fast."] = "Por supuesto. Puedes descansar en cualquier lugar, simplemente elige la opción Descanso en los botones de ejecución. Descansar en cualquier lugar repondrá tu energía para correr más rápido de lo normal, ¡y tus puntos de vida también se repondrán el doble de rápido! Descansar junto a un músico repondrá tu energía de carrera muchas veces más rápido de lo normal, y tus puntos de vida también se repondrán tres veces más rápido.",
    ["That's all for now."] = "Eso es todo por ahora.",
    ["Can I ask you some questions about running?"] = "¿Puedo hacerte algunas preguntas sobre correr?",
    ["Running? Of course! Not that I do much running, I prefer to saunter. But you adventuring types always seem to be in a rush, zipping hither and thither."] = "¿Corriendo? ¡Por supuesto! No es que corro mucho, prefiero pasear. Pero ustedes, los aventureros, siempre parecen tener prisa, yendo de aquí para allá.",
    ["Why do I need to run anyway?"] = "¿Por qué necesito ejecutar de todos modos?",
    ["Running is the simplest way to get somewhere quickly. When you run you move twice as fast as you normally would. Also, you don't look like the cowardly type, but most creatures can't run very fast, so if you don't want to fight, you can always run away."] = "Correr es la forma más sencilla de llegar rápidamente a algún lugar. Cuando corres, te mueves el doble de rápido de lo que lo harías normalmente. Además, no pareces del tipo cobarde, pero la mayoría de las criaturas no pueden correr muy rápido, así que si no quieres pelear, siempre puedes huir.",
    ["Can I keep running forever?"] = "¿Puedo seguir corriendo para siempre?",
    ["No, eventually you'll get tired. When that happens you will stop running, and start walking. It takes a while to get your breath back, but once you've recovered it a little, you can start running again. You recover quickly whilst resting, or more slowly whilst walking."] = "No, eventualmente te cansarás. Cuando eso suceda, dejarás de correr y empezarás a caminar. Te llevará un tiempo recuperar el aliento, pero una vez que lo hayas recuperado un poco podrás empezar a correr de nuevo. Te recuperas rápidamente mientras descansas o más lentamente mientras caminas.",
    ["You may start running by clicking once on the Run button, which is the running man icon at the top-right of the minimal. Clicking the Run button a second time will switch you back to walking. It tells you how much run energy you currently have."] = "Puedes comenzar a correr haciendo clic una vez en el botón Ejecutar, que es el ícono del hombre corriendo en la parte superior derecha del mínimo. Al hacer clic en el botón Ejecutar por segunda vez, volverá a caminar. Te indica cuánta energía de carrera tienes actualmente.",
    ["Well, don't forget to have a rest every now and again."] = "Bueno, no olvides descansar de vez en cuando.",
    ["Jump up on a table and join us!"] = "¡Súbete a una mesa y únete a nosotros!",
    ["Get out of it! You'se aint commin' in 'ere to get our's blood or's our food!"] = "¡Fuera de ahí! ¡No vendrás aquí a buscar nuestra sangre ni nuestra comida!",
    ["*(Before River of Blood:)*"] = "*(Antes de Río de Sangre:)*",
    ["Hey it's the hero! Wow, you're amazing! How on earth did you manage to tackle those two juvinates and Gadderanks? And the town is lovely - you've done a great job!"] = "¡Oye, es el héroe! ¡Guau, eres increíble! ¿Cómo diablos lograste enfrentarte a esos dos juvinates y Gadderanks? Y la ciudad es preciosa. ¡Has hecho un gran trabajo!",
    ["*(After River of Blood:)*"] = "*(Después de Río de Sangre :)*",
    ["Hey it's the hero! Wow, you're amazing! How did you manage to return all the villagers? Things feel so much safer around here now too - great job!"] = "¡Oye, es el héroe! ¡Guau, eres increíble! ¿Cómo conseguiste devolver a todos los aldeanos? Ahora las cosas también se sienten mucho más seguras por aquí: ¡excelente trabajo!",
    ["You're more than welcome."] = "De nada.",
    ["What do you do here?"] = "¿Qué haces aquí?",
    ["I'm Elisabeta the village leader."] = "Soy Elisabeta, el líder de la aldea.",
    ["How do you like your town?"] = "¿Qué te parece tu ciudad?",
    ["It's just perfect, thanks so much for your efforts."] = "Es simplemente perfecto, muchas gracias por tus esfuerzos.",
    ["What's happening around here?"] = "¿Qué está pasando por aquí?",
    ["Oh, not much really, we're all still hiding from the vampyres and eking out a living from this terrible place, hopefully soon we'll be strong enough to make the journey to the temple on the Salve."] = "Oh, no mucho en realidad, todos todavía nos estamos escondiendo del vampyres y ganándonos la vida a duras penas en este terrible lugar, con suerte pronto seremos lo suficientemente fuertes para hacer el viaje al templo en la Salve.",
    ["Oh, not much really, we're all just trying to eke out a living in this place. Some of us still want to head for the Salve and into Misthalin, but honestly, it's not so bad here anymore...in spite of how it might look."] = "Oh, no mucho en realidad, todos estamos tratando de ganarnos la vida a duras penas en este lugar. Algunos de nosotros todavía queremos dirigirnos a la Salve y a Misthalin, pero, sinceramente, ya no está tan mal aquí... a pesar de cómo pueda parecer.",
    ["Is there anything I can do to help out?"] = "¿Hay algo que pueda hacer para ayudar?",
    ["Not as far as I know, we have some basic amenities now which is so very useful, we're all incredibly grateful to you. I've never really seen or known a hero before, so I have nothing to compare one to, but I suspect in most people's judgement, you would be one! I for one am very pleased to have met you."] = "No que yo sepa, ahora contamos con algunos servicios básicos que son muy útiles y todos te estamos increíblemente agradecidos. Nunca antes había visto o conocido a un héroe, así que no tengo nada con qué compararlo, pero sospecho que, a juicio de la mayoría de la gente, ¡tú serías uno! Por mi parte, estoy muy contento de haberte conocido.",
    ["Okay, thanks."] = "Está bien, gracias.",
    ["I am helping with the dig. I am an expert on Third Age architecture."] = "Estoy ayudando con la excavación. Soy un experto en arquitectura de la Tercera Edad.",
    ["What is this place"] = "¿Qué es este lugar?",
    ["In the Third Age, this was a great city, which would have put Varrock to shame!"] = "En la Tercera Edad, esta era una gran ciudad, ¡lo que habría avergonzado a Varrock!",
    ["I don't know, Varrock is pretty impressive."] = "No lo sé, Varrock es bastante impresionante.",
    ["I don't know, Varrock palace is impressive."] = "No lo sé, el palacio Varrock es impresionante.",
    ["Hmph. I don't think it will look this good when it's been buried in the ground for three thousand years!"] = "Hmph. ¡No creo que luzca tan bien después de haber estado enterrado bajo tierra durante tres mil años!",
    ["What happened to the city?"] = "¿Qué pasó con la ciudad?",
    ["No one knows for sure."] = "Nadie lo sabe con seguridad.",
    ["But the The Third Age was a time of destruction, when the gods were violently at war. Many great civilizations were destroyed then."] = "Pero la Tercera Edad fue una época de destrucción, cuando los dioses estaban en guerra violenta. Muchas grandes civilizaciones fueron destruidas entonces.",
    ["Hello, Elissa, I have a proposition for you."] = "Hola, Elissa, tengo una propuesta para ti.",
    ["Of course, Guildmaster, how might I help?"] = "Por supuesto, Guildmaster, ¿en qué puedo ayudar?",
    ["I've seen your work on golems and wondered if you have any interest in joining my research team..."] = "He visto tu trabajo sobre golems y me preguntaba si tienes algún interés en unirte a mi equipo de investigación...",
    ["Hmm, while that would be of interest, I still need to finish off the last of my husband's research on golems. I still need to recover a restored golem instruction from somewhere. I hear some are to be found at the Stormguard Citadel."] = "Hmm, aunque eso sería interesante, todavía necesito terminar lo último de la investigación de mi marido sobre los golems. Todavía necesito recuperar una instrucción de golem restaurada de algún lugar. He oído que algunos se pueden encontrar en Stormguard Citadel.",
    ["Hmm, I'll get back to you on that..."] = "Hmm, ya me comunicaré contigo sobre eso...",
    ["You mean like one of these?"] = "¿Te refieres a uno de estos?",
    ["No way, you have one? If you'd be willing to part with it, I'll sign up right away!"] = "De ninguna manera, ¿tienes uno? Si estás dispuesto a desprenderte de él, ¡me registraré de inmediato!",
    ["Give golem instruction to Elissa?"] = "¿Darle instrucciones de golem a Elissa?",
    ["Welcome to the team, Elissa."] = "Bienvenido al equipo, Elissa.",
    ["Elissa Giovanni has joined your research team!"] = "¡Elissa Giovanni se ha unido a tu equipo de investigación!",
    ["It will be good to bury myself in some different research."] = "Será bueno sumergirme en alguna investigación diferente.",
    ["Oh, wait, sorry, I might need this for something else. Let me get back to you."] = "Oh, espera, lo siento, puede que necesite esto para otra cosa. Déjame volver contigo.",
    ["Greetings, adventurer. Duke Horacio has recently provided us guards with advanced training, as well as much improved swords! I feel much more confident in our ability to defend Lumbridge now that we actually have proper equipment and training!"] = "Saludos, aventurero. ¡Duke Horacio nos ha proporcionado recientemente a los guardias entrenamiento avanzado, así como espadas muy mejoradas! ¡Me siento mucho más seguro de nuestra capacidad para defender Lumbridge ahora que contamos con el equipo y la capacitación adecuados!",
    ["Conversation with the three Sotapanna in the first room, after the first barrier guarded by four Elite Sotapanna."] = "Conversación con los tres Sotapanna en la primera sala, después de la primera barrera custodiada por cuatro Elite Sotapanna.",
    ["Conversation between the two Sotapanna near the Azure door."] = "Conversación entre los dos Sotapanna cerca de la puerta Azul.",
    ["One of the following random quotes may be said by the Sotapanna in the Sanctum."] = "El Sotapanna en el Santuario puede decir una de las siguientes citas aleatorias.",
    ["A highly powerful [Monster] has appeared nearby."] = "Un [Monster] muy potente ha aparecido cerca.",
    ["A highly powerful [Monster] has appeared near your co-op Slayer partner."] = "Un [Monster] muy poderoso ha aparecido cerca de tu socio cooperativo Slayer.",
    ["[Elite monster] has appeared nearby."] = "[Elite monster] ha aparecido cerca.",
    ["[Elite monster] has appeared near your co-op Slayer partner."] = "[Elite monster] ha aparecido cerca de tu socio cooperativo Slayer.",
    ["Have you met Violet? She's so cool! I want hair like hers!"] = "¿Conoces a Violet? ¡Ella es tan genial! ¡Quiero un cabello como el de ella!",
    ["I helped her get here. You wouldn't believe the adventure we had together."] = "La ayudé a llegar hasta aquí. No creerías la aventura que tuvimos juntos.",
    ["You know Violet? Can you ask her if she'll be my best friend?"] = "¿Conoces Violet? ¿Puedes preguntarle si será mi mejor amiga?",
    ["I'll see what I can do."] = "Veré qué puedo hacer.",
    ["What do you think about the island?"] = "¿Qué opinas de la isla?",
    ["We're finally here! Can you believe it? We're finally here!"] = "¡Finalmente estamos aquí! ¿Puedes creerlo? ¡Finalmente estamos aquí!",
    ["Have you been waiting long?"] = "¿Has estado esperando mucho?",
    ["Years! I remember when we first started building the boat; I thought 'this is it Eliza, by summer you'll be on the island'."] = "¡Años! Recuerdo cuando empezamos a construir el barco; Pensé 'esto es Eliza, para el verano estarás en la isla'.",
    ["Summer came and went, then wintumber, then summer again... I had given up hope in all honesty."] = "El verano vino y se fue, luego el invierno, luego el verano otra vez... Honestamente, había perdido la esperanza.",
    ["But we're here now. Really here!"] = "Pero ya estamos aquí. ¡Realmente aquí!",
    ["I should go."] = "Debería irme.",
    ["Happy exploring!"] = "¡Feliz exploración!",
    ["Hmm... What's that... The readings have gone off the chart!"] = "Hmm... ¿Qué es eso? ¡Las lecturas se han salido del gráfico!",
    ["Is it magical interference? I've been seeing spikes occasionally."] = "¿Es una interferencia mágica? He estado viendo picos de vez en cuando.",
    ["Could be. It seems to be location based... Wait..."] = "Podría ser. Parece estar basado en la ubicación... Espera...",
    ["Player? What do you have there? Come talk to us quickly."] = "¿Player? ¿Qué tienes ahí? Ven a hablar con nosotros rápidamente.",
    ["What is that energy reading? Have you been in contact some magical artefact recently?"] = "¿Cuál es esa lectura de energía? ¿Has estado en contacto con algún artefacto mágico recientemente?",
    ["I found a piece of a totem on the island? Could that be it?"] = "¿Encontré un trozo de tótem en la isla? ¿Podría ser eso?",
    ["What do you have in your backpack, Player? It's sending our energy readings off the chart."] = "¿Qué tienes en tu backpack, Player? Está enviando nuestras lecturas de energía fuera del gráfico.",
    ["Do you mean this?"] = "¿Te refieres a esto?",
    ["You show the archaeologists the totem piece you discovered."] = "Muestras a los arqueólogos el tótem que descubriste.",
    ["**Alpheus:** What a discovery! Whatever it is, it seems to contain a vast amount of energy within."] = "**Alpheus:** ¡Qué descubrimiento! Sea lo que sea, parece contener una gran cantidad de energía en su interior.",
    ["Look! It's only one piece of something larger. Perhaps if you could find all the pieces they could be combined..."] = "¡Mira! Es sólo una pieza de algo más grande. Quizás si pudieras encontrar todas las piezas podrían combinarse...",
    ["Are you seriously telling Player to reassemble an ancient artefact of huge energy without considering safety precautions first?"] = "¿En serio le estás diciendo a Player que vuelva a ensamblar un antiguo artefacto de enorme energía sin considerar primero las precauciones de seguridad?",
    ["It's okay actually. I tend to rush into things and most of the time everything works out fine."] = "En realidad, está bien. Tiendo a apresurarme y la mayoría de las veces todo sale bien.",
    ["Goodness! Can you believe this?"] = "¡Dios mío! ¿Puedes creer esto?",
    ["HOW DO YOU DO IT? My whole life I've been told what to be afraid of! I wish I could have your courage."] = "¿CÓMO LO HACES? ¡Toda mi vida me han dicho a qué temer! Ojalá pudiera tener tu coraje.",
    ["Uh... well... I just feel... compelled to do things, you know? Like there's an external force guiding my actions."] = "Uh... bueno... Me siento... obligado a hacer cosas, ¿sabes? Como si hubiera una fuerza externa guiando mis acciones.",
    ["Oh that sounds amazing! You sound like the perfect person to conduct this line of research then!"] = "¡Oh, eso suena increíble! ¡Entonces suenas como la persona perfecta para llevar a cabo esta línea de investigación!",
    ["I concur. Just think of all the paperwork we'll avoid!"] = "Estoy de acuerdo. ¡Solo piensa en todo el papeleo que evitaremos!",
    ["If you find all the pieces of that totem, put them together and see what happens next."] = "Si encuentras todas las piezas de ese tótem, júntalas y mira qué pasa después.",
    ["What can you tell me about totem pieces?"] = "¿Qué puedes decirme sobre las piezas tótem?",
    ["Those totems appear to hold a huge amount of magical energy, but they seem to have broken into pieces."] = "Esos tótems parecen contener una gran cantidad de energía mágica, pero parecen haberse roto en pedazos.",
    ["If you could find all the pieces of a totem and repair it, then it will likely create an item of immense power."] = "Si pudieras encontrar todas las piezas de un tótem y repararlo, probablemente crearías un objeto de inmenso poder.",
    ["Do you have anything I can store totem pieces in?"] = "¿Tienes algo donde pueda guardar piezas de tótem?",
    ["[You receive a reinforced bag that looks like it will be strong enough to carry totem pieces.]"] = "[Recibirás una bolsa reforzada que parece lo suficientemente fuerte como para transportar piezas de tótem.]",
    ["I hope that helps."] = "Espero que eso ayude.",
    ["*(With a totem bag in backpack:)*"] = "*(Con un bolso totem en backpack :)*",
    ["You already have one in your backpack. Are you okay or is the heat getting to you?"] = "Ya tienes uno en tu backpack. ¿Estás bien o te está afectando el calor?",
    ["*(With a totem bag in bank:)*"] = "*(Con un bolso totem en el banco:)*",
    ["You already have one. Tell you what though, I will have someone fetch it for you."] = "Ya tienes uno. Pero te diré una cosa: haré que alguien te lo traiga.",
    ["You've rebuilt a totem? And you're still alive! What luck!"] = "¿Has reconstruido un tótem? ¡Y todavía estás vivo! ¡Qué suerte!",
    ["And just as we've completed some compelling research that may lead to the next step."] = "Y justo cuando hemos completado una investigación convincente que puede llevarnos al siguiente paso.",
    ["Oh yes! This is very exciting! As part of our research we've discovered the island has what we're calling 'magical ley lines'."] = "¡Oh, sí! ¡Esto es muy emocionante! Como parte de nuestra investigación, hemos descubierto que la isla tiene lo que llamamos \"líneas ley mágicas\".",
    ["Yes. There seems to be a flow of magic on and around the island which seems to form concentrations in certain areas. I'm sure the totem has a connection to them."] = "Sí. Parece haber un flujo de magia en y alrededor de la isla que parece formar concentraciones en ciertas áreas. Estoy seguro de que el tótem tiene una conexión con ellos.",
    ["If you explore the island you may find where these totems belong. Placing them should create the connection between the island and the power within the totem."] = "Si exploras la isla, es posible que descubras dónde pertenecen estos tótems. Colocarlos debería crear la conexión entre la isla y el poder dentro del tótem.",
    ["And who knows what that will do."] = "Y quién sabe qué hará eso.",
    ["Maybe an explosion? It will be thrilling regardless I'm sure."] = "¿Quizás una explosión? Será emocionante de todos modos, estoy seguro.",
    ["Sure, I'll see what I can find..."] = "Claro, veré qué puedo encontrar...",
    ["Hey, so, word has got around that you're now an associate of the Archaeology Guild, and that you've set up a research team..."] = "Oye, se ha corrido la voz de que ahora eres asociado del Gremio Archaeology y que has creado un equipo de investigación...",
    ["Alpheus and I were wondering if you could make use of us two as research assistants..."] = "Alpheus y yo nos preguntábamos si podrían utilizarnos a los dos como asistentes de investigación...",
    ["Alpheus and Eliza have joined your research team!"] = "¡Alpheus y Eliza se han unido a tu equipo de investigación!",
    ["Hey, sure thing! The more the merrier. I could do with some assistants as it happens."] = "¡Oye, seguro! Cuantos más, mejor. Me vendría bien algunos asistentes mientras sucede.",
    ["That's awesome, thank you! We'll do you proud!"] = "¡Eso es increíble, gracias! ¡Te haremos sentir orgulloso!",
    ["Yeah, Eliza and I will work hard. You won't regret this! Thank you."] = "Sí, Eliza y yo trabajaremos duro. ¡No te arrepentirás! Gracias.",
    ["She is ignoring you."] = "Ella te está ignorando.",
    ["Apparently you aren't as stupid as you look."] = "Aparentemente no eres tan estúpido como pareces.",
    ["Hello, welcome to our maze. I'm Elkoy the tree gnome."] = "Hola, bienvenido a nuestro laberinto. Soy Elkoy el gnomo del árbol.",
    ["Hello, welcome to our village. I'm Elkoy the tree gnome."] = "Hola, bienvenido a nuestro pueblo. Soy Elkoy el gnomo del árbol.",
    ["I haven't heard of your sort before."] = "No había oído hablar de alguien de tu clase antes.",
    ["There's not many of us left. Once you could find tree gnomes anywhere in the world, now we hide in small groups to avoid capture."] = "Ya no quedan muchos de nosotros. Antes se podían encontrar gnomos de árboles en cualquier parte del mundo, ahora nos escondemos en pequeños grupos para evitar ser capturados.",
    ["Capture by whom?"] = "¿Capturada por quién?",
    ["Tree gnomes have been hunted for so called 'fun' since as long as I can remember."] = "Los gnomos de los árboles han sido cazados por lo que se llama \"diversión\" desde que tengo uso de razón.",
    ["Our main threat nowadays are General Khazard's troops. They know no mercy, but are also very dense. They'll never find their way through our maze."] = "Nuestra principal amenaza hoy en día son las tropas de General Khazard. No conocen la piedad, pero también son muy densos. Nunca encontrarán el camino a través de nuestro laberinto.",
    ["Have fun."] = "Diviértete.",
    ["Hello Elkoy."] = "Hola Elkoy.",
    ["Hi there, I hope life is treating you well. Would you like me to show you the way to the village?"] = "Hola, espero que la vida te esté tratando bien. ¿Quieres que te muestre el camino al pueblo?",
    ["Hi there, I hope life is treating you well. Would you like me to show you the way out of the village?"] = "Hola, espero que la vida te esté tratando bien. ¿Quieres que te muestre el camino para salir del pueblo?",
    ["Ok then, follow me."] = "Ok, entonces sígueme.",
    ["[Elkoy escorts you through the maze...]"] = "[Elkoy te acompaña a través del laberinto...]",
    ["Here we are. Feel free to have a look around."] = "Aquí estamos. Siéntase libre de echar un vistazo a su alrededor.",
    ["Here we are. Have a safe journey."] = "Aquí estamos. Que tengas un viaje seguro.",
    ["No thanks Elkoy."] = "No, gracias Elkoy.",
    ["Ok then, take care."] = "Bueno, entonces cuídate.",
    ["What's going on here? I see a lot of farming patches with nothing growing in them."] = "¿Qué está pasando aquí? Veo muchas parcelas agrícolas en las que no crece nada.",
    ["No, one has just had them installed. One has had the most marvelous idea to bring renewed happiness to one's own dearest husband."] = "No, uno acaba de instalarlos. A una se le ha ocurrido la idea más maravillosa de traer felicidad renovada a su más querido marido.",
    ["One? I'm not sure I understand you-"] = "¿Uno? No estoy seguro de entenderte-",
    ["Oh dear - the common classes, oh how they fill one with intolerable levels of exasperation, I swear to be most true."] = "Dios mío, las clases comunes, oh, cómo llenan a uno con niveles intolerables de exasperación, lo juro por ser muy cierto.",
    ["Ri-ight ... if you say so, my lady. I'll be off then, if you don't mind-"] = "Ci-bien... si usted lo dice, mi señora. Entonces me iré, si no te importa.",
    ["Yes, be off with you, before I call the guards."] = "Sí, vete antes de que llame a los guardias.",
    ["No problem, sorry to have bothered you."] = "No hay problema, lamento haberte molestado.",
    ["Peasant - WAIT!!!"] = "Peasant - ¡¡¡ESPERA!!!",
    ["Are you speaking to me?"] = "¿Me estás hablando a mí?",
    ["Who else would I be speaking to, you funny little [man/woman]? Of course you."] = "¿Con quién más estaría hablando, pequeño y gracioso [man/woman]? Por supuesto que tú.",
    ["Well for a moment there I thought there was a dog around here somewhere..."] = "Bueno, por un momento pensé que había un perro por aquí en alguna parte...",
    ["Oh yes, sarcasm - how amusing. No, no, peasant - I have a question to ask of you, and you are required to answer."] = "Oh, sí, sarcasmo, qué divertido. No, no, campesino. Tengo una pregunta que hacerte y debes responderla.",
    ["Well, seeing as you put it so nicely..."] = "Bueno, ya que lo expresas tan bien...",
    ["Do you know of anyone who might have some degree of horticultural experience?"] = "¿Conoce a alguien que pueda tener algún grado de experiencia en horticultura?",
    ["If you're asking me do I know a gardener, then I'm afraid the answer is no. And with that, I would kindly request that I can take your leave now, m'lady."] = "Si me preguntas si conozco a un jardinero, me temo que la respuesta es no. Y dicho esto, le pido amablemente que pueda despedirse ahora, milady.",
    ["Yes, hurry off peasant - you are of no use to me."] = "Sí, date prisa, campesino, no me sirves de nada.",
    ["[The Queen is looking for somebody with at least level 25 Farming - you may need to practise your Farming skills a little bit more.]"] = "[La Reina está buscando a alguien con al menos nivel 25 Farming; es posible que necesites practicar un poco más tus habilidades Farming.]",
    ["If you're asking me do I know a gardener, then yes I do. I happen to be quite handy at farming myself, as it happens."] = "Si me preguntas si conozco a un jardinero, entonces sí. Da la casualidad de que soy bastante hábil en la agricultura.",
    ["Well, that is as may be. However, this task may also involve some knowledge of the skills of diplomacy and persuasion. From the manner of your speech, these are skills I doubt that you possess."] = "Bueno, eso es lo que puede ser. Sin embargo, esta tarea también puede implicar cierto conocimiento de las habilidades de diplomacia y persuasión. Por tu manera de hablar, estas son habilidades que dudo que poseas.",
    ["Hmmm. I could say that it takes one to know one..."] = "Mmmm. Podría decir que hace falta uno para conocer uno...",
    ["Be off with you, peasant. You are mightily fortunate that I do not call the guards this instant, after which you may never see another sunrise."] = "Vete, campesino. Eres muy afortunado de que no llame a los guardias en este instante, después del cual es posible que nunca vuelvas a ver el amanecer.",
    ["[You may find that completing the quest 'Creature of Fenkenstrain' may set you upon the path you need to follow in order to learn the skills that Queen Ellamaria requires from you.]"] = "[Es posible que descubrir que completar la misión 'Criatura de Fenkenstrain' te indique el camino que debes seguir para aprender las habilidades que la Reina Ellamaria requiere de ti.]",
    ["What, you want to dig up the plants that took one so long to grow? Don't be be ridiculous, you silly little [man/woman]."] = "¿Qué? ¿Quieres desenterrar las plantas que tardaron tanto en crecer? No seas ridículo, pequeño tonto [man/woman].",
    ["All right then, sorry I asked."] = "Muy bien, perdón por preguntar.",
    ["Impertinent peasant! Oh, if you promise to leave one alone then feel free to pick fruit from the White Tree. One is told that they are a great natural energy restorative."] = "¡Campesino impertinente! Oh, si prometes dejar uno en paz, siéntete libre de recoger fruta del Árbol Blanco. Se dice que son un gran reconstituyente energético natural.",
    ["That patch is already fully grown. I don't know what you want me to do with it."] = "Ese parche ya está completamente desarrollado. No sé qué quieres que haga con él.",
    ["That patch is already fully grown! I don't know what you want me to do with it!"] = "¡Ese parche ya está completamente desarrollado! ¡No sé qué quieres que haga con él!",
    ["Greetings, friend. I am a manufacturer of leather."] = "Saludos amigo. Soy fabricante de cuero.",
    ["I see you have started your Lumbridge and Draynor achievement diary. Would you like a needle and thread for Crafting?"] = "Veo que has comenzado tu diario de logros de Lumbridge y Draynor. ¿Quieres aguja e hilo para Crafting?",
    ["Ellis hands you a needle and thread."] = "Ellis te entrega aguja e hilo.",
    ["Here you are then. If you ever find yourself in need of another set, you can always buy needles and thread from most Crafting shops."] = "Aquí estás entonces. Si alguna vez necesitas otro juego, siempre puedes comprar agujas e hilo en la mayoría de las tiendas Crafting.",
    ["Very well then."] = "Muy bien entonces.",
    ["Can I buy some leather then?"] = "¿Puedo comprar algo de cuero entonces?",
    ["I make leather from animal hides. Bring me some cowhides and I'll tan them into soft leather for you."] = "Hago cuero a partir de pieles de animales. Tráeme algunas pieles de vaca y las curtiré hasta convertirlas en cuero suave para ti.",
    ["Leather is rather weak stuff."] = "El cuero es un material bastante débil.",
    ["Normal leather may be quite weak, but it's so easy to craft that anyone can work with it."] = "El cuero normal puede ser bastante débil, pero es tan fácil de elaborar que cualquiera puede trabajar con él.",
    ["Alternatively you could try hard leather. It's not so easy to craft, but I only charge 3 gp per cowhide to prepare it, and it makes much sturdier armour."] = "Alternativamente, puedes probar con cuero duro. No es tan fácil de fabricar, pero solo cobro 3 po por piel de vaca para prepararlo, y hace una armadura mucho más resistente.",
    ["I can also tan snake hides and dragonhides, suitable for crafting into the highest quality armour for rangers."] = "También puedo curtir pieles de serpiente y de dragón, adecuadas para fabricar armaduras de la más alta calidad para los guardabosques.",
    ["Thanks, I'll bear it in mind."] = "Gracias, lo tendré en cuenta.",
    ["What can you tell me about Ali Morrisane?"] = "¿Qué puedes contarme sobre Ali Morrisane?",
    ["I wouldn't mind him setting up shop, but he's brought others in."] = "No me importaría que estableciera una tienda, pero ha traído a otros.",
    ["Two of them came here and said they were going to put me out of business if I didn't listen to them!"] = "¡Dos de ellos vinieron aquí y dijeron que me iban a sacar del negocio si no los escuchaba!",
    ["Hah, as if they think they could threaten me with a hammer and a pair of scissors."] = "Ja, como si pensaran que podrían amenazarme con un martillo y unas tijeras.",
    ["What will you do about the threats?"] = "¿Qué harás con las amenazas?",
    ["The other shopkeepers and I won't give in to their threats. Osman's also told us that he'll make sure we're protected."] = "Los otros comerciantes y yo no cederemos ante sus amenazas. Osman también nos dijo que se asegurará de que estemos protegidos.",
    ["I'll keep tanning leather for people like you to make into clothes and armour."] = "Seguiré curtiendo cuero para que gente como tú lo convierta en ropa y armaduras.",
    ["*(If the player uses any tannable object, such as a cowhide or a snakeskin, on Ellis:)*"] = "*(Si el player usa algún objeto curtible, como piel de vaca o de serpiente, en Ellis :)*",
    ["*(If the player uses any other item on Ellis:)*"] = "*(Si el player usa cualquier otro elemento en Ellis:)*",
    ["Er... Thanks, but no thanks!"] = "Er... ¡Gracias, pero no gracias!",
    ["Here you go!"] = "¡Aquí tienes!",
    ["[Ellis has given you another clue scroll!]"] = "[¡Ellis te ha dado otro pergamino de pistas!]",
    ["What Would You Like To Do"] = "¿Qué te gustaría hacer?",
    ["Ask the camel about its dung."] = "Pregúntale al camello por su estiércol.",
    ["I'm sorry to bother you, but could you spare me a little dung?"] = "Lamento molestarte, pero ¿podrías ahorrarme un poco de estiércol?",
    ["Are you serious?"] = "¿Hablas en serio?",
    ["Oh yes. If you'd be so kind..."] = "Ah, sí. Si fueras tan amable...",
    ["Well, just you close your eyes first. I'm not doing it while you're watching me!"] = "Bueno, primero cierra los ojos. ¡No lo haré mientras me miras!",
    ["I hope that's what you wanted!"] = "¡Espero que eso sea lo que querías!",
    ["Ohhh yes. Lovely."] = "Ohhh, sí. Hermoso.",
    ["Say something unpleasant."] = "Di algo desagradable.",
    ["*The player says one of the following at random:*"] = "*el player dice uno de los siguientes al azar:*",
    ["*Dialogue 1:*"] = "*Diálogo 1:*",
    ["If I go near that camel, it'll probably bite my hand off."] = "Si me acerco a ese camello, probablemente me arrancará la mano de un mordisco.",
    ["What did you say?"] = "¿Qué dijiste?",
    ["Er, nothing important."] = "Er, nada importante.",
    ["Well, it's nice to have someone to talk to. Ollie is so remote, and I can't get up the courage to talk to him."] = "Bueno, es bueno tener alguien con quien hablar. Ollie es muy distante y no puedo reunir el coraje para hablar con él.",
    ["Who's Ollie?"] = "¿Quién es Ollie?",
    ["He's the camel wandering around near that glider. Isn't he so strong and handsome?"] = "Él es el camello que deambula cerca de ese planeador. ¿No es tan fuerte y guapo?",
    ["Er, he just looks like any other camel to me."] = "Er, para mí parece un camello cualquiera.",
    ["How can you not see how wonderful he is? Why, he can cross the Kharidian Desert in three bounds, and he's so strong that he could haul the brick for the Duel Arena in only a day!"] = "¿Cómo no puedes ver lo maravilloso que es? ¡Puede cruzar el Kharidian Desert en tres saltos y es tan fuerte que podría transportar el ladrillo hasta el Duel Arena en solo un día!",
    ["You're a camel, I'm not. Maybe you can see these things better."] = "Tú eres un camello, yo no. Quizás puedas ver estas cosas mejor.",
    ["For someone who understands camel speech, you're not good at these things."] = "Para alguien que entiende el lenguaje de los camellos, no eres bueno en estas cosas.",
    ["*Dialogue 2:*"] = "*Diálogo 2:*",
    ["Mmm... Looks like that camel would make a nice kebab."] = "Mmm... Parece que ese camello sería un buen kebab.",
    ["*Dialogue 3:*"] = "*Diálogo 3:*",
    ["I wonder if that camel has fleas..."] = "Me pregunto si ese camello tendrá pulgas...",
    ["Neither - I'm a polite person."] = "Ninguno de los dos, soy una persona educada.",
    ["*You decide not to be rude.*"] = "*Decides no ser grosero.*",
    ["What's a gnome doing here?"] = "¿Qué hace un gnomo aquí?",
    ["I'm an investigator. I'm watching the implings."] = "Soy investigador. Estoy observando los implantes.",
    ["Why would you want to do that?"] = "¿Por qué querrías hacer eso?",
    ["My client has asked me to find out where certain missing items have been going."] = "Mi cliente me ha pedido que averigüe dónde han ido a parar ciertos elementos faltantes.",
    ["Who is this client?"] = "¿Quién es este cliente?",
    ["I'm not at liberty to discuss that. Investigator-client confidentiality don't you know."] = "No tengo libertad para discutir eso. Confidencialidad investigador-cliente, ¿no lo sabes?",
    ["What do you want to ask?"] = "¿Qué quieres preguntar?",
    ["Where is this place?"] = "¿Dónde está este lugar?",
    ["I've heard it called Puro-Puro. It seems to be the home plane of the implings. I don't think these creatures have a name for it. As you can see there isn't a lot else here other than wheat."] = "He oído que se llama Puro-Puro. Parece ser el plano de origen de los implícitos. No creo que estas criaturas tengan un nombre para ello. Como puedes ver, aquí no hay mucho más que trigo.",
    ["How did you get here?"] = "¿Cómo llegaste aquí?",
    ["The same way you did, I suspect. Through a portal in a wheat field. I followed one back."] = "Sospecho que igual que tú. A través de un portal en un campo de trigo. Seguí a uno de regreso.",
    ["I haven't noticed them do that."] = "No he notado que hagan eso.",
    ["That's why I'm the investigator and you're the adventurer."] = "Por eso yo soy el investigador y tú el aventurero.",
    ["So what are these implings?"] = "Entonces, ¿cuáles son estas implicaciones?",
    ["Can I catch these implings then?"] = "¿Puedo captar estos implings entonces?",
    ["I've heard I may find dragon equipment in Puro-Puro."] = "He oído que puedo encontrar equipamiento para dragones en Puro-Puro.",
    ["So, what are these implings?"] = "Entonces, ¿cuáles son estas implicaciones?",
    ["That's a very interesting question. My best guess is that they are relatives to imps, which is why there are imps here as well. Implings do appear to like collecting objects and, as my clients have noted, have no concept of ownership. However, I do not sense any malicious intent. It is my observation that they collect things that other creatures want, rather than they want them themselves. It seems to provide them with sustenance."] = "Esa es una pregunta muy interesante. Mi mejor suposición es que son parientes de los diablillos, razón por la cual también hay diablillos aquí. A los implings parece gustarles coleccionar objetos y, como han notado mis clientes, no tienen ningún concepto de propiedad. Sin embargo, no percibo ninguna intención maliciosa. Mi observación es que coleccionan cosas que otras criaturas quieren, en lugar de quererlas ellos mismos. Parece proporcionarles sustento.",
    ["So they feed off our desire for things?"] = "¿Entonces se alimentan de nuestro deseo por las cosas?",
    ["Possibly. Either way, it seems that they almost exclusively collect things that people want, except their younglings who I infer haven't learnt the best things to collect yet."] = "Posiblemente. De cualquier manera, parece que coleccionan casi exclusivamente cosas que la gente quiere, excepto sus jóvenes, quienes infiero que aún no han aprendido cuáles son las mejores cosas para coleccionar.",
    ["So the more experienced implings have the more desirable items?"] = "Entonces, ¿los implings más experimentados tienen los elementos más deseables?",
    ["That is my observation. Yes."] = "Esa es mi observación. Sí.",
    ["Can I catch these implings, then?"] = "¿Puedo captar estos implings entonces?",
    ["Indeed you may. In fact I encourage it. You will, however, require some equipment."] = "De hecho, puedes hacerlo. De hecho lo animo. Sin embargo, necesitarás algo de equipo.",
    ["Have you indeed? Well, that may well be true, though bear in mind that implings are quite small so they are unlikely to be lugging a sizeable shield around with them. However, since it seems that dragon items are"] = "¿De verdad lo has hecho? Bueno, eso bien puede ser cierto, aunque tenga en cuenta que los implicados son bastante pequeños, por lo que es poco probable que lleven consigo un escudo de tamaño considerable. Sin embargo, dado que parece que los objetos de dragón son",
    ["very desirable to humans then it certainly is possible that the most expert implings may try to obtain such equipment."] = "muy deseable para los humanos, entonces ciertamente es posible que los implings más expertos intenten obtener dicho equipo.",
    ["So, it's true then? Cool!"] = "Entonces, ¿es cierto? ¡Fresco!",
    ["I should warn you, though, if the impling is strong enough to collect dragon equipment, then you will have to be very skilled at hunting implings in order to catch them."] = "Sin embargo, debo advertirte que si el impling es lo suficientemente fuerte como para recolectar equipo de dragón, entonces tendrás que ser muy hábil cazando implings para poder atraparlos.",
    ["*(Shows other options)*"] = "*(Muestra otras opciones)*",
    ["Ah, good day, it's you again. What can I do for you?"] = "Ah, buenos días, eres tú otra vez. ¿Qué puedo hacer por ti?",
    ["Can you remind me how to catch implings again?"] = "¿Puedes recordarme cómo atrapar implícitos otra vez?",
    ["Certainly."] = "Por supuesto.",
    ["**Elnock Inquisitor:** In Puro-Puro, you will need a butterfly net to catch an impling and at least one special impling jar to store them in. You will also require some experience as a Hunter, since these creatures are elusive. The more immature implings require less experience, but some of the rarer implings are extraordinarily hard to find and catch. Some of these implings have escaped to Gielinor, but have been exhausted by the journey. Assuming you are experienced enough, you can catch them without needing any equipment. Once you have caught an impling in a jar, you can break the jar open to obtain the impling's object, or you can exchange certain combinations of jars with me. I will then return the jars to my clients. In exchange, I will provide equipment that helps you hunt implings and butterflies more effectively. But beware: imps in the maze do not like their kind being captured, and will attempt to steal any full jars you have on you, setting the implings free."] = "**Elnock Inquisitor:** En Puro-Puro, necesitarás un cazamariposas para atrapar un impling y al menos un frasco especial para guardarlo. También necesitarás algo de experiencia como Hunter, ya que estas criaturas son esquivas. Los implícitos más inmaduros requieren menos experiencia, pero algunos de los implícitos más raros son extraordinariamente difíciles de encontrar y detectar. Algunos de estos implings han escapado a Gielinor, pero han quedado agotados por el viaje. Suponiendo que tengas suficiente experiencia, podrás atraparlos sin necesidad de ningún equipo. Una vez que hayas atrapado un implicado en un frasco, puedes abrir el frasco para obtener el objeto del implicado, o puedes intercambiar ciertas combinaciones de frascos conmigo. Luego devolveré los frascos a mis clientes. A cambio, te proporcionaré equipo que te ayudará a cazar implings y mariposas de manera más efectiva. Pero cuidado: a los diablillos en el laberinto no les gusta que capturen a los de su especie e intentarán robar cualquier frasco lleno que tengas encima, liberando a los diablillos.",
    ["Tell me more about these jars."] = "Cuéntame más sobre estos frascos.",
    ["You cannot use an ordinary butterfly jar as a container, as the implings escape from them with ease. I have, however, done some investigating and come up with a solution: if a butterfly jar is coated with a thin layer of a substance that is noxious to them, implings become incapable of escape."] = "No puedes utilizar un frasco de mariposas común y corriente como recipiente, ya que los implings se escapan de ellos con facilidad. Sin embargo, investigué un poco y encontré una solución: si un frasco de mariposas se recubre con una fina capa de una sustancia que les resulta nociva, los implícitos se vuelven incapaces de escapar.",
    ["What substance is that, then?"] = "¿Qué sustancia es esa entonces?",
    ["I have tried a few experiments with the help of a friend back home, and it turns out that a combination of anchovy oil and flowers - marigolds, rosemary or nasturtiums - will work."] = "He probado algunos experimentos con la ayuda de un amigo en casa y resulta que una combinación de aceite de anchoa y flores (caléndulas, romero o capuchinas) funcionará.",
    ["How do you make anchovy oil then?"] = "¿Cómo se hace entonces el aceite de anchoa?",
    ["I'd grind up some cooked anchovies and pass them through a sieve."] = "Yo molía unas anchoas cocidas y las pasaba por un colador.",
    ["Where do I make these jars?"] = "¿Dónde hago estos frascos?",
    ["Well, I believe there is a chemist in Rimmington that has a small still that you could use."] = "Bueno, creo que hay una farmacia en Rimmington que tiene un pequeño alambique que podrías usar.",
    ["Is there anywhere I can buy these jars?"] = "¿Hay algún lugar donde pueda comprar estos frascos?",
    ["Well, I may be able to sell you a few, although I don't have an infinite supply. I can also offer several empty jars in exchange for any full ones you have."] = "Bueno, tal vez pueda venderte algunos, aunque no tengo un suministro infinito. También puedo ofrecer varios frascos vacíos a cambio de los llenos que tengas.",
    ["*(Shows previous options)*"] = "*(Muestra opciones anteriores)*",
    ["Tell me more about these thieving imps."] = "Cuéntame más sobre estos diablillos ladrones.",
    ["Imps and implings appear to be related, and the imps here are quite protective of their smaller relations. If you allow them to get too close then they will attempt to steal jarred implings from your pack, if you have them. They will then set them free, dropping your jar on the floor. So, if you're quick, you may be able to catch it again. I have some impling deterrent which I may trade if you prove that you can catch implings well."] = "Los diablillos y los implícitos parecen estar relacionados, y los diablillos aquí son bastante protectores con sus relaciones más pequeñas. Si les permites acercarse demasiado, intentarán robar implings de tu mochila, si los tienes. Luego los soltarán y dejarán caer el frasco al suelo. Entonces, si eres rápido, es posible que puedas atraparlo nuevamente. Tengo algo de disuasión de implicaciones que puedo intercambiar si demuestras que puedes captar bien las implicaciones.",
    ["So, what's this equipment you can provide, then?"] = "Entonces, ¿cuál es el equipo que puedes proporcionar?",
    ["I have been given permission by my clients to give three pieces of equipment to able hunters. Firstly, I have some imp deterrent. If you bring me three baby implings, two young implings and one gourmet impling already jarred, I will give you a vial. Imps don't like the smell, so they will be less likely to steal jarred implings from you. Secondly, I have magical butterfly nets. If you bring me three gourmet implings, two earth implings and one essence impling I will give you a new net. It will help you catch both implings and butterflies. Lastly, I have magical jar generators. If you bring me three essence implings, two eclectic implings and one nature impling I will give you a jar generator. This object will create either butterfly or impling jars (up to a limited number of charges) without having to carry a pack full of them."] = "Mis clientes me han dado permiso para regalar tres equipos a cazadores capaces. En primer lugar, tengo algo de disuasión para diablillos. Si me traes tres implings bebés, dos implings jóvenes y un implingo gourmet ya envasados, te daré un vial. A los diablillos no les gusta el olor, por lo que será menos probable que te roben los implings en frascos. En segundo lugar, tengo cazamariposas mágicas. Si me traes tres implicaciones gourmet, dos implicaciones de tierra y una implicación de esencia, te daré una red nueva. Te ayudará a atrapar tanto implings como mariposas. Por último, tengo generadores de tarros mágicos. Si me traes tres implicaciones de esencia, dos implicaciones eclécticas y una implicación de naturaleza, te daré un generador de frascos. Este objeto creará frascos de mariposas o de implícitos (hasta un número limitado de cargas) sin tener que llevar un paquete lleno de ellos.",
    ["Could you store some equipment for me?"] = "¿Podrías guardarme algún equipo?",
    ["I suppose I could keep hold of a net and a few empty jars for you. Just give me what you want me to hold."] = "Supongo que podría guardarte una red y algunos frascos vacíos. Sólo dame lo que quieres que te sostenga.",
    ["*(Elnock's Equipment Store opens)*"] = "*(Se abre la tienda de equipos de Elnock)*",
    ["Do you have some spare equipment I can use?"] = "¿Tiene algún equipo de repuesto que pueda usar?",
    ["Can I trade some jarred implings, please?"] = "¿Puedo cambiar algunos implings rotos, por favor?",
    ["*(Elnock's Exchange opens)*"] = "*(Se abre el intercambio de Elnock)*",
    ["Can I buy a few impling jars?"] = "¿Puedo comprar algunos frascos de impling?",
    ["*If the player has not claimed the spare equipment yet:*"] = "*Si el player aún no ha reclamado el equipo de repuesto:*",
    ["Yes! I have some spare equipment for you."] = "¡Sí! Tengo algo de equipo de repuesto para ti.",
    ["There you go. You have everything you need now. If you are ready to start hunting implings, then enter the main part of the maze. Just push through the wheat that surrounds the centre of the maze and get catching!"] = "Ahí lo tienes. Tienes todo lo que necesitas ahora. Si estás listo para comenzar a cazar implings, ingresa a la parte principal del laberinto. ¡Simplemente empuja el trigo que rodea el centro del laberinto y atrapa!",
    ["Thanks, I'll get going."] = "Gracias, me pondré en marcha.",
    ["*If the player has already claimed the spare equipment:*"] = "*Si el player ya ha reclamado el equipo de repuesto:*",
    ["I have already given you some equipment. If you are ready to start hunting implings, then enter the main part of the maze. Just push through the wheat that surrounds the centre of the maze and get catching!"] = "Ya te he dado algunos equipos. Si estás listo para comenzar a cazar implings, ingresa a la parte principal del laberinto. ¡Simplemente empuja el trigo que rodea el centro del laberinto y atrapa!",
    ["**Player:** Hello. What do you do here?"] = "**Player:** Hola. ¿Qué haces aquí?",
    ["I can exchange metal tokens for you, custom fit a set of Trimmed Masterwork Armour or add spikes to your custom-fit armour.<div id=\"Standard\"></div>"] = "Puedo intercambiar fichas de metal por ti, personalizar un conjunto de armadura de obra maestra recortada o agregar púas a tu armadura personalizada.<div id=\"Standard\"></div>",
    ["Metal tokens"] = "Fichas metálicas",
    ["What're metal tokens, you may ask? Well, we did a large recall of some of the older smithing items, due to hazardous smithing conditions when they were created!"] = "¿Qué son las fichas de metal, te preguntarás? Bueno, hicimos un gran retiro de algunos de los artículos de herrería más antiguos, ¡debido a las peligrosas condiciones de herrería cuando fueron creados!",
    ["As such, we've replaced items with tokens of the appropiate metal type, which you can purchase from me, if you've got any tokens."] = "Como tal, hemos reemplazado los artículos con fichas del tipo de metal apropiado, que puedes comprarme si tienes alguna ficha.",
    ["Any other questions?"] = "¿Alguna otra pregunta?",
    ["How can I obtain more tokens?"] = "¿Cómo puedo obtener más tokens?",
    ["You can't obtain any more tokens. We only did the recall once."] = "No puedes obtener más tokens. Sólo hicimos el retiro una vez.",
    ["Can I trade these tokens?"] = "¿Puedo intercambiar estos tokens?",
    ["No, you can't trade these tokens, but you can trade the items you can get by exchanging the tokens."] = "No, no puedes intercambiar estos tokens, pero puedes intercambiar los artículos que puedes obtener al intercambiar los tokens.",
    ["What if I want my old stuff back?"] = "¿Qué pasa si quiero recuperar mis cosas viejas?",
    ["You should be able to buy most of your items back with the tokens we've swapped out for you. If you can't, however, you should be able to smith your old items at a much lower level now."] = "Deberías poder volver a comprar la mayoría de tus artículos con los tokens que hemos intercambiado por ti. Sin embargo, si no puedes, ahora deberías poder forjar tus objetos antiguos a un nivel mucho más bajo.",
    ["I want to exchange these tokens."] = "Quiero intercambiar estos tokens.",
    ["What sort of tokens would you like to exchange?"] = "¿Qué tipo de tokens te gustaría intercambiar?",
    ["Steel."] = "Acero.",
    ["Mithril."] = "Mitril.",
    ["Adamant."] = "Inflexible.",
    ["Rune."] = "Runa.",
    ["Nope."] = "No.",
    ["Custom-fitting masterwork armour."] = "Armadura maestra hecha a medida.",
    ["Ah, I see you have an Artisans' Workshop flyer. In exchange, I have an exclusive pack of sample items for you! You will need 11 spaces in your backpack!"] = "Ah, veo que tienes un folleto del Taller de artesanos. ¡A cambio, tengo un paquete exclusivo de artículos de muestra para ti! ¡Necesitarás 11 espacios en tu backpack!",
    ["Redeem Flyer?"] = "¿Canjear folleto?",
    ["*(If you have enough space in your backpack:)*"] = "*(Si tienes suficiente espacio en tu backpack:)*",
    ["Elof crumples your flyer into a tight ball, and pops it into his mouth. Chewing thoughtfully, he bestows upon you a generous variety of Mining and Smithing supplies!"] = "Elof arruga tu volante hasta convertirlo en una bola apretada y se lo mete en la boca. ¡Masticando pensativamente, te otorga una generosa variedad de suministros Mining y Smithing!",
    ["Wow, thanks! Is there anything else you can give me?<!--It's split into two lines in one dialogue box as per in-game-->"] = "¡Guau, gracias! ¿Hay algo más que puedas darme?<!--It's split into two lines in one dialogue box as per in-game-->",
    ["*(If you do not have enough space in your backpack:)*"] = "*(Si no tienes suficiente espacio en tu backpack:)*",
    ["Come back with 11 spaces in your backpack and I'll give you your free stuff!"] = "¡Vuelve con 11 espacios en tu backpack y te daré tus cosas gratis!",
    ["Exchange which tokens?"] = "¿Intercambiar qué tokens?",
    ["**Elof:** If you've got a fully equipped set of trimmed masterwork, I can custom fit it for you. If it's augmented it'll remain augmented and you'll repair it the same way you repair trimmed masterwork."] = "**Elof:** Si tienes un juego de obras maestras recortadas totalmente equipado, puedo personalizarlo para ti. Si está aumentado, permanecerá aumentado y lo repararás de la misma manera que reparas una obra maestra recortada.",
    ["What does custom-fitting do?"] = "¿Qué hace el ajuste personalizado?",
    ["It will become untradable."] = "Se volverá intransferible.",
    ["It will degrade 50% slower so it'll last longer."] = "Se degradará un 50 % más lento, por lo que durará más.",
    ["It will also never degrade while on a slayer or reaper task."] = "Tampoco se degradará nunca mientras estés en una tarea de cazador o segador.",
    ["But the process is irreversable. Once custom fitted, your masterwork will always be custom fitted."] = "Pero el proceso es irreversible. Una vez hecha a medida, su obra maestra siempre estará hecha a medida.",
    ["*(If you are wearing a full set of trimmed masterwork:)*"] = "*(Si llevas un juego completo de obra maestra recortada:)*",
    ["[Are you sure you want to custom-fit your Trimmed Masterwork armour? This process will make them permanently un-tradeable, make them degrade 50% slower and never degrade when on a slayer or reaper task.]"] = "[¿Estás seguro de que quieres personalizar tu armadura Trimmed Masterwork? Este proceso los hará permanentemente intransferibles, hará que se degraden un 50% más lento y nunca se degradarán cuando estés en una tarea de cazador o segador.]",
    ["Custom-fit your trimmed masterwork?"] = "¿Perfeccionar tu obra maestra recortada a la medida?",
    ["*(If you are not wearing a full set of trimmed masterwork:)*"] = "*(Si no llevas un conjunto completo de obra maestra recortada:)*",
    ["[You must be wearing a full set of trimmed masterwork in order to custom-fit it"] = "[Debes llevar un juego completo de obra maestra recortada para poder personalizarlo.",
    ["Hello. I can add or remove spikes from your custom fit masterwork armour."] = "Hola. Puedo agregar o quitar púas de tu armadura maestra personalizada.",
    ["Do you want to add or remove spikes from your armour?"] = "¿Quieres agregar o quitar púas de tu armadura?",
    ["Add"] = "Añadir",
    ["*(If you do not have any pieces of custom-fit masterwork armour equipped:)*"] = "*(Si no tienes ninguna pieza de armadura maestra hecha a medida equipada:)*",
    ["[You must be wearing at least one piece of eligible armour for me to modify it.]"] = "[Debes llevar al menos una pieza de armadura elegible para que pueda modificarla.]",
    ["*(If you have pieces of custom-fit masterwork armour equipped:)*"] = "*(Si tienes equipadas piezas de armadura maestra hechas a medida:)*",
    ["Are you sure you want to add spikes to your custom-fit Masterwork armour? This process will cost you X Glorious bars."] = "¿Estás seguro de que quieres agregar púas a tu armadura Masterwork personalizada? Este proceso te costará X barras gloriosas.",
    ["Remove"] = "Quitar",
    ["*(If you do not have any pieces of armour with spikes attached equipped:)*"] = "*(Si no tienes ninguna pieza de armadura con púas equipada:)*",
    ["Hello dearie! What can old Elsie do for you?"] = "¡Hola querida! ¿Qué puede hacer el viejo Elsie por ti?",
    ["What are you making?"] = "¿Qué estás haciendo?",
    ["I'm knitting a new stole for Father Lawrence downstairs. He could do with something to keep his neck warm, standing in that draughty old church all day."] = "Estoy tejiendo una estola nueva para Father Lawrence abajo. Le vendría bien algo para mantener el cuello caliente, estando de pie en esa vieja iglesia con corrientes de aire todo el día.",
    ["Can you tell me a story?"] = "¿Puedes contarme una historia?",
    ["Maybe I could tell you a story if you'd fetch me a nice cup of tea."] = "Tal vez podría contarte una historia si me trajeras una buena taza de té.",
    ["I'll think about it."] = "Lo pensaré.",
    ["Can you tell me how to get rich?"] = "¿Puedes decirme cómo hacerme rico?",
    ["Well, dearie, I'm probably not the best person to ask about money, but I think the best thing would be for you to get a good trade. If you've got a trade you can earn your way, that's what my old father told me, Saradomin rest his soul."] = "Bueno, querida, probablemente no sea la mejor persona para preguntar sobre dinero, pero creo que lo mejor sería que consiguieras un buen intercambio. Si tienes un oficio puedes ganarte la vida, eso es lo que me dijo mi padre, Saradomin que en paz descanse.",
    ["I hear people try to get rich by fighting in the Wilderness north of here but that's no way for honest folks to earn a living! So get yourself a good trade, and keep working at it. There's always folks wanting to buy ore and food around here."] = "He oído que hay gente que intenta hacerse rica luchando en el Wilderness al norte de aquí, ¡pero esa no es forma de que la gente honesta se gane la vida! Así que consigue un buen negocio y sigue trabajando en ello. Siempre hay gente que quiere comprar minerales y comida por aquí.",
    ["Thanks for the advice."] = "Gracias por el consejo.",
    ["Ooh - that looks like a lovely cup of tea, dearie. Is it for me?"] = "Oh, parece una deliciosa taza de té, querida. ¿Es para mí?",
    ["Yes, you can have it."] = "Sí, puedes tenerlo.",
    ["Ahh, there's nothing like a nice cuppa tea. I know what, I'll tell you a story to thank you for the lovely tea..."] = "Ahh, no hay nada como una buena taza de té. Ya sé, te contaré una historia para agradecerte el delicioso té...",
    ["A long time ago, when I was a little girl, there was a handsome young man living in Varrock. I saw him here in the church quite often. Everyone said he was going to become a priest, and we girls were so sad about that."] = "Hace mucho tiempo, cuando yo era pequeña, había un joven apuesto que vivía en Varrock. Lo vi aquí en la iglesia con bastante frecuencia. Todo el mundo decía que iba a ser sacerdote y nosotras, las chicas, estábamos muy tristes por eso.",
    ["But young Dissy - that was the young man's nickname - he was a wild young thing. One night he gathered some lads together, and after the evening prayer-meeting they all put on masks and sneaked down to the evil temple in the south of the city, the evil one."] = "Pero el joven Dissy, ese era el apodo del joven, era un joven salvaje. Una noche reunió a algunos muchachos y, después de la reunión de oración vespertina, todos se pusieron máscaras y se escabulleron al templo del mal en el sur de la ciudad, el maligno.",
    ["The next day, there was quite a hubbub. The guards told us that someone had painted 'Saradomin pwns' on the wall of the Zamorakian temple!"] = "Al día siguiente, hubo un gran alboroto. ¡Los guardias nos dijeron que alguien había pintado 'Pwns Saradomin' en la pared del templo zamorakiano!",
    ["Now, we'd always been taught to keep well away from that dreadful place, but it really did us all good to see someone wasn't afraid of the scum who live at that end of town. Old Father Packett was furious, but Dissy just laughed it off."] = "Ahora, siempre nos habían enseñado a mantenernos alejados de ese lugar espantoso, pero realmente nos hizo bien a todos ver que alguien no tenía miedo de la escoria que vive en ese extremo de la ciudad. El viejo padre Packett estaba furioso, pero Dissy simplemente se rió.",
    ["Dissy left town after that, saying he wanted to see the world. It was such a shame, he had the most handsome shoulders..."] = "Dissy se fue de la ciudad después de eso, diciendo que quería ver mundo. Era una lástima, tenía los hombros más bonitos...",
    ["A young man came here looking for stories about Dissy - of course, that's not his proper name, but his friends called him Dissy - and I told him that one. He said Dissy had become a really famous man and there was going to be a book about him."] = "Un joven vino aquí buscando historias sobre Dissy - claro, ese no es su nombre propio, pero sus amigos lo llamaban Dissy - y se lo conté. Dijo que Dissy se había convertido en un hombre muy famoso y que se publicaría un libro sobre él.",
    ["Well, that's all good, but I do wish Dissy had just come back to Varrock. I did miss him so much... well, until I met my Freddie and we got married, but that's another story."] = "Bueno, todo eso está bien, pero desearía que Dissy hubiera regresado a Varrock. Lo extrañé mucho... bueno, hasta que conocí a mi Freddie y nos casamos, pero esa es otra historia.",
    ["Thank you. I'll leave you to your knitting now."] = "Gracias. Te dejo con tu tejido ahora.",
    ["No, keep your hands off my tea."] = "No, mantén tus manos alejadas de mi té.",
    ["Aww. Maybe another time. Anyway, what can old Elsie do for you?"] = "Ay. Quizás en otra ocasión. De todos modos, ¿qué puede hacer el viejo Elsie por ti?",
    ["Well, maybe I could tell you a story if you'd give me that lovely cup of tea you've got there."] = "Bueno, tal vez podría contarte una historia si me das esa deliciosa taza de té que tienes ahí.",
    ["I might. Which one were you thinking of?"] = "Podría hacerlo. ¿En cuál estabas pensando?",
    ["The north-western allotment."] = "La parcela del noroeste.",
    ["The south-eastern allotment."] = "La parcela del sureste.",
    ["Good day."] = "Buenos días.",
    ["Hello, there. It's a lovely day for a walk in the woods. What can I help you with?"] = "Hola. Es un hermoso día para dar un paseo por el bosque. ¿En qué puedo ayudarte?",
    ["I'm just looking around."] = "Sólo estoy mirando a mi alrededor.",
    ["Hello again, how is it going?"] = "Hola de nuevo, ¿cómo te va?",
    ["Not bad, thank you."] = "No está mal, gracias.",
    ["I understand you agreed to help us! This is good news indeed."] = "¡Entiendo que aceptaste ayudarnos! Esta es realmente una buena noticia.",
    ["I understand you agreed to help us! This is good news indeed. Do you need me to re-enchant your crystal teleport seeds?"] = "¡Entiendo que aceptaste ayudarnos! Esta es realmente una buena noticia. ¿Necesitas que vuelva a encantar tus semillas de teletransporte de cristal?",
    ["You do not have enough coins to cover that cost, sorry."] = "No tienes suficiente coins para cubrir ese costo, lo siento.",
    ["150 coins have been removed from your money pouch."] = "Se han eliminado 150 coins de tu bolsa de dinero.",
    ["Arianwyn says you tried your first chant - and it showed promise?"] = "Arianwyn dice que probaste tu primer canto, ¿y resultó prometedor?",
    ["Well, he had to strengthen it, but it was a good start apparently."] = "Bueno, tuvo que fortalecerlo, pero aparentemente fue un buen comienzo.",
    ["Excellent. Well if you have the teleport crystal, we can try and chant it to go to two locations, if you'd like?"] = "Excelente. Bueno, si tienes el cristal de teletransporte, podemos intentar cantarlo para ir a dos lugares, si quieres.",
    ["I've got one right here."] = "Tengo uno aquí.",
    ["Excellent, let's see what you've got - try chanting it for me."] = "Excelente, veamos qué tienes. Intenta cantarlo por mí.",
    ["Okay, sure."] = "Está bien, claro.",
    ["Not bad, but try this..."] = "No está mal, pero prueba esto...",
    ["Nearly! Just a bit more."] = "¡Casi! Sólo un poquito más.",
    ["Excellent, that'll ensure any more seeds will follow suit, try seeing where it can go now."] = "Excelente, eso asegurará que más semillas sigan su ejemplo, intenta ver adónde puede llegar ahora.",
    ["Thanks for your help Eluned."] = "Gracias por tu ayuda Eluned.",
    ["Oh, I don't have one."] = "Oh, no tengo uno.",
    ["I'll be here when you find one."] = "Estaré aquí cuando encuentres uno.",
    ["Not bad, thank you. Why are you still wandering around the forest?"] = "No está mal, gracias. ¿Por qué sigues deambulando por el bosque?",
    ["You mean instead of in Prifddinas? I guess I've spent so long out here, this feels more like home to me. I love the city, but I also still love getting out and wandering the forest."] = "¿Quieres decir en lugar de en Prifddinas? Supongo que he pasado tanto tiempo aquí que me siento más como en casa. Amo la ciudad, pero también me encanta salir y pasear por el bosque.",
    ["Fair enough."] = "Muy bien.",
    ["Hello, Eluned. What's it like being back in Prifddinas?"] = "Hola, Eluned. ¿Cómo es estar de regreso en Prifddinas?",
    ["You might find this hard to believe... but this is my first time in the city. I love it - it's so beautiful. From my earliest memories, the city - or, at least, what remained of it - has always been held by the Iorwerth."] = "Puede que te resulte difícil de creer... pero esta es mi primera vez en la ciudad. Me encanta, es tan hermoso. Desde mis primeros recuerdos, la ciudad, o al menos lo que quedó de ella, siempre ha estado en manos de los Iorwerth.",
    ["So, where were you born, if you don't mind me asking?"] = "Entonces, ¿dónde naciste, si no te importa que te lo pregunte?",
    ["I was born in... huh. That's funny, I don't recall."] = "Nací en... eh. Qué gracioso, no lo recuerdo.",
    ["Didn't your parents ever tell you?"] = "¿Tus padres nunca te lo dijeron?",
    ["Oh. Er... I'm an orphan. I don't know anything about my parents either."] = "Ah. Er... soy huérfano. Tampoco sé nada sobre mis padres.",
    ["Oh, I'm sorry."] = "Oh, lo siento.",
    ["It's okay. Well, I mean, it's not okay... but I don't mind you asking. I was taken in by the Ithell and raised as one of their own. They're all the family I could ever want. I'm always happy to enchant something for you. Islwyn's taught me how to sing weapons now, too!"] = "Está bien. Bueno, quiero decir, no está bien... pero no me importa que lo preguntes. Los Ithell me acogieron y me criaron como uno de los suyos. Son toda la familia que podría desear. Siempre estoy feliz de encantarte algo. ¡Islwyn ahora también me enseñó a cantar armas!",
    ["Oh, you don't have any seeds I can't enchant, nor crystal items for me to repair. I'll be here whenever you do."] = "Oh, no tienes semillas que no pueda encantar, ni objetos de cristal que pueda reparar. Estaré aquí cuando lo hagas.",
    ["*(One of the following is shown every 30 seconds:)*"] = "*(Se muestra uno de los siguientes cada 30 segundos:)*",
    ["Oh hello there! Exciting times are approaching... or possibly approached."] = "¡Hola! Se acercan tiempos emocionantes... o posiblemente se acercan.",
    ["The museum has finally obtained the funding to start digging into the history of Gielinor. Quite literally."] = "El museo finalmente obtuvo la financiación para comenzar a profundizar en la historia de Gielinor. Literalmente.",
    ["Soon the guild will be opening at the Varrock Dig Site and the door to the past will be flung wide open!"] = "¡Pronto el gremio se abrirá en el sitio de excavación Varrock y la puerta al pasado se abrirá de par en par!",
    ["You should give it a look yourself. An accomplished adventurer like you, why I bet you'll be a natural!"] = "Deberías echarle un vistazo tú mismo. Un aventurero consumado como tú, ¡apuesto a que serás natural!",
    ["You'll need quite the skill to dig deep into the earth and uncover the ancient secrets."] = "Necesitarás bastante habilidad para cavar profundamente en la tierra y descubrir los secretos antiguos.",
    ["And I bet there'll be plenty of strange and wonderful discoveries you could make to enhance your adventuring!"] = "¡Y apuesto a que habrá muchos descubrimientos extraños y maravillosos que podrías hacer para mejorar tus aventuras!",
    ["Give it a look, the Archaeology Guild will be coming to the Varrock Dig Site soon!"] = "Échale un vistazo, ¡el gremio Archaeology llegará pronto al sitio de excavación Varrock!",
    ["Greetings."] = "Saludos.",
    ["Where am I?"] = "¿Dónde estoy?",
    ["*Amlodd herald*"] = "*Heraldo de Amlodd*",
    ["As you've probably DIVINED...you're in the heart of Clan Amlodd, masters of divination and summoning. I crack myself up sometimes."] = "Como probablemente hayas DIVINADO... estás en el corazón del Clan Amlodd, maestros de la adivinación y la invocación. A veces me río de risa.",
    ["*Cadarn herald*"] = "*Heraldo de Cadarn*",
    ["Why you find yourself amongst Clan Cadarn friend. We are the noble protectors of elf kind, protecting the secrets of elven magic and archery."] = "Por qué te encuentras entre los amigos del Clan Cadarn. Somos los nobles protectores de los elfos y protegemos los secretos de la magia y el tiro con arco de los elfos.",
    ["*Crwys herald*"] = "*Heraldo de Crwys*",
    ["Around you are the members of the Clan Crwys, tending to the plants and trees within the city."] = "A tu alrededor están los miembros del Clan Crwys, cuidando las plantas y los árboles dentro de la ciudad.",
    ["*Hefin herald*"] = "*Hefin heraldo*",
    ["Breathe in the calm air of serenity. Here Clan Hefin purified themselves in honour of Seren herself."] = "Respira el aire tranquilo de la serenidad. Aquí el Clan Hefin se purificó en honor a la propia Seren.",
    ["*Iorwerth herald*"] = "*Heraldo de Iorwerth*",
    ["Here you will find the great Clan Iorwerth, masters of melee combat and slayers of monsters."] = "Aquí encontrarás al gran Clan Iorwerth, maestros del combate cuerpo a cuerpo y cazadores de monstruos.",
    ["*Ithell herald*"] = "*El heraldo*",
    ["You are at the heart of elven craftsmanship, amongst the Ithell Clan."] = "Estás en el corazón de la artesanía élfica, entre el clan Ithell.",
    ["*Meilyr herald*"] = "*Heraldo Meilyr*",
    ["A noble explorer I see! Welcome to the Meilyr district."] = "¡Veo que es un noble explorador! Bienvenido al distrito de Meilyr.",
    ["*Trahaearn herald*"] = "*Trahaearn heraldo*",
    ["Toiling around you are the members of Clan Trahaearn, the miners and blacksmiths of elven kind."] = "A tu alrededor trabajan duro los miembros del Clan Trahaearn, los mineros y herreros de raza élfica.",
    ["Where is the Voice of Seren in effect?"] = "¿Dónde está vigente la Voz de Seren?",
    ["Seren's voice currently graces the city districts of <Clan> and <Clan>."] = "La voz de Seren actualmente adorna los distritos de la ciudad de <Clan> y <Clan>.",
    ["[Ask about the city]"] = "[Pregunta por la ciudad]",
    ["Ask about the Voice of Seren."] = "Pregunta por la Voz de Seren.",
    ["*Before completion of The Light Within:*"] = "*Antes de completar La luz interior:*",
    ["Although she is broken into many pieces, Seren still lets us know that her Love is always with us. Each hour, she picks one or more clans to bestow her blessing upon."] = "Aunque está rota en muchos pedazos, Seren aún nos deja saber que su Amor siempre está con nosotros. Cada hora, elige uno o más clanes para otorgarles su bendición.",
    ["*After completion of The Light Within:*"] = "*Después de completar La luz interior:*",
    ["Each hour, Seren picks one or more clans to bestow her blessing upon."] = "Cada hora, Seren elige uno o más clanes para otorgarles su bendición.",
    ["While blessed, training skills in that clan's city district will result in greater experience and additional benefits depending on the skill."] = "Si bien es una bendición, entrenar habilidades en el distrito de la ciudad de ese clan dará como resultado una mayor experiencia y beneficios adicionales dependiendo de la habilidad.",
    ["Ask about the clans."] = "Pregunta por los clanes.",
    ["The clans are spread around the city, each focused on a pair of skills. Amlodd study the spiritual realm and focus on summoning and divination. Cadarn are noble warriors and train in magic and ranged combat. Crwys are attuned to the natural world, skilled in farming and woodcutting. Hefin are pure of body and of faith and dedicate themselves to agility and prayer. Iorwerth are born for combat, fearless in their mastery of melee combat and the art of the slayer. Ithell are the artisans of the city, peerless in their crafting and construction abilities. Meilyr are explorers...in various senses of the word...skilled with both dungeoneering and herblore. Trahaearn are the industrious wing of Prifddinas, working both ore and alloy with their mining and smithing skills."] = "Los clanes están repartidos por la ciudad y cada uno se centra en un par de habilidades. Amlodd estudia el reino espiritual y se concentra en la invocación y la adivinación. Cadarn son guerreros nobles y se entrenan en magia y combate a distancia. Los Crwys están en sintonía con el mundo natural y son expertos en agricultura y tala de madera. Los Hefin son puros de cuerpo y de fe y se dedican a la agilidad y la oración. Los Iorwerth nacieron para el combate, intrépidos por su dominio del combate cuerpo a cuerpo y el arte del asesino. Ellos son los artesanos de la ciudad, incomparables en sus habilidades de artesanía y construcción. Los Meilyr son exploradores... en varios sentidos de la palabra... expertos tanto en mazmorras como en herboristería. Trahaearn es el ala trabajadora de Prifddinas, que trabaja tanto minerales como aleaciones con sus habilidades de minería y herrería.",
    ["Ask about the history"] = "pregunta sobre la historia",
    ["Founding the city."] = "Fundación de la ciudad.",
    ["The great city of Prifddinas was originally built many centuries ago by the original settlers, who travelled here with Seren. It was heartbreaking for our ancestors to leave their home of so many years, but worse was the idea of losing Seren. So all elves left Tarddiad and made their way through the World Gate to Gielinor. We brought the original materials from our world Tarddiad, as a reminder of the world left behind. But they had Seren beside them, and so the elves prospered. Crystal singers weaved the inert crystal seeds into the beautiful structures that you see today. Chords became its foundations and harmonies became its architecture. A great tower was built for Seren herself, so all knew where to find her, and it formed the centre of the city. It was named the Tower of Voices, in honour of the music that brought the city to life. Our city has endured - in some form - for centuries. Few places can claim as much."] = "La gran ciudad de Prifddinas fue construida originalmente hace muchos siglos por los colonos originales, que viajaron hasta aquí con Seren. Fue desgarrador para nuestros antepasados ​​dejar el hogar de tantos años, pero peor fue la idea de perder Seren. Entonces todos los elfos abandonaron Tarddiad y atravesaron la Puerta del Mundo hacia Gielinor. Trajimos los materiales originales de nuestro mundo Tarddiad, como recordatorio del mundo que queda atrás. Pero tenían a Seren a su lado, y así los elfos prosperaron. Los cantantes de cristal tejieron las semillas de cristal inertes en las hermosas estructuras que ves hoy. Los acordes se convirtieron en sus cimientos y las armonías en su arquitectura. Se construyó una gran torre para la propia Seren, para que todos supieran dónde encontrarla, y formó el centro de la ciudad. Fue nombrada Torre de las Voces, en honor a la música que dio vida a la ciudad. Nuestra ciudad ha perdurado -de alguna forma- durante siglos. Pocos lugares pueden reclamar tanto.",
    ["Seren and the city."] = "Seren y la ciudad.",
    ["She was the reason that the elven race came to Gielinor. They would rather have stayed with her, than on the world of their birth. Through her tutelage they learned how to tame this strange new world, and prospered. Then, after a few centuries the other 'gods' came. They were brutish, violent and destructive. They cut across Gielinor like a forest fire, destroying everything in their path. To save her people, Seren stood against them, though I'm sure she knew what it would cost her. Guthix awoke, disturbed from his slumber by the war raging above and he cast the gods out of the world. Because she had fought them, he demanded Seren leave with the gods. But such was her love for the elven people, Seren could not bear to leave. She shattered herself and distributed her crystalline essence across the world, knowing that the elves would seek her out and keep her close. She may be shattered and broken, but still we feel her love all around us."] = "Ella fue la razón por la que la raza élfica llegó a Gielinor. Preferirían quedarse con ella que en el mundo donde nacieron. Gracias a su tutela aprendieron a dominar este nuevo y extraño mundo y prosperaron. Luego, después de unos siglos, llegaron los otros \"dioses\". Eran brutales, violentos y destructivos. Atravesaron Gielinor como un incendio forestal, destruyendo todo a su paso. Para salvar a su gente, Seren se enfrentó a ellos, aunque estoy seguro de que sabía lo que le costaría. Guthix despertó, perturbado de su sueño por la guerra que se desataba en el cielo y expulsó a los dioses del mundo. Debido a que ella había luchado contra ellos, exigió que Seren se fuera con los dioses. Pero tal era su amor por los elfos que Seren no podía soportar irse. Se hizo añicos y distribuyó su esencia cristalina por todo el mundo, sabiendo que los elfos la buscarían y la mantendrían cerca. Puede que esté destrozada y rota, pero aun así sentimos su amor a nuestro alrededor.",
    ["The city's reversion."] = "La reversión de la ciudad.",
    ["[Iorwerth herald only]"] = "[Sólo heraldo de Iorwerth]",
    ["It's easy to make out Clan Iorwerth to be the villains, but we were not the ones who abandoned the city. The Cadarn will tell you how they left on a brave voyage of discovery, but it was the Iorwerth who left to protect the city. The 'legendary king Baxtorian'...pffft. He only cared about his own glory. WE were the ones who wanted to keep the city safe. The other clans were not cooperative, so they had to be brought in line. It was for the greater good of Prifddinas, you understand. A firm and absolute government was needed. Only the Iorwerth had the strength of will to maintain order, regardless of the cost. Before long, the Iorwerth's noble efforts had spiralled out of control. What had been intended to protect the city ended up as a civil war that threatened to destroy it. It was during this civil war that the elders gathered together and performed the ritual that would revert the city to its crystalline form. If the war ended with Iorwerth in charge, the elves could have been great. Instead of the isolationist cowards that they were... are again."] = "Es fácil distinguir que el Clan Iorwerth son los villanos, pero no fuimos nosotros quienes abandonamos la ciudad. El Cadarn te contará cómo partieron en un valiente viaje de descubrimiento, pero fueron los Iorwerth quienes partieron para proteger la ciudad. El 'rey legendario Baxtorian'...pffft. Sólo le importaba su propia gloria. Éramos NOSOTROS los que queríamos mantener la ciudad segura. Los otros clanes no cooperaron, por lo que hubo que alinearlos. Fue por el bien de Prifddinas, ¿entiendes? Se necesitaba un gobierno firme y absoluto. Sólo los Iorwerth tenían la fuerza de voluntad para mantener el orden, sin importar el costo. En poco tiempo, los nobles esfuerzos de Iorwerth se salieron de control. Lo que se pretendía proteger la ciudad acabó siendo una guerra civil que amenazaba con destruirla. Fue durante esta guerra civil que los ancianos se reunieron y realizaron el ritual que devolvería a la ciudad su forma cristalina. Si la guerra hubiera terminado con Iorwerth a cargo, los elfos podrían haber sido geniales. En lugar de los cobardes aislacionistas que eran... son de nuevo.",
    ["[Any other heralds]"] = "[Cualquier otro heraldo]",
    ["There were some who didn't want to just hide away in our city, after Seren shattered herself. They were gripped with a desire to explore and to reach out to the other races on Gielinor. Led by Baxtorian, they left for pastures new. But with Clan Cadarn gone, we were left defenceless from the evil that had grown within our own city. Iorwerth, led by the former lord, attacked the city in a desperate grab for power. The remaining clans were not warriors you understand, so the Iorwerth slaughtered them in droves. To protect the culture and traditions of the houses, the great lords of the other houses fled into exile. But before they did, they did the unthinkable. To protect Prifddinas, they performed the Ritual of Reversion and the city began to unmake itself. The people watched in horror as the great city shrank in on itself, homes gone, everything that made them elves...gone. It was necessary. If they had not, who knows what the Iorwerth would have done to our beloved city?"] = "Hubo algunos que no querían simplemente esconderse en nuestra ciudad, después de que Seren se destrozara. Les invadió el deseo de explorar y acercarse a las otras razas en Gielinor. Liderados por Baxtorian, partieron hacia nuevos pastos. Pero con la desaparición del Clan Cadarn, quedamos indefensos ante el mal que había crecido dentro de nuestra propia ciudad. Iorwerth, liderado por el antiguo señor, atacó la ciudad en un intento desesperado por hacerse con el poder. Los clanes restantes no eran guerreros, como comprenderás, por lo que los Iorwerth los masacraron en masa. Para proteger la cultura y las tradiciones de las casas, los grandes señores de las otras casas huyeron al exilio. Pero antes de hacerlo, hicieron lo impensable. Para proteger a Prifddinas, realizaron el Ritual de Reversión y la ciudad comenzó a desmoronarse. La gente observó con horror cómo la gran ciudad se encogía sobre sí misma, los hogares desaparecían, todo lo que los convertía en elfos... desaparecía. Era necesario. Si no lo hubieran hecho, ¿quién sabe qué le habría hecho Iorwerth a nuestra querida ciudad?",
    ["Could I buy your clan's cape?"] = "¿Puedo comprar la capa de tu clan?",
    ["I'll sell you our clan's cape for one million coins."] = "Te venderé la capa de nuestro clan por un millón de coins.",
    ["Buy this clan's cape for 1,000,000 coins?"] = "¿Comprar la capa de este clan por 1.000.000 coins?",
    ["Do you have anything else I can buy?"] = "¿Tienes algo más que pueda comprar?",
    ["There is one thing. An amulet, with Seren's symbol. This has been handed down for generations. It was said that when the clans were brought together its true nature would be revealed. We believed this would occur as the elders returned and Prifddinas grew. Alas, this was not the case. Perhaps we are missing something, or perhaps it's just a story. In any case, we're willing to sell the amulet and allow others to attempt to unlock its secrets."] = "Hay una cosa. Un amuleto con el símbolo de Seren. Esto se ha transmitido de generación en generación. Se decía que cuando los clanes se reunieran, se revelaría su verdadera naturaleza. Creíamos que esto ocurriría cuando los mayores regresaran y Prifddinas creciera. Por desgracia, este no fue el caso. Quizás nos estamos perdiendo algo, o quizás sea sólo una historia. En cualquier caso, estamos dispuestos a vender el amuleto y permitir que otros intenten descubrir sus secretos.",
    ["Purchase Seren's symbol?"] = "¿Comprar el símbolo de Seren?",
    ["I'll sell you Seren's symbol for one million coins. You'll only need one per amulet."] = "Te venderé el símbolo de Seren por un millón de coins. Sólo necesitarás uno por amuleto.",
    ["Buy a Seren symbol for 1,000,000 coins?"] = "¿Comprar un símbolo Seren por 1.000.000 coins?",
    ["Wait, that's Seren's symbol... but it's different... how did you do that?"] = "Espera, ese es el símbolo de Seren... pero es diferente... ¿cómo hiciste eso?",
    ["Each clan in the city had a piece, a small item which attached to Seren's symbol. I...acquired...them and attached them."] = "Cada clan de la ciudad tenía una pieza, un pequeño objeto que se adjuntaba al símbolo de Seren. Yo... los adquirí... y los adjunté.",
    ["So we had the solution the entire time. It all seems so obvious now."] = "Así que tuvimos la solución todo el tiempo. Todo parece tan obvio ahora.",
    ["I wish it had been us who found this, but you have my thanks for showing me, Player."] = "Ojalá hubiéramos sido nosotros quienes hubiéramos encontrado esto, pero tienes mi agradecimiento por mostrármelo, Player.",
    ["You have raised Clan (name) suspicions. 1 out of 3 strikes."] = "Has levantado sospechas del clan (nombre). 1 de cada 3 strikes.",
    ["Clan [name] is starting to notice your sneaky ways. 2 out of 3 strikes. They'll catch you the next time."] = "El clan [name] está empezando a notar tus formas astutas. 2 de 3 strikes. Te atraparán la próxima vez.",
    ["Oh dear, they've caught you and they've warned the rest of clan [name]."] = "Madre mía, te han pillado y han avisado al resto del clan [name].",
    ["Are you a surface-dweller?"] = "¿Eres un habitante de la superficie?",
    ["Yes..."] = "Sí...",
    ["Haha! You look funny! All tall and skinny with tiny eyes!"] = "¡Jaja! ¡Te ves gracioso! ¡Todo alto y delgado con ojos diminutos!",
    ["Are you Player? Did you help Zanik save the city?"] = "¿Eres Player? ¿Ayudaste a Zanik a salvar la ciudad?",
    ["Yes, that was me!"] = "¡Sí, ese era yo!",
    ["When I'm older I'm going to be an adventurer, just like Zanik!"] = "Cuando sea mayor seré un aventurero, ¡como Zanik!",
    ["Sorry, I'm not meant to talk to strangers."] = "Lo siento, no debo hablar con extraños.",
    ["Shh! Don't tell anyone!"] = "¡Shh! ¡No se lo digas a nadie!",
    ["Don't tell anyone what?"] = "¿No decirle a nadie qué?",
    ["SHHH!"] = "¡SHHH!",
    ["Help! Help! The surface people are attacking!"] = "¡Ayuda! ¡Ayuda! ¡La gente de la superficie está atacando!",
    ["It's alright, I'm friendly!"] = "¡Está bien, soy amigable!",
    ["Hi."] = "Hola.",
    ["You seem to be fairly happy for someone so spotty."] = "Pareces estar bastante feliz por alguien tan irregular.",
    ["I'd nearly forgotten about those; running my spice stall has taken my mind off the plagues."] = "Casi me había olvidado de eso; Dirigir mi puesto de especias me ha distraído de las plagas.",
    ["I didn't think that a spice store would eat up so much time."] = "No pensé que una tienda de especias consumiría tanto tiempo.",
    ["Well, I'm trying to find a balm for our spots."] = "Bueno, estoy intentando encontrar un bálsamo para nuestras manchas.",
    ["Any leads?"] = "¿Alguna pista?",
    ["I got some cream from a merchant in Al Kharid that was supposed to help but all it seems to do is repel insects."] = "Compré un poco de crema de un comerciante en Al Kharid que se suponía que ayudaría, pero lo único que parece hacer es repeler insectos.",
    ["This merchant wouldn't be called Ali M, would he?"] = "Este comerciante no se llamaría Ali M, ¿verdad?",
    ["That's him. How do you know him?"] = "Ese es él. ¿Cómo lo conoces?",
    ["I've bought things from him in the past, some more useful than others."] = "Le he comprado cosas en el pasado, algunas más útiles que otras.",
    ["Anyway, I'm rambling. You're here to buy something, not to chat."] = "De todos modos, estoy divagando. Estás aquí para comprar algo, no para charlar.",
    ["What are you doing?"] = "¿Qué estás haciendo?",
    ["I have this potion which I thought might help ease your itching."] = "Tengo esta poción que pensé que podría ayudarte a aliviar la picazón.",
    ["If I thought that these spots could be cured by some potion, I would have mixed up one for myself before now."] = "Si pensara que estas manchas podrían curarse con alguna poción, ya habría preparado una antes.",
    ["Sorry... I was just trying to help."] = "Lo siento... Sólo estaba intentando ayudar.",
    ["If Billy sent you, tell him I ain't interested."] = "Si Billy te envió, dile que no estoy interesado.",
    ["Got anything you don't want to lose?"] = "¿Tienes algo que no quieras perder?",
    ["I'd like to access my bank account, please."] = "Me gustaría acceder a mi cuenta bancaria, por favor.",
    ["I'd like to check my PIN settings."] = "Me gustaría verificar la configuración de mi PIN.",
    ["I'd like to see my collection box."] = "Me gustaría ver mi caja de colección.",
    ["Yes thanks, and I'll keep hold of it, too."] = "Sí, gracias, y lo conservaré también.",
    ["Good day. How many I help you?"] = "Buenos días. ¿Cuantos te ayudo?",
    ["Before we go any further, I should inform you that you have items ready for collection from the Grand Exchange."] = "Antes de continuar, debo informarle que tiene artículos listos para ser recogidos en Grand Exchange.",
    ["This is a branch of the Bank of Gielinor. We have branches in many towns."] = "Esta es una sucursal del Banco de Gielinor. Disponemos de sucursales en muchas localidades.",
    ["And what do you do?"] = "¿Y tú qué haces?",
    ["We will look after your items and money for you. Leave your valuables with us if you want to keep them safe."] = "Nos ocuparemos de tus artículos y de tu dinero. Deje sus objetos de valor con nosotros si desea mantenerlos seguros.",
    ["Didn't you used to be called the Bank of Varrock?"] = "¿No te llamaban antes el Banco de Varrock?",
    ["Yes we did, but people kept on coming into our branches outside of Varrock and telling us that our signs were wrong. They acted as if we didn't know what town we were in or something."] = "Sí, lo hicimos, pero la gente seguía entrando a nuestras sucursales fuera de Varrock y diciéndonos que nuestros carteles estaban equivocados. Actuaron como si no supiéramos en qué ciudad estábamos o algo así.",
    ["Well met! My name's Emilia. I do a bit of this, a bit of that. Just try to survive really, there's nothing much else we can do."] = "¡Bien conocido! Mi nombre es Emilia. Hago un poco de esto, un poco de aquello. Sólo trata de sobrevivir de verdad, no hay mucho más que podamos hacer.",
    ["What ales are you serving?"] = "¿Qué cervezas estás sirviendo?",
    ["Well, we've got Asgarnian Ale, Wizard's Mind Bomb and Dwarven Stout, all for only 3 coins."] = "Bueno, tenemos Asgarnian Ale, Wizard's Mind Bomb y Dwarven Stout, todas por solo 3 coins.",
    ["One Asgarnian Ale, please."] = "Una cerveza Asgarnian, por favor.",
    ["I said 3 coins! You haven't got 3 coins!"] = "¡Dije 3 coins! ¡No tienes 3 coins!",
    ["Sorry, I'll come back another day."] = "Lo siento, volveré otro día.",
    ["Thanks, Emily."] = "Gracias, Emily.",
    ["I'll try the Mind Bomb."] = "Probaré la bomba mental.",
    ["Can I have a Dwarven Stout?"] = "¿Puedo tener una Dwarven Stout?",
    ["I don't feel like any of those."] = "No me apetece nada de eso.",
    ["What can you tell me about dwarves and ale?"] = "¿Qué puedes decirme sobre los enanos y la cerveza?",
    ["Oh it's you again. Forgotten the secret already?"] = "Oh, eres tú otra vez. ¿Ya olvidaste el secreto?",
    ["No... I just... misplaced it."] = "No... Simplemente... lo perdí.",
    ["Mmmmm... the secret is in the gold. Drop a gold coin into asgarnian ale and you'll get this weird golden ale that the dwarves seem to love, I think they're genetically attracted to gold."] = "Mmmmm... el secreto está en el oro. Echa una moneda de oro en cerveza asgarniana y obtendrás esta extraña cerveza dorada que parece encantar a los enanos. Creo que se sienten atraídos genéticamente por el oro.",
    ["Thanks, I won't forg...err.. misplace it, this time."] = "Gracias, esta vez no lo olvidaré... err... extravío.",
    ["I was wondering if you could give some feedback on this mead?"] = "Me preguntaba si podrías darnos algún comentario sobre este hidromiel.",
    ["I'd recognise those old kegs anywhere."] = "Reconocería esos viejos barriles en cualquier lugar.",
    ["I'd love to try the next batch of Leslie's mead."] = "Me encantaría probar el próximo lote de hidromiel de Leslie.",
    ["Mead isn't my favourite choice of drink but that's very nice."] = "El hidromiel no es mi bebida favorita, pero es muy agradable.",
    ["That may be the best mead I've ever drunk actually."] = "En realidad, ese puede ser el mejor hidromiel que he bebido.",
    ["The flavours are very subtle. Delicious."] = "Los sabores son muy sutiles. Delicioso.",
    ["Fantastic, I'll pass that on. Thank you!"] = "Fantástico, lo pasaré. ¡Gracias!",
    ["You need the following skills to start this quest: 74 Firemaking, 76 Constitution, 64 Agility."] = "Necesitas las siguientes habilidades para comenzar esta misión: 74 Firemaking, 76 Constitution, 64 Agility.",
    ["What are you all doing here?"] = "¿Qué están haciendo todos aquí?",
    ["Top secret, my friend. But perhaps when you're more experienced you could help us."] = "Alto secreto, amigo mío. Pero quizás cuando tengas más experiencia puedas ayudarnos.",
    ["It's wonderful!"] = "¡Es maravilloso!",
    ["The ringmaster seemed to want to push us away from the other acts; something about fiery carnage..."] = "El maestro de ceremonias parecía querer alejarnos de los otros actos; algo sobre la masacre de fuego...",
    ["I'm just happy to be running the fire poi again! Let me show you how to do it!"] = "¡Estoy feliz de volver a dirigir el poi de fuego! ¡Déjame mostrarte cómo hacerlo!",
    ["Okay."] = "Está bien.",
    ["Do you want to start your flaming poi performance?"] = "¿Quieres comenzar tu actuación de flaming poi?",
    ["Could you explain it to me again?"] = "¿Podrías explicármelo de nuevo?",
    ["Of course!"] = "¡Por supuesto!",
    ["**Emmett:** You should stand on the nearby star to begin. When you're ready, start spinning!"] = "**Emmett:** Debes pararte en la estrella cercana para comenzar. Cuando estés listo, ¡empieza a girar!",
    ["There's a range of tricks you can do with fire poi, some more difficult than others. You can try any you like, but your skill level will determine which ones you're most likely to be able to complete."] = "Hay una variedad de trucos que puedes hacer con fire poi, algunos más difíciles que otros. Puedes probar cualquiera que quieras, pero tu skill level determinará cuáles es más probable que puedas completar.",
    ["You've got as much time as you like, but you can only perform 6 tricks. At the end, I'll let you know how you've done."] = "Tienes todo el tiempo que quieras, pero solo puedes realizar 6 trucos. Al final te contaré cómo te ha ido.",
    ["If for some reason you want to finish early, just speak to me. You can only do one performance at a time."] = "Si por alguna razón quieres terminar antes, háblame. Sólo puedes hacer una actuación a la vez.",
    ["*(If audience reaction is toggled off)* Can you tell me how I'm doing?"] = "*(Si la reacción de la audiencia está desactivada)* ¿Puedes decirme cómo me va?",
    ["*(If audience reaction is toggled on)* Could you stop telling me how I'm doing?"] = "*(Si la reacción de la audiencia está activada)* ¿Podrías dejar de decirme cómo me va?",
    ["Of course! They won't stop talking to you, but they'll stop telling you if they think you're being repetitive or not."] = "¡Por supuesto! No dejarán de hablarte, pero dejarán de decirte si creen que estás siendo repetitivo o no.",
    ["Do you still want me to stop them?"] = "¿Todavía quieres que los detenga?",
    ["You've already done your fire poi performance this week. Speak to the ringmaster to see if there's anything else you can do."] = "Ya hiciste tu actuación de fire poi esta semana. Habla con el maestro de ceremonias para ver si hay algo más que puedas hacer.",
    ["If you want to end your performance, just tell me or walk away from the performance area."] = "Si quieres finalizar tu actuación, dímelo o aléjate del área de actuación.",
    ["Do you want to end your performance early?"] = "¿Quieres terminar tu actuación antes de tiempo?",
    ["Congratulations! You scored [amount] in your Firemaking (fire poi) performance. You received [amount] experience points."] = "¡Felicitaciones! Obtuviste una puntuación de [amount] en tu actuación de Firemaking (poi de fuego). Recibiste puntos de experiencia [amount].",
    ["I'm sorry, but that performance just wasn't good enough for a reward. Try again next week."] = "Lo siento, pero esa actuación no fue lo suficientemente buena para recibir una recompensa. Vuelve a intentarlo la semana que viene.",
    ["Oh no! You didn't score anything in your Firemaking (fire poi) performance. You received 0 experience points."] = "¡Ay no! No obtuviste nada en tu actuación de Firemaking (fire poi). Recibiste 0 puntos de experiencia.",
    ["Can you tell me how I'm doing?"] = "¿Puedes decirme cómo estoy?",
    ["Sera and I heard about the celebration and we wanted to come join in!"] = "¡Sera y yo nos enteramos de la celebración y queríamos unirnos!",
    ["What is it you're doing exactly?"] = "¿Qué estás haciendo exactamente?",
    ["Fire dancing, which by the way is awesome!"] = "¡El baile del fuego, que por cierto es increíble!",
    ["I can see that..."] = "Puedo ver eso...",
    ["Fire dancing is cool, when you're part of a display team!"] = "¡Bailar con fuego es genial cuando eres parte de un equipo de exhibición!",
    ["I could fire dance all day..."] = "Podría bailar con fuego todo el día...",
    ["Here, have this Poi. Perhaps you can learn and one day you'll become the special like me."] = "Toma, ten este Poi. Quizás puedas aprender y algún día te convertirás en alguien especial como yo.",
    ["Thanks, I'll give it a whirl!"] = "¡Gracias, lo intentaré!",
    ["Have you got any more Pois?"] = "¿Tienes más Pois?",
    ["Sorry, I've not got any on me, but I did give some supplies to Alice."] = "Lo siento, no tengo ninguno encima, pero le di algunos suministros a Alice.",
    ["Ok, thanks."] = "Vale, gracias.",
    ["The time of celebration is upon us!"] = "¡Se acerca el momento de la celebración!",
    ["Come back soon and we can dance with fire!"] = "¡Vuelve pronto y podremos bailar con fuego!",
    ["The Wintumber Warmer event hasn't started yet."] = "El evento Wintumber Warmer aún no ha comenzado.",
    ["Dance with fire."] = "Danza con fuego.",
    ["I was here for the new years celebration!"] = "¡Estuve aquí para la celebración de año nuevo!",
    ["That's over now though... so I guess I'll go and fire dance elsewhere."] = "Aunque eso ya se acabó... así que supongo que iré a bailar con fuego a otro lado.",
    ["The Wintumber Warmer event has ended."] = "El evento Wintumber Warmer ha finalizado.",
    ["Akthanakos! What in the world are you playing at?"] = "¡Akthanakos! ¿A qué diablos estás jugando?",
    ["Minding my own business. Not jeopardising the safety of this entire defence. You?"] = "Me ocupo de mis propios asuntos. Sin poner en peligro la seguridad de toda esta defensa. ¿Tú?",
    ["You're slacking off! If that Arch-Glacor gets loose it'll be the end of us all."] = "¡Estás holgazaneando! Si ese Arch-Glacor se suelta, será el fin de todos nosotros.",
    ["Nonsense. My magic is h olding perfectly. You'd do well to attend to your own incantations."] = "Tonterías. Mi magia se mantiene perfectamente. Harías bien en atender a tus propios encantamientos.",
    ["Looks like you've got company."] = "Parece que tienes compañía.",
    ["Agh! What now?"] = "¡Agh! ¿Y ahora qué?",
    ["Oh. World Guardian. What is it? Can't you see I'm busy?"] = "Oh. Guardián del mundo. ¿Qué es? ¿No ves que estoy ocupado?",
    ["What is it?"] = "¿Qué es?",
    ["What's your role here?"] = "¿Cuál es tu papel aquí?",
    ["Blasted thing's taunting us."] = "Maldita cosa se está burlando de nosotros.",
    ["Its favourite is to put its own core out onto the aqueduct, inviting our troops to attack."] = "Su favorito es colocar su propio núcleo en el acueducto, invitando a nuestras tropas a atacar.",
    ["As soon as they set foot out there, it uses its arms to trap them in place, and the core freezes them to death."] = "Tan pronto como ponen un pie allí, usa sus brazos para atraparlos en su lugar y el núcleo los congela hasta morir.",
    ["I can hold its core in place with my magic, preventing that particular gambit."] = "Puedo mantener su núcleo en su lugar con mi magia, evitando esa táctica en particular.",
    ["Take a break. I can handle this."] = "Hacer una pausa. Puedo manejar esto.",
    ["I don't mean to be rude, but unless you can pummel your way through solid, living ice, this is a terrible idea."] = "No quiero ser grosero, pero a menos que puedas abrirte camino a través de hielo sólido y vivo, esta es una idea terrible.",
    ["If Enakhra stops channelling her spell, you must contend with a mechanic where you must break through icy arms before the Arch-Glacor's core freezes you to death."] = "Si Enakhra deja de canalizar su hechizo, debes enfrentarte a una mecánica en la que debes atravesar brazos helados antes de que el núcleo de Arch-Glacor te congele hasta morir.",
    ["**SELECT AN OPTION**"] = "**SELECCIONA UNA OPCIÓN**",
    ["Yes, Bring it on."] = "Sí, adelante.",
    ["It is - as I believe you mortals put it - your funeral."] = "Es, como creo que ustedes, los mortales, dicen, su funeral.",
    ["The 'Exposed Core' mechanic is now active."] = "La mecánica 'Núcleo expuesto' ahora está activa.",
    ["Speak to Enakhra again if you wish to disable the freezing core attack."] = "Habla con Enakhra nuevamente si deseas desactivar el ataque del núcleo congelado.",
    ["Actually, wait!"] = "En realidad, ¡espera!",
    ["The first sensible thing I've heard all day."] = "La primera cosa sensata que escuché en todo el día.",
    ["Could you start blocking that freezing core attack again?"] = "¿Podrías empezar a bloquear ese ataque central congelado nuevamente?",
    ["A wise request. One moment..."] = "Una petición sabia. Un momento...",
    ["The 'Exposed Core' mechanic has been disabled."] = "La mecánica 'Núcleo expuesto' ha sido desactivada.",
    ["Enakhra is now preventing the Arch-Glacor's freezing core attack. Speak to her again if you wish to re-enable the mechanic."] = "Enakhra ahora está impidiendo el ataque central congelado de Arch-Glacor. Habla con ella nuevamente si deseas volver a habilitar la mecánica.",
    ["Greetings young one. How can I enlighten you?"] = "Saludos joven. ¿Cómo puedo iluminarte?",
    ["What do I have to do in this room?"] = "¿Qué tengo que hacer en esta sala?",
    ["In this chamber you will see various piles of shapes. You can pick up these shapes and enchant them using the enchant jewelry spells. By enchanting these shapes, you'll be converting them into orbs which you can place in the hole in the centre. You will get Enchantment Pizazz Points for every ten shapes that you convert and the points you get depends on the level of enchantment spell you cast. You will get a bonus Pizazz Point for enchanting a certain shape at a certain time, which I will periodically shout out. You will also be rewarded with an item for every so many orbs you deposit into the hole."] = "En esta cámara verás varios montones de formas. Puedes elegir estas formas y encantarlas usando los hechizos de encantar joyería. Al encantar estas formas, las convertirás en orbes que podrás colocar en el agujero del centro. Obtendrás puntos de encantamiento Pizazz por cada diez formas que conviertas y los puntos que obtengas dependerán del nivel del hechizo de encantamiento que lances. Obtendrás un punto de Pizazz adicional por encantar una determinada forma en un momento determinado, que gritaré periódicamente. También serás recompensado con un objeto por cada tantos orbes que deposites en el agujero.",
    ["As weill as the magic experience from casting your enchantment spells, you will get Enchantment Pizazz Points for converting so many shapes, plus a bonus point for converting a shape of the correct type. You should also note that you will occasionally be rewarded with items when you put one of the enchanted orbs in the floor."] = "Además de la experiencia mágica al lanzar tus hechizos de encantamiento, obtendrás puntos de encanto de encantamiento por convertir tantas formas, además de un punto de bonificación por convertir una forma del tipo correcto. También debes tener en cuenta que ocasionalmente serás recompensado con objetos cuando coloques uno de los orbes encantados en el suelo.",
    ["Got any tips that may help me?"] = "¿Tienes algún consejo que pueda ayudarme?",
    ["Try to guess or keep track of the time between the changes of the best shape to enchant. This means you can be ready to run to a different shape when you know it is about to change. Look out for the dragon gems, as these will get you more Pizazz Points!"] = "Intenta adivinar o realizar un seguimiento del tiempo entre los cambios de la mejor forma para encantar. Esto significa que puedes estar listo para correr hacia una forma diferente cuando sepas que está a punto de cambiar. ¡Cuidado con las gemas del dragón, ya que te darán más puntos Pizazz!",
    ["Oh, and a word of warning: should you decide to leave this room by a method other than the exit portals, you will be teleported to the entrance and have any items that you picked up in the room removed."] = "Ah, y una advertencia: si decides salir de esta sala por un método distinto a los portales de salida, serás teletransportado a la entrada y se te quitarán todos los objetos que hayas recogido en la sala.",
    ["Thanks, bye!"] = "¡Gracias, adiós!",
    ["Use what you've learned, young one."] = "Usa lo que has aprendido, joven.",
    ["I am Endwyr, and I am the emissary of Seren, here to tell the world about our crystal goddess. I would be happy to tell you more about Seren, if you have questions. Also, you can declare your allegiance to our cause. If so I may have some work for you."] = "Soy Endwyr y soy el emisario de Seren, aquí para contarle al mundo sobre nuestra diosa de cristal. Estaré encantado de contarte más sobre Seren, si tienes preguntas. Además, puedes declarar tu lealtad a nuestra causa. Si es así, puede que tenga algo de trabajo para ti.",
    ["I am Endwyr, and I am the emissary of Seren, here to tell the world about our crystal goddess. I would be happy to tell you more about Seren, if you have questions."] = "Soy Endwyr y soy el emisario de Seren, aquí para contarle al mundo sobre nuestra diosa de cristal. Estaré encantado de contarte más sobre Seren, si tienes preguntas.",
    ["Can you tell me about Seren?"] = "¿Puedes hablarme de Seren?",
    ["What do you want to know about Seren?"] = "¿Qué quieres saber sobre Seren?",
    ["Who is Seren?"] = "¿Quién es Seren?",
    ["Seren is the crystal goddess, beloved of the elven people. She was one of the first to set foot on this land. When she saw the beauty of Gielinor, she brought the elves to settle here alongside the humans. But with the end of the God Wars, Seren too was bound by the Edicts of Guthix, and although she did not leave, she is not what she once was. We honour our lady, though, and we know she will return to her former glory."] = "Seren es la diosa del cristal, amada por los elfos. Fue una de las primeras en pisar esta tierra. Cuando vio la belleza de Gielinor, trajo a los elfos para que se establecieran aquí junto a los humanos. Pero con el fin de las Guerras de Dios, Seren también quedó sujeta a los Edictos de Guthix y, aunque no se fue, ya no es lo que era. Sin embargo, honramos a nuestra señora y sabemos que volverá a su antigua gloria.",
    ["Why should I follow Seren?"] = "¿Por qué debería seguir a Seren?",
    ["Seren is a goddess of peace and growth. She has always watched over the elves, and she can watch over you too. With Seren, we can build a sanctuary, away from the chaos wrought by the other gods."] = "Seren es una diosa de la paz y el crecimiento. Ella siempre ha velado por los elfos y puede cuidarte a ti también. Con Seren podremos construir un santuario, lejos del caos provocado por los otros dioses.",
    ["What does Seren want?"] = "¿Qué quiere Seren?",
    ["Seren is happy to share the bounty of Gielinor, and does not want to be involved in another God War. We elves live apart from the rest of the world, and we have our own ways, without needing to force them on others. All Seren wants is to share the world without needless conflict, where people can live as they choose."] = "Seren está feliz de compartir la generosidad de Gielinor y no quiere involucrarse con otro Dios War. Los elfos vivimos separados del resto del mundo y tenemos nuestras propias costumbres, sin necesidad de imponerlas a los demás. Todo lo que Seren quiere es compartir el mundo sin conflictos innecesarios, donde las personas puedan vivir como quieran.",
    ["I want to declare my support for Seren!"] = "¡Quiero declarar mi apoyo a Seren!",
    ["That's wonderful! On behalf of Seren's followers, I welcome you. Please, take this banner to show your support. I have a gift for you: a book of stories regarding the gods and their followers. Please, read it and learn wisdom. Although they have lost their way, there is something to be learned from reading of the other gods as well. The book is not yet complete, however. When you complete some jobs I will give you more pages."] = "¡Eso es maravilloso! En nombre de los seguidores de Seren, les doy la bienvenida. Por favor, lleve este banner para mostrar su apoyo. Tengo un regalo para ti: un libro de historias sobre los dioses y sus seguidores. Por favor, léelo y aprende sabiduría. Aunque se han perdido, también hay algo que aprender leyendo sobre los otros dioses. Sin embargo, el libro aún no está completo. Cuando completes algunos trabajos te daré más páginas.",
    ["My goddess, Seren, is holding a council of all the gods and races."] = "Mi diosa, Seren, está celebrando un consejo de todos los dioses y razas.",
    ["To draw attention to this momentous gathering, for this weekend only she has cast her voice beyong Prifddinas and over the whole world."] = "Para llamar la atención sobre esta reunión trascendental, solo durante este fin de semana ha emitido su voz más allá de Prifddinas y en todo el mundo.",
    ["What is the council about?"] = "¿De qué se trata el consejo?",
    ["Lady Seren has become aware of a great threat which faces this world, and wishes to address all of its most influential rulers."] = "Lady Seren se ha dado cuenta de la gran amenaza que enfrenta este mundo y desea dirigirse a todos sus gobernantes más influyentes.",
    ["She has not reavealed the nature of this threat to me. You should visit the council yourself - they can be found upstairs in the castle in Burthorpe."] = "Ella no me ha revelado la naturaleza de esta amenaza. Deberías visitar el consejo tú mismo; se pueden encontrar arriba en el castillo en Burthorpe.",
    ["Tell me more about the weekend event."] = "Cuéntame más sobre el evento del fin de semana.",
    ["Lady Seren casts her voice out into our great city of Prifddinas to empower the clans. Powerful bonuses are imparted to humans depending on the clan."] = "Lady Seren lanza su voz a nuestra gran ciudad de Prifddinas para empoderar a los clanes. Se otorgan poderosas bonificaciones a los humanos según el clan.",
    ["This weekend, at great personal exertion, she has cast it across the entire world. Every two hours a new benefit will become active for everyone."] = "Este fin de semana, con un gran esfuerzo personal, lo ha transmitido por todo el mundo. Cada dos horas se activará un nuevo beneficio para todos.",
    ["The efect is random, and could buff gathering skills, artisan skills, combat or support."] = "El efecto es aleatorio y podría mejorar las habilidades de recolección, las habilidades artesanales, el combate o el apoyo.",
    ["Nevermind."] = "No importa.",
    ["Category:God Emissaries"] = "Categoría:God Emissaries",
    ["Wanderer, your movements are as uncertain as a fledgling in first-flight. Are you lost?"] = "Vagabundo, tus movimientos son tan inciertos como los de un novato en el primer vuelo. ¿Estás perdido?",
    ["Do you have a riddle for me?"] = "¿Tienes un acertijo para mí?",
    ["I do. Here it is:"] = "Sí, sí. Aquí está:",
    ["Give me the answer not in words but with an object."] = "Dame la respuesta no con palabras sino con un objeto.",
    ["Like all gorajo, I have no name; instead, I have a path. I have chosen to be a naabe hoardstalker."] = "Como todo gorajo, no tengo nombre; en cambio, tengo un camino. He elegido ser un acechador de naabe.",
    ["My tribe required a mental trial to be given at this door. I am to stop the unclear of mind from passing into danger."] = "Mi tribu requería que se realizara una prueba mental en esta puerta. Debo evitar que los que no tienen la mente clara entren en peligro.",
    ["Can you open the door for me?"] = "¿Puedes abrirme la puerta?",
    ["I am capable of opening the door, ahnanai."] = "Soy capaz de abrir la puerta, ahnanai.",
    ["Well, go on then!"] = "Bueno, ¡adelante!",
    ["Ah, you wish to skip to the end, like a wolf stalking prey. Naabe, it is not that easy. You must prove your clarity of thought with a trial."] = "Ah, deseas saltar hasta el final, como un lobo acechando a su presa. Naabe, no es tan fácil. Debes demostrar tu claridad de pensamiento con una prueba.",
    ["Your mind is as clear as a mountain lake, ahnanai! You may pass, but do so with caution. Your thinking is sharp, but so are the claws and teeth beyond."] = "¡Tu mente es tan clara como un lago de montaña, ahnanai! Puedes pasar, pero hazlo con precaución. Tu pensamiento es agudo, pero también lo son las garras y los dientes más allá.",
    ["All the doors in the room are now unlocked."] = "Todas las puertas de la habitación ahora están desbloqueadas.",
    ["You have proven to be wise, brah, and you would make your sachem proud. Pass in peace."] = "Has demostrado ser sabio, hermano, y enorgullecerías a tu sachem. Pasa en paz.",
    ["I'm afraid you don't have the necessary runes with you at this time, so I can't allow you to access your account. Please bring twenty runes of one type and you can open your account."] = "Me temo que no tienes las runas necesarias contigo en este momento, por lo que no puedo permitirte acceder a tu cuenta. Traiga veinte runas de un tipo y podrá abrir su cuenta.",
    ["Well met, fellow adventurer! How can I help you?"] = "¡Bien conocido, compañero aventurero! ¿Le puedo ayudar en algo?",
    ["How frightfully rude of me, my dear [chap/lady]. My name is Eniola and I work for that most excellent enterprise, the Bank of Gielinor."] = "Qué terriblemente grosero de mi parte, mi querido [chap/lady]. Mi nombre es Eniola y trabajo para la excelente empresa, el Banco de Gielinor.",
    ["If you work for the bank, what are you doing here?"] = "Si trabajas para el banco, ¿qué haces aquí?",
    ["My presence here is the start of a new enterprise of travelling banks."] = "Mi presencia aquí es el comienzo de una nueva empresa de bancos ambulantes.",
    ["I, and others like me, will provide you with the convenience of having banking facilities where they will be of optimum use to you."] = "Yo y otros como yo le brindaremos la comodidad de contar con servicios bancarios que le serán de máxima utilidad.",
    ["So...what are you doing here?"] = "Entonces... ¿qué estás haciendo aquí?",
    ["The Z.M.I., that is, the Zamorakian Magical Institute, requested my services upon discovery of this altar. We at the Bank of Gielinor are a neutral party and are willing to offer our services regardless of affiliation."] = "La Z.M.I., es decir el Instituto Mágico Zamorakiano, solicitó mis servicios al descubrir este altar. Nosotros en el Banco de Gielinor somos una parte neutral y estamos dispuestos a ofrecer nuestros servicios independientemente de su afiliación.",
    ["So that is why I am here."] = "Por eso estoy aquí.",
    ["Can I access my bank account by speaking to you?"] = "¿Puedo acceder a mi cuenta bancaria hablando con usted?",
    ["Of course, dear [sir/lady]."] = "Por supuesto, querido [sir/lady].",
    ["However, I must inform you that because the Z.M.I. are paying for my services, they require anyone not part of the Institute to pay an access fee to open their bank account."] = "Sin embargo, debo informarles que debido a que el Z.M.I. están pagando por mis servicios, exigen que cualquier persona que no sea parte del Instituto pague una tarifa de acceso para abrir su cuenta bancaria.",
    ["But, as our goal as travelling bankers is to make our customers' lives more convenient, we have accomodated to your needs. We know you will be busy creating runes and do not wish to carry money with you. The charge to open your account is the small amount of twenty of one type of rune. The type of rune is up to you."] = "Pero, como nuestro objetivo como banqueros ambulantes es hacer la vida de nuestros clientes más cómoda, nos adaptamos a sus necesidades. Sabemos que estará ocupado creando runas y no desea llevar dinero consigo. El cargo por abrir su cuenta es la pequeña cantidad de veinte de un tipo de runa. El tipo de runa depende de ti.",
    ["Would you like to pay the price of twenty runes to open your bank account?"] = "¿Te gustaría pagar el precio de veinte runas para abrir tu cuenta bancaria?",
    ["Let me open my account and then I'll give you the runes."] = "Déjame abrir mi cuenta y luego te daré las runas.",
    ["I don't have the runes on me. Let me open my account and then I'll give them to you."] = "No tengo las runas encima. Déjame abrir mi cuenta y luego te los daré.",
    ["It's not that I don't trust you, old [chap/girl], but as the old adage goes: 'Payment comes before friends'."] = "No es que no confíe en ti, viejo [chap/girl], pero como dice el viejo refrán: \"El pago está antes que los amigos\".",
    ["No way! I'm not paying to withdraw my own money."] = "¡De ninguna manera! No estoy pagando para retirar mi propio dinero.",
    ["That's preposterous! I'm not paying runes to withdraw my own stuff."] = "¡Eso es absurdo! No estoy pagando runas para retirar mis propias cosas.",
    ["I'm sorry to hear that, [sir/madam]. If you should reconsider, because I believe this service offers excellent value for money, do not hesitate to contact me."] = "Lamento oír eso, [sir/madam]. Si debes reconsiderarlo, porque creo que este servicio ofrece una excelente relación calidad-precio, no dudes en contactarme.",
    ["It costs twenty runes of one type. Do you wish to continue?"] = "Cuesta veinte runas de un tipo. ¿Quieres continuar?",
    ["I'd like to see my Collection box."] = "Me gustaría ver mi caja de Colección.",
    ["An angry wasp has been attracted to the beehives!"] = "¡Una avispa enojada se ha sentido atraída por las colmenas!",
    ["You need a wasp trap to capture the wasp with!"] = "¡Necesitas una trampa para avispas para capturarlas!",
    ["You calmly capture the wasp in the wasp trap."] = "Capturas tranquilamente a la avispa en la trampa para avispas.",
    ["Greetings. What wisdom do you seek?"] = "Saludos. ¿Qué sabiduría buscas?",
    ["I'm new to this place. Where am I?"] = "Soy nuevo en este lugar. ¿Dónde estoy?",
    ["Well young one, you have entered the Magic Training Arena. It was built at the start of the Fifth Age, when runestones were first discovered. It was made because of the many pointless accidents caused by inexperienced"] = "Bueno, joven, has ingresado al Magic Training Arena. Fue construido a principios de la Quinta Edad, cuando se descubrieron por primera vez las piedras rúnicas. Fue hecho debido a los muchos accidentes inútiles causados por inexpertos.",
    ["mages."] = "magos.",
    ["Who created it?"] = "¿Quién lo creó?",
    ["Good question. It was originally made by the ancestors of the wizards in the Wizards Tower. However, it was destroyed by melee and ranged warriors who took offence at the use of this new 'Magic Art'. Recently, the current"] = "Buena pregunta. Originalmente fue hecho por los antepasados ​​​​de los magos en la Torre de los Magos. Sin embargo, fue destruido por guerreros cuerpo a cuerpo y a distancia que se ofendieron por el uso de este nuevo 'Arte Magic'. Recientemente, la actual",
    ["denizens of the Wizards Tower have resurrected the arena including various Guardians you will see as you look around. We are here to help and to ensure things run smoothly."] = "los habitantes de Wizards Tower han resucitado la arena, incluidos varios Guardianes que verás cuando mires a tu alrededor. Estamos aquí para ayudar y garantizar que todo funcione sin problemas.",
    ["Interesting. So what can I do here?"] = "Interesante. Entonces, ¿qué puedo hacer aquí?",
    ["You may train up your skill in the magic arts by travelling through one of the portals at the back of this entrance hall. By training up in one of these areas you will be awarded special Pizazz Points unique to each room. With"] = "Puedes mejorar tus habilidades en las artes mágicas viajando a través de uno de los portales en la parte trasera de este vestíbulo de entrada. Al entrenar en una de estas áreas, recibirás puntos Pizazz especiales, únicos para cada sala. Con",
    ["these points you may claim a variety of items from my fellow guardian up the stairs."] = "En estos puntos puedes reclamar una variedad de artículos de mi compañero guardián que está arriba de las escaleras.",
    ["How do you record the points I have earned?"] = "¿Cómo se registran los puntos que he ganado?",
    ["You really are full of questions! You will need a special Pizazz Progress Hat! I can give you one if you so wish to train here."] = "¡Realmente estás lleno de preguntas! ¡Necesitarás un sombrero de progreso Pizazz especial! Puedo darte uno si así lo deseas para entrenar aquí.",
    ["Ah, I'm afraid I can't give it to you as you don't have room to carry it!"] = "¡Ah, me temo que no puedo dártelo porque no tienes espacio para llevarlo!",
    ["Here you go. Talk to the hat to find out your current Pizazz Point totals."] = "Aquí tienes. Habla con el sombrero para conocer tus totales actuales de Pizazz Point.",
    ["Talk to it?"] = "¿Hablar con él?",
    ["Well of course, it's a magic Pizazz Progress Hat! Mind your manners though, hats have feelings too!"] = "Bueno, por supuesto, ¡es un sombrero mágico de progreso de Pizazz! Pero cuida tus modales, ¡los sombreros también tienen sentimientos!",
    ["Er... if you insist."] = "Er... si insistes.",
    ["Oh, and a word of warning: should you decide to leave the rooms by any method other than the exit portals, you will be teleported to the entrance and have any items that you picked up in the room removed."] = "Ah, y una advertencia: si decides salir de las habitaciones por cualquier método que no sea los portales de salida, serás teletransportado a la entrada y se te quitarán todos los objetos que hayas recogido en la habitación.",
    ["**Player:** Can you explain the different portals?"] = "**Player:** ¿Puedes explicar los diferentes portales?",
    ["They lead to four areas to train your magic: The Telekinetic Theatre, The Alchemists' Playground, The Enchanting Chamber, and The Creature Graveyard."] = "Conducen a cuatro áreas para entrenar tu magia: El Teatro Telequinético, El Patio de Juegos de los Alquimistas, La Cámara Encantadora y El Cementerio de Criaturas.",
    ["What's the Telekinetic Theatre?"] = "¿Qué es el Teatro Telequinético?",
    ["In there you can earn Telekinetic Pizazz Points for trade upstairs."] = "Allí puedes ganar puntos Telekinetic Pizazz para intercambiarlos en el piso de arriba.",
    ["What will I be doing in there?"] = "¿Qué haré allí?",
    ["That depends on how much of a time-waster you are! You are required to use the Telekinetic Grab spell in order to move a statue through a maze. Casting the spell will move the statue towards you until it reaches a wall. So by"] = "¡Eso depende de cuánto pierdes el tiempo! Debes usar el hechizo Telekinetic Grab para mover una estatua a través de un laberinto. Lanzar el hechizo moverá la estatua hacia ti hasta que llegue a una pared. Entonces por",
    ["standing on the different sides of the maze you can move the statue North, East, South or West. You will be rewarded Pizazz Points for each maze successfully solved."] = "de pie en los diferentes lados del laberinto puedes mover la estatua al norte, este, sur u oeste. Recibirás puntos Pizazz por cada laberinto resuelto con éxito.",
    ["It will be clearer when you arrive and there's a Guardian through the portal that will be able to tell you more. There's a book you can buy from the Rewards Guardian upstairs that will explain it all."] = "Será más claro cuando llegues y habrá un Guardián a través del portal que podrá contarte más. Hay un libro que puedes comprar en Rewards Guardian arriba y que lo explicará todo.",
    ["What's the Alchemists' Playground?"] = "¿Qué es el patio de juegos de los alquimistas?",
    ["In the playground you can earn Alchemist Pizazz Points for trading with the rewards guardian upstairs."] = "En el patio de juegos puedes ganar puntos Alchemist Pizazz por intercambiar con el rewards guardian de arriba.",
    ["What's in there?"] = "¿Qué hay ahí dentro?",
    ["You'll find eight cupboards containing items you can turn to gold using the low and high alchemy spells. The money you earn will be taken from you upon leaving the playground to pay for the upkeep of this training arena"] = "Encontrarás ocho armarios que contienen elementos que puedes convertir en oro usando hechizos de alquimia baja y alta. El dinero que ganes te lo quitarán al salir del patio de recreo para pagar el mantenimiento de este campo de entrenamiento.",
    ["and to help fund magic shops around Gielinor. You will be rewarded with 1 Pizazz Point for every 100 coins deposited and a percentage of the money you create. Keep in mind that you will not be able to take more than 1000 coins"] = "y para ayudar a financiar tiendas de magia alrededor de Gielinor. Serás recompensado con 1 Punto Pizazz por cada 100 coins depositados y un porcentaje del dinero que crees. Ten en cuenta que no podrás llevarte más de 1000 coins",
    ["back out with you."] = "Me voy contigo.",
    ["Sounds simple."] = "Suena simple.",
    ["I am afraid not, for the cost of the items varies, as does their locations in the cupboards. You'll see a list of item costs that will help you decide what you should be converting to gold."] = "Me temo que no, porque el costo de los artículos varía, al igual que su ubicación en los armarios. Verás una lista de costos de artículos que te ayudarán a decidir qué deberías convertir en oro.",
    ["Fear not, it will be clearer when you arrive and there's a Guardian through the portal that will be able to tell you more. You can also buy a book from the Rewards Guardian upstairs that will explain it all."] = "No temas, será más claro cuando llegues y habrá un Guardián a través del portal que podrá contarte más. También puedes comprar un libro en Rewards Guardian arriba que lo explicará todo.",
    ["What's the Enchanting Chamber?"] = "¿Qué es la Cámara Encantadora?",
    ["In here you will be able to earn Enchantment Pizazz Points for trade upstairs."] = "Aquí podrás ganar puntos Enchantment Pizazz para intercambiarlos en el piso de arriba.",
    ["What will I have to do?"] = "¿Qué tendré que hacer?",
    ["You will find yourself amongst various piles of shapes. You can pick up these shapes and use one of your enchanting spells upon it to morph it into an orb. You'll also see a hole in the centre of the room; put the orbs in here and for"] = "Te encontrarás entre varios montones de formas. Puedes recoger estas formas y usar uno de tus hechizos encantadores sobre ellas para transformarlas en un orbe. También verás un agujero en el centro de la habitación; Pon los orbes aquí y para",
    ["every 20 we will credit you with a gift. You will get Pizazz Points for every 10 shapes that you convert and the amount of points depends on the spell you use."] = "cada 20 te acreditaremos un regalo. Obtendrás puntos Pizazz por cada 10 formas que conviertas y la cantidad de puntos depende del hechizo que uses.",
    ["What's the difference between the shapes?"] = "¿Cuál es la diferencia entre las formas?",
    ["Ah, you will be notified of a different shape that will give you a bonus Pizazz Point when you convert that shape. You should also look out for dragon stones, as these will give you more Pizazz Points when you convert them."] = "Ah, se te notificará sobre una forma diferente que te dará un punto de Pizazz adicional cuando conviertas esa forma. También debes estar atento a las piedras de dragón, ya que te darán más puntos Pizazz cuando las conviertas.",
    ["It will be clearer when you arrive and there's a Guardian through the portal that will be able to tell you more. You can also buy a book from the Rewards Guardian upstairs that will explain it all."] = "Será más claro cuando llegues y habrá un Guardián a través del portal que podrá contarte más. También puedes comprar un libro en Rewards Guardian arriba que lo explicará todo.",
    ["What's the Creature Graveyard?"] = "¿Qué es el Cementerio de Criaturas?",
    ["In here you will be able to earn Graveyard Pizazz Points for trade upstairs."] = "Aquí podrás ganar puntos Graveyard Pizazz para intercambiarlos en el piso de arriba.",
    ["But what do I have to do in there?"] = "¿Pero qué tengo que hacer ahí dentro?",
    ["Patience young one. A great many creatures die in this world and much of their remains can cause clutter. We have taken it upon ourselves to teleport many bones from these creatures into this graveyard for a use. It's up to"] = "Paciencia, joven. Muchas criaturas mueren en este mundo y muchos de sus restos pueden causar desorden. Nos hemos encargado de teletransportar muchos huesos de estas criaturas a este cementerio para usarlos. depende de",
    ["you to practice your bones to bananas spell in order to put these bones into immediate use - nutritious food for monsters! Just convert the bones and put them in the holes in the walls. There is a drawback to this room"] = "debes practicar tu hechizo de huesos a plátanos para poder poner estos huesos en uso inmediato: ¡alimento nutritivo para monstruos! Simplemente convierte los huesos y colócalos en los agujeros de las paredes. Hay un inconveniente en esta habitación.",
    ["however, the bones often fall on people so you may want to eat some of those bananas to stay alive. When people die we confiscate Pizazz Points for the effort of teleporting incompetent mages."] = "sin embargo, los huesos a menudo caen sobre las personas, por lo que es posible que quieras comer algunos de esos plátanos para seguir con vida. Cuando la gente muere, confiscamos los puntos Pizazz por el esfuerzo de teletransportar a magos incompetentes.",
    ["What else do I get from this besides bruises?"] = "¿Qué más me sale de esto además de moretones?",
    ["As well as the Pizazz Points for giving us the bananas, you will be credited with runestones for your efforts, and you may be able to save up for a new kind of spell to use in the graveyard!"] = "Además de los puntos Pizazz por darnos los plátanos, se te acreditarán piedras rúnicas por tus esfuerzos y es posible que puedas ahorrar para un nuevo tipo de hechizo para usar en el cementerio.",
    ["It will be clearer when you arrive and one of my fellow guardians through the portal will be able to tell you more. You can also buy a book from the Rewards Guardian upstairs that will explain it all."] = "Será más claro cuando llegues y uno de mis compañeros guardianes a través del portal podrá contarte más. También puedes comprar un libro en Rewards Guardian arriba que lo explicará todo.",
    ["Use what you have learned."] = "Utilice lo que ha aprendido.",
    ["None, I don't really care."] = "Ninguno, realmente no me importa.",
    ["You won't gain with that attitude."] = "No ganarás con esa actitud.",
    ["Can you tell me about this place again?"] = "¿Puedes hablarme de este lugar otra vez?",
    ["Very well. You have entered the magic training arena. It was built at the start of the Fifth Age, when runestones were first discovered. It was made because of the many pointless accidents caused by inexperienced mages."] = "Muy bien. Has entrado en el campo del entrenamiento mágico. Fue construido a principios de la Quinta Edad, cuando se descubrieron por primera vez las piedras rúnicas. Fue creado debido a los muchos accidentes inútiles causados ​​por magos sin experiencia.",
    ["You may train up your skill in the magic arts by travelling through one of the portals at the back of this entrance hall. By training up in one of these areas you will be awarded special Pizazz Points unique to each room. With these points you"] = "Puedes mejorar tus habilidades en las artes mágicas viajando a través de uno de los portales en la parte trasera de este vestíbulo de entrada. Al entrenar en una de estas áreas, recibirás puntos Pizazz especiales, únicos para cada sala. Con estos puntos",
    ["may claim a variety of items from my fellow guardian up the stairs."] = "puedo reclamar una variedad de artículos de mi compañero guardián de las escaleras.",
    ["How do you record the Pizazz Points I have earned?"] = "¿Cómo se registran los puntos Pizazz que he ganado?",
    ["With the special Pizazz Progress Hat I gave you, of course!"] = "¡Con el sombrero de progreso Pizazz especial que te regalé, por supuesto!",
    ["OK."] = "Está bien.",
    ["Can you explain the different portals?"] = "¿Puedes explicar los diferentes portales?",
    ["About the progress hat..."] = "Sobre el sombrero de progreso...",
    ["About the Progress Hat..."] = "Acerca del sombrero de progreso...",
    ["You want another one don't you."] = "Quieres otro, ¿no?",
    ["Sorry, can I?"] = "Lo siento, ¿puedo?",
    ["Which you have stored somewhere I'm sure."] = "Lo cual, estoy seguro, lo tienes almacenado en algún lugar.",
    ["Yes. What's it for?"] = "Sí. ¿Para qué es?",
    ["Collect Pizazz Points from the various areas and the hat will remember your totals. Talk to the hat at any time to find out what points you have. Go upstairs and talk to the Rewards Guardian to claim items for the points."] = "Recoge puntos Pizazz de las distintas áreas y el sombrero recordará tus totales. Habla con el sombrero en cualquier momento para saber qué puntos tienes. Sube las escaleras y habla con Rewards Guardian para reclamar artículos por los puntos.",
    ["Hello. Can I help?"] = "Hola. ¿Puedo ayudar?",
    ["This is Burthorpe Castle, home to His Royal Highness Prince Anlaf, heir to the throne of Asgarnia."] = "Este es el Castillo Burthorpe, hogar de Su Alteza Real el Príncipe Anlaf, heredero del trono de Asgarnia.",
    ["No doubt you're impressed."] = "Sin duda estás impresionado.",
    ["**Select an option**"] = "**Seleccione una opción**",
    ["Where is the prince?"] = "¿Dónde está el príncipe?",
    ["I cannot disclose the prince's exact whereabouts for fear of compromising his personal safety."] = "No puedo revelar el paradero exacto del príncipe por temor a comprometer su seguridad personal.",
    ["But rest assured that he is working tirelessly to maintain the safety and wellbeing of Burthorpe's people."] = "Pero tenga la seguridad de que está trabajando incansablemente para mantener la seguridad y el bienestar de la gente de Burthorpe.",
    ["That's quite an outfit."] = "Es un buen conjunto.",
    ["Why, thank you. I designed it myself. I've always found purple such a cheerful colour!"] = "Bueno, gracias. Lo diseñé yo mismo. ¡Siempre me ha parecido que el morado es un color muy alegre!",
    ["Where did the council go?"] = "¿A dónde fue el consejo?",
    ["They have all returned to their respective kingdoms."] = "Todos han regresado a sus respectivos reinos.",
    ["With the war over, there's no need for a great council any more."] = "Una vez terminada la guerra, ya no hay necesidad de un gran consejo.",
    ["I thought the alliance might last a bit longer."] = "Pensé que la alianza podría durar un poco más.",
    ["That doesn't seem likely."] = "Eso no parece probable.",
    ["Sorry, I cannot stop or Iona will catch me, we are playing tag!"] = "Lo siento, no puedo parar o Iona me atrapará, ¡estamos jugando a la mancha!",
    ["Spare us a few coppers, mister?"] = "¿Ahorre unos cuantos cobres, señor?",
    ["No, go away!"] = "¡No, vete!",
    ["Ooh, I'm all dizzy..."] = "Ooh, estoy todo mareado...",
    ["Why's that?"] = "¿Por qué?",
    ["Well, watching that wheel go round and round and round..."] = "Bueno, ver esa rueda girar y girar y girar...",
    ["and round and round and round..."] = "y vueltas y vueltas y vueltas...",
    ["Looks like you need a bit of a rest."] = "Parece que necesitas descansar un poco.",
    ["and round and round and round again..."] = "y vueltas y vueltas y vueltas otra vez...",
    ["See you around!"] = "¡Nos vemos!",
    ["Very funny."] = "Muy divertido.",
    ["Hello! I'm Ernie the urn collector!"] = "¡Hola! ¡Soy Ernie, el coleccionista de urnas!",
    ["Hello, I'm Player."] = "Hola, soy Player.",
    ["Do you have any urns?"] = "¿Tienes alguna urna?",
    ["What are urns?"] = "¿Qué son las urnas?",
    ["You don't know what an urn is? Inconceivable!"] = "¿No sabes qué es una urna? ¡Inconcebible!",
    ["Urns are big, magical pots. You keep them in your bag, and they collect scraps and wastage while you perform activities that are related to that urn."] = "Las urnas son vasijas grandes y mágicas. Los guardas en tu bolso y recogen restos y desperdicios mientras realizas actividades relacionadas con esa urna.",
    ["For example, a fishing urn collects guppies while your attention is on larger catches."] = "Por ejemplo, una urna de pesca recoge guppies mientras tu atención se centra en las capturas más grandes.",
    ["Once it's full, you can teleport the urn to me!"] = "¡Una vez que esté llena, puedes teletransportarme la urna!",
    ["Sweet little guppies..."] = "Dulces y pequeños guppies...",
    ["Why would I want to give you any urns?"] = "¿Por qué querría regalarte urnas?",
    ["Why wouldn't you, more to the point?"] = "¿Por qué no lo harías tú, más concretamente?",
    ["No, why would I want to send you my full urns?"] = "No, ¿por qué querría enviarte mis urnas completas?",
    ["Oh...for a reward, of course!"] = "Oh... ¡por una recompensa, por supuesto!",
    ["You see, I've seen a lot in my lifetime; I have some tricks of the trade to share with you."] = "Verás, he visto muchas cosas en mi vida; Tengo algunos trucos del oficio para compartir contigo.",
    ["You send me an urn, I reward you with know-how regarding the skill type of your urn. Some might call it...gaining experience."] = "Si me envías una urna, te recompensaré con conocimientos sobre el tipo de habilidad de tu urna. Algunos podrían llamarlo... ganar experiencia.",
    ["That's a strange way to phrase it."] = "Esa es una forma extraña de expresarlo.",
    ["How do I make urns?"] = "¿Cómo hago urnas?",
    ["Oh, just use some soft clay on the pottery wheel and then fire the results in the pottery oven downstairs. Urns are big, so you'll need two batches of clay per urn."] = "Oh, solo usa un poco de arcilla blanda en el torno de alfarería y luego cuece los resultados en el horno de alfarería de abajo. Las urnas son grandes, por lo que necesitarás dos lotes de arcilla por urna.",
    ["Before you can start gathering scraps in your urn, you must attach a rune to it. This dissipates when you teleport the urn to me. Then I gather the precious, wonderful materials."] = "Antes de que puedas comenzar a recolectar restos en tu urna, debes adjuntarle una runa. Esto se disipa cuando teletransportas la urna hacia mí. Luego recojo los materiales preciosos y maravillosos.",
    ["If you get stuck, just show me where you've got to and I'll give you some advice. You can also hand full urns to me in person, if you'd prefer."] = "Si te quedas atascado, muéstrame dónde tienes que ir y te daré algunos consejos. También puedes entregarme las urnas llenas en persona, si lo prefieres.",
    ["I'd like to ask some other questions."] = "Me gustaría hacer algunas otras preguntas.",
    ["Why do you want urns?"] = "¿Por qué quieres urnas?",
    ["Why? WHY?"] = "¿Por qué? ¿POR QUÉ?",
    ["Yes. Why?"] = "Sí. ¿Por qué?",
    ["Oh, I...couldn't possibly say."] = "Oh, yo... no podría decirlo.",
    ["I'm sure you could tell me."] = "Estoy seguro de que podrías decírmelo.",
    ["No, no. It's a secret, tasty experiment. You must never know."] = "No, no. Es un experimento secreto y sabroso. Nunca debes saberlo.",
    ["I'd like more information about a specific urn."] = "Me gustaría obtener más información sobre una urna específica.",
    ["Certainly. I am a bit of an expert, after all."] = "Por supuesto. Después de todo, soy un poco experto.",
    ["Ask about..."] = "Pregunta sobre...",
    ["Prayer urns."] = "Urnas Prayer.",
    ["Prayer urns scoop up the ashes left behind when you slay demonic creatures."] = "Las urnas Prayer recogen las cenizas que quedan cuando matas criaturas demoníacas.",
    ["Weaker demons leave impious ashes behind. Scarier demonic beasties leave accursed ashes, and the most dangerous demons leave infernal ashes. Scrum-diddly-umptious."] = "Los demonios más débiles dejan atrás cenizas impías. Las bestias demoníacas más aterradoras dejan cenizas malditas, y los demonios más peligrosos dejan cenizas infernales. Scrum-tonto-tonto.",
    ["With lower Crafting levels, you are able to create impious urns, which collect impious ashes. Get your skill level up and you'll be able to make urns that collect a smorgasbord of ash types."] = "Con niveles más bajos de Crafting, puedes crear urnas impías, que recolectan cenizas impías. Prepara tu skill level y podrás hacer urnas que recolecten una mezcla heterogénea de tipos de cenizas.",
    ["Fishing urns."] = "Urnas Fishing.",
    ["Ah, fishing urns! These collect my favourite little fish: guppies! All you need to do is keep the urn in your bag when you are fishing, and it'll gather up the delicious little guppies each time you make a catch."] = "¡Ah, urnas de pesca! Estos recogen mis pececitos favoritos: ¡los guppies! Todo lo que necesitas hacer es guardar la urna en tu bolso cuando estés pescando, y recogerá los deliciosos guppies cada vez que captures.",
    ["Cracked fishing urns, made with lower Crafting levels, only collect guppies when fishing at level 10 or below. Higher level urns collect the brave guppies that swim around higher level fish."] = "Las urnas de pesca agrietadas, hechas con niveles más bajos de Crafting, solo recolectan guppies cuando se pesca en el nivel 10 o menos. Las urnas de niveles superiores recogen a los valientes guppies que nadan alrededor de peces de niveles superiores.",
    ["When you are a master crafter, you will be able to make decorated fishing urns. These collect guppies from any kind of fish that you can think of!"] = "Cuando seas master crafter, podrás hacer urnas de pesca decoradas. ¡Estos recolectan guppies de cualquier tipo de pez que puedas imaginar!",
    ["Cooking urns."] = "Urnas Cooking.",
    ["Cooking urns collect lip-smacking food scraps while you are cooking on a fire or range."] = "Las urnas Cooking recogen restos de comida que te relamen los labios mientras cocinas en el fuego o en la estufa.",
    ["Cracked cooking urns, made with lower Crafting levels, collect food scraps from meals that require a Cooking level of 10 or below."] = "Las urnas de cocina agrietadas, fabricadas con niveles más bajos de Crafting, recolectan restos de comida de comidas que requieren un nivel de Cooking de 10 o menos.",
    ["Decorated cooking urns, made at the very highest Crafting levels, collect scraps from even the most complex of meals. These scraps are integral to my experiment!"] = "Las urnas de cocina decoradas, fabricadas con los niveles más altos de Crafting, recogen restos incluso de las comidas más complejas. ¡Estos restos son parte integral de mi experimento!",
    ["Experiment?"] = "¿Experimento?",
    ["Who told you about my experiment? Whatever you've heard is a lie!"] = "¿Quién te habló de mi experimento? ¡Todo lo que has oído es mentira!",
    ["Mining urns."] = "Urnas Mining.",
    ["Magical mining urns! These collect slivers of ore from the rocks you mine."] = "¡Urnas mineras mágicas! Estos recolectan astillas de mineral de las rocas que extraes.",
    ["Cracked urns, made at the lower end of the Crafting scale, will magnetically attract slivers of ore that require a Mining level of 1."] = "Las urnas agrietadas, fabricadas en el extremo inferior de la escala Crafting, atraerán magnéticamente astillas de mineral que requieren un nivel Mining de 1.",
    ["Higher quality urns collect slivers of ore from higher level ores. When you're skilled enough to make decorated mining urns, you'll gather slivers from any ore that you could swing a pickaxe at!"] = "Las urnas de mayor calidad recogen astillas de minerales de niveles superiores. Cuando tengas la habilidad suficiente para hacer urnas mineras decoradas, ¡recolectarás astillas de cualquier mineral al que puedas golpear con un pico!",
    ["Other urns."] = "Otras urnas.",
    ["Smelting urns."] = "Urnas de fundición.",
    ["Smelting urns collect metal scraps while you smelt bars."] = "Las urnas de fundición recogen restos de metal mientras fundes barras.",
    ["Lower level urns only collect metal scraps from bars that require a Smithing level of 1. The highest level urns collect metal scraps from any bar, high level or low level, 'cept for chocolate bars. Trust me, I've tried."] = "Las urnas de nivel inferior solo recogen restos de metal de barras que requieren un nivel Smithing de 1. Las urnas de nivel más alto recogen restos de metal de cualquier barra, de nivel alto o bajo, excepto las barras de chocolate. Créeme, lo he intentado.",
    ["A note to you: I prefer better quality metal scraps. They contribute a more distinctive taste to my delicious experiment."] = "Una nota para usted: prefiero restos de metal de mejor calidad. Aportan un sabor más distintivo a mi delicioso experimento.",
    ["Woodcutting urns."] = "Urnas Woodcutting.",
    ["Woodcutting urns! Wonderful things! These collect tasty woodchips when you chop wood."] = "¡Urnas Woodcutting! ¡Cosas maravillosas! Estos recogen sabrosas astillas de madera cuando cortas leña.",
    ["While you are a crafter at lower levels, you will only be able to make cracked urns. These collect woodchips while you chop wood up to a Woodcutting level of 10."] = "Mientras seas un artesano en niveles inferiores, solo podrás hacer urnas rotas. Estos recolectan astillas de madera mientras cortas madera hasta un nivel Woodcutting de 10.",
    ["When you are a master of the crafting art, you'll be able to make decorated woodcutting urns that collect from even the hardiest of logs."] = "Cuando seas un maestro en el arte de la artesanía, podrás crear urnas decoradas para tallar en madera que recolectarán incluso de los más resistentes de logs.",
    ["Woodchips from magic trees make my lips tingle. I thought you'd like to know."] = "Las astillas de madera de los árboles mágicos hacen que mis labios hormigueen. Pensé que te gustaría saberlo.",
    ["Divination urns."] = "Urnas Divination.",
    ["Wonderful divination urns! Wonderful things! These collect memory fragments."] = "¡Maravillosas urnas de adivinación! ¡Cosas maravillosas! Estos recogen fragmentos de memoria.",
    ["While you are crafting at lower levels, you will only be able to make cracked urns. These collect memory fragments up to a Divination level of 10."] = "Mientras estés elaborando en niveles inferiores, solo podrás hacer urnas rotas. Estos recopilan fragmentos de memoria hasta un nivel Divination de 10.",
    ["When you are a master of the crafting art, you'll be able to make decorated divination urns that collect from even the greatest of memories."] = "Cuando seas un maestro en el arte de la artesanía, podrás crear urnas de adivinación decoradas que coleccionarán incluso los mejores recuerdos.",
    ["You might also want to know that these will collect extra special fragments when you deposit memories into a crater!"] = "¡Quizás también quieras saber que estos recolectarán fragmentos extra especiales cuando deposites recuerdos en un cráter!",
    ["Runecrafting urns."] = "Urnas Runecrafting.",
    ["Runecrafting urns collect rune remnants when utilising rune essence."] = "Las urnas Runecrafting recolectan restos de runas cuando utilizan esencia de runas.",
    ["Lower level urns will collect remnants from anything up to level 9. The highest level urns collect remnants from almost anything!"] = "Las urnas de nivel inferior recogerán restos de cualquier cosa hasta el nivel 9. ¡Las urnas de nivel más alto recogen restos de casi cualquier cosa!",
    ["Hunter urns."] = "Urnas Hunter.",
    ["Ah hunter urns! These ones collect integument iotas from little critters."] = "¡Ah, urnas cazadoras! Estos recolectan ápices de tegumento de pequeños bichos.",
    ["Cracked urns, made at the lower end of the Crafting scale, will be able to collect iotas from creatures that require a Hunter level of 11."] = "Las urnas agrietadas, fabricadas en el extremo inferior de la escala Crafting, podrán recolectar iotas de criaturas que requieren un nivel Hunter de 11.",
    ["If you manage to catch some of the big guys, you'll find my urns filling up in no time!"] = "Si logras atrapar a algunos de los grandes, ¡encontrarás mis urnas llenándose en poco tiempo!",
    ["Farming urns."] = "Urnas Farming.",
    ["Farming urns collect the left over cuttings when farming."] = "Las urnas Farming recogen los esquejes sobrantes durante la agricultura.",
    ["The lowest level urns will work for anything up to level 12."] = "Las urnas de nivel más bajo funcionarán para cualquier cosa hasta el nivel 12.",
    ["I have a few questions about urns in general."] = "Tengo algunas preguntas sobre las urnas en general.",
    ["That's all, thank you."] = "Eso es todo, gracias.",
    ["Good bye!"] = "¡Adiós!",
    ["That clay is far too hard. You'll need to mix it with water before you have clay suitable for making urns."] = "Esa arcilla es demasiado dura. Tendrás que mezclarla con agua antes de tener arcilla adecuada para hacer urnas.",
    ["Ah, lovely clay! You'll need two batches of this, then you can use a potter's wheel to make a beautiful urn!"] = "¡Ah, hermosa arcilla! Necesitarás dos lotes de esto y luego podrás usar un torno de alfarero para hacer una hermosa urna.",
    ["Ah, this urn hasn't been fired! You'll need to take that to a pottery oven. Feel free to use the one downstairs."] = "¡Ah, esta urna no ha sido disparada! Tendrás que llevarlo a un horno de cerámica. Siéntete libre de usar el de abajo.",
    ["This urn has been fired. You can trade it now, or if you want to use it, you'll need to add a rune to it."] = "Esta urna ha sido disparada. Puedes intercambiarlo ahora o, si quieres usarlo, deberás agregarle una runa.",
    ["*Prayer urn*"] = "*urna Prayer*",
    ["This is a prayer urn, so you'll need an air rune to activate it."] = "Esta es una urna de oración, por lo que necesitarás una runa de aire para activarla.",
    ["*Fishing urn*"] = "*urna Fishing*",
    ["This is a fishing urn, so you'll need a water rune to activate it."] = "Esta es una urna de pesca, por lo que necesitarás una runa de agua para activarla.",
    ["*Cooking urn*"] = "*urna Cooking*",
    ["This is a cooking urn, so you'll need a fire rune to activate it."] = "Esta es una urna de cocina, por lo que necesitarás una runa de fuego para activarla.",
    ["*Divination urn*"] = "*urna Divination*",
    ["This is a divination urn, so you'll need a mind rune to activate it."] = "Esta es una urna de adivinación, por lo que necesitarás una runa mental para activarla.",
    ["*Farming urn*"] = "*urna Farming*",
    ["This is a farming urn, so you'll need a nature rune to activate it."] = "Esta es una urna agrícola, por lo que necesitarás una runa de la naturaleza para activarla.",
    ["*Mining urn*"] = "*urna Mining*",
    ["This is a Mining urn, so you'll need an earth rune to activate it."] = "Esta es una urna Mining, por lo que necesitarás una runa de tierra para activarla.",
    ["*Smelting urn*"] = "*Urna de fundición*",
    ["This is a smelting urn, so you'll need a fire rune to activate it."] = "Esta es una urna de fundición, por lo que necesitarás una runa de fuego para activarla.",
    ["*Hunter urn*"] = "*urna Hunter*",
    ["This is a hunter urn, so you'll need a mud rune to activate it."] = "Esta es una urna de cazador, por lo que necesitarás una runa de barro para activarla.",
    ["*Woodcutting urn*"] = "*urna Woodcutting*",
    ["This is a woodcutting urn, so you'll need an earth rune to activate it."] = "Esta es una urna para cortar madera, por lo que necesitarás una runa de tierra para activarla.",
    ["*Runecrafting urn*"] = "*urna Runecrafting*",
    ["This is a runecrafting urn, so you'll need some pure essence to activate it."] = "Esta es una urna de creación de runas, por lo que necesitarás un poco de esencia pura para activarla.",
    ["I see you've activated this urn with a rune."] = "Veo que has activado esta urna con una runa.",
    ["This is a prayer urn, so you should slay some demons to start filling the urn with ashes."] = "Esta es una urna de oración, por lo que debes matar algunos demonios para comenzar a llenar la urna con cenizas.",
    ["This is a fishing urn, so you should take it with you when you go fishing to start collecting guppies."] = "Esta es una urna de pesca, por lo que debes llevarla contigo cuando vayas a pescar para comenzar a recolectar guppies.",
    ["This is a cooking urn, so you should keep it with you when you are cooking to start collecting food scraps."] = "Esta es una urna de cocina, por lo que debes llevarla contigo cuando estés cocinando para comenzar a recolectar restos de comida.",
    ["This is a divination urn, so you should take it with you when you harvest memories to start collecting fragments."] = "Esta es una urna de adivinación, por lo que debes llevarla contigo cuando recolectes recuerdos para comenzar a recolectar fragmentos.",
    ["This is a farming urn, so you should take it with you when you harvest your plants to start collecting cuttings."] = "Esta es una urna agrícola, por lo que debes llevarla contigo cuando coseches tus plantas para comenzar a recolectar esquejes.",
    ["This is a Mining urn, so you should take it with you when you go mining to start collecting ore slivers."] = "Esta es una urna Mining, por lo que debes llevarla contigo cuando vayas a minar para comenzar a recolectar fragmentos de mineral.",
    ["This is a smelting urn, so you should keep it with you when you are smithing to start collecting metal scraps."] = "Esta es una urna de fundición, por lo que debes llevarla contigo cuando estés forjando para comenzar a recolectar restos de metal.",
    ["This is a hunter urn, so you should take it with you when you go hunting to start collecting iotas."] = "Esta es una urna de cazador, por lo que debes llevarla contigo cuando vayas a cazar para empezar a recolectar iotas.",
    ["This is a woodcutting urn, so you should take it with you when you go woodcutting to start collecting woodchips."] = "Esta es una urna para cortar madera, por lo que debes llevarla contigo cuando vayas a cortar madera para comenzar a recolectar astillas.",
    ["This is a runecrafting urn, so you should take it with you when you bind rune essence to start collecting remnants."] = "Esta es una urna de creación de runas, por lo que debes llevarla contigo cuando vincules la esencia de la runa para comenzar a recolectar restos.",
    ["This urn isn't ready yet. Please come back when it's full."] = "Esta urna aún no está lista. Por favor regresa cuando esté lleno.",
    ["A lovely full urn! Let me take that off your hands."] = "¡Una hermosa urna llena! Déjame quitarte eso de las manos.",
    ["You know, you can teleport your full urns straight to me if you're too busy to come back here."] = "Sabes, puedes teletransportar tus urnas llenas directamente hacia mí si estás demasiado ocupado para volver aquí.",
    ["You hand Ernie the urn. You gain [number] [Skill] XP."] = "Le entregas la urna a Ernie. Obtienes [número] [Skill] XP.",
    ["I see you looking at Ernie's urns! You steal 'em, Ernie steals your kidneys. Ernie promise!"] = "¡Te veo mirando las urnas de Ernie! Tú las robas, Ernie te roba los riñones. ¡Ernie lo promete!",
    ["You know nothing! Hehe, Ernie puts the 'urn' in 'Burn'."] = "¡No sabes nada! Jeje, Ernie pone la 'urna' en 'Quemar'.",
    ["Urns are magical pots. They fill up when you're skilling."] = "Las urnas son vasijas mágicas. Se llenan cuando estás entrenando.",
    ["A cooking urn collects juicy, tasty scraps when cooking."] = "Una urna de cocina recoge restos jugosos y sabrosos al cocinar.",
    ["When it's full, add a rune and teleport it to Ernie. Tasty urn for Ernie! Yum-diddly-yum!"] = "Cuando esté lleno, agrega una runa y teletransportala a Ernie. ¡Sabrosa urna para Ernie! ¡Qué rico!",
    ["**Erskine:** Can I interest you in a job? I'll pay you for your work."] = "**Erskine:** ¿Puedo interesarte en un trabajo? Te pagaré por tu trabajo.",
    ["Tell me about yourself."] = "Háblame de ti.",
    ["My name's Erskine. I'm a powerful warrior from Edgeville destined to eradicate the horrors of the Wilderness."] = "Mi nombre es Erskine. Soy un poderoso guerrero de Edgeville destinado a erradicar los horrores de Wilderness.",
    ["Although, I've found that going in there isn't really my thing at the moment, so I'm hiring people to do all that stuff for me under my banner."] = "Aunque descubrí que entrar allí no es lo mío en este momento, así que estoy contratando gente para que haga todo eso por mí bajo mi estandarte.",
    ["If you're interested in doing some combat yourself, I'd be happy to give you a job. I can pay you."] = "Si estás interesado en participar en combate tú mismo, estaré encantado de darte un trabajo. Puedo pagarte.",
    ["What sort of job are you offering?"] = "¿Qué tipo de trabajo ofreces?",
    ["Are you scared to go do it yourself?"] = "¿Tienes miedo de hacerlo tú mismo?",
    ["Of course not, there are... dust storms sometimes and I have an allergy. . Ahem... cough, cough."] = "Por supuesto que no, hay... a veces tormentas de polvo y tengo alergia. . Ejem... tos, tos.",
    ["Okay, I'd like a job."] = "Vale, me gustaría un trabajo.",
    ["So you're incapable of doing your own work?"] = "¿Entonces eres incapaz de hacer tu propio trabajo?",
    ["Are you incapable of doing your own work?"] = "¿Eres incapaz de hacer tu propio trabajo?",
    ["What are you trying to say? That I'm too scared to go into the Wilderness myself in case I die and lose my stuff?"] = "¿Qué intentas decir? ¿Que tengo demasiado miedo para entrar al Wilderness por si muero y pierdo mis cosas?",
    ["I just want to eradicate the monsters, so I need stay here and hire enough people to speed up the process."] = "Solo quiero erradicar a los monstruos, así que necesito quedarme aquí y contratar suficiente gente para acelerar el proceso.",
    ["So, would you like a job now?"] = "Entonces, ¿te gustaría conseguir un trabajo ahora?",
    ["I'm hiring people to kill the monsters out in the north."] = "Estoy contratando gente para matar a los monstruos del norte.",
    ["I'd do it myself, but I've found that the ash and dust isn't good for me. Ahem, cough cough."] = "Lo haría yo mismo, pero descubrí que la ceniza y el polvo no son buenos para mí. Ejem, tos, tos.",
    ["Instead, I'm paying people like you to kill the monsters for me."] = "En lugar de eso, le pago a gente como tú para que mate a los monstruos por mí.",
    ["Effectively, I'm removing dangerous stuff from the Wilderness by telling everyone to get rid of it over and over!"] = "¡Efectivamente, estoy eliminando cosas peligrosas del Wilderness diciéndoles a todos que se deshagan de ellas una y otra vez!",
    ["I can offer cash payments. Alternatively, I bought myself some books about combat but didn't feel like actually venturing past the intro after reading the warnings about the dangers, so you could have one as payment."] = "Puedo ofrecer pagos en efectivo. Alternativamente, me compré algunos libros sobre combate, pero no tenía ganas de aventurarme más allá de la introducción después de leer las advertencias sobre los peligros, así que podrías tener uno como pago.",
    ["Incidentally, if you already have an assignment from elsewhere to kill creatures that you can find in the wilds, do come and see me. Complete your task out there, and I'll give you a special contract that'll work in tandem with it, and give you an additional reward on top."] = "Por cierto, si ya tienes una tarea de otro lugar para matar criaturas que puedes encontrar en la naturaleza, ven a verme. Complete su tarea y le daré un contrato especial que funcionará en conjunto con ella y le daré una recompensa adicional además.",
    ["So would you like a job now?"] = "Entonces, ¿te gustaría conseguir un trabajo ahora?",
    ["Why don't you do it yourself?"] = "¿Por qué no lo haces tú mismo?",
    ["Excellent. Take a look at my contracts and see which one you'd like to do."] = "Excelente. Echa un vistazo a mi contracts y mira cuál te gustaría hacer.",
    ["[The scroll can only track you progress if you carry it while slaying. Bring it back when you've finished.]"] = "[El pergamino sólo puede seguir tu progreso si lo llevas mientras matas. Tráelo de vuelta cuando hayas terminado.]",
    ["Alright, but come back if you change your mind. I can pay you for your work."] = "Está bien, pero vuelve si cambias de opinión. Puedo pagarte por tu trabajo.",
    ["I see you've got a Slayer assignment. I'll pay you extra if you take a contract to do your assignment in the Wilderness."] = "Veo que tienes una tarea de Slayer. Te pagaré extra si aceptas un contrato para realizar tu tarea en Wilderness.",
    ["What are you offering?"] = "¿Qué estás ofreciendo?",
    ["You'll also get a 20% bonus on Slayer XP earned from killing the monsters, an extra 20% Slayer XP when the Demonic skull is worn or in your inventory inside the Wilderness"] = "También obtendrás una bonificación del 20 % en la XP Slayer obtenida al matar monstruos, un 20 % adicional de XP Slayer cuando uses la calavera demoníaca o en tu inventario dentro de Wilderness.",
    ["Plus a choice of [number] combat XP or [number] coins."] = "Además, puedes elegir entre XP de combate [número] o [número] coins.",
    ["Okay, I'll take it."] = "Está bien, lo aceptaré.",
    ["Can I have a different contract instead?"] = "¿Puedo tener un contrato diferente en su lugar?",
    ["Could I ask about something else?"] = "¿Puedo preguntar algo más?",
    ["**Erskine:** Show me your special contract when you've finished it."] = "**Erskine:** Muéstrame tu contrato especial cuando lo hayas terminado.",
    ["**Erskine:** Show me your contract when you've finished it."] = "**Erskine:** Muéstrame tu contrato cuando lo hayas terminado.",
    ["I see you've completed that contract. Good work. Would you like combat XP or cash?"] = "Veo que has completado ese contrato. Trabajo bueno. ¿Quieres XP de combate o dinero en efectivo?",
    ["Combat XP: [number] XP"] = "XP de combate: [número] XP",
    ["[You receive a book about combat.]"] = "[Recibes un libro sobre combate.]",
    ["Cash: [number] coins"] = "Efectivo: [número] coins",
    ["[You receive [number] coins.]"] = "[Recibirás [número] coins.]",
    ["You have a contract in your bank. Shall I fetch it for you?"] = "Tienes un contrato en tu banco. ¿Te lo busco?",
    ["Yes. Please fetch it."] = "Sí. Por favor tráelo.",
    ["[Your contract has been retrieved from your bank.]"] = "[Su contrato ha sido recuperado de su banco.]",
    ["No thanks. Leave it alone."] = "No gracias. Déjalo en paz.",
    ["Very well, but you'll need to have it in your inventory if you want to make any progress on it."] = "Muy bien, pero necesitarás tenerlo en tu inventario si quieres progresar en él.",
    ["*When talking to Eshe at the Golden Palace throne room in Menaphos*"] = "*Al hablar con Eshe en el salón del trono del Palacio Dorado en Menaphos*",
    ["The Pharaoh has angered the gods in his negligence and greed! I have not received visions or messages for aeons and we must make peace with the almighty or we will fall into ruin!"] = "¡El faraón ha enojado a los dioses por su negligencia y avaricia! ¡No he recibido visiones ni mensajes durante eones y debemos hacer las paces con el todopoderoso o caeremos en la ruina!",
    ["[number]/14 owls tracked"] = "[número]/14 búhos rastreados",
    ["Congratulations! You have completed: 'Birds of Prey' - Track all of the owls for Deryn."] = "¡Felicitaciones! Has completado: 'Aves de presa': rastrea todos los búhos para Deryn.",
    ["You have unlocked the title: 'Player,"] = "Has desbloqueado el título: 'Player,",
    ["You can activate this via the 'Titles' tab in the Customisations interface."] = "Puede activar esto a través de la pestaña 'Títulos' en la interfaz de Personalizaciones.",
    ["Home sweet home."] = "Hogar, dulce hogar.",
    ["Location is one of: 'the north-west', 'the south-west', 'the south-east', 'the north-east' and '' <!-- i.e. it will be The essence has spawned in centre!. -->"] = "La ubicación es una de: 'el noroeste', 'el suroeste', 'el sureste', 'el noreste' y '' <!-- i.e. it will be The essence has spawned in centre!. -->",
    ["The essence of death has spawned in [location]"] = "El essence of death ha generado en [location]",
    ["No essence of death arrived because there need to be at least 20 players in the arena."] = "No llegó ningún essence of death porque debe haber al menos 20 jugadores en la arena.",
    ["As you approach the essence of death, it analyses if you are a"] = "Al acercarte al essence of death, este analiza si eres un",
    ["|colour=#64c864|warning=yes}}"] = "|color=#64c864|advertencia=yes}}",
    ["Your inventory was full, so all three weapons were added to the ground."] = "Tu inventario estaba lleno, por lo que las tres armas se agregaron al suelo.",
    ["You are the supreme hunter!"] = "¡Eres el cazador supremo!",
    ["Do you have the key to the excavation site yet?"] = "¿Ya tienes la llave del sitio de excavación?",
    ["No the guard is being a bit slow, but we should have it soon."] = "No, la guardia está siendo un poco lenta, pero deberíamos tenerla pronto.",
    ["Alright, I'll report in again tomorrow."] = "Muy bien, volveré a informar mañana.",
    ["Any news yet on our missing dig team?"] = "¿Alguna novedad sobre nuestro equipo de excavación desaparecido?",
    ["No, I have looked everywhere, but I can see no sign of them."] = "No, he buscado por todas partes, pero no veo ninguna señal de ellos.",
    ["This is not good news, did you find anything else down there?"] = "Estas no son buenas noticias, ¿encontraste algo más ahí abajo?",
    ["Nothing other than the beasts you spoke of."] = "Nada más que las bestias de las que hablaste.",
    ["I must ask you to return to the search and remember if you see anything elven-made down there you must let me know. After all that is what we are here for."] = "Debo pedirte que regreses a la búsqueda y recuerda que si ves algo hecho por los elfos ahí abajo, debes avisarme. Después de todo, para eso estamos aquí.",
    ["I'll come to you as soon as I dig anything up."] = "Iré a verte tan pronto como desenterre algo.",
    ["Oh, hello. May I be of service?"] = "Oh, hola. ¿Puedo ser de utilidad?",
    ["Aah!"] = "¡Ah!",
    ["What's the matter?"] = "¿Qué pasa?",
    ["Oh, it's you. I didn't recognise you there."] = "Oh, eres tú. No te reconocí allí.",
    ["I...I promised you'd never see me again. I didn't think the elder would actually permit other races to enter Prifddinas!"] = "Yo... te prometí que no volverías a verme nunca más. ¡No pensé que el anciano realmente permitiría que otras razas ingresaran a Prifddinas!",
    ["I've given up the military life, and settled with my wife."] = "Dejé la vida militar y me instalé con mi esposa.",
    ["Essyllt, I don't understand. What's going on?"] = "Essyllt, no entiendo. ¿Qué está sucediendo?",
    ["When I was...working...this human had the choice to kill me."] = "Cuando estaba... trabajando... este humano tuvo la opción de matarme.",
    ["W-what? Kill him?"] = "¿Q-qué? ¿Matarlo?",
    ["What manner of brute are you, that you would threaten Lord Iorwerth's emissary of peace?"] = "¿Qué clase de bruto eres para amenazar al emisario de paz de Lord Iorwerth?",
    ["Emissary of peace?"] = "¿Emisario de la paz?",
    ["Emissary of peace? What?"] = "¿Emisario de la paz? ¿Qué?",
    ["Yes, the work I was doing when you met me."] = "Sí, el trabajo que estaba haciendo cuando me conociste.",
    ["Oh, of course. Well it's a long story. I'm sure Essyllt can tell you some other time."] = "Ah, por supuesto. Bueno, es una larga historia. Seguro que Essyllt te lo puede contar en otro momento.",
    ["Essyllt appears to mouth 'thank you'."] = "Essyllt parece decir \"gracias\".",
    ["Hah! Wow, that's a good one. I'm glad I let you live just for that!"] = "¡Ja! Vaya, esa es buena. ¡Me alegro de haberte dejado vivir sólo por eso!",
    ["What's so funny?"] = "¿Qué es tan gracioso?",
    ["I remember his plan. Had I not stopped him, this 'emissary of peace' would have wiped out the entire population of West Ardougne by herding them into a cavern and collapsing the roof!"] = "Recuerdo su plan. ¡Si no lo hubiera detenido, este 'emisario de la paz' ​​habría acabado con toda la población de West Ardougne llevándolos a una caverna y derribando el techo!",
    ["What? Essyllt...that's a lie. Tell me it's a lie."] = "¿Qué? Essyllt...eso es mentira. Dime que es mentira.",
    ["I...Why did you..."] = "Yo... ¿Por qué tú...?",
    ["It's...true, isn't it?"] = "Es... cierto, ¿no?",
    ["Please excuse us, Player. My husband and I need to speak in private."] = "Por favor, discúlpenos, Player. Mi esposo y yo necesitamos hablar en privado.",
    ["I'd like to ask about something else."] = "Me gustaría preguntar sobre algo más.",
    ["I thought you had children."] = "Pensé que tenías hijos.",
    ["You said you had children. Where are they?"] = "Dijiste que tenías hijos. ¿Dónde están?",
    ["They're not here right now. There's um... Dwyfor... Grenfron... and Aeronwen."] = "No están aquí en este momento. Están, eh... Dwyfor... Grenfron... y Aeronwen.",
    ["I've been all around Prifddinas, and I'm yet to encounter elves with those names."] = "He estado en Prifddinas y todavía tengo que encontrar elfos con esos nombres.",
    ["Dwyfor was also in Lord Iorwerth's service, I last saw him entering the Underground Pass."] = "Dwyfor también estaba al servicio de Lord Iorwerth, la última vez que lo vi entrando a Underground Pass.",
    ["Grenfron is assisting in cleaning the Undercity."] = "Grenfron está ayudando a limpiar Entrañas.",
    ["Aeronwy never really stays in one place, she's probably wandering around somewhere."] = "Aeronwy nunca se queda en un solo lugar, probablemente esté deambulando por algún lugar.",
    ["What was that last name again?"] = "¿Cuál era ese apellido otra vez?",
    ["Aeronwy? Yes, Aeronwy."] = "¿Aeronwy? Sí, Aeronwy.",
    ["Didn't you say Aeronwen before?"] = "¿No dijiste Aeronwen antes?",
    ["Just stop already. Your lies are painful to listen to."] = "Detente ya. Es doloroso escuchar tus mentiras.",
    ["Fine. I lied about having children. Maybe one day. I just wanted you to let me live."] = "Bien. Mentí sobre tener hijos. Quizás algún día. Sólo quería que me dejaras vivir.",
    ["I'll keep an eye out."] = "Estaré atento.",
    ["Essyllt appears to let out a sigh of relief, while Mwynen glares at him menacingly."] = "Essyllt parece dejar escapar un suspiro de alivio, mientras Mwynen lo mira amenazadoramente.",
    ["What are you doing now?"] = "¿Qué estás haciendo ahora?",
    ["I've retired. I'm just spending time with my wife, Mwynen."] = "Me jubilé. Sólo estoy pasando tiempo con mi esposa, Mwynen.",
    ["It's certainly been interesting speaking with you, Player. It seems Essyllt and I have a lot to talk about."] = "Sin duda ha sido interesante hablar contigo, Player. Parece Essyllt y tengo mucho de qué hablar.",
    ["I...Bye."] = "Yo... Adiós.",
    ["If it's a house you're wanting, you'll want ot head over to Rimmington and chat to the estate agent there."] = "Si lo que buscas es una casa, querrás dirigirte a Rimmington y charlar con estate agent allí.",
    ["I want a new contract."] = "Quiero un nuevo contrato.",
    ["You're going to require some space in your backpack for a contract."] = "Necesitará algo de espacio en su backpack para un contrato.",
    ["You're handed a Construction contract."] = "Te entregan un Construction contract.",
    ["Here you are, this just came in for [character] over in [location]."] = "Aquí tienes, esto acaba de llegar para [character] en [location].",
    ["Thanks! I'll see what I can do."] = "¡Gracias! Veré qué puedo hacer.",
    ["What's my current contract?"] = "¿Cuál es mi contrato actual?",
    ["It looks like you're in the middle of helping out [character] over in [location]."] = "Parece que estás ayudando a [character] en [location].",
    ["Tell me about contracts"] = "Háblame de contracts",
    ["There are many homeowners around Gielinor that are struggling to keep up with repairs on a regular basis."] = "Hay muchos propietarios alrededor de Gielinor que tienen dificultades para mantenerse al día con las reparaciones de forma regular.",
    ["So right now there's a market opportunity to put your construction skills to use and help them out."] = "Ahora mismo existe una oportunidad de mercado para poner en práctica sus habilidades de construcción y ayudarlos.",
    ["We estate agents can provide you with a contract. This contract will tell you who needs help and what they need repairing."] = "Nosotros, los agentes inmobiliarios, podemos proporcionarle un contrato. Este contrato le indicará quién necesita ayuda y qué necesita reparación.",
    ["All you need to do is head on over and repair all the broken furniture."] = "Todo lo que necesitas hacer es ir y reparar todos los furniture rotos.",
    ["You can either use basic materials for a cheaper, but slower repair job. Or you can use more expensive materials for a faster return and more experience."] = "Puedes utilizar materiales básicos para un trabajo de reparación más económico pero más lento. O puede utilizar materiales más caros para una devolución más rápida y más experiencia.",
    ["Whatever you choose, you'll gain a chunk of experience once you've repaired all the pieces of furniture that need repairing."] = "Elijas lo que elijas, obtendrás una gran cantidad de experiencia una vez que hayas reparado todos los pieces of furniture que necesitan reparación.",
    ["We'll also reward you with contract credits, which you can redeem from any estate agent for assorted rewards."] = "También te recompensaremos con créditos de contrato, que puedes canjear desde cualquier estate agent por recompensas variadas.",
    ["I've lost my plank box."] = "He perdido mi caja de tablones.",
    ["Not to worry, I have another lying around."] = "No te preocupes, tengo otro por ahí.",
    ["Come back when you have some free space in your backpack."] = "Vuelve cuando tengas algo de espacio libre en tu backpack.",
    ["Try not to lose this one though."] = "Pero intenta no perder este.",
    ["Do you have anything I can buy?"] = "¿Tienes algo que pueda comprar?",
    ["I'm sure it's a house you're wanting, but seeing as we've recently recruited Alfred Stonemason, I'll let him give you the rundown on housing. Pop over to him for a chat."] = "Estoy seguro de que es la casa que deseas, pero dado que recientemente reclutamos a Alfred Stonemason, dejaré que te dé un resumen de la vivienda. Acércate a él para charlar.",
    ["Welcome to the Gielinorian Housing Agency! What can I do for you?"] = "¡Bienvenido a la Agencia de Vivienda Gielinorian! ¿Qué puedo hacer por ti?",
    ["Tell me about houses."] = "Háblame de casas.",
    ["It all came out of the wizards' experiments. They found a way to fold space, so that they could pack many acres of land into an area only a foot across."] = "Todo surgió de los experimentos de los magos. Encontraron una manera de plegar el espacio, de modo que pudieran agrupar muchos acres de tierra en un área de sólo un pie de ancho.",
    ["They created several folded-space regions across the world. Each one contains hundreds of small plots where people can build houses."] = "Crearon varias regiones de espacio plegado en todo el mundo. Cada uno contiene cientos de pequeñas parcelas donde la gente puede construir casas.",
    ["Ah, so that's how everyone can have a house without them cluttering up the world!"] = "¡Ah, así es como todos pueden tener una casa sin que abarroten el mundo!",
    ["Quite. The wizards didn't want to get bogged down in the business side of things so they hired me to sell the houses."] = "Bastante. Los magos no querían empantanarse en el aspecto comercial así que me contrataron para vender las casas.",
    ["There are various other people across Gielinor who can help you furnish your house. Or if you're a dab hand at Construction, construct furniture yourself at a furniture workbench."] = "Hay otras personas en Gielinor que pueden ayudarte a amueblar tu casa. O si eres un experto en Construction, construye furniture tú mismo en un banco de trabajo furniture.",
    ["You should start by getting some planks to construct furniture with. Try buying them at the Grand Exchange, or making them yourself at a sawmill."] = "Deberías empezar por conseguir algo de planks para construir furniture. Intente comprarlos en Grand Exchange o hacerlos usted mismo en un aserradero.",
    ["How can I train construction?"] = "¿Cómo puedo entrenar la construcción?",
    ["You can train it right here! You'll find a furniture workbench, as well as members of the Gielinorian Housing Agency who can turn your logs into planks, or turn your noted materials into raw materials."] = "¡Puedes entrenarlo aquí mismo! Encontrará un banco de trabajo furniture, así como miembros de la Agencia de Vivienda Gielinorian que pueden convertir su logs en planks, o convertir sus materiales destacados en materias primas.",
    ["Once you've constructed some furniture, you can place it in a furniture storage chest for use within your house."] = "Una vez que hayas construido un furniture, puedes colocarlo en un cofre de almacenamiento furniture para usarlo dentro de tu casa.",
    ["You can get started with construction training by visiting our headquarters over in Rimmington!"] = "¡Puede comenzar con la capacitación en construcción visitando nuestra sede en Rimmington!",
    ["There you'll find a plethora of amenities to get you well under way with constructing furniture to make your house a home."] = "Allí encontrará una gran cantidad de comodidades que lo ayudarán a comenzar a construir furniture para hacer de su casa un hogar.",
    ["Can you switch my preferred exit portal location please?"] = "¿Puede cambiar la ubicación de mi portal de salida preferida, por favor?",
    ["Where would you like your house portal moved to?"] = "¿A dónde le gustaría trasladar el portal de su casa?",
    ["8. Otot (Mazcab) (25,000 coins)"] = "8. Otot (Mazcab) (25.000 coins)",
    ["Your house portal is already there!"] = "¡El portal de tu casa ya está ahí!",
    ["You need [number] coins to move your house portal there."] = "Necesitas [número] coins para mover el portal de tu casa allí.",
    ["[Your house portal has been moved to [Location].]"] = "[El portal de su casa se ha trasladado a [Location].]",
    ["Can you tell me about construction contracts?"] = "¿Puedes hablarme de construction contracts?",
    ["Can you tell me about the Construction skillcape?"] = "¿Puedes hablarme sobre el Construction skillcape?",
    ["Can you tell me about the Construction skillcape."] = "¿Puedes hablarme sobre el Construction skillcape?",
    ["As you may know, skillcapes are only available to masters in a skill. I have spent my entire life building houses and now I spend my time selling them! As a sign of my abilities I wear this Skillcape of Construction. If you ever have enough skill to build a demonic throne, come and talk to me and I'll sell you a skillcape like mine."] = "Como sabrás, skillcapes solo está disponible para maestros en una habilidad. ¡He pasado toda mi vida construyendo casas y ahora dedico mi tiempo a venderlas! Como muestra de mis habilidades llevo este Skillcape de Construction. Si alguna vez tienes la habilidad suficiente para construir un trono demoníaco, ven a hablar conmigo y te venderé un skillcape como el mío.",
    ["I'm wondering if you've got any skillcapes lying about?"] = "Me pregunto si tienes algún skillcapes por ahí.",
    ["I hope they're not laying about! Any old sod could pick one up and flaunt it around, but..."] = "¡Espero que no estén holgazaneando! Cualquier viejo podría coger uno y hacer alarde de él, pero...",
    ["I have had something made especially for you, the skillcape of Construction as a token of your mastery in the field."] = "He hecho algo especialmente para ti, el skillcape de Construction como muestra de tu maestría en el campo.",
    ["Unfortunately, it's quite costly to procure the materials needed to craft such an impressive cape, so it is yours at a cost."] = "Desafortunadamente, es bastante costoso conseguir los materiales necesarios para crear una capa tan impresionante, por lo que es tuya a un costo.",
    ["Which skillcape would you like to purchase?"] = "¿Qué skillcape te gustaría comprar?",
    ["I'd like the 99 skillcape please."] = "Me gustaría el 99 skillcape, por favor.",
    ["I don't do this for anyone, but I've got a special offer today! Normally I require 99,000 coins for this prestigious item, but for you it's half price. Only 92,000 coins!"] = "No hago esto por nadie, ¡pero hoy tengo una oferta especial! Normalmente necesito 99.000 coins por este prestigioso artículo, pero para ti es la mitad de precio. ¡Solo 92.000 coins!",
    ["92,000 coins? That's much too expensive."] = "¿92.000 coins? Eso es demasiado caro.",
    ["I know where to find you if I change my mind."] = "Sé dónde encontrarte si cambio de opinión.",
    ["I think I have the money right here, actually."] = "De hecho, creo que tengo el dinero aquí.",
    ["Unfortunately all skillcapes are only available with a free hood, it's part of a skill promotion deal; buy one get one free, you know. So, you'll need to free up some backpack space before I can sell you one."] = "Lamentablemente, todos los skillcapes solo están disponibles con una capucha gratuita, es parte de un acuerdo de promoción de habilidades; Compra uno y llévate otro gratis, ya sabes. Por lo tanto, necesitarás liberar algo de espacio en backpack antes de que pueda venderte uno.",
    ["But unfortunately, I was mistaken."] = "Pero desafortunadamente me equivoqué.",
    ["Well, come back and see me when you do."] = "Bueno, vuelve a verme cuando lo hagas.",
    ["Excellent! Wear that cape with pride my friend."] = "¡Excelente! Lleva esa capa con orgullo, amigo mío.",
    ["I've mastered this skill. Is there anything else?"] = "He dominado esta habilidad. ¿Hay algo más?",
    ["There is something...though I have kept it a secret for a very long time. It is something that can only be worn by a true master."] = "Hay algo... aunque lo he mantenido en secreto durante mucho tiempo. Es algo que sólo puede ser usado por un verdadero maestro.",
    ["Not even I can wear it - that's how hard it is to achieve."] = "Ni siquiera yo puedo usarlo, así de difícil es lograrlo.",
    ["You say you're a master. Stand straight, let me take a look at you..."] = "Dices que eres un maestro. Ponte derecho, déjame echarte un vistazo...",
    ["You...really have mastered it. What an honour! It would be my pleasure to sell you a Construction master cape."] = "Tú... realmente lo dominas. ¡Qué honor! Sería un placer venderle un Construction master cape.",
    ["For that I require 99,000 coins."] = "Para eso necesito 99.000 coins.",
    ["99,000 coins? That's much too expensive."] = "¿99.000 coins? Eso es demasiado caro.",
    ["But, unfortunately, I don't have enough coins."] = "Pero, desafortunadamente, no tengo suficiente coins.",
    ["120 Master skillcape."] = "120 Maestro skillcape.",
    ["I'd like the Master cape please."] = "Me gustaría el Master cape, por favor.",
    ["You really have proven yourself, not only to the guild, but to me, Player. I'm beyond impressed with what you've accomplished."] = "Realmente has demostrado tu valía, no solo ante el gremio, sino también ante mí, Player. Estoy más que impresionado con lo que has logrado.",
    ["With that, it'd be my to offer you the Master skillcape for the cost of 120,000 coins."] = "Con eso, sería mi ofrecerte el Master skillcape por el costo de 120,000 coins.",
    ["Buy Construction master cape for 120,000 coins?"] = "¿Comprar Construction master cape por 120.000 coins?",
    ["You do not have enough room in your backpack. Please come back when you have some more."] = "No tienes suficiente espacio en tu backpack. Por favor regresa cuando tengas más.",
    ["You do not have enough money to purchase this cape."] = "No tienes suficiente dinero para comprar esta capa.",
    ["I've noticed there are a couple of versions of each skillcape."] = "He notado que hay un par de versiones de cada skillcape.",
    ["Yes! We, the skill masters, have crafted new versions of all skillcapes! We felt like it was time for a change."] = "¡Sí! ¡Nosotros, los maestros de habilidades, hemos creado nuevas versiones de todos los skillcapes! Sentimos que era hora de un cambio.",
    ["It looks like you're currently using the old model for your Construction skillcape. Would you like to change to the newer one?"] = "Parece que actualmente estás usando el modelo anterior para tu Construction skillcape. ¿Quieres cambiar a uno más nuevo?",
    ["You can still choose to wear the old model skillcape if you want. Would you like to change which model you are currently using?"] = "Aún puedes elegir usar el modelo antiguo skillcape si lo deseas. ¿Le gustaría cambiar el modelo que está utilizando actualmente?",
    ["Yes, I would like to wear the [new/old] version of the skillcape."] = "Sí, me gustaría usar la versión [new/old] del skillcape.",
    ["Would you like to wear the [old/newer] model for just this cape, or for the Quest Cape and all of the skillcapes you own?"] = "¿Te gustaría usar el modelo [old/newer] solo para esta capa, o para el Quest Cape y todos los skillcapes que tienes?",
    ["I would just like to change the Construction skillcape."] = "Solo me gustaría cambiar el Construction skillcape.",
    ["No problem, you will now use the [older/newer] model for your Construction skillcape."] = "No hay problema, ahora utilizarás el modelo [older/newer] para tu Construction skillcape.",
    ["I would like to change all my skillcapes."] = "Me gustaría cambiar todos mis skillcapes.",
    ["No problem, you will now use the [older/newer] model for all of your skillcapes!"] = "¡No hay problema, ahora usarás el modelo [older/newer] para todos tus skillcapes!",
    ["I've changed my mind!"] = "¡He cambiado de opinión!",
    ["No, thank you."] = "No, gracias.",
    ["Great! I'm glad you're still enjoying the [old/new] version!"] = "¡Genial! ¡Me alegra que sigas disfrutando de la versión [old/new]!",
    ["If you want, I can make it so you use the old model for all of the skillcapes you own!"] = "¡Si quieres, puedo hacerlo para que uses el modelo antiguo para todos los skillcapes que tengas!",
    ["Ok, I'd like to wear the old version for all my skillcapes."] = "Ok, me gustaría usar la versión antigua para todos mis skillcapes.",
    ["Great, you will now use the old model for all of your skillcapes!"] = "¡Genial, ahora usarás el modelo antiguo para todos tus skillcapes!",
    ["Certainly. My magic can rebuild the exterior of your house in a completely new style! Which one would you like?"] = "Por supuesto. ¡Mi magia puede reconstruir el exterior de tu casa con un estilo completamente nuevo! ¿Cuál te gustaría?",
    ["Which house style would you like?"] = "¿Qué estilo de casa te gustaría?",
    ["1. Basic wood (1,250)"] = "1. Madera básica (1.250)",
    ["2. Basic stone (2,500)"] = "2. Piedra básica (2500)",
    ["3. Fancy stone (12,500)"] = "3. Piedra elegante (12.500)",
    ["4. Dark stone (12,500)"] = "4. Piedra oscura (12.500)",
    ["5. Fremennik-style wood (5,000)"] = "5. Madera estilo Fremennik (5.000)",
    ["Your house has been re-decorated."] = "Tu casa ha sido redecorada.",
    ["They don't seem to be interested in speaking to you right now."] = "No parecen estar interesados en hablar contigo en este momento.",
    ["Oh, it's you. Is something the matter?"] = "Oh, eres tú. ¿Pasa algo?",
    ["No, all is right at the moment."] = "No, todo está bien en este momento.",
    ["In that case, I'd prefer to be left alone. I'm on the cusp of a breakthrough here."] = "En ese caso, preferiría que me dejaran en paz. Estoy en la cúspide de un gran avance aquí.",
    ["Ah, a new face. You are here to fi- Ah yes, I mean...you are here for fashionable attire, yes?"] = "Ah, una cara nueva. Estás aquí para fi- Ah, sí, quiero decir... estás aquí para vestirte a la moda, ¿no?",
    ["Yes, that's right."] = "Sí, así es.",
    ["Glad to hear it! Then I have something for you."] = "¡Me alegra oírlo! Entonces tengo algo para ti.",
    ["Once you have the space to carry it that is."] = "Una vez que tengas espacio para llevarlo, claro está.",
    ["[Estocada gives you a wide-brimmed hat.]"] = "[Estocada te ofrece un sombrero de ala ancha.]",
    ["This hat is rather special, my friend. I don't often give gifts, but, when I do, I prefer to give them to duellists."] = "Este sombrero es bastante especial, amigo mío. No suelo dar regalos, pero cuando lo hago, prefiero dárselos a los duelistas.",
    ["Erm, no."] = "Mmmm, no.",
    ["Oh. You surprise me."] = "Ah. Me sorprendes.",
    ["Ahh, a duellist. Stay victorious, my friend."] = "Ahh, un duelista. Mantente victorioso, amigo mío.",
    ["My friend, you have not got your hat. Where is it gone to?"] = "Amigo mío, no tienes tu sombrero. ¿A dónde se fue?",
    ["Well, it is not a problem, these things can be overcome."] = "Bueno, no es un problema, estas cosas se pueden superar.",
    ["All you must do is talk to me once there is space to hold this replacement."] = "Todo lo que debes hacer es hablar conmigo una vez que haya espacio para realizar este reemplazo.",
    ["I don't often replace hats, but, when I do, I choose to replace duellists' caps."] = "No suelo reemplazar sombreros, pero, cuando lo hago, elijo reemplazar las gorras de los duelistas.",
    ["I don't often replace hats, but, when I do, I choose only the height of fashion."] = "No suelo reemplazar los sombreros, pero, cuando lo hago, elijo solo lo último en moda.",
    ["I don't often replace hats, but, you were a fighter in the old arena. How could I say no?"] = "No suelo reemplazar sombreros, pero tú eras un luchador en la antigua arena. ¿Cómo podría decir que no?",
    ["Tell me more about this hat, then."] = "Entonces cuéntame más sobre este sombrero.",
    ["All the time you have this hat on your person or in your bank, it will see you win or fall in the Duel Arena and take note. By its magic you can turn into a statue, which shows those who read its plaque how well you have fought - how many you defeat, your win streak, and the like. If you wish to, you can cause the hat to forget all it has seen of your prowess, or instruct it not to show certain elements."] = "Todo el tiempo que tengas este sombrero contigo o en tu banco, te verá ganar o caer en el Duel Arena y tomar nota. Gracias a su magia, puedes convertirte en una estatua, que muestra a quienes leen su placa lo bien que has luchado: a cuántos derrotas, tu racha de victorias y cosas por el estilo. Si lo deseas, puedes hacer que el sombrero olvide todo lo que ha visto de tu destreza o indicarle que no muestre ciertos elementos.",
    ["The Duel Arena was once a shining symbol of duelling prowess...until it was swallowed by the desert. If you remember the time of the Duel Arena and battled there, this hat will remember also."] = "El Duel Arena fue una vez un brillante símbolo de destreza en duelo... hasta que fue tragado por el desierto. Si recuerdas la época del Duel Arena y luchaste allí, este sombrero también te recordará.",
    ["By its magic you can turn into a statue, which shows those who read its plaque how well you fought in the arena before it fell - how many you defeated, your win streak, and the like."] = "Gracias a su magia, puedes convertirte en una estatua, que muestra a quienes leen su placa lo bien que luchaste en la arena antes de que cayera: a cuántos derrotaste, tu racha de victorias y cosas por el estilo.",
    ["If you wish to, you can cause the hat to forget all it has seen of your prowess. Though the Duel Arena may be gone, you may still reclaim glory through duelling other adventurers throughout Gielinor."] = "Si lo deseas, puedes hacer que el sombrero olvide todo lo que ha visto de tu destreza. Aunque es posible que el Duel Arena ya no esté, aún puedes recuperar la gloria batiéndote en duelo con otros aventureros en Gielinor.",
    ["The Duel Arena was once a shining symbol of duelling prowess...until it was swallowed by the desert. What little remains lie to the north of here."] = "El Duel Arena fue una vez un brillante símbolo de destreza en duelo... hasta que fue tragado por el desierto. Lo poco que queda se encuentra al norte de aquí.",
    ["Back then, there hats were used to show off your skills - how many you defeated, your win streak, and the like."] = "En aquel entonces, se usaban sombreros para mostrar tus habilidades: cuántos derrotabas, tu racha de victorias y cosas por el estilo.",
    ["Nowadays, they are used to show off your success in duelling fellow adventurers across Gielinor."] = "Hoy en día, se utilizan para mostrar tu éxito al batirte en duelo con otros aventureros en Gielinor.",
    ["Handy, thanks!"] = "¡Útil, gracias!",
    ["No! You will not interfere.|color=#99FF99}}"] = "¡No! No interferirás.|color=#99FF99}}",
    ["The portal must remain open at all costs."] = "El portal debe permanecer abierto a toda costa.",
    ["Chaos will reign supreme!"] = "¡El caos reinará!",
    ["YOU WILL BURN!"] = "¡QUEMARÁS!",
    ["Enough! You cannot interfere!"] = "¡Basta! ¡No puedes interferir!",
    ["You will be destroyed!"] = "¡Serás destruido!",
    ["Hello there!"] = "¡Hola!",
    ["What's going on? Last time I was here, everything was intact!"] = "¿Qué está pasando? La última vez que estuve aquí, ¡todo estaba intacto!",
    ["Ah, well, you see... There was seemingly an earthquake. The whole Duel Arena, just destroyed!"] = "Ah, bueno, verás... Aparentemente hubo un terremoto. ¡Todo el Duel Arena, simplemente destruido!",
    ["How awful!"] = "¡Qué horrible!",
    ["Indeed. My team and I are helping out the locals to recover and restore what we can."] = "De hecho. Mi equipo y yo estamos ayudando a los locales a recuperar y restaurar lo que podamos.",
    ["Hello there, Player."] = "Hola, Player.",
    ["What's going on here again?"] = "¿Qué está pasando aquí otra vez?",
    ["Unfortunately a devastating earthquake occurred around what was the Duel Arena, turning it into rubble and ruin."] = "Desafortunadamente se produjo un devastador terremoto alrededor de lo que era el Duel Arena, convirtiéndolo en escombros y ruinas.",
    ["Everyone in the area is chipping in to help recover what we can, and to restore the area into an oasis of life and beauty."] = "Todos en el área están contribuyendo para ayudar a recuperar lo que podamos y para restaurar el área y convertirla en un oasis de vida y belleza.",
    ["What can I do to help?"] = "¿Qué puedo hacer para ayudar?",
    ["At the moment, we're trying to unlock that hefty chest over there... We came across it whilst scouring the ruins for artefacts. But it's proving to be a bit more difficult than we anticipated."] = "En este momento, estamos tratando de desbloquear ese cofre pesado que está allí... Lo encontramos mientras buscábamos artefactos en las ruinas. Pero está resultando un poco más difícil de lo que esperábamos.",
    ["So in the meantime, please look around to see what you can help with! There's all sorts that need to be doing each day."] = "Mientras tanto, ¡mire a su alrededor para ver en qué puede ayudar! Hay todo tipo de cosas que hay que hacer cada día.",
    ["Like what?"] = "¿Cómo qué?",
    ["Well, to start with, there's a number of activities around the oasis you might be able to use your skills for."] = "Bueno, para empezar, hay una serie de actividades en el oasis en las que quizás puedas usar tus habilidades.",
    ["The water is horribly infested with scarabs, so you can use your hunting abilities to help clear them out."] = "El agua está terriblemente infestada de escarabajos, por lo que puedes usar tus habilidades de caza para ayudar a eliminarlos.",
    ["With the destruction also came a blooming of new flower species. You might be able to use your farming abilities to cultivate these, for further studying."] = "Con la destrucción también surgió el florecimiento de nuevas especies de flores. Es posible que puedas utilizar tus habilidades agrícolas para cultivarlos y estudiarlos más a fondo.",
    ["And lastly, you can use your agility to explore the area. Let me know if you come across anything interesting!"] = "Y por último, puedes usar tu agilidad para explorar el área. ¡Cuéntame si encuentras algo interesante!",
    ["I've also got a task list here with me if you need anything else to do."] = "También tengo una lista de tareas aquí conmigo si necesitas hacer algo más.",
    ["Open tasks."] = "Tareas abiertas.",
    ["Not much to say, really! My mother and father were archaeologists, so I've been around the profession my whole life. It was only natural that I'd grow up to be one, too."] = "¡No hay mucho que decir, de verdad! Mi madre y mi padre eran arqueólogos, así que he estado en esta profesión toda mi vida. Era natural que yo también creciera y me convirtiera en uno.",
    ["I was born and bred in Varrock, but my work has taken me all over Gielinor. It's what I love about it!"] = "Nací y crecí en Varrock, pero mi trabajo me ha llevado a todo Gielinor. ¡Es lo que me encanta de él!",
    ["Hello there. Have you come to take in a few laps, perhaps? Or maybe to catch some whirligigs?"] = "Hola. ¿Has venido a dar unas vueltas, tal vez? ¿O tal vez para coger algunos remolinos?",
    ["Maybe, but just a flying visit to you first to check off this task..."] = "Tal vez, pero solo una visita rápida a usted primero para completar esta tarea...",
    ["Oh, you want my signature? Ha! I must be famous! Mum and dad would be proud."] = "Ah, ¿quieres mi firma? ¡Ja! ¡Debo ser famoso! Mamá y papá estarían orgullosos.",
    ["It's Not Time to Duel"] = "No es momento de batirse en duelo",
    ["Talk to Etta Stone in front of Het's Oasis, north of Al Kharid."] = "Habla con Etta Stone frente a Het's Oasis, al norte de Al Kharid.",
    ["Thank you! Keep up the good work, Etta."] = "¡Gracias! Sigue con el buen trabajo, Etta.",
    ["Looks like I've completed everything. I'd better go and see Hans about that reward!"] = "Parece que he completado todo. ¡Será mejor que vaya a ver a Hans sobre esa recompensa!",
    ["Ah, World Guardian. How good it is to see you. I wonder, if it's not too much of an inconvenience, could you do me a small favour?"] = "Ah, Guardián Mundial. Que bueno es verte. Me pregunto, si no es mucha molestia, ¿podrías hacerme un pequeño favor?",
    ["With so much of the arena now being...rather forcibly , there are a number of historical artefacts that have appeared."] = "Dado que gran parte de la arena ahora es... bastante forzadamente , han aparecido una serie de artefactos históricos.",
    ["The museum is helping out with the restoration of these artefacts for Al Kharid. But we rather lack the facilities here."] = "El museo está ayudando con la restauración de estos artefactos para Al Kharid. Pero aquí nos faltan las instalaciones necesarias.",
    ["As you're the most trustworthy person I'm aware of, would you be so kind as to drop these off at the museum for me?"] = "Como eres la persona más confiable que conozco, ¿serías tan amable de dejarme esto en el museo?",
    ["Sure, I'll take them to the museum."] = "Claro, los llevaré al museo.",
    ["Fantastic, you'll just need to hand them over the curator."] = "Fantástico, solo tendrás que entregárselos the curator.",
    ["Oh dear, it appears you're already overburdened. When you've got some space free in your backpack come talk to me again."] = "Dios mío, parece que ya estás sobrecargado. Cuando tengas algo de espacio libre en tu backpack ven a hablar conmigo de nuevo.",
    ["You receive a package full of broken bits of pottery."] = "Recibes un paquete lleno de trozos de cerámica rotos.",
    ["Thank you ever so much!"] = "¡Muchas gracias!",
    ["Not right now."] = "No ahora mismo.",
    ["Oh, I totally understand. You must be a very busy person. Well, I'll be here if you change your mind."] = "Oh, lo entiendo totalmente. Debes ser una persona muy ocupada. Bueno, estaré aquí si cambias de opinión.",
    ["Have you delivered the research items yet?"] = "¿Ya entregaste los elementos de investigación?",
    ["No, not yet. I'll get on that."] = "No, todavía no. Me ocuparé de eso.",
    ["Can I help you at all?"] = "¿Puedo ayudarte en algo?",
    ["Yes please. What are you selling?"] = "Sí por favor. ¿Qué estás vendiendo?",
    ["Eva looks lost in thought and doesn't notice you."] = "Eva parece perdido en sus pensamientos y no se da cuenta de ti.",
    ["Ah, Player, good to see you again."] = "Ah, Player, que bueno verte de nuevo.",
    ["Hey Eva!"] = "¡Hola Eva!",
    ["Welcome back Player!"] = "¡Bienvenido de nuevo Player!",
    ["This machine converts junk into runes withouy all of that running back and forth!"] = "¡Esta máquina convierte basura en runas sin que todo eso tenga que correr de un lado a otro!",
    ["If you just follow my rudimentary runecrafting routine you can earn all sorts of Runecrafting XP!"] = "¡Si sigues mi rudimentaria rutina de creación de runas, podrás ganar todo tipo de XP Runecrafting!",
    ["What's the catch?"] = "¿Cuál es el problema?",
    ["No catch, none at all!"] = "¡Ninguna captura, ninguna en absoluto!",
    ["It's a little bit inefficient."] = "Es un poco ineficiente.",
    ["And relatively untested."] = "Y relativamente no probado.",
    ["But this is where you come in!"] = "¡Pero aquí es donde entras tú!",
    ["My spectacularly splendind subject..."] = "Mi sujeto espectacularmente espléndido...",
    ["Uh oh."] = "Oh, oh.",
    ["Why did you enter the Summer Skill Off?"] = "¿Por qué participaste en el Summer Skill Off?",
    ["As you can see, I fancy myself a bit of an inventor."] = "Como puedes ver, me considero un poco inventor.",
    ["I want to share my inventions with the whole of Gielinor"] = "Quiero compartir mis inventos con todo Gielinor",
    ["It's not just about changing the world, it's about changing the entire universe!"] = "¡No se trata sólo de cambiar el mundo, sino de cambiar el universo entero!",
    ["But that's going to be rather expensive."] = "Pero eso será bastante caro.",
    ["Those are some grand ambitions!"] = "¡Esas son grandes ambiciones!",
    ["They are grand but the possibilities are limitless!"] = "¡Son grandiosos pero las posibilidades son ilimitadas!",
    ["I want you to imagine a button."] = "Quiero que imagines un botón.",
    ["I am imagining a button."] = "Me estoy imaginando un botón.",
    ["You press the button."] = "Presionas el botón.",
    ["I press the button."] = "Presiono el botón.",
    ["I don't know, I haven't got that far yet."] = "No lo sé, todavía no he llegado tan lejos.",
    ["Alright then."] = "Muy bien entonces.",
    ["Is this safe?"] = "¿Es esto seguro?",
    ["Almost definitely."] = "Casi definitivamente.",
    ["Are you sure?"] = "¿Estás seguro?",
    ["Most probably."] = "Lo más probable es que.",
    ["I'm in danger aren't I?"] = "Estoy en peligro, ¿no?",
    ["Indubitably."] = "Sin duda.",
    ["Goodbye!"] = "¡Adiós!",
    ["Be seeing you."] = "Nos vemos.",
    ["Salutations Player!"] = "¡Saludos Player!",
    ["Welcome back to the hole!"] = "¡Bienvenido de nuevo al hoyo!",
    ["Glad to be back!"] = "¡Me alegro de estar de regreso!",
    ["This is Eva, she came up short during The Great Herblore Runecrafting War of the Summer Skill Off."] = "Esta es Eva, se quedó corta durante el Gran Herblore Runecrafting War del Summer Skill Off.",
    ["She's still a little upset about it."] = "Ella todavía está un poco molesta por eso.",
    ["What do I need to do here?"] = "¿Qué necesito hacer aquí?",
    ["So, what do I need to do here?"] = "Entonces, ¿qué debo hacer aquí?",
    ["Well Player, it's time for some delightfully dazzling divination!"] = "Bueno, Player, ¡es hora de una adivinación deliciosamente deslumbrante!",
    ["Just follow my orders and you'll make the hole simply divine."] = "Solo sigue mis órdenes y harás que el agujero sea simplemente divino.",
    ["Switch which type of energy you are depositing by selecting either the red or blue wisps."] = "Cambie el tipo de energía que está depositando seleccionando las mechas rojas o azules.",
    ["Matching Eva's suggestions will grant increased XP while skilling at this location!"] = "¡Hacer coincidir las sugerencias de Eva otorgará más XP mientras practicas en esta ubicación!",
    ["Got it!"] = "¡Entendido!",
    ["Yeah you do!"] = "¡Sí, lo haces!",
    ["What's with the new job?"] = "¿Qué pasa con el nuevo trabajo?",
    ["How come you're on hole duty now?"] = "¿Cómo es que ahora estás de servicio?",
    ["Well Player, I figured if I'm to beat out that fool I may as well go all out."] = "Bueno, Player, pensé que si quiero vencer a ese tonto, también podría hacer todo lo posible.",
    ["Clearly there is something special about this hole and I am going to harness that speciality."] = "Claramente hay algo especial en este hoyo y voy a aprovechar esa especialidad.",
    ["I am fully finished with the foolish foolery of the foolish fool foolishly fooling with his foolish fuel."] = "He terminado por completo con la tontería tonta del tonto tonto que tontamente tonto con su tonto combustible.",
    ["Why are you looking at me like that?"] = "¿Por qué me miras así?",
    ["It's nothing... it's just..."] = "No es nada... es solo...",
    ["Have you ever heard a word so much that it doesn't sound like a word anymore?"] = "¿Alguna vez has escuchado tanto una palabra que ya no suena como tal?",
    ["Yes, it's simple semantic satiation."] = "Sí, es simple saciedad semántica.",
    ["Ah!"] = "¡Ah!",
    ["Hehehe..."] = "Jejeje...",
    ["Fool..."] = "Tonto...",
    ["Why did you enter the Winter Chill Off?"] = "¿Por qué participaste en el Winter Chill Off?",
    ["Why did I enter?"] = "¿Por qué entré?",
    ["Pride."] = "Orgullo.",
    ["My pride was damaged by that follically impaired idiot at the Summer Skill Off."] = "Mi orgullo fue dañado por ese idiota con discapacidad fólica en el Summer Skill Off.",
    ["It came right down to the wire."] = "Llegó hasta el último momento.",
    ["I cannot believe that useless plant skill won out over the far superior Runecrafting."] = "No puedo creer que la inútil habilidad de las plantas haya vencido al muy superior Runecrafting.",
    ["Plant skill?"] = "¿Habilidad vegetal?",
    ["You mean herblore?"] = "¿Te refieres a herblore?",
    ["Don't you mention that skill again in my presence."] = "No vuelvas a mencionar esa habilidad en mi presencia.",
    ["I'm sick and tired of hearing 120 herblore this, 120 herblore that."] = "Estoy harto y cansado de escuchar 120 hierbas sobre esto, 120 hierbas sobre aquello.",
    ["120 runecrafting, that's what the people want!"] = "120 runecrafting, ¡eso es lo que la gente quiere!",
    ["No! You're crazy!"] = "¡No! ¡Estás loco!",
    ["Just another fool..."] = "Sólo otro tonto...",
    ["Can I jump in the hole?"] = "¿Puedo saltar al hoyo?",
    ["Can I dungeoneer in the hole?"] = "¿Puedo hacer mazmorras en el hoyo?",
    ["Uh... probably?"] = "Eh... ¿probablemente?",
    ["Sure. I'm gonna say yes."] = "Claro. Voy a decir que sí.",
    ["Alrighty."] = "Muy bien.",
    ["Uh... Hello there."] = "Eh... Hola.",
    ["Chad said that they needed some help running the celebration this year so I tagged along."] = "Chad dijo que necesitaban ayuda para organizar la celebración este año, así que los acompañé.",
    ["What's going on around you then?"] = "¿Qué sucede entonces a tu alrededor?",
    ["Oh! We're summoning pretty fire spirits using special fire stones."] = "¡Oh! Estamos convocando bonitos espíritus de fuego usando piedras de fuego especiales.",
    ["That sounds like a lot of fun."] = "Eso suena muy divertido.",
    ["*(If the fire stone hasn't been claimed:)*"] = "*(Si la piedra de fuego no ha sido reclamada:)*",
    ["Can I have a go?"] = "¿Puedo intentarlo?",
    ["Here, take this fire stone. You can use it to summon one of the fire spirits you see around us."] = "Toma, toma esta piedra de fuego. Puedes usarlo para convocar a uno de los espíritus de fuego que ves a nuestro alrededor.",
    ["Thanks, I'll make use of this."] = "Gracias, haré uso de esto.",
    ["*(If the fire stone has been claimed:)*"] = "*(Si la piedra de fuego ha sido reclamada:)*",
    ["Have you got any more fire stones?"] = "¿Tienes más piedras de fuego?",
    ["We're going to be celebrating the new year with fire! I'll be summoning some fire spirits to make this place really festive looking."] = "¡Vamos a celebrar el año nuevo con fuego! Convocaré algunos espíritus del fuego para que este lugar tenga un aspecto realmente festivo.",
    ["Come back soon and you'll be able to help out as well!"] = "¡Vuelve pronto y podrás ayudar también!",
    ["Chad said that they needed some help running the celebration so I tagged along."] = "Chad dijo que necesitaban ayuda para organizar la celebración, así que los acompañé.",
    ["Summon spirits."] = "Invocar espíritus.",
    ["*(If the warning hasn't been toggled off:)*"] = "*(Si la advertencia no se ha desactivado:)*",
    ["This will give you XP in both Summoning and Firemaking."] = "Esto le dará XP tanto en Summoning como en Firemaking.",
    ["Continue"] = "Continuar",
    ["Continue, and don't show this again"] = "Continuar y no volver a mostrar esto.",
    ["Go back"] = "volver",
    ["*(If the warning has been toggled off:)*"] = "*(Si la advertencia se ha desactivado:)*",
    ["It's time for me to move on now as the celebration of the new year has ended."] = "Es hora de seguir adelante ahora que la celebración del nuevo año ha terminado.",
    ["Maybe I'll see you again for some other fire related holiday!"] = "¡Quizás nos veamos de nuevo en otras festividades relacionadas con el fuego!",
    ["Conversation 1"] = "Conversación 1",
    ["Let me out of here!"] = "¡Déjame salir de aquí!",
    ["I will never let you go, Player!"] = "¡Nunca te dejaré ir, Player!",
    ["Uhm... Because I say so! And, also because I can never have enough servants! Now catch me some fish, I'm hungry."] = "Uhm... ¡Porque yo lo digo! ¡Y también porque nunca tendré suficientes sirvientes! Ahora cógeme un poco de pescado, tengo hambre.",
    ["What fish, where?"] = "¿Qué pez, dónde?",
    ["Talk to my other servants and hurry it up!"] = "¡Habla con mis otros sirvientes y apúrate!",
    ["Conversation 2"] = "Conversación 2",
    ["I will never let you go, [Player Name]!"] = "¡Nunca te dejaré ir, [Player Name]!",
    ["What's it all about?"] = "¿De qué se trata?",
    ["Sit down and I'll tell you. It's a question of servant shortage."] = "Siéntate y te lo cuento. Es una cuestión de escasez de servidores.",
    ["Go on."] = "Continúa.",
    ["You are a skilled worker. A human like you is worth a great deal as a slave."] = "Eres un trabajador calificado. Un humano como tú vale mucho como esclavo.",
    ["A slave? I will have nothing to do with you. Is that clear? Absolutely nothing."] = "¿Un esclavo? No tendré nada que ver contigo. ¿Está eso claro? Absolutamente nada.",
    ["Now, be reasonable, little human. It's just a matter of time before you do everything I ask of you. Play along and this could be a very nice place."] = "Ahora, sé razonable, pequeño humano. Es sólo cuestión de tiempo antes de que hagas todo lo que te pido. Sigue el juego y este podría ser un lugar muy agradable.",
    ["I will not make any deals with you. I'm a human. I will not be pushed, numbered, meowed at, teleported or enslaved. My life is my own."] = "No haré ningún trato contigo. Soy un humano. No seré empujado, numerado, maullado, teletransportado ni esclavizado. Mi vida es mía.",
    ["Is it?"] = "¿Lo es?",
    ["Yes. You won't hold me."] = "Sí. No me abrazarás.",
    ["Won't I? Let me assure you that there's no way out. Just ask my servants."] = "¿No lo haré? Déjame asegurarte que no hay salida. Pregúntale a mis sirvientes.",
    ["Conversation 3"] = "Conversación 3",
    ["How is it possible that you're talking?"] = "¿Cómo es posible que estés hablando?",
    ["How is it possible that you're not meowing?"] = "¿Cómo es posible que no estés maullando?",
    ["Meowing? Why would I be meowing?"] = "¿Maullidos? ¿Por qué estaría maullando?",
    ["Most humans do; that's why I'm wearing this Amulet of Manspeak. I do try to train my staff in civilised speech. Ah, but I suppose things are slightly different in your world. What a dreadful place that must be."] = "La mayoría de los humanos lo hacen; por eso llevo este Amuleto de Manspeak. Intento entrenar a mi staff en un habla civilizada. Ah, pero supongo que las cosas son ligeramente diferentes en tu mundo. Qué lugar tan espantoso debe ser ese.",
    ["I think I'm getting a headache..."] = "Creo que me duele la cabeza...",
    ["Conversation 4"] = "Conversación 4",
    ["What did you do to Bob?"] = "¿Qué le hiciste a Bob?",
    ["Bob? I am Bob! Oh, you mean the Bob in your world? Nothing. I am the incarnation of Bob here on ScapeRune."] = "¿Bob? ¡Soy Bob! Oh, ¿te refieres al Bob en tu mundo? Nada. Soy la encarnación de Bob aquí en ScapeRune.",
    ["What, you mean this is...like some kind of mirror land?"] = "¿Qué? ¿Quieres decir que esto es... como una especie de tierra de espejos?",
    ["Something like that. Somewhere, in ScapeRune, there must be a human servant called Player. But you work just as well for me. Now get to work, human. Fish for me!"] = "Algo así. En algún lugar, en ScapeRune, debe haber un sirviente humano llamado Player. Pero funcionas igual de bien para mí. Ahora ponte a trabajar, humano. ¡Pescado para mí!",
    ["Hi Evil Bob. I'm Player."] = "Hola Evil Bob. Soy Player.",
    ["Ah, a new prisoner!"] = "¡Ah, un nuevo prisionero!",
    ["Not quite. I was hoping to get some blueberries, please."] = "No del todo. Esperaba conseguir algunos arándanos, por favor.",
    ["Hmm. Normally I wouldn't help a human with something they need."] = "Mmm. Normalmente no ayudaría a un humano con algo que necesita.",
    ["But, I am bored. And you did say please."] = "Pero estoy aburrido. Y dijiste por favor.",
    ["You must get me something in return first. Something shiny."] = "Primero debes darme algo a cambio. Algo brillante.",
    ["Something shiny? There's a lot of shiny things."] = "¿Algo brillante? Hay muchas cosas brillantes.",
    ["Not just anything shiny. Something to keep me entertained."] = "No cualquier cosa brillante. Algo que me mantenga entretenido.",
    ["Now, out of my sight."] = "Ahora, fuera de mi vista.",
    ["Evil Bob's eyes glaze over, as he mentally leaves the conversation."] = "Los ojos de Evil Bob se ponen vidriosos mientras mentalmente abandona la conversación.",
    ["Something entertaining for a cat, and shiny. A mouse... A ball of wool, maybe?"] = "Algo entretenido para un gato y brillante. Un ratón... ¿Un ovillo de lana, tal vez?",
    ["Where is my shiny and entertaining item?"] = "¿Dónde está mi artículo brillante y entretenido?",
    ["I don't have it yet."] = "Aún no lo tengo.",
    ["I don't want to see you until you do."] = "No quiero verte hasta que lo hagas.",
    ["I have something shiny for you."] = "Tengo algo brillante para ti.",
    ["Yes? Give it here."] = "¿Sí? Dámelo aquí.",
    ["File:Golden wool.png You place the ball of golden wool down in front of Evil Bob."] = "Archivo:Golden wool.png Colocas el ovillo de lana dorada delante de Evil Bob.",
    ["This is just what I need. Now, off with you."] = "Esto es justo lo que necesito. Ahora, vete contigo.",
    ["Er... Can I have the blueberries now?"] = "Er... ¿Puedo comer los arándanos ahora?",
    ["Ugh. You again. I suppose a deal is a deal."] = "Uf. Tú otra vez. Supongo que un trato es un trato.",
    ["Evil Bob beckons his servant forward."] = "Evil Bob hace una seña a su sirviente para que se acerque.",
    ["Here you go. Homegrown by the prisoners!"] = "Aquí tienes. ¡Cosecha propia de los prisioneros!",
    ["File:Blueberries.png Evil Bob's servant hands you some blueberries."] = "Archivo:Blueberries.png El sirviente de Evil Bob te entrega algunos arándanos.",
    ["Thanks. I think."] = "Gracias. Creo.",
    ["Get me some fish for my supper, slave."] = "Tráeme algo de pescado para la cena, esclavo.",
    ["I lost the blueberries. Can I have some more?"] = "Perdí los arándanos. ¿Puedo tener un poco más?",
    ["I'm not a charity. I'm evil! Bring me more golden wool and you can have more blueberries."] = "No soy una organización benéfica. ¡Soy malvado! Tráeme más lana dorada y podrás tener más arándanos.",
    ["Here you go."] = "Aquí tienes.",
    ["Evil Bob servant takes the golden wool from you, and gives you some more blueberries."] = "El sirviente de Evil Bob te quita la lana dorada y te da más arándanos.",
    ["*The Evil Chicken yelled the following while attacking:*"] = "*El Evil Chicken gritó lo siguiente mientras atacaba:*",
    ["*When he appeared underwater, the phrases were different:*"] = "*Cuando apareció bajo el agua, las frases fueron diferentes:*",
    ["Welcome to my BASEMENT OF DOOM!"] = "¡Bienvenido a mi SÓTANO DE DOOM!",
    ["Evil Dave's Big Day Out'."] = "El gran día libre de Evil Dave\".",
    ["General chat."] = "Charla general.",
    ["Nice basement!"] = "¡Bonito sótano!",
    ["Nice?!"] = "¡¿Bien?!",
    ["I mean, evil!"] = "Quiero decir, ¡malvado!",
    ["Yeah! I'm going to use it to summon DEMONS to DO MY BIDDING, Or raise an ARMY OF THE UNDEAD! And then I'm going to totally, like, take over the world!"] = "¡Sí! ¡Voy a usarlo para convocar DEMONIOS para CUMPLIR MIS ORDENES, o formar un EJÉRCITO DE NO MUERTOS! ¡Y luego voy a conquistar el mundo por completo!",
    ["Ah-ha-ha-ha-ha-haa!"] = "¡Ah-ja-ja-ja-ja-ja!",
    ["So have you had any luck with the demon-summoning?"] = "Entonces, ¿has tenido suerte con la invocación de demonios?",
    ["Well, I thought I should start small, so I asked Wizard Grayzag for some help with summoning imps..."] = "Bueno, pensé que debería empezar poco a poco, así que le pedí ayuda a Wizard Grayzag para invocar diablillos...",
    ["And did you manage to summon any?"] = "¿Y lograste convocar a alguno?",
    ["Well, not imps, exactly. It turns out they're not the lowest form of demon after all. I got these hell-rats."] = "Bueno, diablillos no, exactamente. Resulta que, después de todo, no son la forma más baja de demonio. Tengo estas ratas infernales.",
    ["They're hardly evil at all! They're just like regular rats only they smell vaguely of sulphur!"] = "¡No son nada malvados! ¡Son como ratas normales, sólo que huelen vagamente a azufre!",
    ["Weren't you going to give up evil?"] = "¿No ibas a renunciar al mal?",
    ["See you later."] = "Hasta luego.",
    ["See you later!"] = "¡Hasta luego!",
    ["Of course you will return! There is no escape from my DARK POWER!"] = "¡Por supuesto que volverás! ¡No hay escapatoria de mi PODER OSCURO!",
    ["If my ARMY OF DARKNESS doesn't get you first!"] = "¡Si mi EJÉRCITO DE LA OSCURIDAD no te atrapa primero!",
    ["If you can find your way out of my BASEMENT OF DOOM!"] = "¡Si puedes encontrar la salida de mi SÓTANO DE DOOM!",
    ["Yeah, well..."] = "Sí, bueno...",
    ["I did try. I wore this bright red jumper and I got up in the morning and spent the day outside in the sunshine..."] = "Lo intenté. Me puse este jersey rojo brillante, me levanté por la mañana y pasé el día afuera bajo el sol...",
    ["*Dave shudders*"] = "*Dave se estremece*",
    ["But I couldn't keep it up. I just didn't find anything good very interesting, you know?"] = "Pero no pude seguir así. Simplemente no encontré nada bueno ni muy interesante, ¿sabes?",
    ["Sometimes I worry about the consequences of evil. I don't really want anyone to get hurt, not like what happened with Denath."] = "A veces me preocupo por las consecuencias del mal. Realmente no quiero que nadie salga lastimado, no como lo que pasó con Denath.",
    ["But I can't not be evil! It's just who I am!"] = "¡Pero no puedo no ser malvado! ¡Es simplemente lo que soy!",
    ["Let me try to explain the time travel thing again..."] = "Déjame intentar explicarte lo del viaje en el tiempo otra vez...",
    ["Although you're here, you're also still in the time freeze."] = "Aunque estás aquí, también estás congelado en el tiempo.",
    ["What?"] = "¿Qué?",
    ["I mean, the whole room was frozen in time at the moment the culinomancer cast his spell, right?"] = "Quiero decir, toda la habitación quedó congelada en el tiempo en el momento en que el culinomante lanzó su hechizo, ¿verdad?",
    ["What? I didn't notice anything."] = "¿Qué? No noté nada.",
    ["Of course you didn't! You were frozen!"] = "¡Por supuesto que no! ¡Estabas congelado!",
    ["So how can I be there and also here? Which one is me?"] = "Entonces, ¿cómo puedo estar allí y también aquí? ¿Cuál soy yo?",
    ["I mean, I feel like I'm me, but what if I'm not me?"] = "Quiero decir, siento que soy yo, pero ¿y si no soy yo?",
    ["That would be terrible!"] = "¡Eso sería terrible!",
    ["They're both you!"] = "¡Ambos sois vosotros!",
    ["How does that work?"] = "¿Cómo funciona eso?",
    ["From YOUR point of view I've saved you, but from MINE I haven't."] = "Desde TU punto de vista te he salvado, pero desde el MÍO no.",
    ["Well that's all right, as long as I'm saved from my point of view!"] = "¡Bueno, está bien, siempre y cuando esté salvo desde mi punto de vista!",
    ["But I have to save you, otherwise you won't be saved!"] = "¡Pero tengo que salvarte, de lo contrario no serás salvo!",
    ["But I'm here so you must already have saved me!"] = "¡Pero estoy aquí, así que ya debes haberme salvado!",
    ["That's what I meant, from your point of view I've saved you but from mine I haven't!"] = "Eso es lo que quise decir, desde tu punto de vista te he salvado pero desde el mío no.",
    ["I've got to take the food back in time to give it to you."] = "Tengo que llevar la comida al pasado para dártela.",
    ["I've to take the food back in time to give it to you."] = "Tengo que llevar la comida al pasado para dártela.",
    ["Because otherwise you won't be saved from the culinomancer's spell."] = "Porque de lo contrario no te salvarás del hechizo del culinomante.",
    ["But I was saved from the spell! I remember it!"] = "¡Pero me salvé del hechizo! ¡Lo recuerdo!",
    ["Exactly! That's why I know I have to go back and save you!"] = "¡Exactamente! ¡Por eso sé que tengo que regresar y salvarte!",
    ["What will happen if you don't?"] = "¿Qué pasará si no lo haces?",
    ["I can't not, I already have!"] = "¡No puedo no, ya lo hice!",
    ["I can't not, because I already have!"] = "¡No puedo no, porque ya lo hice!",
    ["The fact that you're here means I already did save you, which means that you have to tell me the correct recipe. It's logically impossible for you not to!"] = "El hecho de que estés aquí significa que ya te salvé, lo que significa que tienes que decirme la receta correcta. ¡Es lógicamente imposible que no lo hagas!",
    ["I don't understand this at all."] = "No entiendo esto en absoluto.",
    ["There will be a temporal paradox and the universe will implode!"] = "¡Habrá una paradoja temporal y el universo implosionará!",
    ["Oh no! That would be bad, and not even in an evil way!"] = "¡Oh, no! ¡Eso sería malo, y ni siquiera de forma perversa!",
    ["Exactly! So you've got to tell me the recipe!"] = "¡Exactamente! ¡Así que tienes que contarme la receta!",
    ["But I still don't understand why you need the recipe when you've already saved me!"] = "¡Pero todavía no entiendo por qué necesitas la receta cuando ya me has salvado!",
    ["I don't know."] = "No lo sé.",
    ["That's not very helpful. I don't even understand why you need the recipe anyway."] = "Eso no es de mucha ayuda. De todos modos, ni siquiera entiendo por qué necesitas la receta.",
    ["You've got to tell me because the magic requires it!"] = "¡Tienes que decírmelo porque la magia lo requiere!",
    ["That's what you said before! Honestly, why make it more complicated than it needs to be?"] = "¡Eso es lo que dijiste antes! Honestamente, ¿por qué hacerlo más complicado de lo necesario?",
    ["Oh, never mind."] = "Oh, no importa.",
    ["Hello Dav-uh Doris?"] = "Hola Dav-uh Doris?",
    ["Look who it is, The Troublemaker."] = "Mira quién es, El Alborotador.",
    ["How are you finding being Dave?"] = "¿Qué te parece ser Dave?",
    ["At first I thought this could be catharsis. I could be the Dave that he never was. I could show him how much better of a Dave I was than him. But soon, it became obvious to me. I could make Dave a better person. I could show Dave what it was like to be Dave. I could make Dave pay."] = "Al principio pensé que esto podría ser una catarsis. Podría ser el Dave que nunca fue. Podría mostrarle que yo era mucho mejor Dave que él. Pero pronto me resultó obvio. Podría hacer de Dave una mejor persona. Podría mostrarle a Dave cómo era ser Dave. Podría hacer que Dave pagara.",
    ["How did that work out for you?"] = "¿Cómo te resultó?",
    ["He doesn't care. He just loves being me. But I learned something. Now I know why Dave wants be evil. Any manner of COLD REPRIEVE is preferable to living out such a MEANINGLESS EXISTENCE."] = "A él no le importa. Le encanta ser yo. Pero aprendí algo. Ahora sé por qué Dave quiere ser malvado. Cualquier forma de RESPUERTO FRÍO es preferible a vivir una EXISTENCIA SIN SENTIDO.",
    ["Um, I'm going to go. Catch you later?"] = "Mmm, me voy. ¿Te veo más tarde?",
    ["GOODBYE DEARIE. GOODBYE."] = "ADIÓS QUERIDA. ADIÓS.",
    ["Oh, I didn't know that!"] = "¡Oh, no lo sabía!",
    ["Baah. Baaah bah ba-baaah. Bah baaaah baaah. Baaaah."] = "Baah. Baaah bah ba-baaah. Bah baaaah baaah. Baaaa.",
    ["*(If big sprout is winning:)*"] = "*(Si el gran brote está ganando:)*",
    ["So evil Niya's sprouts are losing the fight?"] = "¿Entonces los brotes de evil Niya están perdiendo la pelea?",
    ["*(If big zombie sprout is winning:)*"] = "*(Si el gran zombie sprout gana :)*",
    ["Can you remind me how to help you again?"] = "¿Puedes recordarme cómo ayudarte nuevamente?",
    ["So I can promote or corrupt the growth of the bigger sprouts to help them win their fights?"] = "¿Entonces puedo promover o corromper el crecimiento de los brotes más grandes para ayudarlos a ganar sus peleas?",
    ["And if I help out enough with a sister they'll reward me with a set of wings?"] = "¿Y si ayudo lo suficiente con una hermana me recompensarán con un par de alas?",
    ["Goodbye, I guess."] = "Adiós, supongo.",
    ["Goodbye"] = "Adiós",
    ["*(If the daily fatigue is capped:)*"] = "*(Si la fatiga diaria tiene un límite:)*",
    ["So if had some of Alice's magic plant sprays I would be able to help out more today?"] = "Entonces, si tuviera algunos de los aerosoles de plantas mágicas de Alice, ¿podría ayudar más hoy?",
    ["*(First time:)*"] = "*(Primera vez:)*",
    ["*(Subsequent times:)*"] = "*(Tiempos posteriores:)*",
    ["My sisters sprouts are destroying mine! Do something about it!"] = "¡Los brotes de mis hermanas están destruyendo los míos! ¡Haz algo al respecto!",
    ["I have to admit that you've helped me out somewhat more than my sister so far. Make sure it stays that way."] = "Tengo que admitir que hasta ahora me has ayudado un poco más que mi hermana. Asegúrate de que siga así.",
    ["You've helped my sister far too much for my liking, I should do something about you when I have time..."] = "Has ayudado demasiado a mi hermana para mi gusto, debería hacer algo contigo cuando tenga tiempo...",
    ["If only you had some of Alice's magic plant sprays you would be able to help me more today, come back again tomorrow!"] = "Si tan solo tuvieras algunos de los aerosoles de plantas mágicas de Alice, podrías ayudarme más hoy. ¡Vuelve mañana!",
    ["If you know what's good for you, you can help by using your knowledge of herblore to further corrupt the bigger sprouts."] = "Si sabes lo que es bueno para ti, puedes ayudar usando tu conocimiento de la hierba para corromper aún más los brotes más grandes.",
    ["And if you were to help enough I could reward you with one of my older sproouts that I brought back from the dead. They might be strong enough to act as a set of wings."] = "Y si ayudaras lo suficiente, podría recompensarte con uno de mis brotes más viejos que traje de entre los muertos. Podrían ser lo suficientemente fuertes como para actuar como un par de alas.",
    ["If you help me out I could reward you with wings instead!"] = "¡Si me ayudas, podría recompensarte con alas!",
    ["Whatever you do, DON'T promote their growth! That's exactly what my sister wants."] = "Hagas lo que hagas, ¡NO promuevas su crecimiento! Eso es exactamente lo que mi hermana quiere.",
    ["The fighting isn't limited to just here, if you can locate the other sprouts you might find it more rewarding to corrupt the growth there instead."] = "La lucha no se limita solo aquí; si puedes localizar los otros brotes, puede que te resulte más gratificante corromper el crecimiento allí.",
    ["Don't mind my sister, she gets into such a tiff when things don't go her way."] = "No te preocupes por mi hermana, ella se pelea mucho cuando las cosas no salen como ella quiere.",
    ["We'll see about that!"] = "¡Ya veremos!",
    ["Without some magic plant sprays there is only so much you can do a day to help."] = "Sin algunos aerosoles mágicos para plantas, hay mucho que puedes hacer al día para ayudar.",
    ["If you can get your hands on Alice's chests you might be able to find some of those magic plant sprays laying around."] = "Si puedes conseguir los cofres de Alice, es posible que puedas encontrar algunos de esos aerosoles de plantas mágicas por ahí.",
    ["Start corrupting those sprouts!"] = "¡Empieza a corromper esos brotes!",
    ["Oh I can't wait to see the look on my sister's face when she realises that all her precious sprouts are nearly destroyed, just the ones left here."] = "Oh, no puedo esperar a ver la expresión del rostro de mi hermana cuando se dé cuenta de que todos sus preciosos brotes están casi destruidos, solo los que quedan aquí.",
    ["Arise! Rise from the ground and spread yourself throughout Gielinor!"] = "¡Levántate! ¡Levántate del suelo y extiéndete por Gielinor!",
    ["Get a move on and start corrupting the big sprouts,"] = "Muévete y empieza a corromper los grandes brotes.",
    ["I love the smell of burning wood in the morning."] = "Me encanta el olor a madera quemada por la mañana.",
    ["Move it or become kindling!"] = "¡Muévelo o conviértete en leña!",
    ["Shut up Niya!"] = "¡Cállate Niya!",
    ["Start cheering on my small sprouts, or else!"] = "¡Empiece a animar a mis pequeños brotes, o si no!",
    ["Hello there! My colleague tells me you helped to uncover a hidden altar to the god Zaros."] = "¡Hola! Mi colega me dice que ayudaste a descubrir un altar oculto al dios Zaros.",
    ["A great scholar and archaeologist indeed! Good health and prosperity to you."] = "¡Un gran erudito y arqueólogo! Buena salud y prosperidad para ti.",
    ["Thanks."] = "Gracias.",
    ["I have lost my trowel."] = "He perdido mi paleta.",
    ["Deary me. That was a good one as well. It's a good job I have another. Here you go..."] = "Querido amigo. Esa también fue buena. Es un buen trabajo, tengo otro. Aquí tienes...",
    ["Really? Look in your backpack and make sure first."] = "¿En serio? Mira en tu backpack y asegúrate primero.",
    ["Hi! Please complete this."] = "¡Hola! Por favor complete esto.",
    ["[The examiner has given you a puzzle box!]"] = "[¡El examinador te ha dado una caja de rompecabezas!]",
    ["I'm afraid that you have not finished the puzzle."] = "Me temo que no has terminado el rompecabezas.",
    ["[The examiner has given you another clue scroll!]"] = "[¡El examinador te ha dado otro pergamino de pistas!]",
    ["Correct! Well done!"] = "¡Correcto! ¡Bien hecho!",
    ["Right! Time for your exam."] = "¡Correcto! Hora de tu examen.",
    ["But I haven't studied! I'm not prepared!"] = "¡Pero no he estudiado! ¡No estoy preparado!",
    ["Aha! I am, of course, joking. Here, we learn by doing."] = "¡Ajá! Por supuesto, estoy bromeando. Aquí aprendemos haciendo.",
    ["You Dig?"] = "¿Excavas?",
    ["Talk to an examiner at the Varrock Dig Site's Exam Centre."] = "Hable con un examinador en el centro de exámenes del sitio de excavación Varrock.",
    ["So grab a mattock and get stuck in!"] = "¡Así que toma un azadón y quédate atrapado!",
    ["You seem very happy. What's happened?"] = "Pareces muy feliz. ¿Qué ha pasado?",
    ["Saradomin has returned! Soon I shall return to the battle to fight for his glory against evil!"] = "¡Saradomin ha regresado! ¡Pronto regresaré a la batalla para luchar por su gloria contra el mal!",
    ["How did that happen?"] = "¿Cómo sucedió eso?",
    ["Did you see the portal that appeared in Lumbridge?"] = "¿Viste el portal que apareció en Lumbridge?",
    ["Not long ago it finally opened, and through it the evil Zamorak entered the world!"] = "¡No hace mucho que finalmente se abrió y a través de él el malvado Zamorak entró al mundo!",
    ["It's a good thing Saradomin was here to save us."] = "Es bueno que Saradomin estuviera aquí para salvarnos.",
    ["Immediately, they were locked in battle that we mere mortals would struggle to understand."] = "Inmediatamente, se vieron envueltos en una batalla que a nosotros, simples mortales, nos costaría entender.",
    ["Soon, Saradomin's Icyene general came through, and requested that we all aid Saradomin in battle against Zamorak."] = "Pronto, el general Icyene de Saradomin llegó y nos pidió que todos ayudáramos a Saradomin en la batalla contra Zamorak.",
    ["As a White Knight, I must join the battle and aid my lord!"] = "¡Como Caballero Blanco, debo unirme a la batalla y ayudar a mi señor!",
    ["What battle is this?"] = "¿Qué batalla es esta?",
    ["What does Saradomin need?"] = "¿Qué necesita Saradomin?",
    ["Saradomin has called upon everyone to help. And it's not all fighting!"] = "Saradomin ha pedido ayuda a todos. ¡Y no todo es pelear!",
    ["In order to gather power to defeat Zamorak, he needs people to gather Divine Tears, both on and off the battlefield."] = "Para reunir poder para derrotar a Zamorak, necesita personas para recolectar Lágrimas Divinas, tanto dentro como fuera del campo de batalla.",
    ["You should join up too! You can find the recruiter in the camp to the north of the battlefield."] = "¡Tú también deberías unirte! Puedes encontrar al reclutador en el campamento al norte del campo de batalla.",
    ["I am going soon. Although I work only for the glory of Saradomin, I know there will be great rewards for those who help."] = "Me iré pronto. Aunque trabajo sólo para la gloria de Saradomin, sé que habrá grandes recompensas para quienes ayuden.",
    ["How did that start?"] = "¿Cómo empezó eso?",
    ["What about Zamorak?"] = "¿Qué pasa con Zamorak?",
    ["Oh, I see."] = "Oh, ya veo.",
    ["Evil Zamorak fights against our lord on the battlefield."] = "El malvado Zamorak lucha contra nuestro señor en el campo de batalla.",
    ["His minions are numerous, and they are seeking the power that rightfully belongs to Saradomin."] = "Sus secuaces son numerosos y buscan el poder que por derecho pertenece a Saradomin.",
    ["I can hardly believe this, but there are people joining Zamorak too!"] = "¡No puedo creerlo, pero también hay gente que se une a Zamorak!",
    ["They are recruiting both fighters and skilled workers, and some are actually joining with his evil minions!"] = "¡Están reclutando luchadores y trabajadores calificados, y algunos de hecho se están uniendo a sus malvados secuaces!",
    ["I would keep away from the camp to the south of the battlefield - that's where the evil ones are found."] = "Me mantendría alejado del campamento al sur del campo de batalla; ahí es donde se encuentran los malvados.",
    ["How did that start"] = "¿Cómo empezó eso?",
    ["Where is this battlefield?"] = "¿Dónde está este campo de batalla?",
    ["So I could join Zamorak?"] = "¿Entonces podría unirme a Zamorak?",
    ["You could, but I cannot believe that you would join with Zamorak."] = "Podrías, pero no puedo creer que te unieras a Zamorak.",
    ["He may promise you rewards, but at what cost? And can you trust him?"] = "Puede que te prometa recompensas, pero ¿a qué precio? ¿Y puedes confiar en él?",
    ["No. I would keep away from the camp to the south of the battlefield."] = "No. Me mantendría alejado del campamento al sur del campo de batalla.",
    ["How did the battle start?"] = "¿Cómo empezó la batalla?",
    ["The Battle of Lumbridge is a titanic struggle between two gods!"] = "¡La Batalla de Lumbridge es una lucha titánica entre dos dioses!",
    ["The great Saradomin and his followers are fighting the evil Zamorak and his demons!"] = "¡El gran Saradomin y sus seguidores están luchando contra el malvado Zamorak y sus demonios!",
    ["I'm going there as soon as I can. As a White Knight, it is my duty!"] = "Iré allí tan pronto como pueda. ¡Como Caballero Blanco, es mi deber!",
    ["How did that happen"] = "¿Cómo sucedió eso?",
    ["Where is the battlefield?"] = "¿Dónde está el campo de batalla?",
    ["The battlefield is between Lumbridge and Draynor, immediately to the west of Lumbridge Castle."] = "El campo de batalla está entre Lumbridge y Draynor, inmediatamente al oeste del Castillo Lumbridge.",
    ["You'll find the recruiter to the north of the battlefield. Talk to the recruiter there to join with us!"] = "Encontrarás al reclutador al norte del campo de batalla. ¡Habla con el reclutador allí para unirte a nosotros!",
    ["But keep away from the camp to the south. There they are recruiting people to join Zamorak."] = "Pero mantente alejado del campamento del sur. Allí están reclutando personas para unirse a Zamorak.",
    ["How did the battle start"] = "¿Cómo empezó la batalla?",
    ["May Saradomin be with you!"] = "¡Que Saradomin esté contigo!",
    ["Now, do you have a question about the Task System? Or perhaps I know of a quest that might interest you."] = "Ahora, ¿tiene alguna pregunta sobre el sistema de tareas? O tal vez conozco una misión que podría interesarte.",
    ["What do you wish to say?"] = "¿Qué deseas decir?",
    ["I'd like to ask about achievements and task rewards."] = "Me gustaría preguntar sobre los logros y las recompensas de las tareas.",
    ["You mentioned a quest?"] = "¿Mencionaste una misión?",
    ["I did, I did! So, you're interested? Spiffing! I can see the exploring fibre in you!"] = "¡Lo hice, lo hice! Entonces, ¿estás interesado? ¡Escupiendo! ¡Puedo ver la fibra exploradora en ti!",
    ["Er..."] = "Eh...",
    ["Oh, that exploring flames in your eyes! Just like me in my younger days - eager to discover and take on new challenges, eh?"] = "¡Oh, esas llamas exploradoras en tus ojos! Como yo en mi juventud: ansioso por descubrir y asumir nuevos desafíos, ¿eh?",
    ["Um... so you're going to give me a quest?"] = "Um... ¿entonces me vas a dar una misión?",
    ["A quest? But indeed! A tale of riches is what you need, what?"] = "¿Una misión? ¡Pero efectivamente! Una historia de riquezas es lo que necesitas, ¿qué?",
    ["Yes, and I have just the thing. A snow imp wandered through my door one day and I, curious about foreign lands, as every good explorer should be, asked him for tales of his homeland."] = "Sí, y tengo justo lo que necesitas. Un día, un diablillo de las nieves entró por mi puerta y yo, curioso por las tierras extranjeras, como debe ser todo buen explorador, le pedí historias de su tierra natal.",
    ["So, how can I help you?"] = "Entonces, ¿en qué puedo ayudarte?",
    ["About Myths of the White Lands..."] = "Sobre Mitos de las Tierras Blancas...",
    ["I think I've finished all of the Beginner Tasks in the Lumbridge set."] = "Creo que terminé todas las tareas para principiantes del conjunto Lumbridge.",
    ["You have? Oh, well done! We'll make an explorer of you yet."] = "¿Tienes? ¡Ah, bien hecho! Todavía haremos de ti un explorador.",
    ["Thank you. Is there a reward?"] = "Gracias. ¿Hay una recompensa?",
    ["Ah, yes indeed."] = "Ah, sí, claro.",
    ["Having completed the beginner tasks, you have been granted the ability to use the Explorer emote to show to your friends."] = "Después de completar las tareas para principiantes, se te ha otorgado la posibilidad de usar el gesto Explorer para mostrárselo a tus amigos.",
    ["I have also given you an explorer's ring. Now, this is more than just any old ring. Aside from looking good, it also has magical properties giving you a small but useful boost to your Magic and Prayer."] = "También te he regalado un anillo de explorador. Ahora, esto es más que cualquier anillo viejo. Además de verse bien, también tiene propiedades mágicas que le brindan un pequeño pero útil impulso a su Magic y Prayer.",
    ["Your ring has the ability to restore some of your run energy for you."] = "Tu anillo tiene la capacidad de restaurar parte de tu energía de carrera.",
    ["For each of the first three sections of the diary you complete, your ring will gain an extra charge, so the ring you receive from the medium level tasks will have 3 charges for example."] = "Por cada una de las tres primeras secciones del diario que completes, tu anillo obtendrá una carga adicional, por lo que el anillo que recibas de las tareas de nivel medio tendrá 3 cargas, por ejemplo.",
    ["If they should run out, the ring is recharged by the sun each day, so you will be able to use it again tomorrow and so on."] = "Si se agotan, el anillo se recarga con el sol cada día, por lo que podrás volver a usarlo mañana y así sucesivamente.",
    ["As an extra reward, you can have this old magical lamp to help with your skills. I was going to use it myself, but I don't really need it."] = "Como recompensa adicional, puedes tener esta antigua lámpara mágica para ayudarte con tus habilidades. Iba a usarlo yo mismo, pero realmente no lo necesito.",
    ["Thanks very much."] = "Muchas gracias.",
    ["If you should lose your ring, come back to see me and I'm sure I'll have another. Now, did you have anything further to ask?"] = "Si pierdes tu anillo, vuelve a verme y seguro que tendré otro. Ahora, ¿tenías algo más que preguntar?",
    ["What ho, there! How's that ring working out for you?"] = "¡Qué carajo! ¿Cómo te va ese anillo?",
    ["Lost it, eh? Well, I have another one here that you can have. Try not to lose this one; it doesn't do for explorers like us to go losing things, what?"] = "Lo perdiste, ¿eh? Bueno, tengo otro aquí que puedes tener. Intenta no perder este; No sirve que exploradores como nosotros vayamos perdiendo cosas, ¿qué?",
    ["Well, the Achievement System is a method of guiding yourself while you explore the world."] = "Bueno, el Sistema de Logros es un método para guiarte mientras exploras el mundo.",
    ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from me."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de mi parte.",
    ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area that they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
    ["For completing the Lumbridge and Draynor set, you are presented with an explorer's ring."] = "Por completar el conjunto Lumbridge y Draynor, se te presenta un anillo de explorador.",
    ["This ring will become increasingly useful with each difficultly level of the set that you complete."] = "Este anillo será cada vez más útil con cada nivel de dificultad del conjunto que completes.",
    ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
    ["You need to complete all of the Tasks in the set of a particular difficulty, then you can claim your reward. Most of the Lumbridge set's Tasks are straightforward, although you might find some require quests to be started, if not finished."] = "Debes completar todas las tareas del conjunto de una dificultad particular y luego podrás reclamar tu recompensa. La mayoría de las tareas del conjunto Lumbridge son sencillas, aunque es posible que algunas requieran que se inicien, si no se terminan.",
    ["To claim the Lumbridge set reward, speak to Bob in Bob's Axes in Lumbridge, Ned in Draynor Village, or myself."] = "Para reclamar la recompensa del conjunto Lumbridge, habla con Bob en Bob's Axes en Lumbridge, Ned en Draynor Village o conmigo mismo.",
    ["Can I claim any rewards from you?"] = "¿Puedo reclamar alguna recompensa de usted?",
    ["Explorer's ring 1"] = "Anillo del explorador 1",
    ["Explorer's ring 1? Yes, but I'm afraid it would cost you 500 coins."] = "¿Anillo 1 del explorador? Sí, pero me temo que te costaría 500 coins.",
    ["Purchase another for 500 coins?"] = "¿Comprar otro por 500 coins?",
    ["[You're handed another Explorer's ring 1.]"] = "[Te entregan el anillo de otro Explorador 1.]",
    ["Explorer's ring 2"] = "Anillo del explorador 2",
    ["Explorer's ring 2? Yes, but I'm afraid it would cost you 1,000 coins."] = "¿Anillo del explorador 2? Sí, pero me temo que te costaría 1.000 coins.",
    ["Purchase another for 1,000 coins?"] = "¿Comprar otro por 1.000 coins?",
    ["[You're handed another Explorer's ring 2.]"] = "[Te entregan el anillo de otro Explorador 2.]",
    ["Explorer's ring 3"] = "Anillo del explorador 3",
    ["Explorer's ring 3? Yes, but I'm afraid it would cost you 2,000 coins."] = "¿Anillo del explorador 3? Sí, pero me temo que te costaría 2000 coins.",
    ["Purchase another for 2,000 coins?"] = "¿Comprar otro por 2000 coins?",
    ["[You're handed another Explorer's ring 3.]"] = "[Te entregan el anillo de otro Explorador 3.]",
    ["Explorer's ring 4"] = "Anillo del explorador 4",
    ["Explorer's ring 4? Yes, but I'm afraid it would cost you 10,000 coins."] = "¿Anillo del explorador 4? Sí, pero me temo que te costaría 10.000 coins.",
    ["[You're handed another Explorer's ring 4.]"] = "[Te entregan el anillo de otro Explorador 4.]",
    ["Sorry, you're not owed any achievement rewards at the moment. Look at your Achievement System for things to do to earn more."] = "Lo sentimos, no se te debe ninguna recompensa por logros en este momento. Mire su sistema de logros para saber qué hacer para ganar más.",
    ["I'll just fill your inventory with what you need, then."] = "Entonces llenaré tu inventario con lo que necesitas.",
    ["There you go. You didn't have enough space for everything you're owed, so I've held on to the rest."] = "Ahí lo tienes. No tenías suficiente espacio para todo lo que te debían, así que me quedé con el resto.",
    ["There you go."] = "Ahí lo tienes.",
    ["Eh, I haven't made any progress with the stones. Please come back later."] = "Eh, no he avanzado nada con las piedras. Por favor vuelve más tarde.",
    ["I let those stones thaw, making a very smelly discovery."] = "Dejé que esas piedras se descongelaran, haciendo un descubrimiento muy maloliente.",
    ["I'm sorry."] = "Lo siento.",
    ["You knew about it?"] = "¿Lo sabías?",
    ["I did. When I exited the cave with the 'stones' I met some snow imps, who let me into a secret. This whole quest was a prank on you, as they judged you nosy, greedy and annoying. It was meant to teach you a lesson. They didn't leave me much choice but to complete their plan."] = "Lo hice. Cuando salí de la cueva con las 'piedras' me encontré con unos diablillos de nieve, que me contaron un secreto. Toda esta búsqueda fue una broma para ti, ya que te consideraron entrometido, codicioso y molesto. Estaba destinado a enseñarte una lección. No me dejaron mucha opción más que completar su plan.",
    ["Haha, that's a good one, chum! I suppose I deserve it. Nosy, haha!"] = "Jaja, ¡esa es buena, amigo! Supongo que lo merezco. Entrometido, jaja!",
    ["Glad to see you're taking it lightly."] = "Me alegra ver que te lo estás tomando a la ligera.",
    ["Eh, I've got good news! While you were gone, I managed to sell them to a wandering witch for a goodly sum. She identified it as yeti dung, and said it was a key ingredient in some very advanced ancient potions."] = "¡Eh, tengo buenas noticias! Mientras no estabas, logré vendérselos a una bruja errante por una buena suma. Lo identificó como estiércol de yeti y dijo que era un ingrediente clave en algunas pociones antiguas muy avanzadas.",
    ["Really?"] = "¿En serio?",
    ["Yes indeed! I've kept some of the money for you. There you go."] = "¡Sí, claro! He guardado parte del dinero para ti. Ahí tienes.",
    ["Thank you!"] = "¡Gracias!",
    ["I've been to that ice cave the snow imp mentioned. Sliding is great fun! You should go back there sometime."] = "He estado en esa cueva de hielo que mencionó el diablillo de las nieves. ¡Deslizarse es muy divertido! Deberías volver allí alguna vez.",
    ["Oh and I made a fascinating discovery! in some places, there are paintings on the walls that appear to have been made by a primitive civilisation."] = "¡Ah, y hice un descubrimiento fascinante! en algunos lugares hay pinturas en las paredes que parecen haber sido realizadas por una civilización primitiva.",
    ["I know the ones you mean. They're how I figured how to defeat the yeti. I also found more in the other rooms."] = "Sé a quién te refieres. Así es como descubrí cómo derrotar al yeti. También encontré más en las otras habitaciones.",
    ["Ha, but there are some other ones! I could see some behind roots and things. Do go and have a look sometime."] = "¡Ja, pero hay otros! Pude ver algo detrás de las raíces y esas cosas. Ve y echa un vistazo alguna vez.",
    ["From the sound of it, there's one you haven't seen."] = "Por lo que parece, hay uno que no has visto.",
    ["Stupendous! Look what Foreman George and his team of builders have done! This house is perfect!"] = "¡Estupendo! ¡Mira lo que han hecho Foreman George y su equipo de constructores! ¡Esta casa es perfecta!",
    ["I just need to get a carpet and a few decorations and those months of sleeping rough in the ruins of my house will become a distant memory."] = "Sólo necesito una alfombra y algunas decoraciones y esos meses de dormir a la intemperie en las ruinas de mi casa se convertirán en un recuerdo lejano.",
    ["Since the battle between Saradomin and Zamorak started, my house has been a complete wreck!"] = "Desde que comenzó la batalla entre Saradomin y Zamorak, ¡mi casa ha sido un completo desastre!",
    ["But Foreman George and his team are on the case now. I can't wait to see what they do to it."] = "Pero Foreman George y su equipo ahora están en el caso. No puedo esperar a ver qué le hacen.",
    ["One thing's for sure: it can't be any worse than the ruin the battle left me with!"] = "Una cosa es segura: ¡no puede ser peor que la ruina que me dejó la batalla!",
    ["My house! There I was, sat in the living room, having a nice cup of tea and minding my own business, and BANG! My house collapses around me!"] = "¡Mi casa! Allí estaba yo, sentado en la sala de estar, tomando una buena taza de té y ocupándome de mis propios asuntos, y ¡BANG! ¡Mi casa se derrumba a mi alrededor!",
    ["I went to look - after all I am an explorer - and there, right outside my house, I found Saradomin and Zamorak fighting it out!"] = "Fui a buscar, después de todo soy un explorador, y allí, justo afuera de mi casa, encontré a Saradomin y Zamorak peleando.",
    ["Seems that their battle had a rather unfortunate effect on my foundations. So, I went back inside and made another cup of tea."] = "Parece que su batalla tuvo un efecto bastante desafortunado en mis cimientos. Entonces, volví adentro y preparé otra taza de té.",
    ["I thought to myself that it'll take more than a world-destroying battle between two gigantic all-powerful gods to stop me!"] = "¡Pensé para mis adentros que se necesitaría más que una batalla de destrucción mundial entre dos dioses gigantescos y todopoderosos para detenerme!",
    ["So I'm not letting it get me down. I'm still a taskmaster and I have a job to do!"] = "Así que no dejaré que eso me deprima. ¡Todavía soy un capataz y tengo un trabajo que hacer!",
    ["Glad to see the battle is over now. I'm not sure how Zamorak will recover from that defeat."] = "Me alegra ver que la batalla ya terminó. No estoy seguro de cómo se recuperará Zamorak de esa derrota.",
    ["You are seen. All your secrets are laid bare before Cythan's gaze."] = "Ya te ven. Todos tus secretos quedan al descubierto ante la mirada de Cythan.",
    ["Your secret shames. Your hidden fears. The wicked thoughts you have for your friends."] = "Tus vergüenzas secretas. Tus miedos ocultos. Los malos pensamientos que tienes hacia tus amigos.",
    ["That you'd see them suffer. That you'd see them kneel. That they would love you, fear you, or both."] = "Que los verías sufrir. Que los verías arrodillarse. Que te amarían, te temerían o ambas cosas.",
    ["You are a dark thing. A monster. You only pretend to be a hero."] = "Eres algo oscuro. Un monstruo. Sólo pretendes ser un héroe.",
    ["Why be enslaved to the lie?"] = "¿Por qué estar esclavizado a la mentira?",
    ["Free yourself. Become the nightmare you were born to be."] = "Libérate. Conviértete en la pesadilla para la que naciste.",
    ["Let the veil fall. Embrace the Master's gift."] = "Deja caer el velo. Abrazad el regalo del Maestro.",
    ["Sister attend, they approach."] = "Hermana atiende, se acercan.",
    ["They have bested all that came before us. Their skill should be respected."] = "Han superado a todos los que nos precedieron. Se debe respetar su habilidad.",
    ["Yet still, we cannot relent. We must destroy them."] = "Aún así, no podemos ceder. Debemos destruirlos.",
    ["A pity that they oppose us. Imagine what we could achieve together."] = "Una pena que se nos opongan. Imagínese lo que podríamos lograr juntos.",
    ["They could be so much greater than they are now."] = "Podrían ser mucho mayores de lo que son ahora.",
    ["The world guardian is too small a title. Why guard when you could rule?"] = "El título de guardián del mundo es demasiado pequeño. ¿Por qué proteger cuando puedes gobernar?",
    ["The world guardian is too small a focus. Why settle for just one world?"] = "El guardián del mundo es un foco demasiado pequeño. ¿Por qué conformarse con un solo mundo?",
    ["Join us. We shall make you powerful."] = "Únase a nosotros. Te haremos poderoso.",
    ["Kolthregar demands their death."] = "Kolthregar exige su muerte.",
    ["Cythan craves their suffering."] = "Cythan anhela su sufrimiento.",
    ["I shall feed their soul to the void. May it fuel Kranon's sorcery."] = "Alimentaré su alma hasta el vacío. Que alimente la hechicería de Kranon.",
    ["I shall burn the hope from their spirit. I will see them broken before me."] = "Quemaré la esperanza de su espíritu. Los veré destrozados delante de mí.",
    ["Sisters attend, they approach."] = "Las hermanas asisten, se acercan.",
    ["The thread cutter."] = "El cortahilos.",
    ["The storm bringer."] = "El que trae la tormenta.",
    ["The final calamity."] = "La calamidad final.",
    ["They cannot be allowed to interfere."] = "No se les puede permitir interferir.",
    ["The Ambassador must weaken the veil."] = "The Ambassador debe debilitar el velo.",
    ["The elders have decreed it."] = "Los mayores lo han decretado.",
    ["Agnes has decreed it."] = "Agnes lo ha decretado.",
    ["There is too much at stake."] = "Hay demasiado en juego.",
    ["The Tribunal needs it done."] = "El Tribunal necesita que se haga.",
    ["Well hello there; welcome to our little village. Pray, stay awhile."] = "Bueno, hola; bienvenidos a nuestro pequeño pueblo. Por favor, quédate un rato.",
    ["I supply the local fishermen with the tools and bait they need to do their job."] = "Proporciono a los pescadores locales las herramientas y el cebo que necesitan para hacer su trabajo.",
    ["Interesting. Have you been doing it long?"] = "Interesante. ¿Llevas mucho tiempo haciéndolo?",
    ["Why yes, all of my life. I took over from my father, who inherited the business from his father and so on."] = "Pues sí, toda mi vida. I reemplazó a mi padre, quien heredó el negocio de su padre y así sucesivamente.",
    ["In fact, there have been Lovecraft's selling bait for over ten generations."] = "De hecho, Lovecraft ha sido el cebo de venta durante más de diez generaciones.",
    ["Wow, that's some lineage."] = "Vaya, eso sí que es un linaje.",
    ["Oh yes, we have a long and interesting family history. For one reason or another the Lovecraft's have always been bait sellers or writers."] = "Oh, sí, tenemos una historia familiar larga e interesante. Por una razón u otra los Lovecraft siempre han sido vendedores de cebo o escritores.",
    ["Hmm, yes well. I'm sure it's all fascinating, but I..."] = "Hmm, sí, bueno. Estoy seguro de que todo es fascinante, pero yo...",
    ["Oh very, very fascinating, for instance my great grandfather Howard..."] = "Oh, muy, muy fascinante, por ejemplo mi bisabuelo Howard...",
    ["Yawn. Oh, I'm sorry but I really must be getting on. I think my giraffe needs feeding."] = "Bostezo. Oh, lo siento, pero realmente debo seguir adelante. Creo que mi jirafa necesita alimentación.",
    ["Your?"] = "¿Tu?",
    ["Giraffe. Sorry, but he gets cranky without enough sugar. Bye now!"] = "Jirafa. Lo siento, pero se pone de mal humor sin suficiente azúcar. ¡Hasta luego!",
    ["Oh right, goodbye."] = "Ah, claro, adiós.",
    ["Can I buy some fishing supplies please?"] = "¿Puedo comprar algunos suministros de pesca, por favor?",
    ["You are a bit too strange for me. Bye."] = "Eres un poco extraño para mí. Adiós.",
    ["Sniff. Yes, everyone says that."] = "Olfatea. Sí, todo el mundo dice eso.",
    ["You know, you sound just like the mayor?"] = "¿Sabes? ¿Suenas igual que el alcalde?",
    ["Really? That's the nicest thing anyone has ever said. I admire him a great deal. He works so hard for this town."] = "¿En serio? Eso es lo más bonito que alguien haya dicho jamás. Lo admiro mucho. Trabaja muy duro para esta ciudad.",
    ["You look like him as well?"] = "¿Tú también te pareces a él?",
    ["Hmm, I don't think I do."] = "Hmm, no creo.",
    ["No really, what with the unhealthy skin tone and bulging eyes. The resemblance is uncanny."] = "No, realmente, con el tono de piel poco saludable y los ojos saltones. El parecido es asombroso.",
    ["Well, I haven't spoken to him in a while. I don't get out much."] = "Bueno, hace tiempo que no hablo con él. No salgo mucho.",
    ["I can see why."] = "Puedo ver por qué.",
    ["Maybe the Mayor has finally seen how much I admire him and has grown to admire me?"] = "¿Quizás el alcalde finalmente ha visto cuánto lo admiro y ha llegado a admirarme a mí?",
    ["Anything's possible I suppose. Wait a minute, you mean you've always looked that odd?"] = "Supongo que todo es posible. Espera un momento, ¿quieres decir que siempre te has visto así de raro?",
    ["Hey, I resent that!"] = "¡Oye, eso me molesta!",
    ["I'm sorry, it's just... Nevermind."] = "Lo siento, es sólo que... No importa.",
    ["Are you not going home, Ezekial?"] = "¿No te vas a casa, Ezekial?",
    ["Oh, I will soon; I'm just taking in the atmosphere..."] = "Oh, lo haré pronto; Sólo estoy asimilando la atmósfera...",
    ["The 'atmosphere'? This place has brought us nothing but trouble."] = "¿La 'atmósfera'? Este lugar no nos ha traído más que problemas.",
    ["Absolutely, but that just increases my determination to rid the world of those sea slugs once and for all. Anger is an energy, Player."] = "Absolutamente, pero eso solo aumenta mi determinación de librar al mundo de esas babosas marinas de una vez por todas. La ira es una energía, Player.",
    ["I'm a bit worried about you, Ezekial. I think you ought to go home and relax."] = "Estoy un poco preocupado por ti, Ezekial. Creo que deberías irte a casa y relajarte.",
    ["Maybe you're right. I'll go soon, just give me a little more time."] = "Quizás tengas razón. Iré pronto, sólo dame un poco más de tiempo.",
    ["Hello, Ezekial."] = "Hola, Ezequial.",
    ["Why, hello, Player! I'm so pleased to see you again. Life has been very dull in this quiet little village ever since our last adventure."] = "¡Hola, Player! Me alegro mucho de verte de nuevo. La vida ha sido muy aburrida en este pequeño y tranquilo pueblo desde nuestra última aventura.",
    ["I see you have some rubium - would you like to sell it to me?"] = "Veo que tienes rubium. ¿Te gustaría vendérmelo?",
    ["Well, that depends! How much would you give me for [amount] pieces?"] = "Bueno, ¡eso depende! ¿Cuánto me darías por las piezas [amount]?",
    ["For that amount of rubium I can offer you [10 gp per rubium]."] = "Por esa cantidad de rubium te puedo ofrecer [10 gp per rubium].",
    ["Okay, it's a deal!"] = "¡Está bien, trato!",
    ["It's a pleasure doing business with you."] = "Es un placer hacer negocios con usted.",
    ["I'm sorry, Ezekial. I think I'm going to keep hold of it myself for now."] = "Lo siento, Ezekial. Creo que por ahora me lo quedaré yo mismo.",
    ["Come back later if you change your mind. I'm going to need all that I can get hold of if we're going to finally beat the sea slugs."] = "Vuelve más tarde si cambias de opinión. Voy a necesitar todo lo que pueda conseguir si finalmente queremos vencer a las babosas marinas.",
    ["So, no sign of any more sea slug activity?"] = "Entonces, ¿no hay señales de más actividad de babosas marinas?",
    ["No, it's all very quiet around here at the moment. maybe a little too quiet..."] = "No, todo está muy tranquilo por aquí en este momento. tal vez un poco demasiado silencioso...",
    ["I see. Let's hope it stays that way!"] = "Ya veo. ¡Esperemos que siga así!",
    ["Oh, I don't know about that. I'm looking forward to going on another adventure with you sometime."] = "Oh, no sé nada de eso. Estoy deseando emprender otra aventura contigo algún día.",
    ["I need to get going; see you later."] = "Necesito ponerme en marcha; hasta luego.",
    ["Okay, Player. Pray, don't be a stranger."] = "Está bien, Player. Por favor, no seas un extraño.",
    ["Hi Ezekial!"] = "¡Hola Ezekial!",
    ["Hey Player! How's it going?"] = "¡Hola Player! ¿Cómo estás?",
    ["Hah, I doubt we'll see any more of them. Not after the mess we made of their queen. Which is a shame because I really miss our missions together."] = "Ja, dudo que veamos más de ellos. No después del desastre que hicimos con su reina. Lo cual es una pena porque realmente extraño nuestras misiones juntos.",
    ["Don't worry, I'm sure we'll need your explosive expertise again."] = "No te preocupes, estoy seguro de que volveremos a necesitar tu explosiva experiencia.",
    ["Thanks Player."] = "Gracias Player.",
    ["I need to get going now, see you later!"] = "Necesito irme ahora, ¡hasta luego!",
    ["No problems Player. Good luck on your travels!"] = "No hay problemas Player. ¡Buena suerte en tus viajes!",
    ["Everything belongs in a museum! It also happens that contributing to Velucia's collections is a good way to earn chronotes, which you can spend in my shop! Want a look?"] = "¡Todo pertenece a un museo! ¡También sucede que contribuir a las colecciones de Velucia es una buena manera de ganar cronotas, que puedes gastar en mi tienda! ¿Quieres echar un vistazo?",
    ["We have a range of consumables and unlocks to assist your archaeological progress, whatever level of qualification you've achieved!"] = "¡Tenemos una variedad de consumibles y desbloqueos para ayudarte en tu progreso arqueológico, sin importar el nivel de calificación que hayas alcanzado!",
    ["Oh, I see you have an energised meteorite shard. Are you having buyer's remorse? If so, I can offer a refund on that."] = "Oh, veo que tienes un fragmento de meteorito energizado. ¿Tiene usted remordimiento del comprador? Si es así, puedo ofrecer un reembolso por eso.",
    ["Return energised meteorite shard for a full refund?"] = "¿Devolver un fragmento de meteorito energizado para obtener un reembolso completo?",
    ["Yes, refund me."] = "Sí, reembolsame.",
    ["No, I'll keep it."] = "No, me lo quedaré.",
    ["No, thank you. I'll keep hold of it."] = "No, gracias. Lo conservaré.",
}

return dialogues
